#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <string.h>

typedef struct FrameMetrics {
    time_t timestamp;
    int signalStrength;
    char *rsi;
} FrameMetrics;

struct bufferNode {
    FrameMetrics data;
    struct bufferNode* next;
};

#define BUFFER_SIZE 1000

void insert(struct bufferNode** head, FrameMetrics newData) {
    struct bufferNode *node = (struct bufferNode*) malloc(sizeof(struct bufferNode));
    if (!node) return;

    node->data = newData;
    node->next = *head;
    *head = node;
}

bool removeByTimestamp(struct bufferNode** head, time_t timestamp) {
    struct bufferNode *current = *head, *prev;

    while (current != NULL) {
        if (current->data.timestamp == timestamp) {
            prev->next = current->next;
            free(current);
            return true;
        }
        prev = current;
        current = current->next;
    }

    return false;
}

FrameMetrics getByTimestamp(struct bufferNode* head, time_t timestamp) {
    struct bufferNode *current = head;

    while (current != NULL) {
        if (current->data.timestamp == timestamp)
            return current->data;
        current = current->next;
    }

    FrameMetrics empty;
    return empty;
}

void prune(struct bufferNode** head) {
    time_t now = time(NULL);
    struct bufferNode *current = *head, *prev;

    while (current != NULL && current->data.timestamp < now - BUFFER_SIZE) {
        prev->next = current->next;
        free(current);
        current = prev->next;
    }
}
