#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

typedef struct {
    char *metric;
    double threshold;
} Threshold;

typedef struct LogEntry {
    char *event_data;
    time_t timestamp;
} LogEntry;

void parse_log(LogEntry **entries, char *filename) {
    FILE *file = fopen(filename, "r");
    char line[4096];
    size_t len = 0;
    regex_t regex;
    regmatch_t match_info[1];
    int rc;

    const char *regex_pattern = "^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\s+)\\[(\\w+-){3,}\\]\\s*(.*)";

    rc = regcomp(&regex, regex_pattern, REG_EXTENDED | REG_NEWLINE);
    if (rc) {
        perror("Could not compile regular expression");
        exit(EXIT_FAILURE);
    }

    while (fgets(line, sizeof(line), file)) {
        len = strlen(line);
        if (!line[len - 1] == '\n') {
            line[len++] = '\0';
        }
        rc = regexec(&regex, line, 4, match_info, 0);
        if (rc == 0 && match_info[3][0] != '\0') {
            size_t new_size = len + match_info[3][len - match_info[3][0]] + 1;
            LogEntry *new_entry = realloc(*entries, sizeof(LogEntry) * (len + 1));
            strncpy(new_entry[len].event_data, match_info[3], new_size);
            new_entry[len].timestamp = strtotime(match_info[1]);
            (*entries) = new_entry;
        }
    }

    regfree(&regex);
    fclose(file);
}

void extract_metrics(LogEntry *entries, Threshold thresholds[], int count) {
    for (int i = 0; i < count; ++i) {
        int events_count = 0;
        double total = 0.0;

        for (int j = 0; j < count; ++j) {
            if (!strcmp(entries[j].event_data, thresholds[i].metric)) {
                sscanf(entries[j].event_data + strlen(thresholds[i].metric), "%lf", &total);
                if (total >= thresholds[i].threshold) {
                    events_count++;
                }
            }
        }

        printf("%s (Threshold: %.2f): %d events\n", thresholds[i].metric, thresholds[i].threshold, events_count);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_log> <output_summary> <metrics> <thresholds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    LogEntry *entries = NULL;
    parse_log(&entries, argv[1]);

    Threshold thresholds[] = {
        {"metric1", 5.0},
        {"metric2", 3.0}
    };

    extract_metrics(entries, thresholds, sizeof(thresholds) / sizeof(Threshold));

    FILE *summary = fopen(argv[2], "w");
    if (!summary) {
        perror("Could not open output file");
        exit(EXIT_FAILURE);
    }

    fprintf(summary, "%s\n", argv[3]);
    for (int i = 0; i < sizeof(thresholds) / sizeof(Threshold); ++i) {
        fprintf(summary, "%s: %d events\n", thresholds[i].metric, thresholds[i].threshold);
    }

    fclose(summary);
    free(entries);

    return EXIT_SUCCESS;
}
