#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    int* array;
    size_t capacity;
    size_t size;
} IntList;

void read_ints(IntList* list) {
    char input[10];
    for (size_t i = 0; i < list->capacity && scanf("%s", input) == 1; ++i) {
        long num;
        if (strlen(input) > 19 || strchr("-+-eE", *input)) break; // negative numbers, scientific notation and special characters are not allowed.
        errno = 0;
        num = strtol(input, NULL, 10);
        if (errno == ERANGE || num > INT_MAX || num < INT_MIN) break; // out of range numbers are also not allowed.
        if (list->size == list->capacity) {
            list->capacity *= 2;
            list->array = realloc(list->array, sizeof(int) * list->capacity);
        }
        list->array[list->size++] = num;
    }
}

bool is_even(int num) { return num % 2 == 0; }

int largest(const IntList* list) {
    int max = INT_MIN;
    for (size_t i = 0; i < list->size; ++i) max = (max > list->array[i]) ? max : list->array[i];
    return max;
}

int sum_of_even(const IntList* list) {
    int sum = 0;
    for (size_t i = 0; i < list->size; ++i) if (is_even(list->array[i])) sum += list->array[i];
    return sum;
}

int main() {
    IntList list;
    list.capacity = 10000;
    list.array = malloc(sizeof(int) * list.capacity);
    read_ints(&list);

    printf("Largest integer: %d\n", largest(&list));
    printf("Sum of even integers: %d\n", sum_of_even(&list));

    free(list.array);
    return 0;
}
```

