// Define maximum log message length and log rate limit
#define MAX_LOG_MESSAGE_LENGTH 1024
#define LOG_RATE_LIMIT 100
#define TIME_GRANULARITY 1000000 // 100 microseconds

// External logging service API (asynchronous message delivery)
typedef void (*LogServiceAPI)(char*);
LogServiceAPI logService;

// Thread-safe log queue and mutex for concurrent logging operations
pthread_mutex_t log_queue_mutex = PTHREAD_MUTEX_INITIALIZER;
struct LogQueueEntry {
    char message[MAX_LOG_MESSAGE_LENGTH];
    time_t timestamp;
};
struct LogQueueEntry log_queue[LOG_RATE_LIMIT];
size_t log_queue_head = 0, log_queue_tail = 0;

// Function to log a message to the error log if a given condition is met
void log_error(const char *format, ...) {
    // Calculate current timestamp for rate limiting
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t now = tv.tv_sec;

    // Store the log message in a dynamic buffer and count the number of messages within the specified time granularity
    char log_message[MAX_LOG_MESSAGE_LENGTH] = {0};
    size_t num_messages = 0;

    // Implement variable argument handling using va_start, va_arg and va_end
    va_list args;
    va_start(args, format);
    while (num_messages < MAX_LOG_MESSAGE_LENGTH - 1 && format != NULL) {
        int n = snprintf(&log_message[num_messages], MAX_LOG_MESSAGE_LENGTH - num_messages - 1, format == NULL ? "" : "%s ", va_arg(args, char*));
        if (n > 0) {
            num_messages += n;
            format = va_arg(args, char*);
        }
    }
    va_end(args);

    // Check if the log message is within the maximum length limit and rate limited
    if (num_messages <= MAX_LOG_MESSAGE_LENGTH && now - log_queue[log_queue_head].timestamp >= TIME_GRANULARITY) {
        // Lock mutex to access the shared log queue safely
        pthread_mutex_lock(&log_queue_mutex);

        // Append the log message to the first available entry in the log queue, and update the head index if it wraps around
        strncpy(log_queue[log_queue_head].message, log_message, sizeof(log_queue[log_queue_head].message));
        log_queue[log_queue_head].timestamp = now;
        if (++log_queue_head == LOG_RATE_LIMIT) {
            log_queue_head = 0;
        }

        // Unlock mutex to allow other threads to access the shared log queue
        pthread_mutex_unlock(&log_queue_mutex);

        // Call the external logging service API asynchronously to process the log message
        if (logService) {
            logService(log_message);
        }
    }
}
