typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuth2Token;

OAuth2Token* parse_oauth2_token(const char *json_str) {
    json_t *root, *access_token_node, *expires_in_node, *token_type_node, *refresh_token_node;
    OAuth2Token *token = NULL;

    root = json_loads(json_str, 0, NULL);
    if (!root) return NULL;

    access_token_node = json_object_get(root, "access_token");
    expires_in_node = json_object_get(root, "expires_in");
    token_type_node = json_object_get(root, "token_type");
    refresh_token_node = json_object_get(root, "refresh_token");

    if (!access_token_node || !json_is_string(access_token_node) ||
        !expires_in_node || !json_is_integer(expires_in_node) || expires_in_node->u.i <= 0 ||
        !token_type_node || !json_strcmp(token_type_node, "Bearer") ||
        (refresh_token_node && !json_is_string(refresh_token_node))) {
        json_decref(root);
        return NULL;
    }

    token = malloc(sizeof(OAuth2Token));
