struct thread_safe_counter {
    _Atomic long counter;
    pthread_mutex_t mutex;
};

void thread_safe_counter_init(struct thread_safe_counter *counter, long init_value) {
    counter->counter = init_value;
    pthread_mutex_init(&counter->mutex, NULL);
}

void thread_safe_counter_increment(struct thread_safe_counter *counter) {
    pthread_mutex_lock(&counter->mutex);
    ++counter->counter;
    pthread_mutex_unlock(&counter->mutex);
}

void thread_safe_counter_destroy(struct thread_safe_counter *counter) {
    pthread_mutex_destroy(&counter->mutex);
