void insertString(std::vector<std::shared_ptr<std::string>>& vec, const std::string& str1, const std::string& str2) {
    auto it = std::find_if(vec.begin(), vec.end(), [&](const auto& ptr) { return *ptr == str1; });

    if (it != vec.end()) {
        std::shared_ptr<std::string> newStr(std::make_shared<std::string>(str2));
        it++;
        vec.insert(it, newStr);
    } else {
        vec.push_back(std::make_shared<std::string>(str2));
    }
}
