import { Roles, User } from './models'; // Import user and role models

// Add a new role
async function addRole(role: Role): Promise<Role> {
  return await Role.create(role);
}

// Update an existing role
async function updateRole(id: number, updatedRole: Partial<Role>): Promise<Role | null> {
  const role = await Role.findByPk(id);
  if (!role) return null; // Role not found
  await role.update(updatedRole);
  return role;
}

// Remove a role
async function deleteRole(id: number): Promise<number> {
  const count = await Role.destroy({ where: { id } });
  return count;
}

// Assign user to a specific role
async function assignUserToRole(userId: number, roleId: number): Promise<void> {
  const user = await User.findByPk(userId);
  if (!user) throw new Error('User not found'); // User does not exist

  const role = await Role.findByPk(roleId);
  if (!role) throw new Error('Role not found'); // Role does not exist

  await user.setRoles([role]); // Assign user to the role
}
```

