["```javascript
function generateEventHandlers(container) {
  const eventHandlers = {
    click: {},
    mouseover: {}
  };

  const children = container.children;
  let uniqueElements = new Set();

  Array.from(children).forEach((child) => {
    if (!uniqueElements.has(child)) {
      uniqueElements.add(child);

      eventHandlers.click[child.id] = () => console.log(`Clicked on ${child.id}`);
      eventHandlers.mouseover[child.id] = (e) => console.log(`Mouse over on ${child.id}`);

      if (child.hasAttributes && child.hasAttributes().getNamedItemNS) { // For HTML5 elements
        Array.from(child.attributes).forEach((attr) => {
          if (attr.name === 'data-event') {
            const eventType = attr.value;
            eventHandlers[eventType][child.id] = eval(`function ${child.id}_${eventType}(e) { console.log(\`${eventType} on ${child.id}\`); }`);
          }
        });
      } else { // For IE (or old browsers)
        if (child.getAttribute && child.getAttribute('data-event')) {
          const eventType = child.getAttribute('data-event');
          eventHandlers[eventType][child.id] = eval(`function ${child.id}_${eventType}(e) { console.log(\`${eventType} on ${child.id}\`); }`);
        }
      }
    }
  });

  children.forEach((child) => {
    const id = child.id;

    // Check for duplicate event handlers and remove them
    Object.keys(eventHandlers.click).forEach((key) => {
      if (key === id && eventHandlers.click[key] !== undefined) {
        child.addEventListener('click', eventHandlers.click[id]);
      }
    });
    Object.keys(eventHandlers.mouseover).forEach((key) => {
      if (key === id && eventHandlers.mouseover[key] !== undefined) {
        child.addEventListener('mouseover', eventHandlers.mouseover[id]);
      }
    });

    // Add custom event handlers using the 'data-event' attribute (if present)
    Object.keys(eventHandlers).forEach((eventType) => {
      if (child.getAttribute && child.getAttribute('data-event') === eventType) {
        child[`on${eventType}`] = eventHandlers[eventType][id];
      }
    });
  });

  return container.outerHTML;
}
```"]

