import java.util.*;
import java.time.Instant;
import java.time.Duration;
import java.util.stream.*;
import org.apache.commons.math3.stat.outliers.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class OutlierDetector {
    private static final Logger LOGGER = LoggerFactory.getLogger(OutlierDetector.class);

    public void detectOutliers(DoubleStream transactionData) {
        GrubbsTest grubbsTest = new GrubbsTest();
        DoubleSummaryStatistics clusterStats = transactionData.mapToObj(d -> new double[]{d, 1.0}).summaryStatistics(); // Weighted statistics for each cluster

        List<Double>[] clusters = IntStream.range(0, (int) Math.ceil(transactionData.count() / 2.0)).parallel().mapToObj(i -> Arrays.asList(clusterStats.getSum(), clusterStats.getSumOfSquares(), i * 2)).toArray(List[]::new);

        transactionData.forEachOrdered(t -> {
            long start = Instant.now().toEpochMilli();

            int clusterIndex = findClusterIndex(clusters, t - clusterStats.getMean()); // Find the cluster this transaction belongs to
            double[] clusterStatsForThisTransaction = Arrays.copyOfRange(clusters[clusterIndex].toArray(), 0, 3);
            double zScore = (t - clusterStatsForThisTransaction[0]) / Math.sqrt(clusterStatsForThisTransaction[1]); // Calculate z-score for this transaction

            LOGGER.debug("Processing transaction {}", t);

            if (grubbsTest.applies(zScore, clusters.length)) {
                LOGGER.info("Flagging outlier: {}", t);
            }

            long executionTime = Instant.now().toEpochMilli() - start;
            LOGGER.debug("Execution time for this iteration: {} ms", executionTime);
        });
    }

    private int findClusterIndex(List<Double>[] clusters, double delta) {
        return Arrays.asList(clusters).stream().min((a, b) -> Double.compare(Math.abs(delta - (a[0] - a[1])) / Math.sqrt(a[2]), Math.abs(delta - (b[0] - b[1])) / Math.sqrt(b[2]))).get(0).indexOf(clusters);
    }
}
