['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

public class ConnectionPool {
    private final Selector selector;
    private final Map<Integer, SelectionKey> keys = new HashMap<>();

    public ConnectionPool(Set<String> remoteAddresses) throws IOException {
        selector = Selector.open();
        for (String address : remoteAddresss) {
            SocketChannel socketChannel = SocketChannel.open();
            socketChannel.connect(new InetSocketAddress(address, 80));
            SelectionKey key = socketChannel.register(selector, SelectionKey.OP_READ);
            keys.put(key.hashCode(), key);
        }
    }

    public void submitRead(Integer key) {
        SelectionKey selectionKey = keys.get(key);
        if (selectionKey == null || !selectionKey.isValid()) throw new IllegalStateException();
        selectionKey.interestOps(selectionKey.interestOps() | SelectionKey.OP_READ);
        selector.wakeup();
    }

    public void submitWrite(Integer key, ByteBuffer buffer) {
        SelectionKey selectionKey = keys.get(key);
        if (selectionKey == null || !selectionKey.isValid()) throw new IllegalStateException();
        selectionKey.interestOps(selectionKey.interestOps() | SelectionKey.OP_WRITE);
        selectionKey.attach(buffer);
        selector.wakeup();
    }

    public void pollAndProcess() throws IOException {
        int numReadyKeys = selector.selectNow();
        if (numReadyKeys == 0) return;

        for (SelectionKey key : keys.values()) {
            if (key.isValid() && key.isReadable()) {
                SocketChannel socketChannel = (SocketChannel) key.channel();
                ByteBuffer buffer = (ByteBuffer) key.attachment();
                try {
                    socketChannel.read(buffer);
                    // Process the read data here, then call submitWrite to send a response if needed
                    submitWrite(key.hashCode(), buffer);
                } catch (IOException e) {
                    key.cancel();
                    keys.remove(key);
                }
            }
            if (key.isValid() && key.isWritable()) {
                SocketChannel socketChannel = (SocketChannel) key.channel();
                ByteBuffer buffer = (ByteBuffer) key.attachment();
                try {
                    while (buffer.hasRemaining()) {
                        socketChannel.write(buffer);
                    }
                    buffer.clear();
                } catch (IOException e) {
                    key.cancel();
                    keys.remove(key);
                }
            }
        }
    }
}
