        Some(0) => (),
        Some(err) => {
            eprintln!("Compilation failed with exit code: {}", err);
            let stderr = Command::new("cargo")
                .arg("build")
                .stderr(true)
                .output()?;
            let _ = writeln!(log, &stderr.stderr);
        }
        None => {
            eprintln!("Compilation failed without providing an exit code");
            return Err("Compilation failed without providing an exit code".into());
        }
    };

    // Provide a summary of errors if any occur during compilation
    let output = Command::new("cargo")
        .arg("diagnostics")
        .output()?;
    let _ = writeln!(log, &output.stderr);

