const bcrypt = require('bcryptjs');

function generateSecureToken(length, charSet) {
  const chars = charSet || 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let token = '';
  for (let i = 0; i < length; i++) {
