    T data;
    bool isLeaf = false;
    size_t capacity;
    size_t remainingCapacity;

    OctreeNode(size_t capacity_) : capacity(capacity_), remainingCapacity(capacity_) {}
};

template<typename T>
class Octree {
private:
    std::unique_ptr<OctreeNode<T>> root;
    size_t featureSize;
    size_t numberOfLeafNodes;

public:
    Octree(size_t featureSize_, size_t numberOfLeafNodes_) : featureSize(featureSize_), numberOfLeafNodes(numberOfLeafNodes_) {
        root = std::make_unique<OctreeNode<T>>(std::max((unsigned long long)1, (unsigned long long)pow(2, ceil(log2(numberOfLeafNodes_))) * featureSize));
        initialize(root.get());
    }

    void initialize(OctreeNode<T>* node) {
        if (!node->isLeaf && node->remainingCapacity == 0) {
            for (auto& child : node->children) {
                if (!child) {
                    child = std::make_unique<OctreeNode<T>>(*node);
                    initialize(child.get());
                }
            }
        } else if (!node->isLeaf && node->remainingCapacity > 0) {
            --node->remainingCapacity;
        } else if (!node->isLeaf) {
            // Handle case of exceeding memory limit, you may choose a suitable strategy for this scenario.
        } else {
            node->isLeaf = true;
        }
    }
};
