['```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class RandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private int iterations;
    private List<double> generatedValues;

    public RandomValueGenerator(double minValue, double maxValue, int iterations = 1000)
    {
        if (maxValue <= minValue)
            throw new ArgumentException("Maximum value must be greater than minimum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.iterations = iterations;
        generatedValues = new List<double>();
    }

    public double GenerateRandomInteger(bool isInclusive)
    {
        if (isInclusive)
            return Convert.ToInt32(Math.Floor(GenerateRandomFloat()));
        else
            return Convert.ToInt32(Math.Ceiling(GenerateRandomFloat())) + 1;
    }

    public float GenerateRandomFloat(bool isInclusive)
    {
        double range = maxValue - minValue;
        double randomValue = (isInclusive ? Random : Random.Uniform)() * range + minValue;
        return Convert.ToSingle(randomValue);
    }

    public void GenerateValuesAndCalculateStatistics(int iterations = 1000)
    {
        if (iterations <= 0)
            throw new ArgumentOutOfRangeException("Iterations must be a positive value.");

        this.iterations = iterations;
        generatedValues.Clear();

        for (int i = 0; i < iterations; i++)
        {
            generatedValues.Add(GenerateRandomFloat(true));
        }
    }

    public (double mean, double stdDev) CalculateStatistics()
    {
        if (generatedValues.Count == 0)
            throw new InvalidOperationException("Statistical calculation requires data first.");

        double mean = generatedValues.Average();
        double variance = generatedValues.Select(x => Math.Pow(x - mean, 2)).Average();
        double stdDev = Math.Sqrt(variance);

        return (mean, stdDev);
    }

    public override string ToString()
    {
        (double mean, double stdDev) stats = CalculateStatistics();
        return $"Range: {minValue}-{maxValue}, Mean: {mean}, Standard Deviation: {stdDev}";
    }
}
```
