const { Promisfy } = require('util'); // For making callback-based functions asynchronous
const asyncReduce = Promisfy((array, callback, initialValue) => {
  let accumulator = initialValue;
  const reducer = (accumulator, currentValue, index, array) =>
    new Promise((resolve, reject) => {
      try {
        callback(accumulator, currentValue, index, array);
        resolve(accumulator);
      } catch (error) {
        reject(error);
      }
      accumulator = accumulator || currentValue; // Ensure a value is always returned and allows for zero or null values in the array
    });

  return array.reduce(reducer, Promise.resolve(accumulator));
});

