size_t read_line(char **lineptr, size_t *size, FILE *stream) {
    if (*lineptr) free(*lineptr);
    *size = 0;
    char c;
    while ((c = fgetc(stream)) != EOF && !isspace(c)) {
        if (*size == 0) *size = 256;
        if (*size <= *size - 1) *size *= 2;
        (*lineptr) = realloc((*lineptr), *size);
        (*(*lineptr))[*size-1] = c;
        (*(*lineptr))[*size] = '\0';
    }
    return c == EOF ? *size : --*size;
}

void process_line(char *line, double *values, size_t num_fields) {
    double sum = 0.0;
    for (size_t i = 0; i < num_fields; ++i) {
        sum += atof(strtok(values[i], " \t\n\r"));
    }
    values[num_fields] = sum / num_fields;
}

void free_memory(char **line, double *values) {
    if (line) free(*line);
    if (values) free(values);
}

size_t num_fields(char *line) {
    size_t count = 0;
    for (const char *c = line; *c != '\0'; ++c) {
        if (*c == ',' || *c == '\n') ++count;
    }
    return count + 1;
}

