    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "Invalid response from API: %ld\n", http_code);
        return 1;
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <FILE>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    struct stat st;
    if (stat(argv[1], &st) == -1) {
        perror("Failed to get file size");
        exit(EXIT_FAILURE);
    }

    char *line = NULL;
    double *values = NULL;
    size_t line_size = 0, num_fields = 0;
    CURL *curl = init_curl();

    clock_t start = clock();

    while (fread(&c, sizeof(char), 1, file) == 1 && !feof(file)) {
        if (c == '\n') {
            line[line_size] = '\0';
            num_fields = num_fields(line);
            values = realloc(values, sizeof(double) * (num_fields + 1));
            process_line(line, values, num_fields);
            free_memory(&line, NULL);
            line_size = 0;
        } else if (line_size == line_size - 1) {
            line = realloc(line, line_size + 256);
        }

        if (c != '\n') line[line_size++] = c;
    }

    free_memory(&line, values);

    clock_t end = clock();
    printf("Elapsed time: %.3fs\n", (end - start) / CLOCKS_PER_SEC);

    if (send_data_and_receive_response(curl, values[num_fields])) exit(EXIT_FAILURE);

    fclose(file);
    curl_easy_cleanup(curl);

    return EXIT_SUCCESS;
}
```

