typedef struct {
    int bits_per_sample;
    int sample_per_pixel;
    int extra_samples;
    unsigned char *extra_samples_data;
    EVP_CIPHER_CTX *cipher_context;
} ImageMetadata;

ImageMetadata parse_tiff_image(const char *filename, const char *operation) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open the TIFF file.\n");
        ImageMetadata metadata = {0};
        metadata.bits_per_sample = -1;
        return metadata;
    }

    uint16_t photometric;
    int bits_per_sample = -1;
    if (TIFFGetField(tif, TIFFTagPhotometricInterpretation, &photometric) == 0 ||
        TIFFGetField(tif, TIFFTagBitsPerSample, &bits_per_sample) == 0) {
        fprintf(stderr, "Failed to retrieve image metadata.\n");
        ImageMetadata metadata = {0};
        TIFClose(tif);
        return metadata;
    }

    int sample_per_pixel = 1;
    for (int i = 0; i < bits_per_sample; ++i) {
        if (TIFFGetField(tif, TIFFTagSamplePerPixel, &sample_per_pixel) == 0) {
            break;
        }
        ++sample_per_pixel;
    }

    int extra_samples = 0;
    ImageDescriptor *descriptors = TIFFGetFieldDesc(tif);
    for (int i = sample_per_pixel; descriptors && i < descriptors->nDescription; ++i, ++descriptors) {
        if (TIFFGetTagName(descriptors->tag) == TIFFTAGSAMPLEFORMAT ||
            TIFFGetTagName(descriptors->tag) == TIFFTAGSAMPLEPERPIXEL ||
            TIFFGetTagName(descriptors->tag) == TIFFTAGBITSPERSAMPLE) {
            continue;
        }
        ++extra_samples;
    }

    ImageMetadata metadata = {bits_per_sample, sample_per_pixel, extra_samples};
    if (extra_samples > 0) {
        metadata.extra_samples_data = malloc(TIFFScanlineSize(tif) * extra_samples);
    }

    for (int i = sample_per_pixel; descriptors && i < descriptors->nDescription; ++i, ++descriptors) {
        if (TIFFGetTagName(descriptors->tag) == TIFFTAGSAMPLEFORMAT ||
            TIFFGetTagName(descriptors->tag) == TIFFTAGSAMPLEPERPIXEL ||
            TIFFGetTagName(descriptors->tag) == TIFFTAGBITSPERSAMPLE) {
            continue;
        }

        EVP_CIPHER_CTX *cipher_context = NULL;
        if (strcmp(operation, "encrypt") == 0) {
            cipher_context = EVP_EncryptInit_ex(NULL, EVP_aes_256_cbc(), NULL);
        } else if (strcmp(operation, "decrypt") == 0) {
            cipher_context = EVP_DecryptInit_ex(NULL, EVP_aes_256_cbc(), NULL);
        }

        if (cipher_context) {
            const char *data = (char*)TIFFGetFieldBuffer(tif, descriptors->tag);
            int len = TIFFScanlineSize(tif) * descriptors->RowsPerStrip;
            EVP_CIPHER_CTX_set_IV(cipher_context, data);
            void *buffer = malloc(len);
            memcpy(buffer, data + sizeof(void*), len - sizeof(void*));
            EVP_CIPHER_CTX_update(cipher_context, buffer, len, NULL, NULL);
            metadata.extra_samples_data[i - sample_per_pixel] = cipher_context;
        }
    }

    TIFClose(tif);
    return metadata;
}
