#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

char* modifyFilename(const char* filename) {
    int vowelCount = 0;
    const char *specialChars = ":,./?*{}|";
    int specialCharCount = 0;
    int extensionLength = 0;
    const size_t maxLen = 100;
    char newFilename[maxLen];
    memset(newFilename, '\0', maxLen);

    if (!filename || !*filename) return newFilename; // Handle edge case: empty filename

    for (const char *c = filename; *c != '\0'; ++c) {
        if (islower(*c) && isalpha(*c) && strchr( "aeiou", *c)) vowelCount++;
        if (strchr(specialChars, *c)) specialCharCount++;
    }

    extensionLength = (vowelCount + 1) / 2;

    if (extensionLength < 1) extensionLength = 1;

    strcpy(newFilename, filename); // Copy original filename to new one
    int len = strlen(newFilename);

    const char *extStart = NULL;
    for (int i = len - 1; i >= 0 && i < len - extensionLength; --i) {
        if (!isspace(newFilename[i])) extStart = &newFilename[i]; // Find the start of the extension
    }

    if (!extStart) {
        // Edge case: No extension found, add a default one
        strcat(newFilename, ".txt");
        len += 4;
    } else {
        memmove(&newFilename[len], extStart, strlen(extStart)); // Move the current extension to the end of the string
    }

    if (specialCharCount > 5) extensionLength += 2;
    sprintf(&newFilename[len - extensionLength], "%*.f%s", extensionLength, extensionLength, "@#$");

    for (int i = 0; newFilename[i] != '\0'; ++i) {
        if (isspace(newFilename[i])) newFilename[i] = '\0'; // Remove leading and trailing spaces
    }

    return newFilename;
}
