#include <openssl/evp.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { DETERMINISTIC, NON_DETERMINISTIC } init_mode;

int aes256_cbc_init(unsigned char* key, size_t key_len, unsigned char* iv, size_t iv_len, int iterations, init_mode mode, EVP_CIPHER_CTX** ctx) {
    if (key_len < 32 || mode > NON_DETERMINISTIC) {
        return -1; // Invalid inputs
    }

    *ctx = EVP_CIPHER_CTX_new();
    unsigned char derived_key[EVP_MAX_KEY_LENGTH];

    if (mode == DETERMINISTIC && iv_len != 16) {
        free(*ctx);
        return -2; // IV length should be 16 bytes for deterministic mode
    }

    if (iv == NULL) {
        iv = malloc(16);
        RAND_bytes(iv, 16);
    }

    if (mode == NON_DETERMINISTIC) {
        unsigned char salt[EVP_MAX_SALT_LENGTH];
        RAND_bytes(salt, sizeof(salt));

        PBKDF2_HMAC((const EVP_CIPHER *)EVP_aes_256_cbc(), key, key_len, salt, iterations, iv, 16, derived_key, sizeof(derived_key));
    } else { // DETERMINISTIC
        memcpy(derived_key, key, EVP_MAX_KEY_LENGTH);
    }

    if (1 != EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, derived_key, iv)) {
        free(*ctx);
        free(derived_key);
        return -3; // Failed to initialize the cipher context
    }

    if (iv != ctx) {
        free(iv);
    }

    return 0;
}

void aes256_cbc_cleanup(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
