#define BUFFER_SIZE 2048

int compress_png(const char *input_file, const char *output_dir, int compression_level) {
    FILE *in_file = fopen(input_file, "rb");
    if (!in_file) {
        perror("Error opening input file");
        return 1;
    }

    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_PTR, NULL, NULL, NULL);
    if (!png_ptr) {
        fprintf(stderr, "Error creating read struct\n");
        fclose(in_file);
        return 1;
    }

    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        fprintf(stderr, "Error creating info struct\n");
        png_destroy_read_struct(&png_ptr, NULL);
        fclose(in_file);
        return 1;
    }

    if (setjmp(png_jump_cond(png_ptr))) {
        fprintf(stderr, "Error during init_io\n");
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    png_init_io(png_ptr, in_file);
    png_set_expand(png_ptr);
    png_read_info(png_ptr, info_ptr);

    char output_file[256];
    strcpy(output_file, output_dir);
    strcat(output_file, "/");
    strcat(output_file, input_file);
    strcat(output_file, ".png.gz");

    FILE *out_file = fopen(output_file, "wb");
    if (!out_file) {
        perror("Error opening output file");
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    png_set_compression_level(png_ptr, compression_level);

    png_bytep data = NULL;
    int data_size = 0;
    png_bytep gz_data = NULL;
    uLongf gz_data_size = 0;

    if (setjmp(png_jump_cond(png_ptr))) {
        fprintf(stderr, "Error reading data\n");
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    data = (png_bytep) malloc(data_size = png_get_image_size(png_ptr, info_ptr));
    if (!data) {
        fprintf(stderr, "Error allocating memory\n");
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    if (setjmp(png_jump_cond(png_ptr))) {
        fprintf(stderr, "Error reading data again\n");
        free(data);
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    png_read_image(png_ptr, data);

    gzFile gz_file = gzopen(output_file, "wb9");
    if (!gz_file) {
        fprintf(stderr, "Error opening gzip file\n");
        free(data);
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    gz_data = (png_bytep) malloc(gz_data_size = data_size + zlib_compressbound(data_size));
    if (!gz_data) {
        fprintf(stderr, "Error allocating memory for gzip data\n");
        fclose(gz_file);
        free(data);
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    int gz_result = zlib_compress2((Bytef *)gz_data, &gz_data_size, (const Bytef *)data, data_size, compression_level);
    if (gz_result != Z_OK) {
        fprintf(stderr, "Error compressing gzip data\n");
        free(gz_data);
        fclose(gz_file);
        free(data);
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    size_t written = gzwwrite(gz_file, gz_data, gz_data_size);
    if (written != gz_data_size) {
        fprintf(stderr, "Error writing gzip data\n");
        free(gz_data);
        fclose(gz_file);
        free(data);
        png_destroy_write_struct(&png_ptr, NULL);
        fclose(out_file);
        png_destroy_read_struct(&png_ptr, &info_ptr);
        fclose(in_file);
        return 1;
    }

    free(gz_data);
    gzclose(gz_file);
    fclose(out_file);

    png_write_info(png_ptr, info_ptr);
    png_write_data(png_ptr, data, data_size);
    png_write_end(png_ptr, NULL);

    png_destroy_read_struct(&png_ptr, &info_ptr);
    fclose(in_file);

    return 0;
}
