#include <signal.h>
#include <sys/ioctl.h>
#include <linux/fs.h>
#include <time.h>
#include <string.h>

typedef struct {
    pid_t pid;
    int (*cb)(pid_t, int);
    int fd_input[2], fd_output[2], fd_error[2];
    time_t start_time;
} background_process;

void log(const char *msg) {
    // Logging implementation here
}

background_process *run_command_bg(char **args, int (*cb)(pid_t, int)) {
    int status;
    pid_t pid;
    background_process *bg_proc = malloc(sizeof(background_process));

    if ((pid = fork()) < 0) {
        free(bg_proc);
        return NULL;
    }

    if (pid == 0) {
        // Child process
        close(STDIN_FILENO);
        close(STDOUT_FILENO);
        close(STDERR_FILeno);

        dup2(fd_input[1], STDIN_FILENO);
        dup2(fd_output[0], STDOUT_FILENO);
        dup2(fd_error[0], STDERR_FILENO);

        // Redirect stdin, stdout, and stderr to /dev/null
        close(fd_input[1]);
        close(fd_output[0]);
        close(fd_error[0]);
        close(fd_error[1]);

        // Set maximum execution time
        struct timespec timeout = { 10, 0 };
        if (setitimer(ITIMER_REAL, &timeout, NULL) < 0)
            exit(EXIT_FAILURE);

        execvp(args[0], args);
        exit(EXIT_FAILURE); // Command not found or execution failed
    } else {
        // Parent process
        close(fd_input[0]);
        close(fd_output[1]);
        close(fd_error[1]);

        bg_proc->pid = pid;
        bg_proc->cb = cb;

        if (pipe(bg_proc->fd_input) < 0 || pipe(bg_proc->fd_output) < 0 || pipe(bg_proc->fd_error) < 0) {
            free(bg_proc);
            return NULL;
        }

        log("Command started.");
        bg_proc->start_time = time(NULL);

        return bg_proc;
    }
}

void wait_for_process(background_process *bg_proc) {
    int status;
    waitpid(bg_proc->pid, &status, WNOHANG); // Non-blocking wait

    if (WIFEXITED(status)) {
        log("Command completed with exit status: %d", WEXITSTATUS(status));

        close(bg_proc->fd_input[0]);
        close(bg_proc->fd_output[1]);
        close(bg_proc->fd_error[1]);

        if (bg_proc->cb) {
            bg_proc->cb(bg_proc->pid, WEXITSTATUS(status));
        }

        free(bg_proc);
    }
}
