public class WebsiteManager
{
    private readonly string _webConfigTemplateUrl;
    private readonly string _fallbackWebConfigContent;
    private readonly string _queueFile;
    private readonly double _maxCpuUsage;
    private readonly double _maxMemoryUsage;

    public WebsiteManager(string webConfigTemplateUrl, string fallbackWebConfigContent, string queueFile, double maxCpuUsage, double maxMemoryUsage)
    {
        _webConfigTemplateUrl = webConfigTemplateUrl;
        _fallbackWebConfigContent = fallbackWebConfigContent;
        _queueFile = queueFile;
        _maxCpuUsage = maxCpuUsage;
        _maxMemoryUsage = maxMemoryUsage;
    }

    public async Task<bool> AddSiteAsync(string directoryPath, string siteName)
    {
        var directories = Directory.GetDirectories(@"\\server\directories");
        var sites = Directory.GetFiles(directoryPath, "web.config", SearchOption.AllDirectories);

        if (sites.Any(x => Path.GetFileNameWithoutExtension(x) == siteName))
            return false;

        if (!sites.Any(x => Path.GetDirectoryName(x) == directoryPath))
        {
            var webConfigFile = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigFile))
            {
                try
                {
                    using (var wc = new WebClient())
                    {
                        var data = await wc.DownloadDataTaskAsync(_webConfigTemplateUrl);
                        File.WriteAllBytes(webConfigFile, data);
                    }
                }
                catch
                {
                    File.WriteAllText(webConfigFile, _fallbackWebConfigContent);
                }
            }
        }

        var cpuUsage = GetCpuUsage();
        var memoryUsage = GetMemoryUsage();

        if (cpuUsage > _maxCpuUsage || memoryUsage > _maxMemoryUsage)
        {
            File.WriteAllText(_queueFile, $"{siteName} {directoryPath}\n");
            return false;
        }

        Directory.CreateDirectory(Path.Combine(@"\\server\sites", siteName));
        Directory.Move(directoryPath, Path.Combine(@"\\server\sites", siteName));

        var process = new Process
        {
            StartInfo = new ProcessStartInfo(Path.Combine("\\server\\sites", siteName), "/NoArgs")
            {
                WorkingDirectory = Path.Combine(@"\\server\sites", siteName),
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true
            }
        };

        try
        {
            process.Start();
            process.WaitForExit();
            return process.ExitCode == 0;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to start site: {ex.Message}");
            return false;
        }
    }

    private double GetCpuUsage()
    {
        // Implement your CPU usage measurement logic here
    }

    private double GetMemoryUsage()
    {
        // Implement your memory usage measurement logic here
    }
}
