import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Callable;
import java.util.logging.Level;
import java.util.logging.Logger;

public class CommandExecutor {
    private static final Logger LOGGER = Logger.getLogger(CommandExecutor.class.getName());
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final ConcurrentHashMap<String, Future<?>> runningTasks = new ConcurrentHashMap<>();

    public void executeCommand(String command, long timeout, String workingDirectory) {
        Path dataFile = Paths.get(workingDirectory, "data.txt");
        if (Files.exists(dataFile)) {
            try {
                Files.deleteIfExists(dataFile);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error while deleting data file:", e);
            }
        }

        Callable<Void> callable = () -> {
            Process process;
            try {
                process = new ProcessBuilder(command).directory(new File(workingDirectory)).redirectErrorStream(true)
                    .start();

                PrintWriter outputWriter = new PrintWriter(new FileWriter("output.log"));
                TeeOutputStream errorWriter = new TeeOutputStream(new FileWriter("error.log"), process.getErrorStream());

                process.getOutputStream().close();
                process.inputStream().close();

                StreamGobbler outputGobbler = new StreamGobbler(process.getInputStream(), outputWriter);
                StreamGobbler errorGobbler = new StreamGobbler(errorWriter, Level.SEVERE);

                executor.submit(outputGobbler).start();
                executor.submit(errorGobbler).start();

                long startTime = System.currentTimeMillis();
                Future<Integer> future = executor.submit(() -> {
                    int exitValue = process.waitFor(timeout, TimeUnit.SECONDS);
                    long endTime = System.currentTimeMillis();

                    if (exitValue != 0) {
                        LOGGER.log(Level.WARNING, "Command execution failed with exit value: " + exitValue);
                    }

                    LOGGER.log(Level.INFO, String.format("Command execution finished in %d ms. Exit value: %d", (endTime - startTime), exitValue));
                    return exitValue;
                });

                runningTasks.put(command, future);

                future.get();
                runningTasks.remove(command);
            } catch (InterruptedException | IOException | ExecutionException | TimeoutException e) {
                LOGGER.log(Level.SEVERE, "Error while executing command:", e);
            }

            return null;
        };

        try {
            Future<Void> future = executor.submit(callable).get();
        } catch (InterruptedException | ExecutionException e) {
            LOGGER.log(Level.SEVERE, "Error while submitting command execution task:", e);
        }
    }
}

class StreamGobbler extends Thread {
    private final InputStream input;
    private final OutputStream output;

    public StreamGobbler(InputStream input, OutputStream output) {
        this.input = input;
        this.output = output;
    }

    @Override
    public void run() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(input))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.write((line + "\n").getBytes());
            }
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error while reading command output stream:", e);
        }
    }
}
```

This code provides a basic implementation of the tasks you specified. It uses an `ExecutorService` to manage concurrent command executions and ensures efficient resource management by closing input and output streams as soon as possible. Logging is handled using Java's built-in logging framework, and exceptions are logged or handled gracefully when necessary.

To integrate this into an existing application framework, you would need to create a CommandExecutor instance within your application and call the `executeCommand()` method with the appropriate parameters. The log files will be created in the specified working directory.']

