bool isValidOAuth2AccessTokenResponse(const char *json_str) {
    json_t *root;
    json_error_t error;

    root = json_loads(json_str, 0, &error);
    if (!root || error.text) {
        fprintf(stderr, "JSON parsing error: %s\n", error.text);
        return false;
    }

    if (json_object_size(root) < 3) {
        json_decref(root);
        return false;
    }

    const char *access_token = json_object_get(root, "access_token");
    const char *token_type = json_object_get(root, "token_type");
    int expires_in;
    if (!access_token || !token_type || strlen(access_token) == 0 || strlen(token_type) != 7 || strcmp(token_type, "Bearer") != 0) {
        json_decref(root);
        return false;
    }

    if (json_object_has_member(root, "expires_in")) {
        expires_in = json_integer_value(json_object_get(root, "expires_in"));
        if (expires_in <= 0) {
            json_decref(root);
            return false;
        }
    } else {
        expires_in = -1; // Indicate that 'expires_in' is not present
    }

    if (json_object_has_member(root, "refresh_token")) {
        const char *refresh_token = json_object_get(root, "refresh_token");
        if (strlen(refresh_token) == 0) {
            json_decref(root);
            return false;
        }
    }

    json_decref(root);
    return true;
}
