#include <openssl/evp.h>

typedef struct {
    EVP_CIPHER *cipher;
    unsigned char iv[AES_BLOCK_SIZE];
} decrypt_context;

int validate_token(char *json) {
    json_t *root = json_loads(json, JSON_DECREF | JSON_ERROR_ON_MISSING);
    if (!root) return 0;

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");
    json_t *refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !json_is_string(access_token) ||
        !expires_in || !json_is_number(expires_in) ||
        !token_type || !json_is_string(token_type)) return 0;

    if (strcmp(json_string_value(token_type), "Bearer") != 0 ||
        json_integer_value(expires_in) <= 0) return 0;

    if (refresh_token && (!json_is_string(refresh_token))) return 0;

    json_decref(root);
    return 1;
}

decrypt_context *prepare_for_decryption(unsigned char *key, unsigned int key_len, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = EVP_aes_128_cbc();

    if (!EVP_CIPHER_init(&ctx, cipher, key, iv)) goto err;
    decrypt_context *dec_ctx = malloc(sizeof(decrypt_context));
    if (!dec_ctx) goto err;

    memcpy(dec_ctx->iv, iv, AES_BLOCK_SIZE);
    dec_ctx->cipher = ctx->cipher;
    return dec_ctx;

err:
    if (dec_ctx) free(dec_ctx);
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int decrypt_message(decrypt_context *dec_ctx, unsigned char **buf, size_t *len) {
    int encrypted_len = *len;
    unsigned char *plaintext = malloc(encrypted_len);
    if (!plaintext) return 0;

    EVP_CIPHER_CTX *ctx = dec_ctx->cipher;
    if (!EVP_DecryptUpdate(ctx, plaintext, &plaintext[encrypted_len], *buf, encrypted_len) > 0 ||
        !EVP_DecryptFinal_ex(ctx, plaintext + encrypted_len, NULL)) goto err;

    *len = encrypted_len - AES_BLOCK_SIZE;
    *buf = plaintext;
    return 1;

err:
    if (plaintext) free(plaintext);
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 4) return 1;

    const char *base64_msg = argv[1];
    const char *json = argv[2];
    unsigned char *key = (unsigned char *)argv[3];
    unsigned int key_len = strlen((const char *)key);

    if (!validate_token(json)) return 1;

    decrypt_context *dec_ctx = prepare_for_decryption(key, key_len, IV);
    if (!dec_ctx) return 1;

    unsigned char *message = (unsigned char *)base64_decode((const char *)base64_msg);
    if (!message) return 1;

    int result = decrypt_message(dec_ctx, &message, NULL);
    if (!result) {
        free(message);
        decrypt_context_free(dec_ctx);
        return 1;
    }

    // Do something with the decrypted message...

    free(message);
    decrypt_context_free(dec_ctx);
    return 0;
}
