using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.PADDING;
using Org.BouncyCastle.Security;

namespace AesHmacDecryption
{
    public static class Decryptor
    {
        private const int SaltLength = 16;
        private const int KeyLength = 32;
        private const int IvLength = 16;
        private const int MacLength = 32;
        private const int TagLength = 16;

        public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, byte[] macKey)
        {
            try
            {
                using (var aes = Aes.Create())
                {
                    var parameters = new ParametersWithIV(aes.CreateDecryptor(), iv);
                    var decryptor = CryptoServiceProvider.CreateDecryptor(parameters);

                    PaddedBufferedBlockCipher paddingCipher = new PaddedBufferedBlockCipher(decryptor);
                    PKCS7Padding padding = new PKCS7Padding();
                    paddingCipher.SetPadding(padding);

                    int totalLength = ciphertext.Length;
                    byte[] paddedCipherText = new byte[totalLength + TagLength];
                    Array.Copy(ciphertext, 0, paddedCipherText, 0, totalLength);
                    paddingCipher.DoFinal(paddedCipherText, TagLength, out _);

                    ICryptoTransform hmac = new HmacSha256();
                    hmac.Init(new KeyParameter(macKey));
                    var hmacValue = hmac.ComputeHash(paddingCipher.GetOutput());

                    if (!Array.Equal(hmacValue, Array.Copy(paddedCipherText, totalLength - MacLength, MacLength)))
                    {
                        Console.WriteLine("Error: HMAC validation failed.");
                        return new byte[0];
                    }

                    MemoryStream decryptedStream = new MemoryStream();
                    CryptoStream decryptionStream = new CryptoStream(new MemoryStream(paddedCipherText, 0, TagLength), decryptor, CryptoStreamMode.Read);
                    decryptionStream.CopyTo(decryptedStream);
                    var decryptedData = decryptedStream.ToArray();

                    // Trim the decrypted data of any unnecessary padding
                    return new ArraySegment<byte>(decryptedData).TakeWhile(b => b != 0).ToArray();
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error: Decryption failed.");
                Console.WriteLine($"Exception details: {ex.Message}");
                return new byte[0];
            }
        }
    }
}
```

