public T LoadFromCompressedBinary<T>(string filePath) where T : new()
{
    var logger = LogManager.GetLogger(typeof(Program));

    try
    {
        using (FileStream stream = File.OpenRead(filePath))
        {
            using (var reader = new GZipStream(stream, CompressionMode.Decompress))
            {
                using (var buffer = new MemoryStream())
                {
                    reader.CopyTo(buffer);
                    buffer.Position = 0;

                    var jsonText = Encoding.UTF8.GetString(buffer.ToArray());
                    return JsonConvert.DeserializeObject<T>(jsonText);
                }
            }
        }
    }
    catch (Exception ex)
    {
        logger.Error($"Failed to load data from '{filePath}'. Error: {ex}", ex);
        throw;
    }
}
