import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import sun.misc.BASE64Decoder;
import com.sun.org.apache.xerces.internal.impl.xs.traversers.XPathVisitorImpl;

public class Deserializer {
    private static final String ALGORITHM = "DESede";

    public static MyCustomObject deserializeBase64Encrypted(byte[] encryptedData, String key, byte[] iv) throws RuntimeException {
        try (Cipher cipher = Cipher.getInstance(ALGORITHM)) {
            SecretKeySpec keySpec = new SecretKeySpec(key.getBytes(), ALGORITHM);
            IvParameterSpec ivSpec = new IvParameterSpec(iv);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

            byte[] decryptedData = cipher.doFinal(new BASE64Decoder().decodeBuffer(new String(encryptedData, StandardCharsets.UTF_8)));

            ByteArrayInputStream bais = new ByteArrayInputStream(decryptedData);
            ObjectInputStream ois = new ObjectInputStream(bais);

            MyCustomObject obj = (MyCustomObject) ois.readObject();

            if (!"Bearer".equals(obj.getTokenType()) || obj.getExpiresIn() <= 0) {
                throw new RuntimeException("Invalid object details: token_type should be 'Bearer' and expires_in should be a positive integer.");
            }

            return obj;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Error while deserializing object.", e);
        } catch (Exception e) {
            throw new RuntimeException("Error while decrypting the data.", e);
        }
    }
}

class MyCustomObject implements XPathVisitorImpl, Serializable {
    private String tokenType;
    private int expiresIn;

