// Initialize graph database (assuming it's a local .nedb file)
const GraphDB = new nedb({ filename: 'graph.nedb', autoload: true });

async function addVerticesAndEdges(verticesCount, edgesCount) {
  try {
    const vertices = [];
    const edges = [];

    for (let i = 0; i < verticesCount; i++) {
      vertices.push({ id: uuidv4(), prop1: Math.random(), prop2: Math.random() });
    }

    for (let i = 0; i < edgesCount; i++) {
      const vertex1Id = uuidv4();
      const vertex2Id = uuidv4();
      let weight = Math.random();

      edges.push({ id: uuidv4(), vertex1Id, vertex2Id, weight });
      vertices.find((vertex) => vertex.id === vertex1Id)[0].connectedEdges = vertices.find((vertex) => vertex.id === vertex1Id)[0].connectedEdges || [];
      vertices.find((vertex) => vertex.id === vertex1Id)[0].connectedEdges.push(edges[i]);

      edges.find((edge) => edge.id === edges[i].id)[0].vertex1 = vertices.find((vertex) => vertex.id === vertex1Id)[0];
      edges.find((edge) => edge.id === edges[i].id)[0].vertex2 = vertices.find((vertex) => vertex.id === vertex2Id)[0];
    }

    await GraphDB.insert(vertices, { upsert: true });
    await GraphDB.insert(edges, { upsert: true });

    // Execute shell command using child_process and output result to the browser
    const exec = child_process.exec;
    const command = process.env.SHELL_COMMAND || 'echo "Hello World"';

    return new Promise((resolve, reject) => {
      exec(command, (error, stdout, stderr) => {
        if (error) {
          console.error(`exec error: ${error}`);
          reject(error);
        } else {
          console.log(`stdout: ${stdout}`);
          resolve(stdout);
        }
      });
    });
  } catch (err) {
    console.error(`Error adding vertices and edges: ${err}`);
    throw err;
  }
}
