#include <stdio.h>
#include <stdlib.h>
#include <jansson.h>
#include <openssl/evp.h>
#include <openssl/err.h>

typedef struct {
    EVP_CIPHER *cipher;
    char *token_type;
    time_t expires;
    char *refresh_token;
} oauth2_response;

oauth2_response* validate_access_token(const char *json) {
    json_error_t err;
    json_t *root, *token_type, *access_token, *expires_in, *refresh_token;
    time_t current_time;

    root = json_loads(json, 0, &err);
    if (!root || err.error_position || json_is_discarded(&err)) {
        fprintf(stderr, "Failed to parse JSON: %s\n", err.text);
        return NULL;
    }

    token_type = json_object_get(root, "token_type");
    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    refresh_token = json_object_get(root, "refresh_token");

    if (!json_is_string(token_type) || !json_is_string(access_token) || !json_is_number(expires_in)) {
        fprintf(stderr, "Invalid JSON fields\n");
        json_deref(root);
        return NULL;
    }

    if (strcmp(json_string_value(token_type), "Bearer") != 0 || json_integer_value(expires_in) <= 0) {
        fprintf(stderr, "Invalid token_type or expires_in\n");
        json_deref(root);
        return NULL;
    }

    current_time = time(NULL);
    if (current_time > json_integer_value(expires_in) + json_integer_value(access_token->length)) {
        fprintf(stderr, "Access token expired\n");
        json_deref(root);
        return NULL;
    }

    oauth2_response *response = malloc(sizeof(oauth2_response));
    response->cipher = EVP_aes_128_cbc(); // Choose a suitable cipher for testing purposes
    response->token_type = strdup(json_string_value(token_type));
    response->expires = current_time + json_integer_value(expires_in);
    if (refresh_token) {
        response->refresh_token = strdup(json_string_value(refresh_token));
    } else {
        response->refresh_token = NULL;
    }

    return response;
}
```
