#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h>
#include <openssl/evp.h>
#include <openssl/err.h>

typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuth2Response;

OAuth2Response validate_response(char *json) {
    json_t *root, *token, *tt, *ri;
    OAuth2Response res;

    root = json_loads(json, 0, NULL);
    if (!root) {
        fprintf(stderr, "Invalid JSON\n");
        exit(1);
    }

    token = json_object_get(root, "access_token");
    tt = json_object_get(root, "token_type");
    ri = json_object_get(root, "refresh_token");

    if (!token || !tt || (strcmp(tt->string, "Bearer") != 0) || (ri && strcmp(ri->string, "") == 0)) {
        fprintf(stderr, "Invalid OAuth2 response\n");
        exit(1);
    }

    res.access_token = json_string_value(token);
    res.token_type = tt->string;
    res.refresh_token = ri ? ri->string : "";

    if (json_object_get(root, "expires_in") && json_is_number(json_object_get(root, "expires_in"))) {
        res.expires_in = json_integer_value(json_object_get(root, "expires_in"));
    } else {
        fprintf(stderr, "Missing or invalid expires_in field\n");
        exit(1);
    }

    if (res.expires_in <= 0 || res.expires_in > INT_MAX) {
        fprintf(stderr, "Invalid expires_in value: %d\n", res.expires_in);
        exit(1);
    }

    return res;
}

EVP_CIPHER *prepare_cipher(char *param) {
    EVP_CIPHER_TYPE cipher_type;
    const EVP_CIPHER_CTX *ctx;
    EVP_CIPHER *cipher;

    if (strcmp(param, "DES") == 0) {
        cipher_type = EVP_des_ecb();
    } else if (strcmp(param, "DES-EDE") == 0) {
        cipher_type = EVP_des_ede();
    } else if (strcmp(param, "DES-EDE3") == 0) {
        cipher_type = EVP_des_ede3_cbc();
    } else if (strcmp(param, "CFB") == 0) {
        cipher_type = EVP_cfb128();
    } else if (strcmp(param, "NULL") == 0) {
        return NULL;
    } else {
        fprintf(stderr, "Invalid encryption mode: %s\n", param);
        exit(1);
    }

    cipher = EVP_CIPHERnew(cipher_type);
    ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_init(ctx, cipher);

    return cipher;
}
