typedef struct {
    EVP_CIPHER_CTX* ctx;
    char token[257];
    int expires_in;
    const char* refresh_token;
} OAuthTokenData;

OAuthTokenData validate_json(char* json) {
    Json::Reader reader;
    Json::Value obj;
    if (!reader.parse(json, obj)) {
        fprintf(stderr, "Error parsing JSON: %s\n", reader.getFormatedErrorMessages().c_str());
        exit(EXIT_FAILURE);
    }

    if (!obj["access_token"].isString() || !obj["expires_in"].isIntegral() || obj["token_type"].empty()) {
        fprintf(stderr, "Missing or invalid required fields in JSON.\n");
        exit(EXIT_FAILURE);
    }

    const char* access_token = obj["access_token"].asCString();
    int expires_in = obj["expires_in"].asInt();
    if (strlen(access_token) > 256 || expires_in <= 0 || strcmp(obj["token_type"].asCString(), "Bearer") != 0) {
        fprintf(stderr, "Invalid access token or expiration time.\n");
        exit(EXIT_FAILURE);
    }

    if (obj.isMember("refresh_token")) {
        const char* refresh_token = obj["refresh_token"].asCString();
        // Add your strong token pattern validation here
    }

    return {nullptr, access_token, expires_in, obj.isMember("refresh_token") ? obj["refresh_token"].asCString() : nullptr};
}

OAuthTokenData* init_cipher(const char* mode) {
    const EVP_CIPHER* cipher;
    EVP_CIPHER_CTX* ctx;

    if (strcmp(mode, "encrypt") == 0) {
        cipher = EVP_des_ecb(); // Or EDE, EDE3, or CFB depending on the required mode
    } else if (strcmp(mode, "decrypt") == 0) {
        cipher = EVP_des_ecb(); // Or EDE, EDE3, or CFB depending on the encryption mode used during the previous operation
    } else if (strcmp(mode, "none") == 0) {
        return new OAuthTokenData{nullptr, "", 0, nullptr};
    } else {
        fprintf(stderr, "Invalid mode specified.\n");
        exit(EXIT_FAILURE);
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error allocating EVP_CIPHER_CTX.\n");
        exit(EXIT_FAILURE);
    }

    int rc = EVP_CIPHER_init(ctx, cipher, nullptr, nullptr, mode == 0 ? NULL : (mode[0] == 'd'));
    if (rc != 1) {
        fprintf(stderr, "Error initializing EVP_CIPHER.\n");
        exit(EXIT_FAILURE);
    }

    return new OAuthTokenData{ctx, "", 0, nullptr};
}

void encrypt_decrypt(OAuthTokenData& data) {
    if (!data.ctx) {
        return; // Null encryption mode
    }

    const char* input = "Your input string goes here";
    int len = strlen(input);
    unsigned char iv[EVP_CIPHER_iv_length(data.ctx->cipher)];

    if (len > 4096 || EVP_CIPHER_CTX_ctrl(data.ctx, EVP_CTRL_GCM_SET_IVLEN, sizeof(iv)) <= 0) {
        fprintf(stderr, "Input string too large or IV length error.\n");
        exit(EXIT_FAILURE);
    }

    if (EVP_CIPHER_CTX_ctrl(data.ctx, EVP_CTRL_GCM_SET_IV, iv, sizeof(iv)) <= 0) {
        fprintf(stderr, "Error setting IV.\n");
        exit(EXIT_FAILURE);
    }

    unsigned char* output = static_cast<unsigned char*>(malloc(len + EVP_CIPHER_block_size(data.ctx->cipher)));
    if (!output) {
        fprintf(stderr, "Error allocating memory for output.\n");
        exit(EXIT_FAILURE);
    }

    int rc = data.ctx->mode == EVP_ENCRYPT ? EVP_EncryptUpdate(data.ctx, output, len + sizeof(iv), reinterpret_cast<const unsigned char*>(input), len) : EVP_DecryptUpdate(data.ctx, output, len + sizeof(iv), reinterpret_cast<unsigned char*>(input), len);
    if (rc <= 0) {
        fprintf(stderr, "Error during encryption or decryption.\n");
        exit(EXIT_FAILURE);
    }

    rc = data.ctx->mode == EVP_ENCRYPT ? EVP_EncryptFinal_ex(data.ctx, output + len, &len) : EVP_DecryptFinal_ex(data.ctx, output + len, &len);
    if (rc <= 0) {
        fprintf(stderr, "Error during encryption or decryption.\n");
        exit(EXIT_FAILURE);
    }

    data.token[strlen(data.token)] = '\0';
    strncpy(data.token, reinterpret_cast<const char*>(output), sizeof(data.token));
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <JSON> <MODE> <CIPHERTEXT>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    OAuthTokenData token_data = validate_json(argv[1]);
    OAuthTokenData* cipher_data = init_cipher(argv[2]);

    encrypt_decrypt(*cipher_data);

    // Use the validated access_token and expires_in in your application
    if (cipher_data->expires_in <= 0 || token_data.expires_in <= 0 || cipher_data->expires_in > token_data.expires_in) {
        fprintf(stderr, "Expires_in value is invalid or token expiration is too early.\n");
        exit(EXIT_FAILURE);
    }

    // Perform your application logic with the validated access_token and expires_in

    EVP_CIPHER_CTX_free(cipher_data->ctx);
    free(cipher_data);
    return 0;
}
