#include <stdio.h>
#include <string.h>
#include <jansson.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/cbc.h>
#include <openssl/cfb8.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

typedef struct {
    int rounds;
    const char *mode;
} EncryptOptions;

int validate_json(const char *json) {
    json_t *root = json_loads(json, 0, NULL);
    if (!root) return 0;

    if (json_object_get(root, "access_token") == JSON_NULL ||
        json_object_get(root, "expires_in") == JSON_NULL ||
        !json_is_integer(json_object_get(root, "expires_in")) ||
        json_object_get(root, "token_type") == JSON_NULL ||
        strcmp(json_string_value(json_object_get(root, "token_type")), "Bearer") != 0 ||
        strlen(json_string_value(json_object_get(root, "access_token"))) > 256 ||
        json_object_size(root) > 4) {
        json_decref(root);
        return 0;
    }

    const char *refresh_token = json_object_get(root, "refresh_token");
    if (refresh_token && strlen(refresh_token) > 128 && strpbrk(refresh_token, "/\\:#%$@!~*?<>|") == NULL) {
        json_decref(root);
        return 0;
    }

    json_decref(root);
    return 1;
}

int encrypt_decrypt(const char *access_token_json, const EncryptOptions *options, const char *input, unsigned char *output, size_t *output_len) {
    json_t *root = json_loads(access_token_json, 0, NULL);
    if (!root) return -1;

    int cbc_cbf = (strcmp(json_string_value(json_object_get(root, "mode")), "CBC") == 0);
    const char *algorithm = (options->rounds > 0) ? (cbc_cbf ? "AES-" : "DES-"): "";
    const char *mode = cbc_cbf ? "CFB8" : "ECB";
    const int rounds = options->rounds;
    AES_KEY aes_key;
    DES_cblock tdes_keys[3];

    if (strncmp(algorithm, "AES", 3) == 0) {
        if (!AES_set_encrypt_key((const unsigned char *)ACCESS_TOKEN, 128, &aes_key)) goto error;
    } else if (strncmp(algorithm, "DES", 3) == 0) {
        DES_ede3_set_encrypt_key((const unsigned char *)ACCESS_TOKEN, tdes_keys);
    }

    unsigned char iv[AES_BLOCK_SIZE];
    if (cbc_cbf && (strlen(json_string_value(json_object_get(root, "iv"))) != AES_BLOCK_SIZE)) goto error;
    memcpy(iv, json_string_value(json_object_get(root, "iv")), AES_BLOCK_SIZE);

    int len = strlen(input);
    if (len > 4096) goto error;

    unsigned char *buffer = malloc(AES_BLOCK_SIZE + len);
    memcpy(buffer, iv, AES_BLOCK_SIZE);

    int encrypt = 1;
    for (int i = 0; i < rounds; ++i) {
        if (encrypt) {
            if (!options->mode[0]) encrypt = 0;
            else if (strcmp(options->mode, "CFB8") == cbc_cbf) encrypt = 0;
        } else {
            if (strcmp(options->mode, "CBC") == !cbc_cbf) encrypt = 1;
            else if (strcmp(options->mode, "CFB8") == cbc_cbf) encrypt = 1;
        }

        int block_len = AES_BLOCK_SIZE - (len % AES_BLOCK_SIZE);
        memcpy(buffer + AES_BLOCK_SIZE, input, len < block_len ? len : block_len);

        if (encrypt) {
            if (strcmp(algorithm, "AES") == 0) {
                AES_cbc_encrypt((const unsigned char *)buffer + AES_BLOCK_SIZE, buffer + AES_BLOCK_SIZE, len < block_len ? len : block_len, &aes_key, iv, encrypt ? CBC_ENCRYPT : CBC_DECRYPT);
            } else if (strcmp(algorithm, "DES") == 0) {
                DES_ede3_cbc_encrypt((const unsigned char *)buffer + AES_BLOCK_SIZE, buffer + AES_BLOCK_SIZE, len < block_len ? len : block_len, tdes_keys, iv, encrypt ? CBC_ENCRYPT : CBC_DECRYPT);
            }
        } else {
            if (strcmp(algorithm, "AES") == 0) {
                AES_cbc_decrypt((const unsigned char *)buffer + AES_BLOCK_SIZE, buffer + AES_BLOCK_SIZE, len < block_len ? len : block_len, &aes_key, iv);
            } else if (strcmp(algorithm, "DES") == 0) {
                DES_ede3_cbc_decrypt((const unsigned char *)buffer + AES_BLOCK_SIZE, buffer + AES_BLOCK_SIZE, len < block_len ? len : block_len, tdes_keys, iv);
            }
        }
    }

    if (encrypt) {
        memcpy(output, buffer + AES_BLOCK_SIZE, len);
        *output_len = len;
        free(buffer);
        json_decref(root);
        return 0;
    }

error:
    fprintf(stderr, "Error: %s\n", strerror(errno));
    json_decref(root);
    free(buffer);
    return -1;
}

int main(int argc, char **argv) {
