const regex = /(?<book>[A-Za-z]+)\s+(?<chapter>\d{1,3})\s+(?<verse>\d{1,5})/g;

function analyzeText(text) {
    let matches = [];
    let result = {};

    while (match = regex.exec(text)) {
        const book = match.groups.book.toLowerCase();
        const chapter = parseInt(match.groups.chapter, 10);
        const verse = parseInt(match.groups.verse, 10);

        if (!result[book]) {
            result[book] = {};
        }

        if (!result[book].chapters) {
            result[book].chapters = {};
        }

        if (!result[book].chapters[chapter]) {
            result[book].chapters[chapter] = [];
        }

        result[book].chapters[chapter].push(verse);
    }

    return result;
}
