static void* lib_ctx;
static EVP_CIPHER_CTX *aes256_ctx, *chacha20_ctx, *sha256_ctx;
static unsigned char ed25519_priv[ED25519_PRIVATE_KEY_SIZE], ed25519_pub[ED25519_PUBLIC_KEY_SIZE];

void crypt_lib_init() {
    lib_ctx = mmap(NULL, sizeof(EVP_LIBRARY), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    EVP_add_cipher("AES-256-CFB8", EVP_aes_256_cfb8());
    EVP_add_cipher("ChaCha20", chacha20_ctx = EVP_CIPHER_CTX_new());
    EVP_add_digest("SHA-256", SHA256_EVP());
    EVP_add_digest_alias("SHA-256", "SHA384", SHA256_EVP());
    EVP_add_digest_alias("SHA-256", "SHA512", SHA256_EVP());
    EVP_add_digest_alias("ChaCha20", "ChaChaPoly1305", EVP_chacha20_poly1305());
    EVP_add_digest_alias("EdDSA-ED25519", "Ed25519", EVP_pkey_ed25519());

    // Initialize secure random number generator
    RAND_poll();

    // Generate and store Ed25519 key pair
    if (1 != EVP_PKEY_generate_param(NULL, ed25519_priv, sizeof(ed25519_priv)) ||
        1 != EVP_PKEY_keygen(NULL, ed25519_pub, NULL, ed25519_priv, NULL)) {
        fprintf(stderr, "Error generating Ed25519 key pair\n");
        exit(EXIT_FAILURE);
    }
}

void aes256_cbc_encrypt(unsigned char* iv, unsigned char *in, unsigned int in_len, unsigned char *out) {
    // Use caching mechanism for AES-256-CFB8 context
    if (!aes256_ctx) aes256_ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(aes256_ctx, EVP_get_cipherbyname("AES-256-CFB8"), NULL, NULL, iv);
    EVP_EncryptUpdate(aes256_ctx, out, in_len, in, 0);
}

void chacha20_poly1305_encrypt(const unsigned char* nonce, const unsigned char *in, unsigned int in_len, unsigned char *out) {
    // Use ChaCha20 and Poly1305 with cached context
    EVP_CIPHER_CTX_reset(chacha20_ctx);
    EVP_EncryptInit(chacha20_ctx, EVP_get_cipherbyname("ChaCha20"), NULL, NULL, nonce);
    EVP_EncryptUpdate(chacha20_ctx, out, in_len, in, 0);
    EVP_CIPHER_CTX_ctrl(chacha20_ctx, EVP_CTRL_CHACHA20_POLY1305_ENCRYPT, NULL, out + in_len);
}

void sha256_digest(const unsigned char *in, unsigned int in_len, unsigned char *out) {
    EVP_DigestInit_ex(sha256_ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(sha256_ctx, in, in_len);
    EVP_DigestFinal_ex(sha256_ctx, out, NULL);
}
