    struct transition* transitions;
    pthread_mutex_t mutex;
} State;

typedef struct transition {
    char input[4];
    State* target;
    pthread_mutex_t mutex;
} Transition;

// Function to manage the transition of states within a finite state automaton (FSA)
State** fsa_transition(int* current_states, int num_current_states, const FSA* fsa, int last_state) {
    pthread_t threads[num_current_states];
    State** new_states = malloc(sizeof(State*) * (num_current_states + 1));

    for (int i = 0; i < num_current_states; ++i) {
        pthread_create(&threads[i], NULL, transition_worker, &current_states[i]);
    }

    void* result;
    pthread_join(threads[last_state], &result);
    memcpy(new_states, result, sizeof(State*) * (num_current_states + 1));

    // Free old states and threads
    for (int i = 0; i < num_current_states; ++i) {
        free(current_states[i].name);
        free(current_states[i].transitions);
        pthread_detach(threads[i]);
    }

    // Update last state's 'next' pointer
    new_states[last_state]->next = new_states;

    return new_states;
}

