    current_state->num_transitions++;
    current_state->transitions = realloc(current_state->transitions, sizeof(Transition) * (current_state->num_transitions + 1));
    current_state->transitions[current_state->num_transitions - 1] = *transition;
    pthread_mutex_unlock(&current_state->mutex);

    return new_state;
}
```
