void initialize_crypto_library() {
    EVP_CIPHER_CTX *ctx;

    // AES-128-GCM
    const EVP_CIPHER *aes = EVP_aes_128_gcm();
    EVP_add_cipher(aes);

    // Camellia-128-CBC
    const EVP_CIPHER *camellia = EVP_camellia_128_cbc();
    EVP_add_cipher(camellia);

    // ChaCha20-Poly1305
    const EVP_CIPHER *chacha = EVP_chacha20_poly1305();
    EVP_add_cipher(chacha);

    // SHA-256 and SHA-3 (Keccak-f[256])
    const EVP_MD *sha256 = EVP_sha256();
    const EVP_MD *sha3 = EVP_keccak256();
    EVP_add_digest(sha256, "SHA-256");
    EVP_add_digest(sha3, "SHA-3");

    // ECDSA with P256
    const EC_KEY *ecdsa_key = EC_KEY_new();
    if (!EC_KEY_set_curve_nist_p256(ecdsa_key)) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    EVP_add_digestalias("ECDSA", "SHA-256", (unsigned char *)EVP_PKEY_get0_EC_KEY(ecdsa_key), EC_KEY_size(ecdsa_key));

    // Memory management: Prevent memory leaks
    EVP_CIPHER_CTX_free(ctx);
    EC_KEY_free(ecdsa_key);
}
