#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <png.h>
#include <zlib/zlib.h>
#include <time.h>
#include <sys/stat.h>
#include <json-c/json.h>

enum { MAX_FILE_SIZE = 10000000 }; // Adjustable maximum file size threshold (in bytes)

typedef struct {
    char input[256];
    char output[256];
    char log[256];
    int compression_level;
    int quality;
    unsigned long max_size;
} Args;

int compress_image(Args* args) {
    FILE *in, *out, *log_file = NULL;
    png_structp png_ptr;
    png_infop info_ptr;
    z_stream strm;

    in = fopen(args->input, "rb");
    if (!in) {
        fprintf(stderr, "Failed to open input file: %s\n", args->input);
        return 1;
    }

    out = fopen((const char*)args->output, "wb");
    if (!out) {
        fprintf(stderr, "Failed to create output file: %s\n", args->output);
        fclose(in);
        return 1;
    }

    log_file = fopen((const char*)args->log, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to create log file: %s\n", args->log);
        fclose(in);
        fclose(out);
        return 1;
    }

    png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) {
        fprintf(stderr, "Failed to initialize libpng struct\n");
        fclose(in);
        fclose(out);
        fclose(log_file);
        return 1;
    }

    info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        fprintf(stderr, "Failed to initialize libpng info struct\n");
        png_destroy_read_struct(&png_ptr, NULL, NULL);
        fclose(in);
        fclose(out);
        fclose(log_file);
        return 1;
    }

    if (setjmp(png_jmpbuf(png_ptr))) {
        fprintf(stderr, "Error during init_io\n");
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        fclose(in);
        fclose(out);
        fclose(log_file);
        return 1;
    }

    png_init_io(png_ptr, in);
    png_read_info(png_ptr, info_ptr);

    // Handle potential errors during reading image information

    png_bytep data = NULL;
    int width = 0, height = 0;
    int bit_depth = 0, color_type = 0;
    if (setjmp(png_jmpbuf(png_ptr))) {
        fprintf(stderr, "Error reading image information\n");
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        fclose(in);
        fclose(out);
        fclose(log_file);
        return 1;
    }

    png_get_IHDR(png_ptr, info_ptr, &width, &height, &bit_depth, &color_type, NULL, NULL, NULL);

    // Perform any required optimization or error handling based on image dimensions and settings

    uLongf total_out = height * width * (color_type == PNG_COLOR_TYPE_GRAY || color_type == PNG_COLOR_TYPE_PALETTE ? 1 : 3);

    // Set up zlib compression stream
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    deflateInit(&strm, args->compression_level);

    if (total_out > args->max_size) {
        fprintf(stderr, "Output file exceeds maximum size limit\n");
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        deflateEnd(&strm);
        fclose(in);
        fclose(out);
        fclose(log_file);
        return 1;
    }

    data = (png_bytep)malloc(total_out + total_out / 2); // Allocate additional memory for deflating PNG data
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for compressed data\n");
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        deflateEnd(&strm);
        fclose(in);
        fclose(out);
        fclose(log_file);
        return 1;
    }

    // Perform image compression and write the compressed data to the output file

    png_bytep ptr = data;
    png_bytep dst = data + total_out;

    while (png_get_row(png_ptr, info_ptr, &ptr)) {
        const uLongf len = fread(ptr, 1, width * (color_type == PNG_COLOR_TYPE_GRAY || color_type == PNG_COLOR_TYPE_PALETTE ? 1 : 3), in);
        if (feof(in)) break;

        uLongf outlen = FILTER_TYPE > 0 ? len * FILTER_TYPE->filter_length / 8 : len;
        if (strm.avail_out < outlen) {
            deflateReset(&strm);
        }

        strm.next_in = ptr;
        strm.avail_in = len;

        while (strm.avail_out == 0) {
            if (deflateOut(out, &strm, dst - data) < 1) break;
            outlen -= (dst - data);
        }

        ptr += len * (color_type == PNG_COLOR_TYPE_GRAY || color_type == PNG_COLOR_TYPE_PALETTE ? 1 : 3);
    }

    fseek(out, -(long)(dst - data), SEEK_SET); // Rewind the output file to write the remaining compressed data
    fwrite(data, 1, dst - data, out);

    free(data);
    deflateEnd(&strm);
    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    fclose(in);
    fclose(out);
    fclose(log_file);

    // Calculate and log compression metrics

    double compression_ratio = (double)total_out / (dst - data);
    clock_t start = clock();
    // Perform any necessary operations to obtain time taken for compression
    double time_taken = (clock() - start) / CLOCKS_PER_SEC;

    JsonObject* log_data = json_object_new_object();
    json_object_object_add(log_data, "compression_ratio", json_object_new_double(compression_ratio));
    json_object_object_add(log_data, "time_taken", json_object_new_double(time_taken));

    // Write the log data to the specified directory in JSON format

    return 0;
}
```
