#include <openssl/err.h>
#include <openssl/pem.h>
#include <jansson.h>
#include <windows.h>

typedef struct {
    const char *jwt;
    const char *filename;
    const char *user_id;
    const char *json_obj;
} Args;

static int check_role(const char *role) {
    // Simplified role validation function for this example. In a real-world scenario, you'd use a connection to a database or other data source.
    return strcmp("admin", role) == 0;
}

static int validate_jwt(const EVP_PKEY *key, const jchar_t *token) {
    JWT jwt = jwt_new();

    if (!jwt_init(&jwt, token)) {
        ERR_clear_error();
        return 0;
    }

    // Decode header and payload separately
    const jchar_t *header, *payload;
    jwt_header_parts_t parts;
    if (!jwt_get_header(jwt, &header, &parts)) {
        ERR_clear_error();
        return 0;
    }

    // Verify the signature of the header and payload
    if (!jwt_verify_signature(&jwt, key, header, parts.algorithm)) {
        ERR_clear_error();
        return 0;
    }

    // Parse the claims from the payload
    json_t *claims = json_loads(jwt_get_raw_data(jwt), 0, NULL);
    if (!json_is_object(claims)) {
        ERR_clear_error();
        json_decref(claims);
        return 0;
    }

    const char *sub, *iat, *exp, *roles;
    if ( !json_object_get_string_ex(claims, "sub", &sub) ||
         !json_object_get_string_ex(claims, "iat", &iat) ||
         !json_object_get_string_ex(claims, "exp", &exp) ||
         !json_object_get_string_ex(claims, "roles", &roles)) {
        ERR_clear_error();
        json_decref(claims);
        return 0;
    }

    // Validate claims
    time_t current_time = time(NULL);
    if (strtol(iat, NULL, 10) + 60 > current_time || strtol(exp, NULL, 10) - 60 < current_time) {
        ERR_clear_error();
        json_decref(claims);
        return 0;
    }

    const char **role_arr = json_array_get(json_object_get(claims, "roles"), NULL);
    if (!role_arr || !*role_arr) {
        ERR_clear_error();
        json_decref(claims);
        return 0;
    }

    // Check for admin role
    if (!check_role(*role_arr)) {
        ERR_clear_error();
        json_decref(claims);
        return 0;
    }

    jwt_free(jwt);
    json_decref(claims);
    return 1;
}

static void modify_filename(const char *original, char **new_filename) {
    size_t len = strlen(original);
    if (len < 4 || strcmp(&original[len - 3], ".exe")) {
        snprintf(new_filename, 256, "%s_%lu.exe", original, time(NULL));
    } else {
        // Handle extension-less files or unsupported extensions here
        snprintf(new_filename, 256, "%s_%lu.exe", original, time(NULL));
    }
}

static void *process_token(void *arg) {
    Args *args = arg;

    // Your code for processing the token here (e.g., decoding it using jwt_decode(), verifying claims with validate_jwt())

    if (!validate_jwt(/* your key pointer */, args->jwt)) {
        printf("Invalid or expired JWT\n");
        return NULL;
    }

    // Modify the filename based on the original filename and the user ID
    char new_filename[256];
    modify_filename(args->filename, new_filename);

    // Your code for performing privileged actions here (e.g., file manipulation using CreateFile(), WriteFile(), etc.)

    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 6) {
        printf("Usage: %s <jwt> <filename> <user_id> <json_obj>\n", argv[0]);
        return 1;
    }

    Args args = {argv[1], argv[2], argv[3], argv[4]};
    HANDLE thread = CreateThread(NULL, 0, process_token, &args, 0, NULL);

    WaitForSingleObject(thread, INFINITE);

    return 0;
}
