#include <arpa/inet>
#include <netdb.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <openssl/md5.h>

typedef struct FSA {
    int num_states;
    int *states;
    void (*transition)(struct FSA *, int, char);
    void *error_state;
    pthread_mutex_t mutex;
} FSA;

typedef struct StateList {
    int len;
    int *states;
    u_char ip[16]; // 16 bytes for IPv4 address
    pthread_mutex_t mutex;
} StateList;

int dns_resolve(const char *hostname, u_char *ip) {
    struct hostent *he = gethostbyname(hostname);
    if (!he) return -1; // Error: Host not found
    memcpy(ip, he->h_addr, sizeof(he->h_addr));
    return 0;
}

StateList* fsa_process_input(int *current_states, int num_current_states, FSA *fsa, int last_state) {
    StateList *new_list = mmap(NULL, sizeof(StateList), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);
    if (!new_list) return NULL; // Error: Out of memory

    new_list->len = num_current_states + 16; // Reserve space for IPs and some extra room
    new_list->states = malloc(new_list->len * sizeof(int));
    if (!new_list->states) {
        munmap(new_list, sizeof(StateList));
        return NULL; // Error: Out of memory
    }

    memcpy(new_list->states, current_states, num_current_states * sizeof(int));

    int error = 0;
    pthread_t threads[num_current_states];
    for (int i = 0; i < num_current_states; ++i) {
        char input[1024];
        strncpy(input, current_states[i] >= fsa->num_states ? "Error" : "", sizeof(input));
        const char *hostname = fsa->transition != NULL ? fsa->transition(fsa, current_states[i], input) : "";
        u_char ip[16];
        int err = dns_resolve(hostname, ip);
        if (err < 0) error = 1; // Error: DNS resolution failed
        else {
            new_list->states[num_current_states + i] = ip[0] | (ip[1] << 8) | (ip[2] << 16) | (ip[3] << 24);
            // Convert the rest of the IP address to an integer for future transition calculations
            memcpy(&new_list->states[num_current_states + i + 4], &ip[4], sizeof(u_char) * 12);
        }

        pthread_attr_t attr;
        pthread_attr_init(&attr);
        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
        pthread_create(&threads[i], &attr, process_input_thread, (void *)new_list);
    }

    for (int i = 0; i < num_current_states; ++i) {
        void *ret;
        pthread_join(threads[i], &ret);
        if (ret != PTR_ERR && ret != NULL) error |= *(int *)ret > 0; // Error: An error state was reached
    }

    pthread_mutex_init(&new_list->mutex, NULL);
    new_list->states[last_state] = num_current_states + (error ? fsa->num_states : -1); // Store the next list index or an error state index

    if (fsa->error_state != NULL) {
        // If there's a special error state, check if we reached it and return an error code
        if (new_list->states[last_state] == fsa->num_states) error = 1;
    }

    pthread_mutex_destroy(&fsa->mutex);
    free(fsa->states);
    fsa->states = new_list->states;
    fsa->num_states = new_list->len;

    if (error) {
        // If an error was reached, clean up and return NULL
        munmap(new_list, sizeof(StateList));
        free(new_list->states);
        return NULL;
    }

    return new_list;
}

void* process_input_thread(void *arg) {
    StateList *new_list = arg;
    int index = pthread_self() % new_list->len; // Assign each thread a unique index to access the state list concurrently

    while (1) {
        pthread_mutex_lock(&new_list->mutex);
        if (new_list->states[index] >= new_list->len) break; // Exit the loop when we reach an error state or the end of the list

        int state = new_list->states[index];
        char input[1024];
        strncpy(input, state >= fsa->num_states ? "Error" : "", sizeof(input));
        const char *hostname = fsa->transition != NULL ? fsa->transition(fsa, state, input) : "";
        u_char ip[16];
        int err = dns_resolve(hostname, ip);
        if (err < 0) break; // Exit the loop when DNS resolution fails

        int next = state + ip[0] | (ip[1] << 8) | (ip[2] << 16) | (ip[3] << 24);
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, input, strlen(input));
        u_char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &ctx);

        // Perform further processing on the digest here if needed

        pthread_mutex_unlock(&new_list->mutex);
    }

    pthread_exit((error_t *)&(!err)); // Return an error code indicating whether DNS resolution failed
}
