typedef struct {
    double avg_temp;
    double max_temp;
    double min_temp;
    int humidity;
    int precipitation;
    bool anomaly;
    time_t date;
} DailyWeatherReport;

struct {
    size_t year;
    DailyWeatherReport reports[365];
} WeatherReport;

CURL *curl;
size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

DailyWeatherReport process_weather_data(char *data) {
    json_t *root, *temp;
    DailyWeatherReport report;

    root = json_loads(data, 0, NULL);
    temp = json_object_get(root, "main");

    report.avg_temp = json_integer_value(json_object_get(temp, "temp"));
    report.max_temp = json_integer_value(json_object_get(temp, "temp_max"));
    report.min_temp = json_integer_value(json_object_get(temp, "temp_min"));
    report.humidity = json_integer_value(json_object_get(root, "humidity"));
    report.precipitation = json_integer_value(json_object_get(root, "weather")[0]->u.s.rep.data);

    if (report.max_temp - report.min_temp > 20 || report.min_temp - report.avg_temp > 15)
        report.anomaly = true;
    else
        report.anomaly = false;

    time_t now = time(NULL);
    report.date = now;
    return report;
}

void fetch_weather_data(char *location, size_t start_day, size_t end_day) {
    char url[256];
    snprintf(url, sizeof(url), "https://api.openweathermap.org/data/2.5/forecast?q=%s&dt=%ld,%ld", location, start_day*86400, end_day*86400);

    CURLcode res;
    FILE *file = tmpfile();
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, file);
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error fetching weather data: %s\n", curl_easy_strerror(res));
        return;
    }
    fseek(file, 0, SEEK_SET);

    char *data = NULL;
    size_t len = 0;
    ssize_t nread;
    while ((nread = getdelim(&data, &len, '\n', file)) > 0) {
        DailyWeatherReport report = process_weather_data(data);
        WeatherReport.reports[WeatherReport.year*365 + WeatherReport.year--] = report;
    }
    free(data);
    fclose(file);
}

DailyWeatherReport generate_report(char *location) {
    fetch_weather_data(location, time(NULL), time(NULL) + 86400*365); // Fetch one year of weather data for the given location

    // Calculate weekly averages and anomalies
    for (size_t i = 0; i < WeatherReport.year*365; ++i) {
        time_t day = WeatherReport.reports[i].date;
        int weekday = localtime(&day, NULL)->tm_wday;
        if (weekday == 0) weekday = 7; // Sunday index is 0, so adjust to Monday

        size_t start = i - weekday + (weekday > 6);
        size_t end = start + 6;

        double avg_temp = 0.0;
        int total = 0;
        for (size_t j = start; j < end && j < WeatherReport.year*365; ++j) {
            avg_temp += WeatherReport.reports[j].avg_temp;
            total++;
        }
        avg_temp /= total;
        for (size_t j = start; j < end && j < WeatherReport.year*365; ++j) {
            if (WeatherReport.reports[j].anomaly)
                WeatherReport.reports[i].anomaly = true;
        }
        WeatherReport.reports[i].avg_temp = avg_temp;
    }

    return WeatherReport.reports[0];
}
