import os
import sys
import hashlib
import concurrent.futures
import logging
from threading import Event

class FileHasher:
    def __init__(self, max_memory=1024 * 1024 * 64, num_threads=os.cpu_count(), log_level=logging.INFO):
        self.max_memory = max_memory
        self.num_threads = num_threads
        self.log = logging.getLogger(__name__)
        self.log.setLevel(log_level)
        self.cancel_event = Event()

    def _hasher(self, file_path):
        hash_obj = hashlib.md5()
        with open(file_path, 'rb') as f:
            chunk_size = 8 * 1024 * 1024  # 8 MB chunks for large files
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hash_obj.update(data)
                self._track_memory()
        return hash_obj.hexdigest()

    def _track_memory(self):
        current_memory = sum([os.path.getsize(f) for f in os.listdir('/path/to/your/cache') if os.path.isfile(os.path.join('/path/to/your/cache', f))])
        if current_memory > self.max_memory:
            self.log.warning(f"Memory usage exceeded, consider increasing cache size.")

    def _modify_list(self, lst, find_str, insert_str):
        for i, item in enumerate(lst):
            if item == find_str:
                lst[i + 1] = insert_str
                break
        else:
            lst.append(insert_str)

    def _hash_files(self, file_paths, use_threads=True, log_details=False):
        if not use_threads:
            for file_path in file_paths:
                self._hasher(file_path)
        else:
            with concurrent.futures.ThreadPoolExecutor(max_workers=self.num_threads) as executor:
                future_to_file = {executor.submit(self._hasher, file_path): file_path for file_path in file_paths}
                for future in concurrent.futures.as_completed(future_to_file):
                    file_path = future_to_file[future]
                    digest = future.result()
                    self.log.info(f"{digest} - {file_path}")
                    if self.cancel_event.is_set():
                        self.cancel_event.clear()
                        break

    def hash_files(self, file_paths, use_threads=True, log_details=False):
        try:
            self._hash_files(file_paths, use_threads, log_details)
        except KeyboardInterrupt:
            self.cancel_event.set()
            self._hash_files([self.cancel_event.wait(timeout=10) for _ in file_paths], False, log_details)

    def integrate_cpp_function(self):
        # C++ component integration code goes here
        pass

if __name__ == "__main__":
    hasher = FileHasher()
    hasher.hash_files(['file1.txt', 'file2.txt'], use_threads=True, log_details=True)
