static ResourceBundle* load_bundle(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    size_t capacity = 8;
    ResourceItem **items = malloc(capacity * sizeof(ResourceItem*));
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    bundle->items = items;
    bundle->capacity = capacity;
    bundle->count = 0;
    bundle->lock = PTHREAD_MUTEX_INITIALIZER;

    char line[4096];
    size_t bytes_read = fread(line, sizeof(char), sizeof(line), file);
    while (bytes_read > 0) {
        if (bundle->count == bundle->capacity) {
            capacity *= 2;
            items = realloc(items, capacity * sizeof(ResourceItem*));
            bundle->items = items;
        }

        ResourceItem *item = &items[bundle->count];
        item->data = malloc(bytes_read);
        item->length = bytes_read;
        memcpy(item->data, line, bytes_read);

        if (parse_resource(item, line)) {
            free(item->data);
            free(item);
            bundle->count--;
            continue;
        }

        bundle->count++;

        bytes_read = fread(line, sizeof(char), sizeof(line), file);
