typedef struct {
    int bits_per_sample;
    int sample_per_pixel;
    int photometric_interpretation;
    int strip_offsets;
    int extra_samples;
    AES_KEY cipher;
} ImageMetadata;

ImageMetadata parse_tiff_image(const char *filename, const char *filter, int *extra_samples) {
    TIFF *tif = TIFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Cannot open file %s\n", filename);
        exit(1);
    }

    ImageMetadata metadata;
    if (TIFDestinator(tif, &metadata.bits_per_sample, &metadata.sample_per_pixel, NULL) != 1) {
        fprintf(stderr, "Error: TIFF header is malformed or unsupported\n");
        exit(1);
    }

    if (metadata.bits_per_sample != 1 && metadata.bits_per_sample != 2 &&
        metadata.bits_per_sample != 4 && metadata.bits_per_sample != 8 &&
        metadata.bits_per_sample != 16) {
        fprintf(stderr, "Error: Unsupported bits per sample: %d\n", metadata.bits_per_sample);
        exit(1);
    }

    if (TIFFGetField(tif, TIFFTagSAMPLESPERPIXEL) != metadata.sample_per_pixel) {
        fprintf(stderr, "Error: Incorrect sample per pixel value\n");
        exit(1);
    }

    metadata.photometric_interpretation = TIFFGetField(tif, TIFFTagPHOTOMETRICINTERPRETATION);
    metadata.strip_offsets = TIFFGetField(tif, TIFFTagStripOffsets);

