struct state* processFSATransitions(FSA* fsa, struct state** current_states, size_t num_current_states, int last_state_id) {
    struct thread_data *threads = malloc(max_threads * sizeof(struct thread_data));
    if (!threads) return NULL;

    for (size_t i = 0; i < num_current_states; ++i) {
        threads[i].current_states = current_states + i;
        threads[i].num_current_states = num_current_states;
        threads[i].fsa = fsa;
        threads[i].last_state_id = last_state_id;
    }

    active_threads = 0;

    for (size_t i = 0; i < num_current_states; ++i) {
        pthread_mutex_lock(&mutex);
        while (active_threads >= max_threads && !feof(stdin)) {
            pthread_cond_wait(&cond, &mutex);
        }

        if (active_threads < max_threads) {
            threads[i].input[0] = '\0';
            strncat((char*)&threads[i].input, ((struct state*)current_states[i])->input, sizeof(threads[i].input) - 1);
            pthread_create(&threads[i].thread_id, NULL, dns_lookup, &threads[i]);
            active_threads++;
            pthread_mutex_unlock(&mutex);
        } else {
            free(threads);
            return NULL; // Insufficient memory available.
        }
    }

    // Process the remaining threads and update the FSA's state list when all threads are done.

    struct state* new_states = malloc((num_current_states + active_threads) * sizeof(struct state));
    if (!new_states) {
        free(threads);
        return NULL; // Insufficient memory available.
    }

    for (size_t i = 0; i < num_current_states + active_threads; ++i) {
        new_states[i].id = -1;
    }

    pthread_mutex_lock(&mutex);
    while (active_threads > 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    pthread_mutex_unlock(&mutex);

    update_states(fsa, new_states, num_current_states + active_threads);

    free(threads);
    return new_states;
}
