const char VOWELS[] = "aeiouAEIOU";
const int SPECIAL_CHAR_COUNT = 4; // Length of special character sequence "@#$"
const int MAX_EXTENSION_LENGTH = 7; // Includes the special characters and possible digit extension

// Helper function to count vowels in a string
int count_vowels(char *str) {
    int count = 0;
    for (size_t i = 0; str[i]; ++i)
        if (strchr(VOWELS, str[i])) count++;
    return count;
}

// Function to modify filename based on given constraints
char *modify_filename(char *filename) {
    // Truncate the filename if it exceeds 80 characters
    if (strlen(filename) > 80)
        strncpy(filename, filename, 75);

    // Count vowels and prepare new extension length
    int vowel_count = count_vowels(filename);
    int extension_length = (vowel_count + MAX_EXTENSION_LENGTH - 1) / MAX_EXTENSION_LENGTH;

    // Check if the truncated filename is too long after appending the new extension
    if ((strlen(filename) + extension_length + SPECIAL_CHAR_COUNT > 80)) {
        fprintf(stderr, "Error: The resulting filename is too long.\n");
        return NULL;
    }

    // Prepend "file_" to the filename if it starts with a number
    bool start_with_number = false;
    for (size_t i = 0; filename[i]; ++i) {
        if (isdigit(filename[i])) {
            start_with_number = true;
            break;
        }
    }
    if (start_with_number)
        strcat(filename, "_file");

    // Append special character sequence to the new extension
    char *extension = malloc(extension_length + SPECIAL_CHAR_COUNT);
    snprintf(extension, extension_length + SPECIAL_CHAR_COUNT, "@#$%.*s",
             extension_length - 1, "@#$");

    // Count additional digits if the filename contains more than 5 special characters
    int extra_digits = 0;
    for (size_t i = 0; filename[i]; ++i) {
        if (i != strlen(filename) - 1 && isalnum(filename[i]) && is_special_char(filename[i + 1]))
            extra_digits++;
    }
    extension[extension_length + SPECIAL_CHAR_COUNT - 1] += extra_digits;

    // Append additional digits if required
    if (extra_digits) {
        snprintf(extension + extension_length, MAX_EXTENSION_LENGTH, "%d", extra_digits);
        extension[extension_length + SPECIAL_CHAR_COUNT] = '\0';
    }

    // Append the new extension to the filename
    strcat(filename, extension);

    // Remove leading and trailing spaces from the resulting filename
    char *result = malloc(strlen(filename) + 1);
    int i = 0, j = 0;
    for (size_t k = 0; filename[k]; ++k) {
        if (!isspace(filename[k])) {
            result[i++] = filename[k];
        }
    }
    result[i] = '\0';

    return result;
}

// Helper function to check if a character is a special character
bool is_special_char(char c) {
    for (int i = 0; i < SPECIAL_CHAR_COUNT; ++i)
        if (c == "@"[i] || c == "#"[i] || c == "$"[i]) return true;
    return false;
}

// Unit tests
void test_modify_filename() {
    char *test_filenames[] = {
        "test.txt", "1test.txt", "test@#$$.txt", "test123.txt", "test_vowel.txt"
    };
    char **results = malloc(sizeof(char*) * sizeof(test_filenames) / sizeof(char*));
    for (size_t i = 0; i < sizeof(test_filenames) / sizeof(char*); ++i) {
        results[i] = modify_filename(test_filenames[i]);
        printf("Expected: %s\n", test_filenames[(i + 1) % sizeof(test_filenames)]);
        printf("Result:   %s\n\n", results[i]);
    }
}
