['```csharp
using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Threading;
using System.Collections.Concurrent;

namespace Base64Decryption
{
    public class TripleDES Decrypter
    {
        private byte[] _key;
        private byte[] _iv;

        public TripleDESDecrypter(byte[] key, byte[] iv)
        {
            _key = key;
            _iv = iv;
        }

        private TripleDESCryptoServiceProvider CreateTripleDESInstance()
        {
            var tripleDes = new TripleDESCryptoServiceProvider();
            tripleDes.Key = _key;
            tripleDes.IV = _iv;
            return tripleDes;
        }

        public string Decrypt(string base64EncodedMessage)
        {
            try
            {
                using (var cryptoTransform = CreateTripleDESInstance().CreateDecryptor())
                {
                    byte[] decryptedData;
                    using (var memoryStream = new MemoryStream(Convert.FromBase64String(base64EncodedMessage)))
                    using (var cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Read))
                        decryptedData = cryptoStream.ToArray();

                    return Encoding.UTF8.GetString(decryptedData);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error while decrypting message: {ex.Message}");
                return string.Empty;
            }
        }
    }

    public class MessageProcessor
    {
        private ConcurrentQueue<string> _messageQueue = new ConcurrentQueue<string>();
        private ConcurrentBag<TripleDESDecrypter> _decryptorPool = new ConcurrentBag<TripleDESDecrypter>();
        private int _maxPoolSize;

        public MessageProcessor(int maxPoolSize, byte[] key, byte[] iv)
        {
            _maxPoolSize = maxPoolSize;
            for (int i = 0; i < _maxPoolSize; i++)
                _decryptorPool.Add(new TripleDESDecrypter(key, iv));
        }

        public void EnqueueMessage(string base64EncodedMessage) => _messageQueue.Enqueue(base64EncodedMessage);

        public string DequeueAndProcessMessage()
        {
            if (_messageQueue.IsEmpty) return string.Empty;

            string base64EncodedMessage;
            _messageQueue.TryDequeue(out base64EncodedMessage);

            var decryptor = _decryptorPool.FirstOrDefault();
            if (decryptor == null)
                decryptor = new TripleDESDecrypter(key: _decryptorPool.First().Key, iv: _decryptorPool.First().IV);

            var plainTextMessage = decryptor.Decrypt(base64EncodedMessage);
            return plainTextMessage;
        }
    }
}
```
In this solution, we have two classes `TripleDESDecrypter` and `MessageProcessor`. The `TripleDESDecrypter` class is responsible for decrypting the Base64-encoded messages using Triple DES with a given key and initialization vector (IV). It also logs any errors that occur during the decryption process.

The `MessageProcessor` class manages the concurrent processing of multiple messages received from an external API endpoint. It stores the messages in a `ConcurrentQueue<string>`, which allows for efficient concurrent access. Additionally, it maintains a pool of `TripleDESDecrypter` instances using a `ConcurrentBag<TripleDESDecrypter>`. When dequeuing a message, if there are no available decryptors in the pool, a new one is created with the same key and IV as the first instance in the pool. This ensures consistent behavior across threads and helps manage potential synchronization issues.

Finally, when you need to process messages concurrently, call `EnqueueMessage(string base64EncodedMessage)` to add a new message to the queue, then use `DequeueAndProcessMessage()` to retrieve and decrypt a message from the queue while ensuring proper thread safety. This solution is scalable and optimized for performance with efficient memory usage when processing large volumes of messages concurrently.']

