#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

#define AES_BLOCK_SIZE 16
#define KEY_STRETCH_ITERATIONS 100000
#define KEY_LENGTH 32

static void aes_cleanup(AES_KEY *aes) {
    memset(aes->rd_key, 0, AES_BLOCK_SIZE);
    AES_free_key(aes);
}

AES_KEY* aes_init(const char *passphrase) {
    unsigned char key[KEY_LENGTH];
    unsigned char salt[SHA256_DIGEST_LENGTH];

    // Generate random salt for key derivation
    if (RAND_bytes(salt, sizeof(salt)) <= 0) {
        fprintf(stderr, "Failed to generate salt: %s\n", strerror(errno));
        return NULL;
    }

    // Derive a key from passphrase using PKCS#5/PBKDF2 with HMAC-SHA-256
    if (PKCS5_PBKDF2_HMAC((const unsigned char *)passphrase, strlen(passphrase), salt, sizeof(salt), KEY_STRETCH_ITERATIONS, SHA256_DIGEST_SIZE, key)) {
        fprintf(stderr, "Failed to derive key: %s\n", strerror(errno));
        return NULL;
    }

    AES_KEY aes;
    memset(&aes, 0, sizeof(AES_KEY));

    // Initialize AES-256-CBC context using the derived key
    if (AES_set_encrypt_key((const unsigned char *)key, 256, &aes) != 1) {
        fprintf(stderr, "Failed to initialize AES context: %s\n", strerror(errno));
        return NULL;
    }

    // Set initial vector (IV) to a random value to ensure CBC-mode encryption is secure
    if (RAND_bytes(aes.iv, AES_BLOCK_SIZE) <= 0) {
        fprintf(stderr, "Failed to generate IV: %s\n", strerror(errno));
        aes_cleanup(&aes);
        return NULL;
    }

    return &aes;
}
```

