#include <iostream>
#include <map>
#include <vector>
#include <chrono>
#include <ctime>
#include <sstream>
#include <fstream>
#include <memory>

enum class LogLevel { DEBUG, INFO, WARNING, ERROR };
struct LogEntry {
    LogLevel level;
    std::time_t timestamp;
    std::string message;

    friend std::ostream& operator<<(std::ostream& os, const LogEntry& le) {
        auto t = *std::localtime(&le.timestamp);
        std::stringstream ss;
        ss << t.tm_year + 1900 << '-' << t.tm_mon + 1 << '-' << t.tm_mday << ' '
          << t.tm_hour << ':' << t.tm_min << ':' << t.tm_sec << ' ' << static_cast<int>(le.level)
          << ": " << le.message;
        return os << ss.str();
    }
};

class LogManager {
public:
    explicit LogManager(size_t maxSize) : m_maxSize(maxSize) {}

    void insert(const LogLevel& level, std::time_t timestamp, const std::string& message) {
        auto it = m_entries.emplace(std::make_pair(level, std::vector<LogEntry>{}).second);
        it->second.push_back({ level, timestamp, message });
        prune();
    }

    const LogEntry* find(const LogLevel& level, std::time_t timestamp) {
        auto it = m_entries.find(level);
        if (it == m_entries.end()) return nullptr;

        for (const auto& le : it->second) {
            if (le.timestamp == timestamp) return &le;
        }
        return nullptr;
    }

    void remove(const LogEntry& entry) {
        for (auto& [level, logs] : m_entries) {
            auto it = std::find(logs.begin(), logs.end(), entry);
            if (it != logs.end()) {
                logs.erase(it);
                break;
            }
        }
    }

    void prune() {
        size_t count = 0;
        for (auto& [_, logs] : m_entries) {
            logs.erase(std::remove_if(logs.begin(), logs.end(),
                [](const LogEntry& entry) {
                    auto now = std::time(nullptr);
                    return now - entry.timestamp > 24 * 60 * 60; // Remove entries older than 1 day
                }), logs.end());
            if (logs.size() > m_maxSize) {
                logs.erase(logs.begin(), logs.begin() + (logs.size() - m_maxSize));
            }
            count += logs.size();
        }
    }

    void serialize(const std::string& filename) const {
        std::ofstream outfile(filename);
        for (const auto& [level, logs] : m_entries) {
            for (const auto& le : logs) {
                outfile << le << '\n';
            }
        }
    }

    void deserialize(const std::string& filename) {
        std::ifstream infile(filename);
        while (infile.good()) {
            LogEntry entry;
            infile >> entry;
            insert(entry.level, entry.timestamp, entry.message);
        }
    }

private:
    size_t m_maxSize;
    std::multimap<LogLevel, std::vector<LogEntry>> m_entries;
};
```
