    size_t num_transitions;
    int **transitions;
    u_char *ip_addr;
    char *state_name;
};

typedef struct state_list {
    struct FSA *fsa;
    int *current_states;
    int last_state;
    struct state_list *next;
} StateList;

void thread_func(StateList **state_lists, pthread_t *tid) {
    MD5_CTX ctx;
    u_char digest[MD5_DIGEST_LENGTH];
    char input[256];
    struct hostent *host;
    int i, j;

    while (1) {
        for (i = 0; i < state_lists[*tid]->current_states[state_lists[*tid]->last_state]; ++i) {
            if (DNS_query(state_lists[*tid]->fsa->ip_addr, state_lists[*tid]->fsa->state_name[state_lists[*tid]->current_states[i]], input, sizeof(input)) == 0) {
                if (MD5((u_char *)input, strlen(input), digest) != NULL) {
                    // Process the MD5 hash here...
                }
            }
        }

        // Sleep for a short period to avoid DNS queries per second limit.
        usleep(100000);
    }
}

StateList *processFSATransitions(int **current_states, size_t num_states, struct FSA *fsa, int last_state) {
    StateList *head = NULL, *tail = NULL;
    pthread_t threads[10];
    sem_t mem_sem, dns_sem;
    size_t mem_used = 0;
    struct timeval tv;

    sem_init(&mem_sem, 0, 10);
    sem_init(&dns_sem, 0, num_states > 10 ? num_states : 10);

    for (size_t i = 0; i < num_states; ++i) {
        if (current_states[last_state][i] != -1 && mem_used + sizeof(StateList) + fsa->states * sizeof(int) <= 1048576) { // 1 MB
            StateList *new_state = malloc(sizeof(StateList));
            new_state->fsa = fsa;
            new_state->current_states = malloc((fsa->states + 1) * sizeof(int));
            new_state->next = NULL;

            for (size_t j = 0; j < fsa->states; ++j) {
                new_state->current_states[j] = current_states[j][i];
            }

            new_state->current_states[fsa->states] = i;
            sem_wait(&mem_sem);
            mem_used += sizeof(StateList) + fsa->states * sizeof(int);

            if (pthread_create(&threads[tail ? tail->id : 0], NULL, thread_func, &new_state) != 0) {
                free(new_state->current_states);
                free(new_state);
                sem_post(&mem_sem);
                return NULL;
            }

            if (tail) {
                tail->next = new_state;
                tail = new_state;
            } else {
                head = tail = new_state;
            }
        }
    }

    sem_destroy(&mem_sem);
    sem_destroy(&dns_sem);

    return head;
}
