int validate_oauth2_access_token(const char *json) {
    json_t *root, *token_type, *expires_in, *access_token;
    int ret = 1;

    root = json_loads(json, 0, NULL);
    if (!root) return 0;

    token_type = json_object_get(root, "token_type");
    expires_in = json_object_get(root, "expires_in");
    access_token = json_object_get(root, "access_token");

    if (!json_is_string(token_type) || strcmp("Bearer", json_string_value(token_type)) != 0) {
        ret = 0;
    } else if (!json_is_integer(expires_in) || json_integer_value(expires_in) <= 0 || json_integer_value(expires_in) > 7200) {
        ret = 0;
    } else if (access_token == NULL) {
        ret = 0;
    }

    json_decref(root);
    return ret;
