  2. JavaScript Function (Biblical Entity Extraction)

```javascript
const regex = /(\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1\sSamuel|2\sSamuel|1\sKings|2\sKings|1\sChronicles|2\sChronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b|\b(\d{1,3}:\s*\d{1,5})\b)/gi;

function extractBiblicalEntities(text) {
    const matches = text.match(regex);
    if (!matches) return [];

    const entities = {};
    for (const match of matches) {
        const book = match.split(/\s+/)[0];
        let chapterVerse;
        if (book === 'Ezra' || book === 'Nehemiah') {
            // Handle books with split chapters and verses
            chapterVerse = match.match(/\d{1,3}/g);
            if (!chapterVerse) continue;
            chapterVerse = chapterVerse[0];
        } else {
            chapterVerse = match.split(':')[1];
        }
        const verseNumbers = chapterVerse.split(/[\s,.]/).map(Number);
        if (entities[book]) {
            entities[book].push(...verseNumbers);
        } else {
            entities[book] = verseNumbers;
        }
    }
    return Object.values(entities);
}
