                    System.out.println("File is not readable: " + filePath);
                    continue;
                }
            } catch (FileNotFoundException e) {
                System.out.println("File is not readable: " + filePath);
                continue;
            }

            accessibleFiles.put(filePath, true);
        }

        return accessibleFiles;
    }
