    if (!root || !json_is_object(root)) {
        return false;
    }

    bool has_access_token = false, has_expires_in = false, has_token_type = false, has_refresh_token = false;
    std::regex refresh_token_pattern("^[a-zA-Z0-9_-]{1,128}$");

    for (json_object_iter iter = json_objects(root); iter.has_next(); ) {
        const char* key = json_object_iter_keyv(iter.next());
        json_t *value = json_object_get(root, key);

        if (!strcmp(key, "access_token")) {
            if (json_is_string(value) && strlen((const char*)json_string_value(value)) <= 256) {
                has_access_token = true;
            } else {
                return false;
            }
        } else if (!strcmp(key, "expires_in")) {
            if (json_is_number(value) && json_integer_value(value) >= 0 && json_integer_value(value) < 3600) {
                has_expires_in = true;
            } else {
                return false;
            }
        } else if (!strcmp(key, "token_type")) {
            if (json_is_string(value) && !strcmp((const char*)json_string_value(value), "Bearer")) {
                has_token_type = true;
            } else {
                return false;
            }
        } else if (!strcmp(key, "refresh_token")) {
            if (json_is_string(value) && std::regex_match((const char*)json_string_value(value), refresh_token_pattern)) {
                has_refresh_token = true;
            }
        }
    }

    return has_access_token && has_expires_in && has_token_type && (has_refresh_token || !strcmp(key, "refresh_token"));
}

void generate_key(const char* password, unsigned char key[AES_BLOCK_SIZE]) {
    // Key derivation using SHA-256 with a PBKDF2-HMAC implementation
    constexpr size_t iterations = 100000;
    constexpr size_t salt_size = AES_BLOCK_SIZE;
    unsigned char salt[salt_size];
    RAND_bytes(salt, salt_size);

    unsigned char hash[SHA256_DIGEST_LENGTH];
    for (size_t i = 0; i < iterations; ++i) {
        // Combine password, salt and iteration number into a single block
        unsigned char data[salt_size + 1 + sizeof(unsigned int)];
        memcpy(data, password, strlen(password));
        memcpy(data + strlen(password), salt, salt_size);
        *(uint32_t*)(data + salt_size) = i;

        SHA256((const unsigned char*)data, sizeof(data), hash);
    }

    // Copy the final hash into the key array, taking the first AES_BLOCK_SIZE bytes
    memcpy(key, hash, AES_BLOCK_SIZE);
}

void clean_up() {
    // Disable cipher and release resources
}

