#include <boost/date_time/posix_time/ptime.hpp>
#include <boost/filesystem.hpp>
#include <boost/circular_buffer.hpp>

namespace fs = boost::filesystem;

struct AuditEvent {
    std::string type;
    boost::posix_time::ptime timestamp;
    int userID;
    std::string ipAddress;
    std::string message;

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int) {
        ar & type & timestamp & userID & ipAddress & message;
    }
};

class AuditEventManager {
private:
    std::unordered_map<std::tuple<std::string, boost::posix_time::ptime, int>, std::unique_ptr<AuditEvent>> events;
    std::unordered_map<int, boost::circular_buffer<std::unique_ptr<AuditEvent>>> userEvents; // Cache for frequently accessed user events
    mutable std::mutex mtx;
    std::atomic<size_t> maxSize{10000};
    size_t currentSize = 0;
    bool offlineMode = false;
    bool syncing = false;
    std::condition_variable cv;
    std::thread syncThread;

public:
    AuditEventManager() {}

    void setMaxSize(size_t size) { maxSize = size; }

    void push(const AuditEvent & event) {
        std::lock_guard<std::mutex> lock(mtx);
        if (currentSize + 1 > maxSize) {
            // Prune the collection to maintain the maximum size.
            auto it = events.begin();
            while (currentSize > maxSize && it != events.end()) {
                currentSize--;
                it = events.erase(it);
            }
        }
        currentSize++;
        events[{event.type, event.timestamp, event.userID}] = std::unique_ptr<AuditEvent>(new AuditEvent(event));
        userEvents[event.userID].push_back(std::move(events[{event.type, event.timestamp, event.userID}]));
    }

    void search(const std::string & type, const boost::posix_time::ptime & timestamp, int userID, std::function<void(const AuditEvent&)> callback) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, type, timestamp, userID](){
            if (!offlineMode && !syncing) {
                // If the system is online and not syncing, check for events directly.
                auto it = events.find({type, timestamp, userID});
                return it != events.end();
            } else {
                // Otherwise, check the user cache.
                const auto& userBuffer = userEvents[userID];
                for (const auto& event : userBuffer) {
                    if (event->type == type && event->timestamp == timestamp && event->userID == userID) {
                        lock.unlock();
                        callback(*event);
                        return true;
                    }
                }
                return false;
            }
        });

        // If the event was not found in the cache, search the complete collection.
        auto it = events.find({type, timestamp, userID});
        if (it != events.end()) {
            callback(*it->second.get());
        }
    }

    void deleteEvent(const AuditEvent & event) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = events.find({event.type, event.timestamp, event.userID});
        if (it != events.end()) {
            currentSize--;
            events.erase(it);

            // Remove from the user cache as well.
            userEvents[event.userID].remove_if([&](const std::unique_ptr<AuditEvent>& e) { return *e == event; });
        }
    }

    void setOfflineMode(bool state) { offlineMode = state; }
    bool isOfflineMode() const { return offlineMode; }

    void startSyncThread() {
        syncThread = std::thread([this](){
            // Implement periodic synchronization with the external logging service here.
        });
    }

    void stopSyncThread() {
        if (syncThread.joinable()) {
            syncing = true;
            cv.notify_all();
            syncThread.join();
        }
    }
};
```

