#include <boost/serialization/vector.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>
#include <boost/functional/hash.hpp>
#include <boost/scoped_ptr.hpp>

struct LogEntry {
    enum class Level { DEBUG, INFO, WARNING, ERROR };
    std::time_t timestamp;
    Level logLevel;
    std::string message;

    friend class boost::serialization::access;

    template<class Archive> void serialize(Archive& ar, const unsigned int version) {
        ar & timestamp & logLevel & message;
    }
};

class LogManager {
private:
    struct Hash {
        std::size_t operator()(const LogEntry& le) const noexcept {
            auto h1 = boost::hash<std::time_t>{}(le.timestamp);
            auto h2 = boost::hash<int>{}(static_cast<int>(le.logLevel));
            return h1 ^ (h2 << 1);
        }
    };

    std::mutex mtx;
    std::vector<LogEntry> logs;
    size_t maxSize;
    std::map<std::pair<size_t, std::time_t>, size_t, Hash> pruneCounter;
    size_t memoryUsage;
    std::ofstream consoleLogFile;
    std::ofstream fileLogFile;
    int verbosityLevel;

public:
    LogManager(size_t maxSize_, const std::string& consoleLogFilePath, const std::string& fileLogFilePath, int verbosityLevel_)
        : maxSize(maxSize_), consoleLogFile(consoleLogFilePath, std::ios_base::out | std::ios_base::trunc),
          fileLogFile(fileLogFilePath, std::ios_base::out | std::ios_base::app), verbosityLevel(verbosityLevel_) {}

    void insert(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mtx);
        logs.push_back(entry);
        if (logs.size() > maxSize) {
            prune();
        }
    }

    const LogEntry* find(const LogEntry& entry) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(logs.begin(), logs.end(), [&entry](const LogEntry& e) { return e == entry; });
        if (it != logs.end()) {
            ++pruneCounter[{static_cast<size_t>(entry.logLevel), entry.timestamp}];
            return &*it;
        }
        return nullptr;
    }

    void remove(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(logs.begin(), logs.end(), [&entry](const LogEntry& e) { return e == entry; });
        if (it != logs.end()) {
            logs.erase(it);
            --memoryUsage += sizeof(LogEntry);
            pruneCounter[{static_cast<size_t>(entry.logLevel), entry.timestamp}]--;
            if (pruneCounter[{static_cast<size_t>(entry.logLevel), entry.timestamp}] <= 0) {
                pruneCounter.erase({static_cast<size_t>(entry.logLevel), entry.timestamp});
            }
        }
    }

    void prune() {
        if (logs.size() > maxSize) {
            std::nth_element(logs.begin(), logs.begin() + maxSize, logs.end(), [](const LogEntry& a, const LogEntry& b) {
                return a.timestamp < b.timestamp;
            });
            logs.erase(logs.end() - (logs.size() - maxSize), logs.end());
        }
    }

    void saveToDisk(const std::string& filePath) const {
        boost::scoped_ptr<std::ofstream> oa(new std::ofstream(filePath, std::ios_base::out | std::ios_base::trunc));
        boost::archive::text_oarchive oarch(*oa);
        oarch << logs;
    }

    void loadFromDisk(const std::string& filePath) {
        boost::scoped_ptr<std::ifstream> ia(new std::ifstream(filePath));
        boost::archive::text_iarchive iarch(*ia);
        ia->exceptions(std::ios_base::badbit); // Throw exceptions for errors
        iarch >> logs;
    }

    void log(const LogEntry& entry) {
        if (verbosityLevel <= static_cast<int>(entry.logLevel)) {
            std::lock_guard<std::mutex> lockConsole(consoleLogFile.mutex());
            consoleLogFile << "[" << entry.logLevel << "] " << entry.timestamp << ": " << entry.message << "\n";
            if (fileLogFile.is_open()) {
                std::lock_guard<std::mutex> lockFile(fileLogFile.mutex());
                fileLogFile << "[" << entry.logLevel << "] " << entry.timestamp << ": " << entry.message << "\n";
            }
        }
    }

    void setVerbosityLevel(int newVerbosityLevel) {
        verbosityLevel = newVerbosityLevel;
    }

    int getVerbosityLevel() const {
        return verbosityLevel;
    }
};
