#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct FrameMetrics {
    time_t timestamp;
    int signalStrength;
    char* rsi; // Variable-length data field representing received signal indicators (RSI)
    enum SignalQualityLevel qualityLevel;
    int channelFrequency;
} FrameMetrics;

struct BufferContext {
    FrameMetrics* buffer;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t notFull, notEmpty;
};

void initBuffer(struct BufferContext*, int);
void freeBuffer(struct BufferContext*);
FrameMetrics* getNewFrameMetrics();
int compareFrameMetricsByTimestamp(const void*, const void*);

void enqueue(struct BufferContext*, FrameMetrics*);
FrameMetrics* dequeue(struct BufferContext*);
FrameMetrics* findEntryByTimestamp(struct BufferContext*, time_t);

void pruneBuffer(struct BufferContext*);
void* threadRunner(void* arg);

// Mocking library initialization and reset
extern void blueslip_init();
extern void blueslip_reset();

void runTestWithConcurrency(const char* label, int bufferSize, int maxConcurrency, void(*f)(struct BufferContext*)) {
    struct BufferContext buffer;
    initBuffer(&buffer, bufferSize);
    blueslip_init();

    pthread_t threads[maxConcurrency];
    for (int i = 0; i < maxConcurrency; ++i) {
        int rc = pthread_create(&threads[i], NULL, &threadRunner, &buffer);
        if (rc) {
            printf("Error: Unable to create thread %d\n", i);
            freeBuffer(&buffer);
            blueslip_reset();
            return;
        }
    }

    for (int i = 0; i < maxConcurrency; ++i) {
        pthread_join(threads[i], NULL);
    }

    f(&buffer); // Run the test function

    freeBuffer(&buffer);
    blueslip_reset();
}

void* threadRunner(void* arg) {
    struct BufferContext* buffer = (struct BufferContext*)arg;
    while (true) {
        FrameMetrics* frameMetrics = getNewFrameMetrics();
        // Perform operations with the FrameMetrics object...

        pthread_mutex_lock(&buffer->lock);
        enqueue(buffer, frameMetrics);
        pruneBuffer(buffer);
        pthread_mutex_unlock(&buffer->lock);
    }

    return NULL;
}

void initBuffer(struct BufferContext* buffer, int capacity) {
    buffer->buffer = malloc(capacity * sizeof(FrameMetrics));
    if (!buffer->buffer) {
        fprintf(stderr, "Error: Unable to allocate memory for buffer\n");
        exit(EXIT_FAILURE);
    }

    buffer->size = 0;
    buffer->capacity = capacity;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->notFull, NULL);
    pthread_cond_init(&buffer->notEmpty, NULL);
}

void freeBuffer(struct BufferContext* buffer) {
    if (buffer->buffer) {
        for (size_t i = 0; i < buffer->size; ++i) {
            free(buffer->buffer[i].rsi); // Free the RSI field of each FrameMetrics object...
        }
        free(buffer->buffer);
    }
}

FrameMetrics* getNewFrameMetrics() {
    FrameMetrics* frameMetrics = malloc(sizeof(FrameMetrics));
    if (!frameMetrics) {
        fprintf(stderr, "Error: Unable to allocate memory for new FrameMetrics\n");
        exit(EXIT_FAILURE);
    }

    frameMetrics->timestamp = time(NULL);
    frameMetrics->signalStrength = 0;
    frameMetrics->rsi = NULL; // Allocate and initialize the RSI field as needed...
    frameMetrics->qualityLevel = SIGNAL_QUALITY_UNKNOWN;
    frameMetrics->channelFrequency = 0;

    return frameMetrics;
}

int compareFrameMetricsByTimestamp(const void* a, const void* b) {
    const FrameMetrics* fa = (const FrameMetrics*)a;
    const FrameMetrics* fb = (const FrameMetrics*)b;
    return fa->timestamp - fb->timestamp;
}

void enqueue(struct BufferContext* buffer, FrameMetrics* frameMetrics) {
    pthread_mutex_lock(&buffer->lock);

    while (buffer->size == buffer->capacity && !pthread_trylock(&buffer->notFull)) {
        pthread_cond_wait(&buffer->notEmpty, &buffer->lock);
    }

    if (buffer->size < buffer->capacity) {
        memcpy(buffer->buffer + buffer->size, frameMetrics, sizeof(FrameMetrics));
        ++buffer->size;
        pthread_mutex_unlock(&buffer->lock);
        pthread_cond_signal(&buffer->notFull);
    } else {
        free(frameMetrics->rsi); // Free the RSI field of the FrameMetrics object...
        free(frameMetrics);
        pthread_mutex_unlock(&buffer->lock);
    }
}

FrameMetrics* dequeue(struct BufferContext* buffer) {
    pthread_mutex_lock(&buffer->lock);

    while (buffer->size == 0 && !pthread_trylock(&buffer->notEmpty)) {
        pthread_cond_wait(&buffer->notFull, &buffer->lock);
    }

    if (buffer->size > 0) {
        FrameMetrics* dequeued = buffer->buffer[0];
        memmove(buffer->buffer, buffer->buffer + 1, sizeof(FrameMetrics) * --buffer->size);
        pthread_mutex_unlock(&buffer->lock);
        pthread_cond_signal(&buffer->notEmpty);
        return dequeued;
    } else {
        pthread_mutex_unlock(&buffer->lock);
    }

    return NULL;
}

FrameMetrics* findEntryByTimestamp(struct BufferContext* buffer, time_t timestamp) {
    FrameMetrics* found = NULL;
    pthread_mutex_lock(&buffer->lock);

    qsort(buffer->buffer, buffer->size, sizeof(FrameMetrics), compareFrameMetricsByTimestamp);

    size_t start = 0;
    size_t end = buffer->size;
    while (start < end) {
        size_t mid = (start + end) / 2;
        if (buffer->buffer[mid].timestamp > timestamp) {
            end = mid;
        } else {
            start = mid + 1;
        }
    }

    if (start < buffer->size && buffer->buffer[start].timestamp == timestamp) {
        found = &buffer->buffer[start];
    }

    pthread_mutex_unlock(&buffer->lock);
    return found;
}

void pruneBuffer(struct BufferContext* buffer) {
    if (buffer->size >= buffer->capacity) {
        pthread_mutex_lock(&buffer->lock);
        FrameMetrics* oldest = findEntryByTimestamp(buffer, INT32_MIN);
        if (oldest) {
            free(oldest->rsi); // Free the RSI field of the FrameMetrics object...
            free(oldest);
            memmove(buffer->buffer, buffer->buffer + 1, sizeof(FrameMetrics) * --buffer->size);
        }
        pthread_mutex_unlock(&buffer->lock);
    }
}
