import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ConcurrentModificationException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.concurrent.locks.ReentrantLock;

public class ResourceManager {
    private final Map<String, PriorityQueue<ResourceRequest>> resourceRequests;
    private final ReentrantLock lock = new ReentrantLock();
    private static final int MAX_UTILIZATION = 90;
    private static final String DISTRIBUTED_STORAGE_SYSTEM_URL = "distributed://storage-system";

    public ResourceManager() {
        resourceRequests = new LinkedHashMap<>();
    }

    // Utility method to calculate MD5 hash of a given string
    public String md5(String text) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] result = digest.digest(text.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : result) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error calculating MD5 hash", e);
        }
    }

    // Insert a ResourceRequest into the collection
    public void insertResourceRequest(String resourceType, String description, Priority priority, long timestamp, String requestId) {
        lock.lock();
        try {
            if (!resourceRequests.containsKey(resourceType)) {
                resourceRequests.put(resourceType, new PriorityQueue<>());
            }
            ResourceRequest request = new ResourceRequest(resourceType, description, priority, timestamp, requestId);
            resourceRequests.get(resourceType).add(request);
        } finally {
            lock.unlock();
        }
    }

    // Search for a ResourceRequest with the given ID in the collection
    public ResourceRequest findResourceRequestById(String requestId) {
        lock.lock();
        try {
            for (Map.Entry<String, PriorityQueue<ResourceRequest>> entry : resourceRequests.entrySet()) {
                for (ResourceRequest request : entry.getValue()) {
                    if (request.getRequestId().equals(requestId)) {
                        return request;
                    }
                }
            }
        } finally {
            lock.unlock();
        }
        return null;
    }

    // Delete the ResourceRequest with the highest priority and timestamp among all low-priority requests
    public void deleteResourceRequest() {
        lock.lock();
        try {
            for (Map.Entry<String, PriorityQueue<ResourceRequest>> entry : resourceRequests.entrySet()) {
                PriorityQueue<ResourceRequest> queue = entry.getValue();
                ResourceRequest lowPriorityRequest;
                while ((lowPriorityRequest = queue.peek()) != null && lowPriorityRequest.getPriority() == Priority.LOW) {
                    long currentTime = System.currentTimeMillis();
                    if (currentTime - lowPriorityRequest.getTimestamp() > 60 * 60 * 24 * 7) { // 1 week timeout
                        queue.poll();
                    } else {
                        break;
                    }
                }
                if (lowPriorityRequest != null) {
                    queue.remove(lowPriorityRequest);
                }
            }
        } finally {
            lock.unlock();
        }
    }

    // Serialize the collection and save it to the distributed storage system
    public void serialize() throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new BufferedOutputStream(new URL(DISTRIBUTED_STORAGE_SYSTEM_URL + "/ResourceManager").openStream()))){
            oos.writeObject(resourceRequests);
        } catch (Exception e) {
            throw new RuntimeException("Error serializing ResourceManager", e);
        }
    }

    // Deserialize the collection from the distributed storage system and load it into memory
    public void deserialize() throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new BufferedInputStream(new URL(DISTRIBUTED_STORAGE_SYSTEM_URL + "/ResourceManager").openStream()))){
            resourceRequests = (LinkedHashMap<String, PriorityQueue<ResourceRequest>>) ois.readObject();
        } catch (Exception e) {
            throw new RuntimeException("Error deserializing ResourceManager", e);
        }
    }
}
