    atomic<bool> externalServiceAvailable{true};
    optional<third_party_logging_framework> thirdPartyLogger;
    fs::path logFile;

    void prune() {
        if (std::chrono::system_clock::now() - pruneData.lastPruneTime > std::chrono::seconds(10)) {
            auto it = logs.rbegin();
            while (logs.size() > pruneData.maxSize && it != logs.rend()) {
                it = logs.erase(it);
            }
            pruneData.lastPruneTime = std::chrono::system_clock::now();
        }
    }

public:
    LogManager(const fs::path& logFile, const PruneData& pruneData, optional<third_party_logging_framework> thirdPartyLogger)
