        std::lock_guard<mutex> lock(dataMutex);
        logs.push_back(entry);
        auto it = timestamps.find(entry.timestamp);
        if (it == timestamps.end()) {
            timestamps[entry.timestamp] = { entry };
        } else {
            it->second.push_back(entry);
        }
        logLevels[entry.logLevel].push_back(entry);
        prune();
    }

