```python
import hashlib
from concurrent.futures import ProcessPoolExecutor, as_completed

def file_hash(filePath, chunkSize=64 * 1024):
    hasher = hashlib.md5()
    with open(filePath, 'rb') as f:
        for chunk in iter(lambda: f.read(chunkSize), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_files_in_parallel(fileList, chunkSize=64 * 1024, numWorkers=os.cpu_count()):
    with ProcessPoolExecutor(max_workers=numWorkers) as executor:
        results = list(executor.map(file_hash, fileList, chunkSize))
    return results
