#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <signal.h>
#include <stdbool.h>
#include <sys/time.h>
#include "blueslip.h"
#include "logging_service.h" // External logging service API

typedef struct FrameMetrics {
    time_t timestamp;
    int signal_strength;
    size_t rsi_len;
    char *rsi;
    int signal_quality_level;
    int channel_frequency;
} FrameMetrics;

struct BufferManager {
    FrameMetrics *buffer;
    size_t bufferSize;
    size_t capacity;
    size_t length;
    sem_t lock;
    pthread_mutexattr_t mutexAttr;
    pthread_cond_t notFull, notEmpty;
    int maxConcurrency;
    bool pruningEnabled;
    time_t pruningInterval;
    struct timespec pruneTimeout;
};

void bufferManagerInit(struct BufferManager *bm, size_t bufferSize, int maxConcurrency, time_t pruningInterval) {
    // Initialize semaphore and mutex attributes
    sem_init(&bm->lock, 0, 1);
    pthread_mutexattr_init(&bm->mutexAttr);
    pthread_mutexattr_settype(&bm->mutexAttr, PTHREAD_MUTEX_RECURSIVE);

    bm->bufferSize = bufferSize;
    bm->capacity = bufferSize;
    bm->length = 0;
    bm->maxConcurrency = maxConcurrency;
    bm->pruningEnabled = pruningInterval > 0;
    bm->pruningInterval = pruningInterval;

    if (bm->pruningEnabled) {
        // Initialize prune timeout using pruning interval
        bm->pruneTimeout.tv_sec = bm->pruningInterval;
        bm->pruneTimeout.tv_nsec = 0;
    }
}

void bufferManagerDestroy(struct BufferManager *bm) {
    if (bm->buffer) free(bm->buffer);
    sem_destroy(&bm->lock);
    pthread_mutexattr_destroy(&bm->mutexAttr);
}

void bufferManagerPrune(struct BufferManager *bm) {
    // Prune the oldest entries to maintain the specified buffer size
    if (bm->length > bm->bufferSize && bm->pruningEnabled) {
        time_t currentTime = time(NULL);
        FrameMetrics *oldestEntry = NULL;
        FrameMetrics temp;

        pthread_mutex_lock(&bm->mutexAttr);
        for (size_t i = 0; i < bm->length && oldestEntry == NULL; ++i) {
            if (bm->buffer[i].timestamp < oldestEntry->timestamp || oldestEntry == NULL)
                oldestEntry = &bm->buffer[i];
        }
        pthread_mutex_unlock(&bm->mutexAttr);

        if (oldestEntry) {
            memmove(&temp, oldestEntry, sizeof(FrameMetrics));
            free(oldestEntry->rsi);
            free(oldestEntry);

            pthread_mutex_lock(&bm->mutexAttr);
            --bm->length;
            memmove(bm->buffer, bm->buffer + 1, (bm->length * sizeof(FrameMetrics)));
            pthread_mutex_unlock(&bm->mutexAttr);
        }
    }
}

void* insertEntry(void *arg, struct BufferManager *bm, FrameMetrics *entry) {
    // Insert the given entry into the buffer while handling concurrent access and pruning

    pthread_mutex_lock(&bm->mutexAttr);

    if (bm->length >= bm->capacity) {
        // Buffer is full; prune old entries and try again
        bufferManagerPrune(bm);

        if (bm->length >= bm->capacity) {
            pthread_mutex_unlock(&bm->mutexAttr);
            return NULL;
        }
    }

    memcpy(&bm->buffer[bm->length], entry, sizeof(FrameMetrics));
    ++bm->length;

    // Signal that the buffer is not empty if it was before insertion
    sem_post(&bm->notEmpty);

    pthread_mutex_unlock(&bm->mutexAttr);
    return NULL;
}

bool tryAcquire(struct BufferManager *bm) {
    // Try to acquire a lock on the buffer; return true if successful, false otherwise

    bool acquired = false;
    int ret;

    do {
        ret = sem_trywait(&bm->lock);
        if (ret > 0) acquired = true;
    } while (!acquired && ret == EBUSY);

    return acquired;
}

void* deleteEntry(void *arg, struct BufferManager *bm, time_t timestamp) {
    // Delete the entry with the given timestamp from the buffer while handling concurrent access and pruning

    FrameMetrics *target = NULL;
    int ret;

    do {
        if (!tryAcquire(bm)) {
            sem_timedwait(&bm->lock, &bm->pruneTimeout);
            continue;
        }

        pthread_mutex_lock(&bm->mutexAttr);

        for (size_t i = 0; i < bm->length && target == NULL; ++i) {
            if (bm->buffer[i].timestamp == timestamp) {
                target = &bm->buffer[i];
                memmove(bm->buffer + i, bm->buffer + i + 1, ((bm->length - i - 1) * sizeof(FrameMetrics)));
                --bm->length;
            }
        }

        pthread_mutex_unlock(&bm->mutexAttr);
        sem_post(&bm->lock);

        if (target) {
            free(target->rsi);
            free(target);
        }
    } while (target == NULL);

    return NULL;
}

FrameMetrics* retrieveEntry(struct BufferManager *bm, time_t timestamp) {
    // Retrieve the entry with the given timestamp from the buffer while handling concurrent access

    FrameMetrics *target = NULL;

    if (tryAcquire(bm)) {
        pthread_mutex_lock(&bm->mutexAttr);

        for (size_t i = 0; i < bm->length && target == NULL; ++i) {
            if (bm->buffer[i].timestamp == timestamp)
                target = &bm->buffer[i];
        }

        pthread_mutex_unlock(&bm->mutexAttr);
        sem_post(&bm->lock);
    }

    return target;
}

void bufferManagerTest(const char *label, void (*f)(struct BufferManager *), size_t bufferSize, int maxConcurrency, time_t pruningInterval) {
    // Run the given test function on the buffer manager and handle logging, mocking library resetting, and concurrent access using a thread pool

    struct BufferManager bm;
    bufferManagerInit(&bm, bufferSize, maxConcurrency, pruningInterval);

    logging_service_init(); // Initialize external logging service
    blueslip_reset(); // Reset mocking library for isolated testing environments

    pthread_t threadPool[maxConcurrency];
    int ret = pthread_mutexattr_destroy(&bm.mutexAttr);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to destroy mutex attributes\n");
        exit(1);
    }

    for (int i = 0; i < maxConcurrency; ++i)
        pthread_create(&threadPool[i], NULL, f, &bm);

    for (int i = 0; i < maxConcurrency; ++i)
        pthread_join(threadPool[i], NULL);

    bufferManagerDestroy(&bm); // Clean up buffer manager
    logging_service_deinit(); // Deinitialize external logging service
}
