#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    char *name;
    int value;
} item;

// Function to generate a random number within a specified range
int rand_in_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to manage the dynamic collection of items
item* create_item_collection(size_t initial_size, size_t item_count) {
    size_t capacity = initial_size < item_count ? item_count : initial_size;
    item *items = malloc(capacity * sizeof(item));

    if (!items) {
        fprintf(stderr, "Failed to allocate memory for items.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < capacity; ++i) {
        items[i].name = malloc(256 * sizeof(char)); // Assume a maximum name length of 255 characters, including null terminator.
        if (!items[i].name) {
            fprintf(stderr, "Failed to allocate memory for item name.\n");
            exit(EXIT_FAILURE);
        }
    }

    size_t index = 0;
    for (size_t i = 0; i < capacity && index < item_count; ++i) {
        snprintf(items[index].name, 256, "Item %d", i);
        items[index].value = rand_in_range(1, 100);
        ++index;
    }

    return items;
}

// Function to resize the collection as needed
void resize_item_collection(item **items, size_t new_capacity) {
    item *new_items = malloc(new_capacity * sizeof(item));

    if (!new_items) {
        fprintf(stderr, "Failed to allocate memory for new items.\n");
        exit(EXIT_FAILURE);
    }

    size_t min_index = 0;
    size_t old_size = *items ? sizeof(*items) / sizeof(item) : 0;
    size_t copy_count = old_size < new_capacity ? old_size : new_capacity;

    for (size_t i = 0; i < copy_count; ++i) {
        snprintf(new_items[i].name, 256, (*items)[min_index].name);
        new_items[i].value = (*items)[min_index].value;
        ++min_index;
    }

    // Free the old memory and update the pointer to the new one.
    for (size_t i = 0; i < old_size; ++i) {
        free((*items)[i].name);
    }
    free(*items);
    *items = new_items;
}
```
