typedef struct DeviceState {
    int id;
    unsigned long flags;
    time_t timestamp;
    char* config;
} DeviceState;

struct DeviceListNode {
    DeviceState state;
    struct DeviceListNode* next;
};

typedef struct DeviceListNode DeviceListNode;

DeviceListNode* create_node(DeviceState state) {
    DeviceListNode* node = malloc(sizeof(DeviceListNode));
    if (!node) return NULL;
    node->state = state;
    node->next = NULL;
    return node;
}

void append_device(DeviceListNode** head, DeviceState state) {
    DeviceListNode* new_node = create_node(state);
    if (!new_node) return;
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    DeviceListNode* current = *head;
    while (current->next != NULL) current = current->next;
    current->next = new_node;
}

DeviceState* find_device(const int id, DeviceListNode** head) {
    for (DeviceListNode* current = *head; current != NULL; current = current->next) {
        if (current->state.id == id) return &current->state;
    }
    return NULL;
}

void update_device(int id, const DeviceState new_state, DeviceListNode** head) {
    DeviceState* state_ptr = find_device(id, head);
    if (state_ptr == NULL) return;
    *state_ptr = new_state;
}

void refresh_config(DeviceListNode** head) {
    // Implement your periodic refresh strategy here
}

void free_list(DeviceListNode** head) {
    DeviceListNode* current = *head;
    while (current != NULL) {
        DeviceListNode* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
