#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char name[256];
    int value;
} item;

typedef struct container {
    item *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} container;

void initContainer(container *c, size_t initialCapacity) {
    c->capacity = initialCapacity;
    c->size = 0;
    c->data = malloc(initialCapacity * sizeof(item));
    if (!c->data) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    memset(c->data, 0, initialCapacity * sizeof(item));
    pthread_mutex_init(&c->lock, NULL);
}

void resizeContainer(container *c) {
    if (c->size == c->capacity) {
        size_t newCapacity = c->capacity ? c->capacity * 2 : 4;
        item *tmp = realloc(c->data, newCapacity * sizeof(item));
        if (!tmp) {
            fprintf(stderr, "Error: Out of memory\n");
            exit(EXIT_FAILURE);
        }
        c->data = tmp;
        c->capacity = newCapacity;
    }
}

void randomizeValue(item *i) {
    srand((unsigned int)time(NULL));
    i->value = rand() % 100 + 1;
}

int addItem(container *c, const char *name) {
    if (c->size == c->capacity) resizeContainer(c);

    pthread_mutex_lock(&c->lock);
    randomizeValue(&c->data[c->size]);
    strncpy(c->data[c->size].name, name, sizeof(c->data[c->size].name));
    c->size++;
    pthread_mutex_unlock(&c->lock);
    return 0;
}

void printItems(const container *c) {
    if (!c->size) return;

    pthread_mutex_lock(&c->lock);
    for (size_t i = 0; i < c->size; ++i) {
        printf("%s: %d\n", c->data[i].name, c->data[i].value);
    }
    pthread_mutex_unlock(&c->lock);
}

// Safe usage with multi-threading
void freeContainer(container *c) {
    if (c->data) {
        free(c->data);
        c->data = NULL;
    }
    c->size = 0;
    c->capacity = 0;
    pthread_mutex_destroy(&c->lock);
}
```

This code implements a container structure to manage items, where each item consists of a name (a null-terminated string) and an integer value. The container uses dynamic memory allocation for optimal memory usage.

The `addItem()` function adds an item with a randomized integer value within the specified range (1-100), ensuring efficient memory management by dynamically resizing the collection when necessary. It also includes a thread-safe lock to handle multi-threaded environments and manages external data sources for potential item names, as they may arrive in batches or asynchronously.

The container structure is designed for scalability by minimizing overhead while ensuring that performance degradation does not occur when handling large numbers of items. It prevents memory leaks by properly cleaning up resources through the `freeContainer()` function and optimizes memory usage with efficient dynamic resizing and randomization techniques.']

