class SensorData {
public:
    int id;
    double temperature, humidity;
    std::tm timestamp;
    bool valid;

    SensorData(int id, double temp, double hum, const std::tm& timestamp, bool valid = true)
        : id(id), temperature(temp), humidity(hum), timestamp(timestamp), valid(valid) {}
};

class SensorDataManager {
private:
    struct Node {
        SensorData data;
        Node* next;
        explicit Node(SensorData d) : data(d), next(nullptr) {}
    };

    std::unordered_map<int, Node*> sensors;
    Node* head = nullptr;
    size_t size = 0;

public:
    void insert(const SensorData& data) {
        if (!sensors.count(data.id)) {
            Node* newNode = new Node(data);
            sensors[data.id] = newNode;
            if (head == nullptr) head = newNode;
            else head->next = newNode;
            ++size;
        }
    }

    const SensorData& getSensorData(int id) const {
        auto it = sensors.find(id);
        if (it != sensors.end()) return it->second->data;
        throw std::out_of_range("Invalid sensor ID");
    }

    void validate() {
        Node* current = head;
        size_t validCount = 0;
        while (current) {
            if (current->data.valid && timestamp_diff(&(current->data.timestamp), std::time(nullptr)) <= 60 * 5) // 5 minutes threshold
                ++validCount, current = current->next;
            else {
                Node* temp = current;
                current = current->next;
                delete temp;
            }
        }
        head = nullptr;
        size = validCount;
    }

    size_t getSize() const { return size; }
};
```

