using BenchmarkDotNet;
using Neo4j.Driver;

public class DecryptionService
{
    private readonly IDictionary<string, IReadOnlyList<byte>> _keyIVPairs;
    private readonly ISession _session;

    public DecryptionService(IDictionary<string, IReadOnlyList<byte>> keyIVPairs, string connectionString)
    {
        _keyIVPairs = keyIVPairs;
        var driver = GraphDatabase.Driver(connectionString);
        _session = driver.Session();
    }

    public ConcurrentQueue<string> DecryptMessages(ConcurrentQueue<string> base64EncodedMessages)
    {
        var decryptedMessages = new ConcurrentQueue<string>();
        var tasks = new List<Task>();

        foreach (var message in base64EncodedMessages)
        {
            tasks.Add(Task.Run(() =>
            {
                try
                {
                    using (var cryptoServiceProvider = TripleDESCryptoServiceProvider.Create())
                    {
                        var keyAndIV = _keyIVPairs[message];
                        cryptoServiceProvider.Key = keyAndIV[0];
                        cryptoServiceProvider.IV = keyAndIV[1];

                        var decryptTransform = cryptoServiceProvider.CreateDecryptor();
                        var data = Convert.FromBase64String(message);
                        var plainText = Encoding.UTF8.GetString(decryptTransform.TransformFinalBlock(data, 0, data.Length));

                        _session.RunAsync("CREATE (m:Message { message:'$plainText' })", parameters: new { plainText }).Result;
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine(ex);
                }
            }));
        }

        Task.WhenAll(tasks).ContinueWith(_ =>
        {
            foreach (var task in tasks)
            {
                if (!task.IsFaulted)
                    decryptedMessages.Enqueue(task.Result);
            }
        });

        return decryptedMessages;
    }
}
```

