    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

void network_config_list_resize(NetworkConfigList* list, unsigned int new_capacity) {
    if (new_capacity <= list->size) return;

    NetworkConfig* temp = realloc(list->data, sizeof(NetworkConfig) * new_capacity);
    if (!temp) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    list->data = temp;
    list->capacity = new_capacity;
}

NetworkConfig* network_config_at(const NetworkConfigList* list, unsigned int index) {
    if (index >= list->size) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return NULL;
    }
    return list->data + index;
}

NetworkConfig* network_config_by_id(const NetworkConfigList* list, const char* interface_id) {
    for (unsigned int i = 0; i < list->size; ++i) {
        if (strcmp(network_config_at(list, i)->interface_id, interface_id) == 0) return network_config_at(list, i);
    }
    return NULL;
}

void network_config_append(NetworkConfigList* list, const NetworkConfig* config) {
    if (list->size == list->capacity) network_config_list_resize(list, list->capacity + 16);

    memcpy(list->data + list->size, config, sizeof(NetworkConfig));
    ++list->size;
}

void network_config_update_by_id(NetworkConfigList* list, const char* interface_id, const NetworkConfig* new_config) {
    for (unsigned int i = 0; i < list->size; ++i) {
        if (strcmp(network_config_at(list, i)->interface_id, interface_id) == 0) {
            memcpy(network_config_at(list, i), new_config, sizeof(NetworkConfig));
            return;
        }
    }
}
