    }

    // Implement additional functionality: handle string input and size limit
    if (output != NULL) {
        size_t str_len = strlen(*output);
        if (str_len <= sizeof(*output)) {
            *output = realloc(*output, str_len + 1);
            if (*output == NULL) {
                fprintf(stderr, "Failed to allocate memory for output string\n");
                free(keys);
                free(offsets);
                free(records);
