#include <pthread.h>
#include <time.h>

typedef struct Item {
    char *name;
    int value;
} Item;

struct Node {
    Item item;
    struct Node* next;
};

struct Collection {
    struct Node* head;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void init_collection(struct Collection* collection, size_t initial_capacity) {
    if (initial_capacity == 0)
        initial_capacity = 1;
    collection->head = NULL;
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
}

void add_item(struct Collection* collection, const char *name, int value) {
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    new_node->item.name = strdup(name);
    new_node->item.value = value;
    new_node->next = NULL;

    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        struct Node* temp_head = collection->head;
        for (size_t i = 0; i < new_capacity - collection->capacity; ++i) {
            new_node->next = (struct Node*)malloc(sizeof(struct Node));
            new_node->next->item.name = NULL;
            new_node->next->next = temp_head;
            temp_head = new_node;
        }
        collection->capacity = new_capacity;
    }
    new_node->next = collection->head;
    collection->head = new_node;
    ++(collection->size);

    pthread_mutex_unlock(&collection->mutex);

    // Update the values of existing items
    struct Node* current = collection->head;
    for (size_t i = 0; i < collection->size; ++i) {
        current->item.value = rand() % 100 + 1;
        current = current->next;
    }
}

void destroy_collection(struct Collection* collection) {
    struct Node* current = collection->head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp->item.name);
        free(temp);
    }
    pthread_mutex_destroy(&collection->mutex);
}

// Logging function for memory usage and performance metrics
void log(const char* message) {
    // Implement logging using your preferred logging library or system calls
}

// Thread-safe add_item function for multi-threaded environments
void* thread_add_item(void *param) {
    struct Collection* collection = param;
    const char* name = "Thread Item";
    int value = rand() % 100 + 1;
    add_item(collection, name, value);
    log("Added item: name=%s, value=%d", name, value);
    pthread_exit(NULL);
}
