Config* get_config_by_id(const struct network_configs* configs, const char* interface) {
    for (size_t i = 0; i < configs->length; ++i) {
        if (strcmp(configs->data[i].interface, interface) == 0) {
            return &configs->data[i];
        }
    }
    return NULL;
}

void add_config(struct network_configs* configs, const Config new_config) {
    pthread_mutex_lock(&configs->lock);

    // Reallocate memory if the array is full and can't hold the new configuration.
    if (configs->length == configs->capacity) {
        size_t new_capacity = configs->capacity ? configs->capacity * 2 : 1;
        Config* temp = realloc(configs->data, sizeof(Config) * new_capacity);
        if (!temp) {
            pthread_mutex_unlock(&configs->lock);
            log_error("Failed to allocate memory for network configurations.");
            return;
        }
        configs->data = temp;
        configs->capacity = new_capacity;
    }

    // Add the new configuration and increment the length.
    memcpy(&configs->data[configs->length], &new_config, sizeof(Config));
    configs->length++;

    pthread_mutex_unlock(&configs->lock);
}

void update_config(struct network_configs* configs, const Config updated_config, const char* interface) {
    pthread_mutex_lock(&configs->lock);

    size_t index = -1;
    for (size_t i = 0; i < configs->length; ++i) {
        if (strcmp(configs->data[i].interface, interface) == 0) {
            index = i;
            break;
        }
    }

    // If the configuration with the given interface was found.
    if (index != -1) {
        memcpy(&configs->data[index], &updated_config, sizeof(Config));
    } else {
        log_error("Failed to update network configuration: interface not found.");
    }

    pthread_mutex_unlock(&configs->lock);
}

void invoke_custom_error_cb(const Config* config) {
