import hashlib
import concurrent.futures
from functools import lru_cache

@lru_cache(maxsize=None)
def read_file_chunked(filename, chunk_size):
    with open(filename, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            yield data

def md5_hash_file(filename, chunk_size=64 * 1024):
    hasher = hashlib.md5()
    with concurrent.futures.ThreadPoolExecutor() as executor:
        with executor.map(lambda chunk: hasher.update(chunk), read_file_chunked(filename, chunk_size)) as chunks:
            pass
    return hasher.hexdigest()
