std::string pyFileHasher(const std::string& filename) {
    Py_Initialize(); // Initialize the Python interpreter

    PyObject* pModule = PyImport_ImportModule("__main__");
    if (pModule == nullptr) {
        PyErr_Print();
        Py_Finalize();
        return "";
    }

    PyObject* pFunc = PyObject_GetAttrString(pModule, "md5file");
    if (pFunc == nullptr) {
        PyErr_Print();
        Py_Finalize();
        return "";
    }

    PyObject* pArgs = PyTuple_New(1);
    if (pArgs == nullptr) {
        PyErr_Print();
        Py_Finalize();
        return "";
    }
    PyObject* pArg0 = PyUnicode_DecodeFSDefault(filename.c_str());
    if (pArg0 == nullptr) {
        PyErr_Print();
        Py_Finalize();
        return "";
    }
    PyTuple_SetItem(pArgs, 0, pArg0);

    PyObject* pResult = PyObject_CallObject(pFunc, pArgs);
    if (pResult == nullptr) {
        PyErr_Print();
        Py_Finalize();
        return "";
    }

    std::string result;
    if (PyString_Check(pResult)) {
        result = PyString_AsUTF8(pResult);
    } else {
        PyErr_Print();
        Py_Finalize();
        return "";
    }

    Py_DECREF(pModule);
    Py_XDECREF(pFunc);
    Py_XDECREF(pArgs);
    Py_XDECREF(pResult);
    Py_Finalize();

    return result;
}
