#include <iostream>
#include <unordered_map>
#include <chrono>
#include <mutex>
#include <boost/asio.hpp>
#include <boost/thread/tss.hpp>

using boost::asio::ip::tcp;

typedef std::pair<uint64_t, std::string> SessionIDAndIP; // Session ID and IP address
struct ConnectionStatus {
    uint64_t sessionID;
    bool isActive;
};

// thread-safe data structure for the connection list
using ConnectionList = std::unordered_map<SessionIDAndIP, ConnectionStatus>;
boost::thread_specific_ptr<ConnectionList> g_connList;
std::mutex g_connListMutex;

void init() {
    g_connList.reset(new ConnectionList());
}

ConnectionList* getConnList() {
    if (!g_connList) {
        init();
    }
    return g_connList.get_pointer();
}

// function to handle network connection status updates, thread-safe
void updateConnectionStatus(uint64_t sessionID, const tcp::endpoint& endpoint, bool isActive) {
    std::lock_guard<std::mutex> lock(g_connListMutex);

    auto it = getConnList()->find({ sessionID, endpoint.address().to_string() });
    if (it == getConnList()->end()) {
        getConnList()->emplace({ {sessionID, endpoint.address().to_string()}, ConnectionStatus{ sessionID, isActive }});
    } else {
        it->second.isActive = isActive;
    }
}

// function to retrieve the number of active connections at any given time
size_t getNumberOfActiveConnections() {
    std::lock_guard<std::mutex> lock(g_connListMutex);
    size_t count = 0;
    for (auto& elem : *getConnList()) {
        if (elem.second.isActive) {
            ++count;
        }
    }
    return count;
}
```

