void grow(void **ptr, size_t newCapacity) {
    void *newMem = realloc(*ptr, newCapacity * sizeof(**ptr));
    if (!newMem) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    *ptr = newMem;
}

LargeInt* largeIntInit(long long value, size_t capacity) {
    LargeInt *intObj = malloc(capacity * sizeof(LargeInt));
    if (!intObj) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    memset(intObj, 0, capacity * sizeof(LargeInt));
    for (size_t i = 0; i < capacity; ++i) intObj[i].value = value;
    return intObj;
}

StringMapKey* stringMapKeyInit(char *key, size_t capacity) {
    StringMapKey *keyObj = malloc(capacity * sizeof(StringMapKey));
    if (!keyObj) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    memset(keyObj, 0, capacity * sizeof(StringMapKey));
    for (size_t i = 0; i < capacity; ++i) keyObj[i].key = key;
    return keyObj;
}

ItemContainer* itemContainerInit(size_t capacity) {
    ItemContainer *container = malloc(sizeof(ItemContainer));
    if (!container) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    container->items = malloc(capacity * sizeof(Item));
    if (!container->items) {
        free(container);
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    container->capacity = capacity;
    container->length = 0;
    return container;
}

void itemContainerAdd(ItemContainer *container, Item item) {
    if (container->length == container->capacity) grow(container->items, container->capacity * 2);
    memcpy(&container->items[container->length], &item, sizeof(item));
    ++container->length;
}

void largeIntFree(LargeInt *intObj) {
    free(intObj);
}

void stringMapKeyFree(StringMapKey *keyObj) {
    size_t i;
    for (i = 0; i < keyObj->length; ++i) free(keyObj[i].key);
    free(keyObj);
}

void itemContainerFree(ItemContainer *container) {
    free(container->items);
    free(container);
}

void populateCollection(ItemContainer *container, int itemsCount) {
    if (itemsCount < 1 || itemsCount > container->capacity) {
        fprintf(stderr, "Invalid number of items to add\n");
        exit(EXIT_FAILURE);
