#include <pthread.h>
#include <semaphore.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int age;
} item;

// Custom error codes for clarity and ease of debugging
enum ErrorCodes { SUCCESS = 0, MEMORY_ERROR = -1, INVALID_ARGUMENT = -2, THREAD_LIMIT_EXCEEDED = -3 };

struct large_int {
    pthread_mutex_t lock;
    void *value;
};

struct str_key {
    pthread_mutex_t lock;
    char *key;
    struct large_int count;
};

typedef struct thread_data {
    int max_items;
    sem_t *sem, *full;
    item **items;
    struct str_key *keys;
    struct large_int *values;
} thread_data;

void init_large_int(struct large_int *li) {
    li->value = calloc(1, sizeof(long long));
    if (!li->value) {
        perror("calloc");
        exit(MEMORY_ERROR);
    }
    pthread_mutex_init(&li->lock, NULL);
}

void init_str_key(struct str_key *sk) {
    sk->key = calloc(1, sizeof(char));
    if (!sk->key) {
        perror("calloc");
        exit(MEMORY_ERROR);
    }
    pthread_mutex_init(&sk->lock, NULL);
    init_large_int(&sk->count);
}

void init_item(item **item) {
    *item = malloc(sizeof(item));
    if (!*item) {
        perror("malloc");
        exit(MEMORY_ERROR);
    }
    (*item)->name = NULL;
    (*item)->age = 0;
}

void destroy_large_int(struct large_int *li) {
    free(li->value);
    pthread_mutex_destroy(&li->lock);
}

void destroy_str_key(struct str_key *sk) {
    free(sk->key);
    destroy_large_int(&sk->count);
    pthread_mutex_destroy(&sk->lock);
}

void destroy_item(item *item) {
    free(item->name);
    free(item);
}

int add_item(thread_data *td, item *item) {
    int idx = (td->items - td->items + td->max_items) % td->max_items;
    if ((td->items[idx] && (++(td->items[idx]->count.value)) > 1) || idx == td->current) {
        return THREAD_LIMIT_EXCEEDED;
    }
    td->items[idx] = item;
    td->items[idx]->name = strdup(item->name);
    if (!td->items[idx]->name) {
        perror("strdup");
        return MEMORY_ERROR;
    }
    td->items[idx]->age = item->age;
    pthread_mutex_lock(&td->items[idx]->lock);
    (td->items[idx]->count.value)++;
    pthread_mutex_unlock(&td->items[idx]->lock);
    return SUCCESS;
}

item *get_item(thread_data *td, const char *key) {
    struct str_key *sk = td->keys;
    int idx = (sk - td->keys + 1) % td->max_items;
    pthread_mutex_lock(&sk[idx].lock);
    for (int i = idx; i < td->max_items; i = (i + 1) % td->max_items) {
        if (!strcmp(key, sk[i].key)) {
            item *item = td->items[i];
            pthread_mutex_lock(&item->lock);
            int count = *(long long *)item->count.value;
            pthread_mutex_unlock(&item->lock);
            if (count > 0) {
                (--(td->items[i]->count.value));
                pthread_mutex_unlock(&sk[i].lock);
                return item;
            }
        }
        idx = (i + 1) % td->max_items;
    }
    pthread_mutex_unlock(&sk[idx].lock);
    return NULL;
}

void *populate(void *data) {
    thread_data *td = data;
    int items_added = 0, random_age;

    while (items_added < td->max_items && items_added + td->items_allocated <= td->max_items) {
        item *new_item = malloc(sizeof(item));
        if (!new_item) {
            perror("malloc");
            return NULL;
        }
        random_age = rand() % 100 + 1;
        init_item(&new_item);
        strcpy(new_item->name, "Item");
        new_item->age = random_age;

        if (add_item(td, new_item) == SUCCESS) {
            items_added++;
        } else {
            destroy_item(new_item);
        }
    }
    sem_post(td->full);
    return NULL;
}

int manage_memory(thread_data *td, int max_items, int items_allocated) {
    td->max_items = max_items;
    td->items_allocated = items_allocated;
    td->items = calloc((max_items + items_allocated), sizeof(item *));
    if (!td->items) {
        perror("calloc");
        return MEMORY_ERROR;
    }
    td->keys = calloc((max_items + items_allocated), sizeof(struct str_key));
    if (!td->keys) {
        perror("calloc");
        free(td->items);
        return MEMORY_ERROR;
    }
    td->values = calloc((max_items + items_allocated), sizeof(struct large_int));
    if (!td->values) {
        perror("calloc");
        free(td->keys);
        free(td->items);
        return MEMORY_ERROR;
    }
    td->sem = sem_init(0, 0, max_items);
    if (td->sem == SEM_FAILED) {
        perror("sem_init");
        destroy_large_int(td->values);
        free(td->keys);
        free(td->items);
        return MEMORY_ERROR;
    }
    td->full = sem_init(0, 0, 0);
    if (td->full == SEM_FAILED) {
        perror("sem_init");
        destroy_large_int(td->values);
        free(td->keys);
        free(td->items);
        sem_destroy(td->sem);
        return MEMORY_ERROR;
    }

    for (int i = 0; i < max_items + items_allocated; ++i) {
        init_str_key(&td->keys[i]);
        init_large_int(&td->values[i]);
    }
    return SUCCESS;
}
