} Item;

// Global variables for data structures management
pthread_mutex_t largeIntsMutex, stringsMutex, itemsMutex;
void* largeIntsMemoryPool = NULL;
void* stringsMemoryPool = NULL;
sem_t itemsSemaphore;
int numItems = 0;
Item** items;

// Function to initialize data structures
void initDataStructures(size_t numThreads, size_t maxItemsPerThread) {
    pthread_mutex_init(&largeIntsMutex, NULL);
    pthread_mutex_init(&stringsMutex, NULL);
    pthread_mutex_init(&itemsMutex, NULL);

    sem_init(&itemsSemaphore, 0, numThreads * maxItemsPerThread);

    largeIntsMemoryPool = calloc(1 << 20, sizeof(long long)); // 1MB for large integers
    stringsMemoryPool = calloc(1 << 24, sizeof(char) * 128); // 16MB for strings

    items = malloc(numThreads * maxItemsPerThread * sizeof(Item*));
}

// Function to free data structures
void freeDataStructures() {
    free(largeIntsMemoryPool);
    free(stringsMemoryPool);
    free(items);

    pthread_mutex_destroy(&largeIntsMutex);
    pthread_mutex_destroy(&stringsMutex);
    pthread_mutex_destroy(&itemsMutex);
    sem_destroy(&itemsSemaphore);
}

// Function to manage large integers, minimizing memory fragmentation
long long* allocateLargeInt() {
    long long *result;
    void *ptr = NULL;
    size_t alignedSize = sizeof(long long) + (sizeof(long long) - 1) & ~(sizeof(long long) - 1);

    if ((ptr = realloc(largeIntsMemoryPool, largeIntsMemoryPool == NULL ? alignedSize : largeIntsMemoryPool + alignedSize)) == NULL) {
        fprintf(stderr, "Failed to allocate memory for large integers\n");
        exit(EXIT_FAILURE);
    }

    result = (long long*)ptr;
    largeIntsMemoryPool += alignedSize;
    return result;
}

// Function to manage strings, minimizing memory fragmentation
char* allocateString() {
    char *result;
    void *ptr = NULL;
    size_t alignedSize = sizeof(char) * 128 + (sizeof(char) * 128 - 1) & ~(sizeof(char) * 128 - 1);

    if ((ptr = realloc(stringsMemoryPool, stringsMemoryPool == NULL ? alignedSize : stringsMemoryPool + alignedSize)) == NULL) {
        fprintf(stderr, "Failed to allocate memory for strings\n");
        exit(EXIT_FAILURE);
    }

    result = (char*)ptr;
    stringsMemoryPool += alignedSize;
    return result;
}

// Function to manage items, ensuring thread safety and dynamic population with a maximum limit
void* populateItems(void* arg) {
    size_t maxItemsPerThread = *(size_t*)arg;

    for (int i = 0; i < maxItemsPerThread; ++i) {
        sem_wait(&itemsSemaphore);

        // Acquire mutexes and allocate memory
        pthread_mutex_lock(&itemsMutex);

        Item *item = items[numItems];
        if (item == NULL) {
            item = malloc(sizeof(Item));
            if (!item) {
                fprintf(stderr, "Failed to allocate memory for an item\n");
                exit(EXIT_FAILURE);
            }
            memset(item, 0, sizeof(Item));
        }

        numItems++;

        pthread_mutex_unlock(&itemsMutex);

        // Populate the item and log the event
