        //log_event(logBuf);

        // Release mutexes and signal to move on
        pthread_mutex_lock(&itemsMutex);
        pthread_mutex_unlock(&stringsMutex);
        pthread_mutex_unlock(&largeIntsMutex);
    }

    return NULL;
}

// Function to handle user input for number of threads and max items per thread
void handleUserInput() {
