void* mem_pool_alloc(struct mem_pool *pool, size_t size) {
    if (pool->length - (uintptr_t)pool->start < size) return NULL;
    void *ptr = (char*)pool->start + pool->length - size;
    pool->length -= size;
    return ptr;
}

