#include <stdbool.h>
#define MAX_STRUCTURES 1000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static AES_KEY aes_key;
static unsigned char iv[AES_BLOCK_SIZE];
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static int num_structures = 0;
static int max_structures = MAX_STRUCTURES;

void aes_init(const unsigned char *password) {
    SHA1_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, password, strlen((char*)password));
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1_Final(hash, &ctx);
    AES_set_encrypt_key(hash, 256, &aes_key);
    memset(iv, 0, sizeof(iv)); // Fixed IV length
}

NFAPI_CRC_INDICATION_PDU_T* aes_encrypt(const unsigned char *data, RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti) {
    pthread_mutex_lock(&list_mutex);
    if (num_structures >= max_structures) {
        free(list[num_structures - 1].crc_indication.data); // Free oldest structure
        --num_structures;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list[num_structures];
    memcpy(&(pdu->rx_ue_info), &rx_ue_info, sizeof(RX_UE_INFORMATION_TAG));
    memcpy(&(pdu->rnti), &rnti, sizeof(RNTI));
    pdu->crc_indication.data = malloc(sizeof(CRC_INDICATION_REL8_TAG) + sizeof(unsigned char)); // Allocate new CRC flag
    memset(pdu->crc_indication.data, 0, sizeof(CRC_INDICATION_REL8_TAG) + sizeof(unsigned char));
    pdu->crc_indication.length = sizeof(unsigned char);
    *(uint8_t*)(pdu->crc_indication.data) = rand() & 1; // Set CRCFLAG randomly

    AES_cbc_encrypt((const unsigned char *)data, pdu->data, sizeof(unsigned char), &aes_key, iv, AES_ENCRYPT);
    ++num_structures;
    pthread_mutex_unlock(&list_mutex);

    return pdu;
}

void aes_cleanup() {
    pthread_mutex_lock(&list_mutex);
    if (list) {
        for(int i = 0; i < num_structures; ++i) {
            free(list[i].crc_indication.data);
        }
        free(list);
        list = NULL;
    }
    AES_free_key(&aes_key);
    memset(iv, 0, sizeof(iv)); // Clear IV
    pthread_mutex_unlock(&list_mutex);
}
```
