        return NULL;
    }

    size_t last = num_current_states - 1;

    // Allocate memory for the new state list
    size_t new_num_states = num_current_states + 1;
    int *new_states = (int *)malloc(new_num_states * sizeof(int));
    int *new_next = (int *)malloc((new_num_states + 1) * sizeof(int));
    time_t *new_timestamps = (time_t *)calloc(new_num_states, sizeof(time_t));
    int *new_ref_counts = (int *)calloc(new_num_states, sizeof(int));

    if (!new_states || !new_next || !new_timestamps || !new_ref_counts) {
        pthread_mutex_unlock(&fsa->lock);
        free(new_states);
        free(new_next);
        free(new_timestamps);
        free(new_ref_counts);
        return NULL;
    }

    // Copy current states and update reference counts
    for (size_t i = 0; i <= last; ++i) {
        new_states[i] = current_states[i];
        fsa->ref_count[new_states[i]]++;
        new_next[i] = fsa->next[current_states[i]];
        new_timestamps[i] = fsa->timestamp[current_states[i]];
        new_ref_counts[i] = fsa->ref_count[current_states[i]];
    }

    // Handle intermediate states
    size_t state = last;
    while (fsa->states[state] != FSA_INTERMEDIATE) {
        state = new_next[state];
    }

    // Update next pointer of the last state in the list to point to the newly created state list
    fsa->next[current_states[last]] = (int)(new_num_states - 1);

    // Process intermediate states and insert new states if necessary
    while (fsa->states[state] == FSA_INTERMEDIATE) {
        size_t next_state = fsa->next[state];

        // Check for valid transition to the next state
        if (!valid_transition(state, next_state, fsa)) {
            continue;
        }

        new_states[new_num_states - 1] = next_state;
        new_next[new_num_states - 1] = fsa->next[next_state];
        new_timestamps[new_num_states - 1] = fsa->timestamp[next_state];
        new_ref_counts[new_num_states - 1] = fsa->ref_count[next_state];

        // Recurse for the next intermediate state
        state = next_state;
    }

    // Update last state and return the new state list
    last++;
    fsa->states = new_states;
    fsa->num_states = new_num_states;
    fsa->next = new_next;
    fsa->timestamp = new_timestamps;
    fsa->ref_count = new_ref_counts;

    pthread_mutex_unlock(&fsa->lock);
    return fsa->states;
}
```

