#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct FrameMetrics {
    time_t timestamp;
    int signal_strength;
    size_t data_len;
    char* data;
} FrameMetrics;

struct Node {
    FrameMetrics metrics;
    struct Node* next;
};

static struct Node** head = NULL;
static size_t capacity = 0, size = 0;
static const int prune_interval = 60; // in seconds
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_memory(const char* message) {
    printf("%s: Total allocated memory: %ld bytes\n", message, (long int)(4 * size + sizeof(struct Node)*size));
}

void prune() {
    if (capacity == 0 || size < capacity) return;

    struct Node* current = *head;
    time_t now = time(NULL);
    size_t to_remove = (now - (*head)->metrics.timestamp) / prune_interval;

    for (size_t i = 0; i < to_remove && current != NULL; ++i, current = current->next) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
        --size;
    }
}

FrameMetrics* find(time_t timestamp) {
    pthread_mutex_lock(&mutex);
    struct Node* current = *head;
    while (current != NULL && current->metrics.timestamp < timestamp)
        current = current->next;
    pthread_mutex_unlock(&mutex);
    return current == NULL ? NULL : &current->metrics;
}

void insert(FrameMetrics metrics) {
    pthread_mutex_lock(&mutex);
    if (size >= capacity) prune();

    struct Node* newNode = malloc(sizeof(struct Node));
    if (!newNode) return;
    memcpy(&newNode->metrics, &metrics, sizeof(FrameMetrics));
    newNode->next = *head;
    *head = newNode;

    if (rand() % 10 == 0) // Update existing items with a random number within a specified range
        for (struct Node* current = *head; current != NULL; current = current->next) {
            current->metrics.signal_strength = rand() % 100 + 1;
        }

    ++size;
    log_memory("Before update");
    // Perform additional operations or calculations based on the updated collection
    log_memory("After update");
    pthread_mutex_unlock(&mutex);
}

void destroy() {
    pthread_mutex_lock(&mutex);
    struct Node* current = *head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
    capacity = size = 0;
    pthread_mutex_unlock(&mutex);
}
```

