#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

typedef struct FrameMetrics {
    time_t timestamp;
    int signalStrength;
    char* RSI;
} FrameMetrics;

struct FrameMetricsManager {
    size_t capacity;
    size_t currentSize;
    FrameMetrics* data;
    pthread_mutex_t mutex;
    bool isPaused;
};

void FrameMetricsComparator(const void *a, const void *b) {
    return (*((time_t*) a) - *((time_t*) b));
}

FrameMetricsManager* createFrameMetricsManager(size_t capacity) {
    FrameMetricsManager* fmm = malloc(sizeof(FrameMetricsManager));
    if (!fmm) {
        perror("malloc");
        return NULL;
    }

    fmm->capacity = capacity;
    fmm->currentSize = 0;
    fmm->data = calloc(capacity, sizeof(FrameMetrics));
    if (!fmm->data) {
        perror("calloc");
        free(fmm);
        return NULL;
    }

    fmm->mutex = PTHREAD_MUTEX_INITIALIZER;
    fmm->isPaused = false;

    qsort(fmm->data, capacity, sizeof(FrameMetrics), FrameMetricsComparator);
    return fmm;
}

void destroyFrameMetricsManager(FrameMetricsManager* fmm) {
    for (size_t i = 0; i < fmm->currentSize; ++i) {
        free(fmm->data[i].RSI);
    }
    free(fmm->data);
    free(fmm);
}

FrameMetrics* insertFrameMetrics(FrameMetricsManager* fmm, const FrameMetrics* metrics) {
    pthread_mutex_lock(&fmm->mutex);
    if (fmm->currentSize >= fmm->capacity && !fmm->isPaused) {
        pruneOldEntries(fmm);
    }
    for (size_t i = 0; i < fmm->currentSize; ++i) {
        if (metrics->timestamp <= fmm->data[i].timestamp) {
            memmove(&(fmm->data[i + 1]), &(fmm->data[i]), sizeof(FrameMetrics) * (fmm->currentSize - i));
            memcpy(&(fmm->data[i]), metrics, sizeof(FrameMetrics));
            break;
        }
    }
    if (++fmm->currentSize > fmm->capacity) {
        fmm->capacity *= 2;
        FrameMetrics* newData = realloc(fmm->data, sizeof(FrameMetrics) * fmm->capacity);
        if (!newData) {
            perror("realloc");
            pthread_mutex_unlock(&fmm->mutex);
            return NULL;
        }
        fmm->data = newData;
    }
    qsort(fmm->data, fmm->currentSize, sizeof(FrameMetrics), FrameMetricsComparator);
    pthread_mutex_unlock(&fmm->mutex);
    return &(fmm->data[fmm->currentSize - 1]);
}

void deleteFrameMetricsByTimestamp(FrameMetricsManager* fmm, time_t timestamp) {
    pthread_mutex_lock(&fmm->mutex);
    size_t index = binarySearch(fmm->data, fmm->capacity, timestamp, FrameMetricsComparator);
    if (index < fmm->currentSize && fmm->data[index].timestamp == timestamp) {
        memmove(&(fmm->data[index]), &(fmm->data[index + 1]), sizeof(FrameMetrics) * (fmm->currentSize - index - 1));
        --fmm->currentSize;
    }
    pthread_mutex_unlock(&fmm->mutex);
}

FrameMetrics* retrieveFrameMetricsByTimestamp(const FrameMetricsManager* fmm, time_t timestamp) {
    pthread_mutex_lock(&fmm->mutex);
    size_t index = binarySearch(fmm->data, fmm->currentSize, timestamp, FrameMetricsComparator);
    FrameMetrics* metrics = NULL;
    if (index < fmm->currentSize && fmm->data[index].timestamp == timestamp) {
        metrics = &(fmm->data[index]);
    }
    pthread_mutex_unlock(&fmm->mutex);
    return metrics;
}

void pauseFrameMetricsManager(FrameMetricsManager* fmm) {
    pthread_mutex_lock(&fmm->mutex);
    fmm->isPaused = true;
    pthread_mutex_unlock(&fmm->mutex);
}

void resumeFrameMetricsManager(FrameMetricsManager* fmm) {
    pthread_mutex_lock(&fmm->mutex);
    fmm->isPaused = false;
    pthread_mutex_unlock(&fmm->mutex);
}

size_t binarySearch(const FrameMetrics* data, size_t length, time_t key, int (*comparator)(const void*, const void*)) {
    size_t low = 0;
    size_t high = length - 1;
    while (low <= high) {
        size_t mid = (low + high) / 2;
        if (!(*comparator)(&(data[mid].timestamp), &key)) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

void pruneOldEntries(FrameMetricsManager* fmm) {
    time_t currentTime = time(NULL);
    size_t limitIndex = fmm->currentSize - (fmm->capacity / 4);
    for (size_t i = fmm->currentSize - 1; i >= limitIndex; --i) {
        if (fmm->data[i].timestamp + ((time_t)(86400 * 7)) <= currentTime) { // prune entries older than one week
            free(fmm->data[i].RSI);
            memmove(&(fmm->data[i]), &(fmm->data[i - 1]), sizeof(FrameMetrics) * (fmm->currentSize - i));
            --fmm->currentSize;
        }
    }
}
```

