struct FrameMetrics {
    int timestamp;
    int signalStrength;
    std::vector<int> rsiIndicators;
};

class DynamicFrameCollection {
private:
    std::list<FrameMetrics> frames_;
    int capacity_;
    int windowSize_;
    unsigned long long totalItems_;
    std::mutex mutex_;

public:
    explicit DynamicFrameCollection(int initCapacity, int windowSize) :
        capacity_(initCapacity), windowSize_(windowSize), totalItems_(0) {}

    void insert(const FrameMetrics& frame) {
        std::unique_lock<std::mutex> lock(mutex_);
        frames_.emplace_back(frame);
        totalItems_++;

        // Prune old entries if necessary
        while (frames_.size() > capacity_) {
            auto it = frames_.begin();
            std::advance(it, windowSize_);
            frames_.erase(it, frames_.end());
        }
    }

    void updateExistingItems(int min, int max) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto& frame : frames_) {
            frame.signalStrength = rand() % (max - min + 1) + min;
        }
    }

    void batchInsert(const std::vector<FrameMetrics>& frames) {
        std::unique_lock<std::mutex> lock(mutex_);
        totalItems_ += frames.size();
        frames_.insert(frames_.end(), frames.begin(), frames.end());

        // Prune old entries if necessary
        while (frames_.size() > capacity_) {
            auto it = frames_.begin();
            std::advance(it, windowSize_);
            frames_.erase(it, frames_.end());
        }
    }
};
