typedef struct FrameMetrics {
    time_t timestamp;
    int signalStrength;
    char* rsiData; // Variable-length data field
} FrameMetrics;

struct ConcurrentFrameMetricsManager {
    size_t capacity;
    size_t count;
    FrameMetrics** metrics;
    pthread_mutex_t lock;
    pthread_cond_t full, empty;
};

void destroy_frame_metrics(FrameMetrics* metrics) {
    free(metrics->rsiData);
    free(metrics);
}

void increment_count(struct ConcurrentFrameMetricsManager* manager) {
    pthread_mutex_lock(&manager->lock);
    manager->count++;
    if (manager->count == manager->capacity && manager->capacity > 0)
        pthread_cond_signal(&manager->empty);
    pthread_mutex_unlock(&manager->lock);
}

bool decrement_and_check_empty(struct ConcurrentFrameMetricsManager* manager) {
    bool empty = false;
    pthread_mutex_lock(&manager->lock);
    if (manager->count > 0) {
        manager->count--;
        if (manager->count == manager->capacity - 1 && manager->capacity > 0)
            pthread_cond_signal(&manager->full);
        empty = manager->count == 0;
    }
    pthread_mutex_unlock(&manager->lock);
    return empty;
}

void prune(struct ConcurrentFrameMetricsManager* manager) {
    time_t now = time(NULL);
    FrameMetrics** current = manager->metrics;
    for (size_t i = 0; i < manager->capacity && i < manager->count; ++i, ++current) {
        if ((now - (*current)->timestamp) > MAX_AGE) {
            destroy_frame_metrics(*current);
            --manager->count;
        } else {
            FrameMetrics* temp = current[manager->capacity - 1];
            *current = *current + 1;
            current[manager->capacity - 1] = temp;
        }
    }
}

void concurrent_frame_metrics_insert(struct ConcurrentFrameMetricsManager* manager, FrameMetrics* metrics) {
    pthread_mutex_lock(&manager->lock);
    while (manager->count == manager->capacity) {
        pthread_cond_wait(&manager->full, &manager->lock);
    }
    increment_count(manager);
    (*manager->metrics[manager->count - 1]) = *metrics;
    metrics->rsiData = malloc(strlen(metrics->rsiData) + 1);
    strcpy(metrics->rsiData, metrics->rsiData);
    prune(manager);
    pthread_mutex_unlock(&manager->lock);
}

void* process_metrics(void* arg) {
    struct ConcurrentFrameMetricsManager* manager = arg;

    while (true) {
        concurrent_frame_metrics_insert(manager, malloc(sizeof(FrameMetrics)));
        // Process the inserted FrameMetrics structure here.

        pthread_mutex_lock(&manager->lock);
        while (!decrement_and_check_empty(manager))
            pthread_cond_wait(&manager->empty, &manager->lock);
        pthread_mutex_unlock(&manager->lock);
    }
}

void concurrent_frame_metrics_manager_init(struct ConcurrentFrameMetricsManager* manager, size_t capacity) {
    manager->capacity = capacity;
    manager->count = 0;
    manager->metrics = calloc(manager->capacity, sizeof(FrameMetrics*));
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->full, NULL);
    pthread_cond_init(&manager->empty, NULL);
}
