    event_t flush_event;
    event_set(&flush_event, -1, EV_PERSIST | EV_TIMER, flush_log_messages_cb, logger);
    event_loop_control(logger->event_loop, &flush_event, EVCTL_ADD);
    event_active(logger->event_loop, &flush_event) ? 0 : event_timer(&flush_event, logger->config.max_log_messages_per_second * 1000); // Trigger in milliseconds
}

void* flush_log_messages_cb(evutil_socket_t wd, short events, void* arg) {
    struct Logger* logger = static_cast<struct Logger*>(arg);
    flush_log_messages(logger);
    return NULL;
}
