    int max_log_file_size;
    bool use_external_logging;
    // Configuration for external logging service...
};

struct LogMessage {
    struct timespec timestamp;
    LogLevel level;
    char message[4096];
};

struct Logger {
    sem_t log_mutex;
    pthread_t log_thread_id;
    struct LogMessage *log_buffer;
    size_t log_buffer_size;
    size_t log_buffer_index;
    struct timespec last_flush_timestamp;
    int log_file_descriptor;
    struct LoggerConfig config;
};

void logger_init(struct Logger *logger, const char *log_directory, int log_file_count,
                 int max_log_messages_per_second, int max_log_file_size, bool use_external_logging) {
    // Initialize semaphore and other variables...
