}

void logger_destroy(struct Logger *logger) {
    // Close log file descriptor and free resources...
}

void logger_set_level(struct Logger *logger, LogLevel level) {
    // Store the current log level...
}

void log_internal(struct Logger *logger, LogLevel level, const char *format, ...) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (now.tv_nsec - logger->last_flush_timestamp.tv_nsec >= 1000000000 / logger->config.max_log_messages_per_second) {
        sem_wait(&logger->log_mutex);
        logger->last_flush_timestamp = now;
        fsync(logger->log_file_descriptor);
        sem_post(&logger->log_mutex);
    }

    if (level <= logger->current_log_level) {
        sem_wait(&logger->log_mutex);

        struct LogMessage *msg = &logger->log_buffer[logger->log_buffer_index];
        msg->timestamp = now;
        msg->level = level;

        va_list args;
        va_start(args, format);
        snprintf(msg->message, sizeof(msg->message), format, args...);
        va_end(args);

        logger->log_buffer_index = (logger->log_buffer_index + 1) % logger->log_buffer_size;
        if (logger->log_buffer_index == 0) {
            // If buffer is full, wake up the log thread to process messages...
        }

        sem_post(&logger->log_mutex);
    }
}

void* log_thread(void *arg) {
    struct Logger *logger = arg;

    while (true) {
        sem_wait(&logger->log_mutex);

        if (logger->log_buffer_index != 0) {
            // Process messages in the buffer...
        }

        sem_post(&logger->log_mutex);
        usleep(1000);
    }
}

void logger_flush(struct Logger *logger) {
    sem_wait(&logger->log_mutex);

    if (logger->log_buffer_index != 0) {
        // Flush messages to disk...
    }

    sem_post(&logger->log_mutex);
}

void logger_open(struct Logger *logger) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    int log_file_index = now.tv_sec % logger->config.log_file_count;
    char log_filename[256];
    snprintf(log_filename, sizeof(log_filename), "%s/log%d.txt", logger->config.log_directory, log_file_index);

    logger->log_file_descriptor = open(log_filename, O_WRONLY | O_CREAT | O_APPEND | O_SYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
}
