namespace bs = boost::serialization;

enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

class LogEntry {
public:
    LogLevel level;
    std::time_t timestamp;
    std::string message;

    friend class bs::access;
    template<typename Archive> void serialize(Archive& ar, const unsigned int) {
        ar & level & timestamp & message;
    }
};

class LogManager {
public:
    explicit LogManager(size_t max_size, const std::string& log_service_url) : _maxSize(max_size), _logServiceUrl(log_service_url) {}

    void insert(const LogLevel& level, const std::time_t& timestamp, const std::string& message);
    std::vector<LogEntry> search(const LogLevel& level, const std::time_t& timestamp);
    void remove(const LogLevel& level, const std::time_t& timestamp);

    void prune();
    void serializeToDisk();
    void deserializeFromDisk();

private:
    size_t _maxSize;
    std::string _logServiceUrl;

    // Use unordered_map to store the log entries and unordered_multimap for efficient search based on log level and timestamp.
    using LogMap = std::unordered_map<std::time_t, LogEntry>;
    using LogMultimap = std::unordered_multimap<LogLevel, LogMap>;

    // Helper function to prune logs by age or frequency of log levels.
    void pruneByAge();
    void pruneByFrequency(const LogLevel& level);

    // Networking and serialization functions are omitted for brevity.
};

void LogManager::insert(const LogLevel& level, const std::time_t& timestamp, const std::string& message) {
    auto it = _logs.insert({level, {timestamp, message}});
    if (it.second == false) { // Update existing entry instead of inserting a new one.
        it.first->second.message += "\n" + message;
    }
}

std::vector<LogEntry> LogManager::search(const LogLevel& level, const std::time_t& timestamp) {
    auto searchResult = _logs.equal_range({level, timestamp});
    std::vector<LogEntry> result;
    for (auto it = searchResult.first; it != searchResult.second; ++it) {
        result.push_back(it->second);
    }
    return result;
}

void LogManager::remove(const LogLevel& level, const std::time_t& timestamp) {
    auto searchResult = _logs.equal_range({level, timestamp});
    for (auto it = searchResult.first; it != searchResult.second; ++it) {
        it->second.erase(it->first);
    }
}

