typedef struct {
    uint64_t id;
    time_t timestamp;
    int rsi;
    // Variable-length data field for CRC indications
    char data[256];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint64_t id;
    time_t timestamp;
    int signal_strength;
    // Variable-length data field for RSI
    char data[256];
} FrameMetrics;

#define MAX_CACHE_SIZE 1024

struct ConcurrentNFCacheManager {
    NFAPI_CRC_INDICATION_PDU_T cache_pdus[MAX_CACHE_SIZE];
    FrameMetrics cache_metrics[MAX_CACHE_SIZE];
    int pdu_head, pdu_tail;
    int metrics_head, metrics_tail;
    pthread_mutex_t cache_mutex;
    pthread_cond_t cache_cond;
};

void init_concurrent_nfcache_manager(struct ConcurrentNFCacheManager* manager) {
    pthread_mutex_init(&manager->cache_mutex, NULL);
    pthread_cond_init(&manager->cache_cond, NULL);
    manager->pdu_head = manager->pdu_tail = 0;
    manager->metrics_head = manager->metrics_tail = 0;
}

bool insert_pdu(struct ConcurrentNFCacheManager* manager, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (manager->pdu_tail - manager->pdu_head >= MAX_CACHE_SIZE) return false;

    pthread_mutex_lock(&manager->cache_mutex);

    while (manager->pdu_tail - manager->pdu_head > 0 && memcmp(manager->cache_pdus[manager->pdu_tail - 1].data, pdu->data, sizeof(pdu->data)) == 0) {
        manager->pdu_tail--;
    }

    memcpy(&manager->cache_pdus[manager->pdu_tail], pdu, sizeof(*pdu));
    manager->pdu_tail++;

    if (manager->pdu_tail > MAX_CACHE_SIZE) manager->pdu_tail = 0;
    pthread_mutex_unlock(&manager->cache_mutex);

    pthread_cond_signal(&manager->cache_cond);

    return true;
}

bool insert_metrics(struct ConcurrentNFCacheManager* manager, const FrameMetrics* metrics) {
    if (manager->metrics_tail - manager->metrics_head >= MAX_CACHE_SIZE) return false;

    pthread_mutex_lock(&manager->cache_mutex);

    while (manager->metrics_tail - manager->metrics_head > 0 && memcmp(manager->cache_metrics[manager->metrics_tail - 1].data, metrics->data, sizeof(metrics->data)) == 0) {
        manager->metrics_tail--;
    }

    memcpy(&manager->cache_metrics[manager->metrics_tail], metrics, sizeof(*metrics));
    manager->metrics_tail++;

    if (manager->metrics_tail > MAX_CACHE_SIZE) manager->metrics_tail = 0;
    pthread_mutex_unlock(&manager->cache_mutex);

    pthread_cond_signal(&manager->cache_cond);

    return true;
}

