    uint16_t sample_per_pixel;
    uint32_t extra_samples;
    uint16_t *extra_info;
} ImageInfo;

// Custom allocator for cipher objects
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

EVP_CIPHER_CTX* create_cipher_context() {
    EVP_CIPHER_CTX *ctx = (EVP_CIPHER_CTX *)custom_alloc(sizeof(EVP_CIPHER_CTX));
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL)) {
        free(ctx);
        fprintf(stderr, "Error initializing cipher context\n");
        exit(EXIT_FAILURE);
    }
    return ctx;
}

void parse_tiff(const char *filename, ImageInfo *image_info, EVP_CIPHER_CTX **cipher_ctx) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", TIFFGetErrMsg());
        exit(EXIT_FAILURE);
    }

    // Parse image information
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) != 1 &&
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) != 2 &&
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) != 4 &&
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) != 8 &&
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) != 16) {
        fprintf(stderr, "Unsupported number of bits per sample\n");
        exit(EXIT_FAILURE);
    }

    image_info->bits_per_sample = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, 1);
    image_info->sample_per_pixel = TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL, 1);

    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES) > 0) {
        image_info->extra_samples = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES);
        image_info->extra_info = (uint16_t *)calloc(image_info->extra_samples, sizeof(uint16_t));
        for (size_t i = 0; i < image_info->extra_samples; ++i) {
            image_info->extra_info[i] = TIFFGetField(tif, (2 + i) * TIFFTAG_SAMPLEFORMAT);
        }
    } else {
        image_info->extra_samples = 0;
    }

    // Implement image filtering and other custom operations here

    *cipher_ctx = create_cipher_context();

    // Log performance and resource usage if necessary

    TIFFClose(tif);
}

// ... (other functions to process the image, apply a filter, perform encryption, etc.)
