    *readings = malloc(sizeof(SensorReading) * 1024);

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        SensorReading* reading = &(*readings)[*num_readings];
        sscanf(line, "%s %f", reading->sensor_id, &reading->value);
        (*num_readings)++;

        // Reallocate memory if needed (e.g., when the number of readings reaches 2 * current capacity).
        if (*num_readings == *num_readings / 2 * 2) {
            *readings = realloc(*readings, sizeof(SensorReading) * (*num_readings * 2));
        }
    }

    qsort(*readings, *num_readings, sizeof(SensorReading), compare_readings);
