bool is_anomaly(const SensorReading* reading, char* thresholds) {
    char* token = strtok(thresholds, ",");
    while (token != NULL) {
        char sensor_id[32];
        float threshold;
        sscanf(token, "%s %f", sensor_id, &threshold);

        if (strcmp(sensor_id, reading->sensor_id) == 0) {
            return reading->value > threshold;
        }

        token = strtok(NULL, ",");
    }
    return false;
}

void generate_report(const SensorReading* readings, size_t num_readings, FILE* report, bool debug) {
