        fprintf(stderr, "Usage: %s <input file> <output file> <kpis> <thresholds> <debug> <timeout>\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    const char *kpis = argv[3];
    const char *thresholds = argv[4];
    bool debug = atoi(argv[5]) != 0;
    int timeout = atoi(argv[6]);

