    int num_sources = 0;

    // Initialize data sources and parse the input stream
    while (parse_data(sources + num_sources, input)) {
        num_sources++;
    }

    struct timeval start, end;
    gettimeofday(&start, NULL);
    double timeout_sec = (double)timeout;
    double elapsed = 0.0;

    FILE *output = fopen(output_file, "w");
    if (!output) {
        perror("Error opening output file");
        return 1;
    }

    while ((elapsed < timeout_sec) && (num_sources > 0)) {
        double current_time = gettimeofday_s();
        elapsed += (current_time - start.tv_sec) + (current_time - start.tv_usec) * 1e-6;

        // Process each data source in parallel
        pthread_t threads[num_sources];
        for (int i = 0; i < num_sources; ++i) {
            pthread_create(&threads[i], NULL, process_data, sources + i);
        }

        // Wait for all data processing threads to finish
        for (int i = 0; i < num_sources; ++i) {
            pthread_join(threads[i], NULL);
        }

        // Generate report and update it incrementally
        generate_report(output, kpis, thresholds, debug);
    }

    fclose(input);
    fclose(output);

    return 0;
}
