    // Other configuration parameters...
};

class NetworkService {
public:
    void reloadConfiguration(const std::string& filename) {
        std::ifstream configFile(filename);
        if (!configFile.is_open()) {
            std::cerr << "Failed to open configuration file." << std::endl;
            return;
        }

        picojson::value root;
        picojson::parse(configFile, root);

        boost::property_tree::ptree pt;
        boost::property_tree::read_json(root, pt);

        Configuration newConfig;
        newConfig.port = pt.get<int>("port");
        newConfig.ipAddress = pt.get<std::string>("ipAddress");
        // ... Populate the rest of the configuration structure...

        std::mutex configMutex;
        {
            std::lock_guard<std::mutex> lock(configMutex);
            _currentConfig = newConfig;
        }

        reloadCompleteCallback();
    }

private:
    Configuration _currentConfig;
    std::function<void()> reloadCompleteCallback;

    // Other private members for the custom buffer management system and ongoing connections...
};
```

