use regex::Regex;

type Result<T> = std::result::Result<T, Box<dyn Error>>;

mod lexer {
    // Implement your custom lexer here
}

mod parser {
    // Implement your custom parser here
}

fn generate_llvm_ir(path: &PathBuf) -> Result<String> {
    let file = File::open(&path)?;
    let reader = BufReader::new(file);

    if !path.extension().unwrap()?.eq("ll") {
        return Err(Box::error(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            "Invalid file extension",
        )));
    }

    let (tx, rx) = channel::<Result<parser::Node>>();
    tokio::task::spawn_blocking(move || {
        let lexer = lexer::Lexer::new(&reader);
        let mut parser = parser::Parser::new(&lexer);
        loop {
            match parser.parse()? {
                Some(node) => tx.send(Ok(node)),
                None => break,
            }
        }
    });

    let mut buffer = Vec::new();
    std::mem::swap(&mut buffer, &mut reader.into_inner());

    // Read and handle comments and whitespace here

    let mut optimized_nodes: Vec<parser::Node> = vec![];
    while let Ok(node) = rx.recv() {
        optimized_nodes.push(node);
    }

    if tx.send(Ok(parser::EOF)).is_err() {
        return Err(Box::error(std::io::Error::new(
            std::io::ErrorKind::BrokenPipe,
            "Channel closed prematurely",
        )));
    }

    let ir = generate_optimized_llvm_code(&optimized_nodes);

    if is_debug_mode() {
        print_parsed_nodes(&optimized_nodes);
    }

    Ok(ir)
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <FILE>", args[0]);
        return Ok(());
    }

    let path = PathBuf::from(&args[1]);
    generate_llvm_ir(&path).map_err(Box::new)?;

    Ok(())
}
