#include <vector>
#include <memory>
#include <algorithm>
#include <iterator>
#include <string>

void insert_string(std::vector<std::shared_ptr<std::string>>& vec, const std::string& first, const std::string& second, size_t index = 0) {
    auto it = std::find_if(vec.begin(), vec.end(), [&first](const std::shared_ptr<std::string> sptr) { return *sptr == first; });

    if (it != vec.end() && index <= vec.size()) {
        if (index < it - vec.begin())
            std::rotate(it, ++it, vec.end());
        *it = std::move(second);
    } else if (index == vec.size()) {
        vec.push_back(std::make_shared<std::string>(second));
    } else {
        it = vec.begin();
        auto nextIt = it;
        ++nextIt;
        while (nextIt != vec.end() && *nextIt != first) {
            it = nextIt++;
        }
        if (it != vec.end()) {
            vec.insert(it, std::make_shared<std::string>(second));
        } else {
            vec.push_back(std::make_shared<std::string>(second));
        }
    }
}
```
This code defines a function called `insert_string`, which takes four arguments: a reference to a vector of shared pointers to strings, two string arguments, and an optional integer index. The function iterates through the vector using `std::find_if` until it finds the first occurrence of the first argument or reaches the end of the vector.

If the specified index is valid (i.e., within the vector's size), the second string argument is inserted at the specified position, taking care to move existing elements if necessary. Otherwise, the function searches for the first argument and inserts the second argument either before or after it, as appropriate. The function uses `std::rotate` to shift elements when needed to ensure proper insertion.

The function also ensures that any existing shared pointers are updated appropriately by moving the new string into the shared_ptr at the correct position (using `std::move`) and properly managing memory with the use of smart pointers."]

