#include <iostream>
#include <fstream>
#include <map>
#include <mutex>
#include <queue>
#include <string>
#include <thread>
#include <atomic>
#include <boost/asio.hpp>
#include <boost/noncopyable.hpp>
#include <boost/config.hpp>

namespace logging {
    class LogLevel final : private boost::noncopyable {
        public:
            enum Level { TRACE, DEBUG, INFO, WARNING, ERROR, FATAL };
            static constexpr std::map<Level, std::string> level_names = {{TRACE, "Trace"}, {DEBUG, "Debug"}, {INFO, "Info"}, {WARNING, "Warning"}, {ERROR, "Error"}, {FATAL, "Fatal"}};

            Level level;

            explicit LogLevel(Level l) : level(l) {}
    };

    class Logger final : private boost::noncopyable {
        public:
            virtual ~Logger() = default;
            virtual void log(const std::string& message, const LogLevel& level) = 0;

            static Logger& get(const std::string& name);
            static void set_level(const std::string& name, const LogLevel& level);

        private:
            friend class LoggerFactory;

            explicit Logger(const std::string& name) : name_(name), log_file_(std::move(open_log_file())) {}

            void rotate_log_file();

            std::string name_;
            std::ofstream log_file_;
            const boost::filesystem::path log_path_;
            mutable std::mutex mtx_;
            static std::queue<std::pair<std::string, LogLevel>> messages_;
            static std::atomic<bool> rotating_;
            static std::atomic<bool> asynchronous_;

        protected:
            virtual void open_log_file() const = 0;
    };

    class ConsoleLogger final : public Logger {
        public:
            void log(const std::string& message, const LogLevel& level) override {
                std::lock_guard<std::mutex> lock(mtx_);
                std::cout << "[" << level_names.at(level).c_str() << "] [" << name_ << "]: " << message << std::endl;
            }

            void open_log_file() const override { return boost::filesystem::path{}; }
    };

    class FileLogger final : public Logger {
        public:
            void log(const std::string& message, const LogLevel& level) override {
                std::lock_guard<std::mutex> lock(mtx_);
                if (asynchronous_) {
                    messages_.emplace(message, level);
                } else {
                    log_file_ << "[" << level_names.at(level).c_str() << "] [" << name_ << "]: " << message << std::endl;
                }
            }

            void open_log_file() const override {
                auto it = log_path_.parent_path().end();
                auto current = log_path_.end();
                while (it != log_path_.begin()) {
                    --it;
                    if (boost::filesystem::exists(*it)) {
                        current = it;
                        break;
                    }
                }

                if (current == log_path_.end()) {
                    boost::filesystem::create_directories(log_path_);
                }

                auto file_name = boost::filesystem::canonical(*log_path_ / name_ + ".log").filename().string();
                return *log_path_ / (file_name);
            }
    };

    class LoggerFactory final {
        public:
            static Logger& create(const std::string& name, const std::string& log_path, bool asynchronous = false) {
                if (asynchronous) {
                    // Implement asynchronous logging using Boost.Asio or a similar library
                }

                auto console_logger = new ConsoleLogger(name);
                auto file_logger = new FileLogger();
                file_logger->log_path_ = log_path;

                return *console_logger;
            }
    };
} // namespace logging

namespace {
    logging::Logger& logging::Logger::get(const std::string& name) {
        static std::map<std::string, std::unique_ptr<logging::Logger>> loggers;
        auto it = loggers.find(name);
        if (it == loggers.end()) {
            loggers[name] = logging::LoggerFactory::create(name);
            it = loggers.find(name);
        }
        return *it->second;
    }

    void logging::Logger::set_level(const std::string& name, const LogLevel& level) {
        auto it = loggers.find(name);
        if (it != loggers.end()) {
            it->second->level_ = level;
        }
    }
} // namespace

#include <boost/asio/io_service.hpp>
std::queue<std::pair<std::string, logging::LogLevel>> logging::Logger::messages_;
bool logging::Logger::rotating_ = false;
bool logging::Logger::asynchronous_ = false;
```
This code provides a basic structure for a logging framework in C++. It supports multiple log levels, configuration of file rotation policies, and asynchronous logging to minimize impact on application performance. Each application has its own configurable logging channel, and the system allows dynamic switching of log levels at runtime.

The `ConsoleLogger` class logs messages directly to the console, while the `FileLogger` writes messages to a file (with support for asynchronous writing using Boost.Asio). The framework is designed to be easily extendable with other logging destinations if needed.

Keep in mind that this code only shows the main structure of the logging system and does not include actual file rotation implementation, thread safety, integration with external monitoring tools, or any optimizations for high-throughput environments. These aspects would require additional work based on specific requirements and constraints.']

