    public function addRole($roleName, array $properties = []) {
        if (in_array($roleName, $this->roles)) {
            throw new Exception("Role already exists");
        }
        $this->roles[] = ['name' => $roleName, 'properties' => $properties];
    }

    public function updateRole($roleName, array $properties = []) {
        if (!in_array($roleName, $this->roles)) {
            throw new Exception("Role does not exist");
        }
        foreach ($this->roles as &$role) {
            if ($role['name'] === $roleName) {
                $role = ['name' => $roleName, 'properties' => array_merge($role['properties'], $properties)];
                break;
            }
        }
    }

    public function removeRole($roleName) {
        if (!in_array($roleName, $this->roles)) {
            throw new Exception("Role does not exist");
        }
        unset($this->roles[array_search($roleName, $this->roles)]);
    }

    public function assignRole($userId, $roleName) {
        if (!in_array($userId, array_keys($this->usersRoles))) {
            throw new Exception("User does not exist");
        }
        if (!in_array($roleName, array_column($this->roles, 'name'))) {
            throw new Exception("Role does not exist");
        }
        $currentRoles = $this->usersRoles[$userId];
        if (in_array($roleName, $currentRoles)) {
            throw new Exception("User already has this role");
        }
        // Check role hierarchy and user limits here
        $this->usersRoles[$userId][] = $roleName;
    }
}
