public class BackgroundServiceManager {
 private final ExecutorService executor;
 private final MonitoringSystem monitoringSystem;
 private final Supplier<Boolean> resourceAvailabilityMetrics;
 private volatile boolean serviceRunning = false;
 private static final Logger LOGGER = LoggerFactory.getLogger(BackgroundServiceManager.class);

 @Inject
 public BackgroundServiceManager(ExecutorService executor, MonitoringSystem monitoringSystem,
 Supplier<Boolean> resourceAvailabilityMetrics) {
 this.executor = executor;
 this.monitoringSystem = monitoringSystem;
 this.resourceAvailabilityMetrics = resourceAvailabilityMetrics;
 }

 public void startBackgroundService() {
 if (serviceRunning) {
 LOGGER.warn("Tried to start background service that is already running.");
 return;
 }

