 handleFailure();
 }
 };

 serviceRunning = true;
 executor.execute(service);
 monitoringSystem.sendStatusUpdate("Background Service Started");
 }

 public void stopBackgroundService() {
 if (!serviceRunning) {
 LOGGER.warn("Tried to stop background service that is not running.");
 return;
 }

 serviceRunning = false;
 executor.shutdownNow();
 monitoringSystem.sendStatusUpdate("Background Service Stopped");
 }

