['1. For generating a secure token in C#:

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Linq;

public class SecureTokenGenerator
{
    private readonly string _characterSet;
    private byte[] _randomBytes;

    public SecureTokenGenerator(string characterSet, int tokenLength)
    {
        _characterSet = characterSet;
        GenerateRandomBytes(tokenLength);
    }

    private void GenerateRandomBytes(int length)
    {
        using (var rngCryptoServiceProvider = new RNGCryptoServiceProvider())
        {
            var randomBytes = new byte[length];
            rngCryptoServiceProvider.GetBytes(randomBytes);
            _randomBytes = randomBytes;
        }
    }

    public string GenerateToken(int tokenLength)
    {
        if (tokenLength <= 0 || tokenLength > _characterSet.Length)
            throw new ArgumentOutOfRangeException(nameof(tokenLength));

        var token = Enumerable.Repeat(_randomBytes, tokenLength).Select(b => _characterSet[_randomBytes[0] % _characterSet.Length]).ToArray();
        return new string(token);
    }
}
```

