    def scale(self, action, unit=1):
        read_capacity = int(self.table.describe()['Table']['ProvisionedThroughput']['ReadCapacityUnits']) + unit * (action == 'up')
        write_capacity = int(self.table.describe()['Table']['ProvisionedThroughput']['WriteCapacityUnits']) + unit * (action == 'up')
        self.table.update_time_to_live({'ProvisionedThroughput': {'ReadCapacityUnits': read_capacity, 'WriteCapacityUnits': write_capacity}})

    def close(self):
        self.table = None
```

