public class OrderProcessor {
    private final Inventory inventory;
    private final PaymentService paymentService;
    private final ShippingAPI shippingAPI;
    private final Lock lock = new ReentrantLock();

    public OrderProcessor(Inventory inventory, PaymentService paymentService, ShippingAPI shippingAPI) {
        this.inventory = inventory;
        this.paymentService = paymentService;
        this.shippingAPI = shippingAPI;
    }

    public void processOrder(Order order) {
        try (Transaction transaction = new Transaction()) {
            // Lock to ensure thread safety during order processing
            lock.lock();

            // Check if the order is valid
            if (!isValidOrder(order)) {
                printFailed("Invalid order details");
                return;
            }

            // Update inventory, apply discounts, and calculate total cost
            BigDecimal totalCost = calculateTotalCost(order);

            // Check if there's enough stock in the inventory for the order
            if (!inventory.hasEnoughStock(order)) {
                printFailed("Not enough stock to fulfill the order");
                return;
            }

            // Deduct inventory items and apply payment
            transaction.begin();
            inventory.deductItemsFromStock(order);
            boolean paymentConfirmation = paymentService.applyPayment(order, totalCost);

            if (paymentConfirmation) {
                // Generate shipment and update order status using external shipping API
                Shipment shipment = generateShipment();
                DeliveryTime deliveryTime = shippingAPI.estimateDeliveryTime(shipment);
                order.setStatus("Processing")
                        .setEstimatedDeliveryDate(deliveryTime.getDeliveryDate())
                        .setShipment(shipment);

                // Commit the transaction if everything went well
                transaction.commit();
                printSuccess("Order processed successfully");
            } else {
                // Rollback the transaction if payment confirmation fails
                transaction.rollback();
                printFailed("Payment failed");
            }
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

