using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class PerformanceDataAnalyzer
{
    private readonly Dictionary<string, (decimal MinThreshold, decimal MaxThreshold, Queue<decimal> Values) > _metrics;
    private const int TimeWindowSize = 60; // minutes

    public PerformanceDataAnalyzer(IDictionary<string, (decimal min, decimal max)> thresholds)
    {
        _metrics = new Dictionary<string, (decimal MinThreshold, decimal MaxThreshold, Queue<decimal>)>();
        foreach (var entry in thresholds)
            _metrics[entry.Key] = (entry.Value.min, entry.Value.max, new Queue<decimal>(TimeWindowSize));
    }

    public void AddMetric(string metricName, decimal value)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        _metrics[metricName].Values.Enqueue(value);

        if (_metrics[metricName].Values.Count > TimeWindowSize)
            _metrics[metricName].Values.Dequeue();
    }

    public decimal GetAverage(string metricName)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        return _metrics[metricName].Values.Average();
    }

    public decimal GetMinimum(string metricName)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        return _metrics[metricName].Values.Min();
    }

    public decimal GetMaximum(string metricName)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        return _metrics[metricName].Values.Max();
    }

    public decimal GetStandardDeviation(string metricName)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        return Math.Sqrt(_metrics[metricName].Values.Select(v => Math.Pow(v - _metrics[metricName].Average(), 2)).Average());
    }

    public bool IsOutlier(string metricName, decimal zScoreThreshold)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        var mean = _metrics[metricName].Average();
        var stdDev = GetStandardDeviation(metricName);
        return Math.Abs((GetCurrentValue(metricName) - mean) / stdDev) > zScoreThreshold;
    }

    private decimal GetCurrentValue(string metricName)
    {
        if (!_metrics.ContainsKey(metricName))
            throw new KeyNotFoundException($"Invalid metric name: '{metricName}'");

        return _metrics[metricName].Values.LastOrDefault();
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        foreach (var entry in _metrics)
            sb.AppendLine($"{entry.Key}: MinThreshold={entry.Value.MinThreshold}, MaxThreshold={entry.Value.MaxThreshold}, Average={GetAverage(entry.Key)}, Minimum={GetMinimum(entry.Key)}, Maximum={GetMaximum(entry.Key)}, StandardDeviation={GetStandardDeviation(entry.Key)}");
        return sb.ToString();
    }
}
```
This code defines a `PerformanceDataAnalyzer` class that manages a dynamic set of performance metrics and provides the required functionality to add new metrics, retrieve statistical values, identify outliers based on Z-scores, and handle invalid data gracefully by throwing appropriate exceptions. The class also overrides the `ToString()` method for easy display of current thresholds and statistical summary of the metrics.

The code uses a `Dictionary<string, (decimal MinThreshold, decimal MaxThreshold, Queue<decimal> Values)>` to store the performance metrics data, where the keys represent the metric names and the values contain minimum and maximum acceptable threshold, an enqueued queue for storing the metric values, and the average value. The `TimeWindowSize` constant is set to 60 minutes, but can be modified if needed.

The class uses efficient memory usage and processing speed techniques such as using a queue for storing the data points within the time window and calculating standard deviations in an incremental way by maintaining the variance of each value added to the queue. The calculation of average, minimum, maximum, and standard deviation are done lazily when needed to avoid unnecessary computations.

The class handles large datasets efficiently as it only keeps track of the most recent data points within the time window and discards older ones when new data is added. Additionally, the class uses the `Min`, `Max`, `Average`, `LastOrDefault` LINQ methods to calculate statistical values in an efficient manner.']

