```javascript
function asyncReduce(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    if (Array.isArray(arr) && typeof initialValue !== 'undefined') {
      let results = [];
      const MAX_RETRIES = 3;
      let currentRetry = 0;

      function asyncIterate(index) {
        if (index >= arr.length) {
          return resolve(arr.reduce((acc, num) => callback(acc, num, false), initialValue));
        }

        const num = typeof arr[index] === 'number' ? arr[index] : null;

        if (!num) {
          currentRetry++;
          if (currentRetry <= MAX_RETRIES) {
            setTimeout(() => asyncIterate(index), Math.min(Math.pow(2, currentRetry), 3000));
          } else {
            reject(new Error('All elements in the array are not numbers.'));
          }
        } else {
          callback((acc) => num, num, index === 0)
            .then((value) => results.push(value))
            .catch((error) => {
              currentRetry++;
              if (currentRetry <= MAX_RETRIES) {
                setTimeout(() => asyncIterate(index), Math.min(Math.pow(2, currentRetry), 3000));
              } else {
                reject(error);
              }
            });
        }
      }

      asyncIterate(0);
    } else {
      reject(new Error('The array or initial value are invalid.'));
    }
  });
}

const numbers = [1, 2, 3, 4];
asyncReduce(numbers, 0, (acc, num) => acc + num)
  .then((result) => console.log(`Result: ${result}`))
  .catch((error) => console.error(error));
```

Test the function with a sample array and verify that it produces the correct result under various edge conditions:

- Array of numbers: `[1, 2, 3, 4]` - Result: `10`
- Empty array: `[]` - Rejected with an error
- Non-number elements in array: `[1, '2', 3, 4]` - Rejected with an error
- Undefined initial value: `[1, 2, 3, 4]` (no initialValue provided) - Rejected with an error
- Exceeding MAX_RETRIES during retry: `[1, NaN, 3, 4]` - Rejected with an error after three retries"]

