#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

typedef struct {
    int count;
    double *values;
} LineData;

void read_line(FILE *, char **line) {
    size_t len = 0;
    char *buf = NULL;
    ssize_t read;

    while ((read = getline(&buf, &len, stdin)) != -1) {
        *line = realloc(*line, read + 1);
        memcpy(*line, buf, read);
        (*line)[read] = '\0';
    }
    free(buf);
}

int parse_values(const char *line, int *num_values) {
    int count = 0;
    const char *ptr = line;
    while (count < *num_values && isspace(*ptr)) ptr++;

    for (; count < *num_values; count++) {
        double val = strtod(ptr, &ptr);
        if (*ptr != '\0' || !isdigit(*ptr)) return 0;
        while (isspace(*ptr++));
    }

    *num_values = count;
    return 1;
}

void process_line(const char *line, LineData *data) {
    int num_values;
    if (!parse_values(line, &num_values)) return;

    double sum = data->values[0] + data->values[num_values - 1];
    double avg_second_third = (data->values[(num_values - 2) / 2] + data->values[(num_values + 2) / 2]) / 2.0;

    if (num_values % 2 == 0) {
        qsort(data->values, num_values, sizeof(double), (int (*)(const void*, const void*) ) compare);
        data->values[num_values / 2] = (data->values[(num_values - 1) / 2] + data->values[(num_values + 1) / 2]) / 2.0;
    }

    printf("%f,%f", sum, avg_second_third);
    if (num_values % 2 == 0) printf(",%f\n", data->values[num_values / 2]);
}

int compare(const void *a, const void *b) {
    return (*(const double *) a - *(const double *) b);
}

int main() {
    char line[4096];
    LineData data;

    while (fgets(line, sizeof(line), stdin)) {
        LineData *tmp = realloc(data.values, sizeof(double) * (data.count + 1));
        if (!tmp) {
            fprintf(stderr, "Memory allocation error\n");
            return 1;
        }
        data.values = tmp;

        data.count = 0;
        process_line(line, &data);
        free(line);
    }

    if (data.values) free(data.values);
    return 0;
}
