bool validate_oauth2_token(const std::string& json_str) {
    nlohmann::json j = nlohmann::json::parse(json_str, nullptr); // Use a JSON parsing library to handle potential errors gracefully
    if (!j.is_object()) {
        return false;
    }

    const auto access_token_it = j.find("access_token");
    if (access_token_it == j.end() || access_token_it->second.empty()) {
        return false;
    }

    const auto expires_in_it = j.find("expires_in");
    if (expires_in_it == j.end()) {
        return false;
    }

    try {
        int64_t expires_in = std::stoll(expires_in_it->second); // Parse the integer value of "expires_in"
        if (expires_in <= 0) {
            return false;
        }
    } catch (const std::exception& e) {
        return false;
    }

    const auto token_type_it = j.find("token_type");
    if (token_type_it == j.end() || token_type_it->second != "Bearer") {
        return false;
    }

    // Optional refresh_token validation
    const auto refresh_token_it = j.find("refresh_token");
    if (refresh_token_it != j.end() && refresh_token_it->second.empty()) {
        return false;
    }

    return true;
}
