using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace EncryptionUploader
{
    public class ResponseObject
    {
        public bool Success { get; set; }
        public string Message { get; set; }
    }

    public class EncryptAndUploadService
    {
        private const string BaseAddress = "https://your-remote-service.com";
        private readonly HttpClient _httpClient;
        private SymmetricAlgorithm _encryptionAlgorithm;
        private ICryptoTransform _encryptor;
        private byte[] _encryptionKey;
        private long _keyExpiration;

        public EncryptAndUploadService(HttpClient httpClient, string encryptionAlgorithmName)
        {
            _httpClient = httpClient;
            InitializeEncryptionAlgorithm(encryptionAlgorithmName);
        }

        private void InitializeEncryptionAlgorithm(string encryptionAlgorithmName)
        {
            var keySize = 256; // Set the desired key size for the encryption algorithm
            switch (encryptionAlgorithmName.ToLower())
            {
                case "aes-128":
                    _encryptionAlgorithm = AES.Create();
                    break;
                case "aes-192":
                    _encryptionAlgorithm = AES.Create(keySize: keySize * 2);
                    break;
                case "aes-256":
                    _encryptionAlgorithm = AES.Create(keySize: keySize * 4);
                    break;
                default:
                    throw new ArgumentException("Invalid encryption algorithm.");
            }
        }

        private void GenerateEncryptionKey()
        {
            using var rngCsp = new RNGCryptoServiceProvider();
            var keyBytes = new byte[32]; // Set the desired key size for the encryption algorithm
            rngCsp.GetBytes(keyBytes);
            _encryptionKey = keyBytes;
        }

        private void CheckKeyExpiration()
        {
            if (DateTime.UtcNow > DateTimeOffset.FromUnixTimeSeconds(_keyExpiration))
                GenerateEncryptionKey(); // Generates a new key if it has expired
        }

        public async Task<ResponseObject> EncryptAndUpload(byte[] data)
        {
            CheckKeyExpiration();

            using var msData = new MemoryStream(data);
            using var msEncrypted = new MemoryStream();

            _encryptor = _encryptionAlgorithm.CreateEncryptor(_encryptionKey, _encryptionAlgorithm.IV);
            var cryptoTransform = _encryptor.TransformStream(msEncrypted);
            msData.CopyTo(cryptoTransform);

            // Upload the encrypted data to the remote service using HTTPS POST
            var requestContent = new StreamContent(msEncrypted);
            var response = await _httpClient.PostAsync($"{BaseAddress}/api/upload", requestContent);
            response.EnsureSuccessStatusCode();

            // Parse the JSON response from the remote service
            using (var reader = new StreamReader(await response.Content.ReadAsStreamAsync()))
            {
                var jsonResponse = JObject.Parse(await reader.ReadToEndAsync());
                return JsonConvert.DeserializeObject<ResponseObject>(jsonResponse["result"].ToString());
            }
        }
    }
}
```
