public class HashService
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(HashService));
    private readonly Dictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>();

    public async Task<IDictionary<string, (string MD5, string SHA256)>> HashStringsAsync(IEnumerable<string> strings)
    {
        var results = new ConcurrentDictionary<string, (string MD5, string SHA256)>();

        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
        Parallel.ForEach(strings, options, s =>
        {
            var md5Bytes = HashStringToByteArray(s, HashAlgorithmName.MD5);
            var sha256Bytes = HashStringToByteArray(s, HashAlgorithmName.SHA256);

            results[s] = (BitConverter.ToString(md5Bytes).Replace("-", "").ToLower(), BitConverter.ToString(sha256Bytes).Replace("-", "").ToLower());
            _cache[s] = sha256Bytes;

            // Monitor operation counts and performance metrics
            MonitorOperationCountAndPerformanceMetrics();
        });

        return results.ToDictionary(k => k.Key, v => v.Value);
    }

    private byte[] HashStringToByteArray(string s, HashAlgorithmName algorithm)
    {
        var bytes = Encoding.UTF8.GetBytes(s);
        var hashAlgorithm = SHA256.Create();
        return hashAlgorithm.ComputeHash(bytes);
    }

    private void MonitorOperationCountAndPerformanceMetrics()
    {
        // Integrate with an existing logging framework to monitor operation counts and performance metrics
        Log.Info($"Hashed: {_cache.Count}");
    }
}
```
