{
    var key = CalculateCacheKey(payload);
    if (_cache.TryGetValue(key, out var cachedResponse))
        return cachedResponse;

    using (var request = new HttpRequestMessage())
    {
        request.Method = HttpMethod.Post;
        request.Content = new StringContent(payload);
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _token);

        try
        {
            var response = await _httpClient.SendAsync(request);
            if (!response.IsSuccessStatusCode)
                return HandleErrorResponse(response);

            var content = await response.Content.ReadAsStringAsync();
            return DeserializeResponse<T>(content);
        }
        catch (TaskCanceledException)
        {
            // Log error without exposing sensitive information
            Console.WriteLine($"Network issue while sending request.");
            return new ApiResponse<T> { Success = false };
        }
        catch (HttpRequestException ex)
        {
            // Log error without exposing sensitive information
            Console.WriteLine($"API request failed: {ex.Message}");
            return new ApiResponse<T> { Success = false };
        }
    }
