void loadData() {
    std::ifstream inputFile("data.bin", std::ios::binary);

    if (!inputFile.is_open()) {
        BOOST_LOG_TRIVIAL(error) << "Error opening file.";
        return;
    }

    try {
        boost::iostreams::filtering_stream<boost::iostreams::input> inputStream;
        std::string extension;

        std::copy(inputFile.rdbuf(), inputFile.rdbuf(), std::istream_iterator<char>(inputStream));

        while (!inputStream.eof()) {
            inputStream >> extension;
            if (extension == ".gz") {
                inputStream.push(boost::iostreams::gzip_decompressor());
            } else if (extension == ".deflate") {
                inputStream.push(boost::iostreams::deflate_decompressor());
            }
