        cipherContexts.pop_front();

        if (EVP_DecryptInit2(ctx, NULL, key, static_cast<unsigned char*>(iv), iv_len) <= 0) {
            BOOST_LOG_TRIVIAL(error) << "Error initializing cipher context.";
            return;
        }
    }

    unsigned int dataLen = sizeof(data);
    unsigned char* decryptedData = static_cast<unsigned char*>(malloc(dataLen));

    if (EVP_DecryptUpdate(ctx, decryptedData, &dataLen, reinterpret_cast<const unsigned char*>(data), dataLen) <= 0 ||
        EVP_DecryptFinal_ex(ctx, decryptedData + dataLen, &dataLen) <= 0) {
        BOOST_LOG_TRIVIAL(error) << "Error during decryption.";
        free(decryptedData);
        return;
    }

    // Process the decrypted data here

    free(decryptedData);
}
