const FormData = require('form-data'); // For handling multipart/form-data
const concurrently = require('concurrently'); // For handling concurrency
const Q = require('q'); // For promise chaining and handling

const cloudStorageConfig = {
  // Configure your cloud storage service settings here, e.g.:
  provider: 'your_cloud_storage_provider',
  apiKey: 'your_api_key',
  baseUrl: 'https://api.your_cloud_storage_service.com/upload',
  concurrencyLimit: 5, // Number of files to upload concurrently
  retryPolicy: {
    maxAttempts: 3, // Maximum number of retries for a failed upload
    delay: 10000 // Delay between retries (in milliseconds)
  }
};

const createFormData = (fileUrl) => {
  const promise = Q.defer();

  axios.get(fileUrl, { responseType: 'stream' })
    .then((response) => {
      const formData = new FormData();
      formData.append('file', response.data);
      promise.resolve(formData);
    })
    .catch((error) => {
      if (error.response && error.response.status === 404) {
        // Invalid URL, handle accordingly
        promise.reject(new Error(`Invalid file URL: ${fileUrl}`));
      } else if (!/^image\/\w+/.test(error.response.headers['content-type'])) {
        // Unsupported file type, handle accordingly
        promise.reject(new Error(`Unsupported file type for URL: ${fileUrl}`));
      } else {
        // Network failure or other errors, handle accordingly
        promise.reject(error);
      }
    });

  return promise.promise;
};

