  const options = {
    url: `${config.baseUrl}`,
    headers: {
      'Authorization': `Bearer ${config.apiKey}`
    },
    data: formData,
    onUploadProgress: progressEvent => {
      // Real-time progress tracking
    }
  };

  return axios.post(options);
};

