class Registry:
    def __init__(self):
        self.factories = {}

    def register(self, key: str, factory: Callable[[Dict], Type]):
        self.factories[key] = factory

    async def deserialize_from_json(self, json_str: str) -> Any:
        data = await JSONSerializer.loads(json_str)
        cls = self.get_class_for_json(data)
