def stream_and_process(url, chunk_size=None):
    try:
        response = requests.get(url, stream=True, timeout=10)
        if not response.ok:
            return None, {"error": f"Failed to load {url}"}

        progress_bar = tqdm.tqdm(total=response.content_length, unit="B", desc=url)
        chunks = response.iter_content(chunk_size=chunk_size or get_chunk_size())

        metadata = {}
        try:
            for chunk in chunks:
                progress_bar.update(len(chunk))
                metadata.update(extract_metadata(BytesIO(chunk)))
        except Exception as e:
            return None, {"error": f"Error processing {url}: {e}"}

        try:
            transaction = Transaction(*validate_transaction(response.headers["Content-Type"], chunk))
        except Exception as e:
            return None, {"error": f"Invalid transaction data in {url}: {e}"}

        progress_bar.close()
        return transaction, metadata
    except requests.exceptions.RequestException as e:
        return None, {"error": f"Network error accessing {url}: {e}"}

