import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class FileHash {
    static class CustomStructure {
        String password;
        Object connection;
        Runnable callback;

        public CustomStructure(String password, Object connection, Runnable callback) {
            this.password = password;
            this.connection = connection;
            this.callback = callback;
        }
    }

    private static MessageDigest getSHA256() throws NoSuchAlgorithmException {
        return MessageDigest.getInstance("SHA-384");
    }

    public static BigInteger generateFileHash(CustomStructure cs) throws IOException, NoSuchAlgorithmException {
        if (cs.password == null || cs.password.isEmpty() || cs.connection == null || cs.callback == null)
            throw new IllegalArgumentException("Invalid CustomStructure object");

        Path filePath = Paths.get(cs.password);
        if (!Files.exists(filePath) || Files.notIsRegularFile(filePath))
            throw new FileNotFoundException();

        MessageDigest sha256 = getSHA256();

        try (InputStream inputStream = Files.newInputStream(filePath)) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            BigInteger totalBytes = BigInteger.ZERO;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                sha256.update(buffer, 0, bytesRead);
                totalBytes = totalBytes.add(BigInteger.valueOf(bytesRead));
                if (cs.callback != null) cs.callback.run(); // Invoke callback periodically for progress monitoring
            }
        } catch (IOException e) {
            throw e;
        }

        return sha256.digest();
    }
}
