    public class DecryptionService
    {
        private readonly IMongoDatabase _database;
        private readonly TripleDes _tripleDes;
        private readonly ConcurrentQueue<Base64EncodedMessage> _messageQueue = new ConcurrentQueue<Base64EncodedMessage>();
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(Environment.ProcessorCount, Environment.ProcessorCount);

        public DecryptionService(IMongoDatabase database, byte[] key, byte[] iv)
        {
            _database = database;
            _tripleDes = new TripleDes(key, iv);
        }

        public void EnqueueMessage(Base64EncodedMessage message)
        {
            _messageQueue.Enqueue(message);
            _semaphore.Release();
        }

        public async Task ProcessMessagesAsync()
        {
            while (true)
            {
                await _semaphore.WaitAsync();

                if (_messageQueue.TryDequeue(out var message))
                {
                    try
                    {
                        var plainText = DecryptMessage(message);
                        ProcessDecryptedData(plainText);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error processing message: {ex.Message}");
                    }
                }
            }
        }

        private string DecryptMessage(Base64EncodedMessage message)
        {
            var bytes = Convert.FromBase64String(message.Message);
            return _tripleDes.Decrypt(bytes, 0, bytes.Length);
        }

        private void ProcessDecryptedData(string plainText)
        {
            var bsonDoc = BsonDocument.Parse(plainText);
            // Integrate with your existing graph database environment here
            using (var client = new MongoClient("mongodb://localhost:27017"))
            {
                var db = client.GetDatabase("YourDatabaseName");
                var collection = db.GetCollection<BsonDocument>("YourCollectionName");

                // Add random number of vertices and edges with randomly generated properties
                for (int i = 0; i < RandomNumberGenerator.GetInt32(1, 100); i++)
                {
                    var vertex = new BsonDocument("Vertex" + i, bsonDoc["Property"]);
                    collection.InsertOneAsync(vertex);

                    for (int j = 0; j < RandomNumberGenerator.GetInt32(1, 5); j++)
                    {
                        var edge = new BsonDocument("Edge" + i + "_" + j, vertex);
                        collection.InsertOneAsync(edge);
                    }
                }
            }
        }
    }

    public class Base64EncodedMessage
    {
        public string Message { get; set; }
    }
}
