    return (tolower(c) == 'a' || tolower(c) == 'e' || tolower(c) == 'i' ||
            tolower(c) == 'o' || tolower(c) == 'u');
}

inline int countVowels(const std::string& str) {
    int count = 0;
    for (auto c : str) {
        if (isVowel(c))
            ++count;
    }
    return count;
}

// Function to handle file operations and transformations
std::string processFile(const std::string& inputFileName) {
    // Log the operation start time, user ID, and filename
    logOperation("Start", getuid(), inputFileName);

    FileHandler handler;
    handler.fileName = inputFileName;
    handler.lineNumber = 0;

    // Truncate the filename if necessary
    size_t truncatedLength = 75;
    if (inputFileName.length() > truncatedLength) {
        handler.fileName = inputFileName.substr(0, truncatedLength);
        logError("Filename is too long after truncation");
        return "";
    }

    // Modify the extension based on the number of vowels and special characters
    size_t newExtensionLength = countVowels(handler.fileName) / 2 + (countVowels(handler.fileName) % 2 == 0 ? 0 : 1) + 4; // For @#$ and potential extra digits for special chars
    if (newExtensionLength > MAX_ALLOWED_FILENAME_LENGTH - handler.fileName.length()) {
        logError("Insufficient space for the new extension");
        return "";
    }
    std::string extension = handler.fileName.substr(handler.fileName.find_last_of('.')); // Extract current extension
    handler.fileName = handler.fileName.replace(handler.fileName.end() - extension.length(), extension.length(), ""); // Remove the current extension
    handler.fileName += "." + std::string(newExtensionLength, '@') + "@#$"; // Add the new extension with @#$ at the end

    // Check for special characters and handle extra digits if necessary
    size_t specialCharCount = 0;
    for (auto c : handler.fileName) {
        if (c == '@' || c == '#' || c == '$') {
            ++specialCharCount;
        }
    }
    if (specialCharCount > 5) {
        handler.fileName += std::to_string(handler.fileName.size() / 2 + specialCharCount - 6);
    }

    // Open the file, read its lines, sort them, and extract a sequence number from the last line
    handler.fileStream.open(handler.fileName);
    if (!handler.fileStream) {
        logError("Cannot open the file");
        return "";
    }
    std::string line;
    while (std::getline(handler.fileStream, line)) {
        ++handler.lineNumber;
        handler.lines.push_back(line);
    }
    sort(handler.lines.begin(), handler.lines.end());

    // Extract a sequence number from the last line
    if (!handler.lines.empty()) {
        std::istringstream iss(handler.lines[handler.lines.size() - 1]);
        std::string token;
        int sequenceNumber = 0;
        while (std::getline(iss, token, ' ')) {
            if (std::isdigit(token[0])) {
                sequenceNumber = std::stoi(token);
                break;
            }
        }
        handler.sequenceNumber = sequenceNumber;
    }

    // Close the file and log the operation end time, user ID, and filename
    handler.fileStream.close();
    logOperation("End", getuid(), handler.fileName);

    return handler.fileName + "_seq" + std::to_string(handler.sequenceNumber);
}

