2. Implement the function to initialize the random number generator:

```c
RAND_CTX *RAND_init(int flags, const unsigned char *user_seed, size_t user_seed_len) {
    RAND_CTX *ctx = (RAND_CTX *)malloc(sizeof(RAND_CTX));
    if (!ctx) return NULL;

    ctx->flags = flags;
    ctx->user_seed = user_seed;
    ctx->user_seed_len = user_seed_len;

    RAND_method *method;
    if (flags & RAND_SRC_SYSTEM) {
        method = RAND_get_default_method();
    } else if (flags & RAND_SRC_USER) {
        method = RAND_user_method();
    } else if (flags & RAND_SRC_BOTH) {
        method = RAND_pollard_diffuni_method(ctx->user_seed, ctx->user_seed_len);
    } else {
        free(ctx);
        ERR_load_CRYPTO_strings();
        return NULL; // Invalid flags
    }

    if (!RAND_method_set_rng((RAND_METHOD *) method, (void *) ctx)) {
        ERR_print_errors_fp(stderr);
        free(ctx);
        return NULL; // Unable to set RNG method
    }

    return ctx;
}
```

3. Implement the function to clean up and disable the random number generator:

```c
void RAND_cleanup(RAND_CTX *ctx) {
    if (ctx->flags & RAND_SRC_USER) free(ctx->user_seed);
    RAND_cleanup_all();
    free(ctx);
}
