        if (it != deviceMap.end()) {
            cache.insert(it->second, device);
        } else {
            if (cache.size() >= cacheSize) {
                cache.pop_front();
                deviceMap.erase(cache.front().id);
            }
            cache.push_back(device);
        }
    }

    bool remove(const std::string& id) {
        auto it = deviceMap.find(id);
        if (it != deviceMap.end()) {
            cache.erase(it->second);
            deviceMap.erase(it);
            return true;
        }
        return false;
    }

    DeviceStatus* find(const std::string& id) const {
        auto it = deviceMap.find(id);
        if (it != deviceMap.end()) {
            return &it->second->front();
        }
        return nullptr;
    }

private:
    void purgeInactiveDevices() {
        std::chrono::system_clock::time_point now = std::chrono::system_clock::now();
        for (auto it = cache.begin(); it != cache.end();) {
            if (now - std::chrono::system_clock::to_time_t(it->lastOnline) > archiveInterval.count()) {
                it = cache.erase(it);
                deviceMap.erase(it->id);
            } else {
                ++it;
            }
        }
    }
};
