    const chaptersVerses = text.match(/(\b(?:[A-Z]{3}) (\d+):?\s*(?:\d+|[A-Za-z,.!\-’]+))/g);

    let bookCounts = _.zipObject(books, Array(books.length).fill(0));
    let chapterVerseCounts = {};

    if (chaptersVerses) {
        chaptersVerses.forEach((match) => {
            const [book, chapterAndRest] = match.split(' ');
            const chapter = parseInt(chapterAndRest.split(':')[0], 10);
            const verse = chapterAndRest.split(':')[1] || '';

            if (isNaN(chapter)) return;

            bookCounts[book]++;
            if (!chapterVerseCounts[book]) chapterVerseCounts[book] = {};
            chapterVerseCounts[book][`${chapter}:${verse}`] = true;
        });
    }

    return {bookCounts, chapterVerseCounts};
}
