public class TransactionProcessor {
    private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd");
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public Map<String, Transaction> processTransactions(List<File> files) {
        Map<String, Transaction> validFiles = new HashMap<>();

        List<ConcurrentLinkedQueue<Transaction>> transactionQueues = new LinkedList<>();
        for (int i = 0; i < Runtime.getRuntime().availableProcessors(); i++) {
            transactionQueues.add(new ConcurrentLinkedQueue<>());
        }

        for (File file : files) {
            if (!file.exists() || !file.isFile()) {
                System.err.println("Invalid or inaccessible file: " + file.getAbsolutePath());
                continue;
            }

            validFiles.put(file.getName(), new Transaction(file));
        }

        for (Map.Entry<String, File> entry : validFiles.entrySet()) {
            EXECUTOR.submit(() -> processTransaction(entry.getValue(), transactionQueues));
        }

        try {
            EXECUTOR.shutdown();
            EXECUTOR.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        for (int i = 0; i < transactionQueues.size(); i++) {
            while (!transactionQueues.get(i).isEmpty()) {
                Transaction transaction = transactionQueues.get(i).poll();
                validFiles.put(transaction.getFile().getName(), transaction);
            }
        }

        return validFiles;
    }

    public static String md5(String str) throws Exception {
        MessageDigest messageDigest = MessageDigest.getInstance("MD5");
        byte[] arrayOfByte = messageDigest.digest(str.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : arrayOfByte) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void processTransaction(File file, List<ConcurrentLinkedQueue<Transaction>> transactionQueues) {
        try (DataInputStream inputStream = new DataInputStream(new BufferedInputStream(new GZIPInputStream(new FileInputStream(file)))) {
            Transaction transaction = new Transaction(inputStream);

            long startTime = System.currentTimeMillis();
            boolean isValid = validateTransaction(transaction);

            if (isValid) {
                transactionQueues.get(transaction.getId().hashCode() % transactionQueues.size()).add(transaction);
            } else {
                logEvent("Transaction validation failed", startTime, System.currentTimeMillis());
            }
        } catch (IOException e) {
            logEvent("Error processing transaction: " + e.getMessage(), 0, System.currentTimeMillis());
        }
    }

    private boolean validateTransaction(Transaction transaction) {
        if (!transaction.getId().matches("\\A[a-zA-Z0-9]{32}\\z")) {
            return false;
        }

        if (!transaction.getSenderAccount().matches("\\A[0-9]+\\z")) {
            return false;
        }

        if (!transaction.getReceiverAccount().matches("\\A[0-9]+\\z")) {
            return false;
        }

        BigDecimal amount = transaction.getAmount();
        if (amount == null || amount.compareTo(BigDecimal.ZERO) <= 0) {
            return false;
        }

        if (!ISO_4217.contains(transaction.getCurrency())) {
            return false;
        }

        try {
            Date transactionDate = DATE_FORMAT.parse(transaction.getTransactionDate());
        } catch (ParseException e) {
            return false;
        }

        if (!Arrays.asList("completed", "pending", "failed", "canceled").contains(transaction.getTransactionStatus())) {
            return false;
        }

        BigDecimal transactionFee = transaction.getTransactionFee();
        if (transactionFee != null && transactionFee.compareTo(BigDecimal.ZERO) < 0) {
            return false;
        }

        if (transaction.getReferenceNumber().length() > 64) {
            return false;
        }

        return true;
    }

    private void logEvent(String message, long startTime, long endTime) {
