                case "expires_in":
                    int expiresIn;
                    return int.TryParse(p.Value.ToString(), out expiresIn) && expiresIn > 0;
                case "token_type":
                    return p.Value.ToString().Equals("Bearer", StringComparison.OrdinalIgnoreCase);
