    public Map<String, Transaction> processTransactions(List<byte[]> transactionFiles) {
        Map<String, Transaction> validTransactions = new HashMap<>();

        for (int i = 0; i < transactionFiles.size(); ) {
            int batchSize = Math.min(MAX_BATCH_SIZE, transactionFiles.size() - i);
            List<byte[]> batch = transactionFiles.subList(i, i + batchSize);
            List<Future<Map<String, Transaction>>> futures = executor.invokeAll(createProcessors(batch));

            for (Future<Map<String, Transaction>> future : futures) {
                try {
                    Map<String, Transaction> batchResults = future.get();
                    validTransactions.putAll(batchResults);
                } catch (Exception e) {
                    logEvent("Error processing transactions: " + e.getMessage());
                }
            }

            i += batchSize;
        }

        return validTransactions;
    }

    private Processor createProcessor(byte[] transactionFile) {
        return () -> {
            Transaction transaction = parseTransaction(transactionFile);
            if (transaction == null) {
                logEvent("Invalid transaction file: " + new String(transactionFile));
                return emptyMap();
            }

            logEvent("Start processing transaction " + transaction.getTransactionId());
            if (!validateTransaction(transaction)) {
                logEvent("Rejected transaction " + transaction.getTransactionId() + ": Invalid or incorrect fields.");
                return emptyMap();
            }

            logEvent("End processing transaction " + transaction.getTransactionId());
            return Map.of(transaction.getTransactionId(), transaction);
        };
    }

    private Processor[] createProcessors(List<byte[]> transactions) {
        Processor[] processors = new Processor[transactions.size()];
        for (int i = 0; i < transactions.size(); i++) {
            processors[i] = createProcessor(transactions.get(i));
        }
        return processors;
    }

