    }

    public NetworkInterface getPrimaryInterface() {
        return findInterfaceByPriority(PRIORITY_PRIMARY);
    }

    public NetworkInterface getSecondaryInterface() {
        return findInterfaceByPriority(PRIORITY_SECONDARY);
    }

    public NetworkInterface getTertiaryInterface() {
        return findInterfaceByPriority(PRIORITY_TERTIARY);
    }

    private NetworkInterface findInterfaceByPriority(Priority priority) {
        return interfaces.values().stream()
                .filter(networkInterface -> networkInterface.getPriority().equals(priority))
                .findFirst()
                .orElse(null);
    }

    public void startMonitoringInterfaces() {
        for (NetworkInterface networkInterface : interfaces.values()) {
            executor.submit(() -> networkInterface.monitorHealth());
        }
    }

    private void loadConfiguration() {
        try {
            JSONObject config = cloudConfigService.fetchConfiguration();
            JSONArray interfaceArray = config.getJSONArray("interfaces");
            for (int i = 0; i < interfaceArray.length(); i++) {
                JSONObject interfaceObj = interfaceArray.getJSONObject(i);
                NetworkInterface networkInterface = new NetworkInterface(interfaceObj);
                addInterface(networkInterface);
            }
        } catch (IOException | JSONException e) {
            // Handle exceptions gracefully, potentially retrying later or using cached data
        }
    }

    public String getConfigurationChecksum() {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] configBytes = cloudConfigService.fetchConfiguration().toString().getBytes();
            digest.update(configBytes);
            BigInteger bigInt = new BigInteger(1, digest.digest());
            return bigInt.toString(16);
        } catch (NoSuchAlgorithmException | IOException e) {
            // Handle exceptions gracefully
            return null;
        }
    }
}
```

