  // Remove punctuation and convert text to lowercase
  const cleanedText = text.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()\[\]\\|@\+<>\"'\s]+/g, '').toLowerCase();

  // Split the text into individual words and loop through them
