    unsigned char iv[AES_BLOCK_SIZE];
} aes256gcm_ctx;

int generate_salt(unsigned char *salt, size_t salt_len) {
    if (salt_len < AES_BLOCK_SIZE) return 1; // Minimum required length is AES block size (16 bytes)
    rand_bytes(salt, salt_len);
    return 0;
}

aes256gcm_ctx *aes256gcm_init(const char *password, const unsigned char *iv, size_t iv_len, unsigned int iterations) {
    if (!password || strlen(password) < AES_KEYSIZE / 8 + SHA256_DIGEST_LENGTH) return NULL; // Minimum required password length is AES key size (32 bytes) + SHA-256 digest length (32 bytes)

    unsigned char derived_key[AES_KEYSIZE];
    unsigned char salt[AES_BLOCK_SIZE];
    if (generate_salt(salt, sizeof(salt))) return NULL; // Failed to generate salt

    const EVP_CIPHER *cipher = EVP_aes_256_gcm();
    int key_len = AES_KEYSIZE;

    if (1 != EVP_PBKDF2(password, strlen(password), salt, sizeof(salt), iterations, EVP_sha256(), derived_key, &key_len)) return NULL; // Failed to derive key with PBKDF2-HMAC-SHA256

    aes256gcm_ctx *ctx = malloc(sizeof(aes256gcm_ctx));
    if (!ctx) return NULL;

    memset(ctx->iv, 0, sizeof(ctx->iv));
    if (iv && iv_len < AES_BLOCK_SIZE) iv_len = AES_BLOCK_SIZE;
    if (iv_len > 0) memcpy(ctx->iv, iv, iv_len);

    AES_set_encrypt_key(derived_key, key_len * 8, &ctx->cipher);
    return ctx;
}

void aes256gcm_cleanup(aes256gcm_ctx *ctx) {
    if (!ctx) return;
    free(ctx);
}
