['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int id;
    int timeout;
    bool active;
    time_t creation_time;
} Session;

typedef struct node {
    Session session;
    struct node *next;
} Node;

Node* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_t expiration_thread;

void add_session(int id, int timeout) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
    new_node->session.id = id;
    new_node->session.timeout = timeout;
    new_node->session.active = true;
    new_node->session.creation_time = time(NULL);
    new_node->next = head;
    head = new_node;
}

void update_session(int id, int timeout) {
    Node *current = head;
    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (current->session.id == id) {
            current->session.timeout = timeout;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

void update_status(int id, bool status) {
    Node *current = head;
    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (current->session.id == id) {
            current->session.active = status;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

Session get_session(int index) {
    Node *current = head;
    Session session;
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < index && current != NULL; ++i)
        current = current->next;
    if (current == NULL) {
        fprintf(stderr, "Index out of range\n");
        session.id = -1;
    } else {
        session = current->session;
    }
    pthread_mutex_unlock(&list_lock);
    return session;
}

Session get_session_by_id(int id) {
    Node *current = head;
    Session session;
    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (current->session.id == id) {
            session = current->session;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
    return session;
}

void close_inactive_sessions() {
    time_t now = time(NULL);
    Node *current = head;
    Node *prev = NULL;
    while (current != NULL) {
        if ((now - current->session.creation_time) > current->session.timeout) {
            if (prev == NULL)
                head = current->next;
            else
                prev->next = current->next;
            free(current);
        } else {
            prev = current;
        }
        current = current->next;
    }
}

void run_expiration_thread() {
    while (true) {
        close_inactive_sessions();
        sleep(1);
    }
}
```

This code defines a `Session` struct for managing user sessions, along with a dynamic list using linked nodes. The provided functions allow adding new sessions, updating session details, and retrieving session information based on index or ID. The function to close inactive sessions has been implemented, but it should be run in a background thread (e.g., using pthreads).

The code also includes error handling for out-of-memory situations and index out of range errors.']

