#include <boost/serialization/access.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/archive/text_iarchive.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/circular_buffer.hpp>

class AuditEvent {
public:
    enum EventType { LOGIN, LOGOUT, TRANSACTION, ERROR };
    EventType type;
    std::time_t timestamp;
    int user_id;
    std::string ip_address;
    std::string message;

    AuditEvent(EventType t, std::time_t timestmp, int uid, const std::string& ip, const std::string& msg) : type(t), timestamp(timestmp), user_id(uid), ip_address(ip), message(msg) {}

    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive & ar, const unsigned int version) {
        ar & type & timestamp & user_id & ip_address & message;
    }
};

class AuditLogManager {
private:
    std::unordered_map<EventType, std::deque<AuditEvent>> events_;
    std::unordered_map<std::pair<EventType, int>, boost::circular_buffer<const AuditEvent*>> cache_;
    std::mutex mtx_;
    size_t max_size_;
    std::chrono::steady_clock::time_point last_prune_;
    constexpr static double CACHE_RATIO = 0.1;

public:
    AuditLogManager(size_t maxSize) : max_size_(maxSize), last_prune_(std::chrono::steady_clock::now()) {}

    void insert(const AuditEvent& event) {
        std::lock_guard<std::mutex> lock(mtx_);
        events_[event.type].push_back(event);
        pruneIfNeeded();
        cacheUpdate(event);
    }

    const AuditEvent* find(const EventType& type, int userID, std::time_t timestamp) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = events_.find(type);
        if (it != events_.end()) {
            for (auto& event : it->second) {
                if (event.timestamp == timestamp && event.user_id == userID) {
                    return &event;
                }
            }
        }
        return nullptr;
    }

    void remove(const EventType& type, int userID, std::time_t timestamp) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = events_.find(type);
        if (it != events_.end()) {
            for (auto iter = it->second.begin(); iter != it->second.end(); ++iter) {
                if ((*iter).timestamp == timestamp && (*iter).user_id == userID) {
                    iter = it->second.erase(iter);
                    pruneIfNeeded();
                    break;
                }
            }
        }
    }

    void serializeToFile(const std::string& filename) {
        std::ofstream outfile(filename, std::ios::binary | std::ios::out);
        boost::archive::text_oarchive oarch(outfile);
        for (auto& pair : events_) {
            oarch & boost::serialization::make_nvp("EventType_" + std::to_string(pair.first), pair.second);
        }
    }

    void deserializeFromFile(const std::string& filename) {
        std::ifstream infile(filename, std::ios::binary | std::ios::in);
        boost::archive::text_iarchive iarch(infile);
        for (; events_.empty(); ) {
            try {
