                iarch & events;
                for (auto& event : events) {
                    insert(event);
                }
            } catch (const std::exception& e) {
                // Handle exception if any
            }
        }
    }

private:
    void pruneIfNeeded() {
        if ((std::chrono::steady_clock::now() - last_prune_) > std::chrono::seconds(60)) {
            for (auto& pair : events_) {
                pair.second.pop_front();
                if (pair.second.empty()) {
                    events_.erase(pair.first);
                }
            }
            last_prune_ = std::chrono::steady_clock::now();
        }
    }

    void cacheUpdate(const AuditEvent& event) {
        if (cache_.find({event.type, event.user_id}) == cache_.end()) {
            cache_[{event.type, event.user_id}] = boost::circular_buffer<const AuditEvent*>(CACHE_RATIO * events_[event.type].size());
        }
        auto& cb = cache_[{event.type, event.user_id}];
        if (cb.capacity() > 0) {
            cb.push_back(&event);
            while (cb.size() > cb.capacity()) {
                delete [] *cb.front();
                cb.pop_front();
            }
        }
    }
};
```
