typedef struct {
    EVP_CIPHER_CTX *aes;
    EVP_CIPHER_CTX *camellia;
    EVP_MD_CTX *md5;
    EVP_MD_CTX *sha1;
    EVP_MD_CTX *sha256;
    EVP_MD_CTX *sha512;
    RSA *rsa;
    HMAC_CTX *hmac_sha256;
    HMAC_CTX *hmac_sha512;
} crypt_context;

crypt_context* create_crypt_context() {
    crypt_context *ctx = malloc(sizeof(crypt_context));
    ctx->aes = NULL;
    ctx->camellia = NULL;
    ctx->md5 = NULL;
    ctx->sha1 = NULL;
    ctx->sha256 = NULL;
    ctx->sha512 = NULL;
    ctx->rsa = NULL;
    ctx->hmac_sha256 = NULL;
    ctx->hmac_sha512 = NULL;
    return ctx;
}

void destroy_crypt_context(crypt_context *ctx) {
    if (ctx->aes != NULL) EVP_CIPHER_CTX_free(ctx->aes);
    if (ctx->camellia != NULL) EVP_CIPHER_CTX_free(ctx->camellia);
    if (ctx->md5 != NULL) EVP_MD_CTX_free(ctx->md5);
    if (ctx->sha1 != NULL) EVP_MD_CTX_free(ctx->sha1);
    if (ctx->sha256 != NULL) EVP_MD_CTX_free(ctx->sha256);
    if (ctx->sha512 != NULL) EVP_MD_CTX_free(ctx->sha512);
    if (ctx->rsa != NULL) RSA_free(ctx->rsa);
    if (ctx->hmac_sha256 != NULL) HMAC_CTX_free(ctx->hmac_sha256);
    if (ctx->hmac_sha512 != NULL) HMAC_CTX_free(ctx->hmac_sha512);
    free(ctx);
}

bool init_crypt_context(crypt_context *ctx, const char* key, const char* iv, const char* algorithm) {
    // Initialize AES context
    if (strcmp(algorithm, "AES") == 0) {
        ctx->aes = AES_set_encrypt_key((const unsigned char*) key, 128, NULL);
        if (ctx->aes == NULL) return false;
        AES_ctx_iv_length(ctx->aes);
        if (AES_init_cbf(ctx->aes, (unsigned char*) key, (unsigned char*) iv, NULL)) return false;
    }

    // Initialize Camellia context
    else if (strcmp(algorithm, "Camellia") == 0) {
        ctx->camellia = CAMELLIA_set_encrypt_key((const unsigned char*) key, 128, NULL);
        if (ctx->camellia == NULL) return false;
        CAMELLIA_ctx_iv_length(ctx->camellia);
        if (CAMELLIA_init_cbf(ctx->camellia, (unsigned char*) key, (unsigned char*) iv, NULL)) return false;
    }

    // Initialize MD5 context
    ctx->md5 = MD5_CTX_new();
    if (ctx->md5 == NULL) return false;

    // Initialize SHA1 context
    ctx->sha1 = SHA1_CTX_new();
    if (ctx->sha1 == NULL) return false;

    // Initialize SHA256 context
    ctx->sha256 = SHA256_CTX_new();
    if (ctx->sha256 == NULL) return false;

    // Initialize SHA512 context
    ctx->sha512 = SHA512_CTX_new();
    if (ctx->sha512 == NULL) return false;

    return true;
}

bool derive_rsa_key(crypt_context *ctx, const char* private_key, const char* public_key) {
    ctx->rsa = PEM_read_RSAPrivateKey(private_key, NULL, NULL, NULL);
    if (ctx->rsa == NULL) return false;

    RSA *tmp_pub_key = PEM_read_RSA_PUBKEY(public_key, NULL, NULL, NULL);
    if (tmp_pub_key == NULL) return false;

    if (!RSA_check_key(ctx->rsa, tmp_pub_key)) {
        RSA_free(tmp_pub_key);
        RSA_free(ctx->rsa);
        return false;
    }

    RSA_free(tmp_pub_key);
    return true;
}

// Implement HMAC-SHA256 and HMAC-SHA512 functions here...

void encrypt(const crypt_context *ctx, unsigned char* buffer, size_t length) {
    // Encrypt buffer using AES or Camellia context
    AES_cipher(ctx->aes, (unsigned char*) buffer, (unsigned char*) buffer);
}

void decrypt(const crypt_context *ctx, unsigned char* buffer, size_t length) {
    // Decrypt buffer using AES or Camellia context
    AES_decrypt((unsigned char*) buffer, (unsigned char*) buffer);
}

void digest(const crypt_context *ctx, unsigned char* buffer, size_t length, unsigned char* output) {
    // Compute digest over buffer using MD5, SHA1, SHA256 or SHA512 context
    if (ctx->md5 != NULL) MD5_update(ctx->md5, buffer, length);
    if (ctx->sha1 != NULL) SHA1_Update(ctx->sha1, buffer, length);
    if (ctx->sha256 != NULL) SHA256_Update(ctx->sha256, buffer, length);
    if (ctx->sha512 != NULL) SHA512_Update(ctx->sha512, buffer, length);
    if (ctx->md5 != NULL) MD5_final(output, ctx->md5);
    if (ctx->sha1 != NULL) SHA1_final(output, ctx->sha1);
    if (ctx->sha256 != NULL) SHA256_final(output, ctx->sha256);
    if (ctx->sha512 != NULL) SHA512_final(output, ctx->sha512);
}

void sign(const crypt_context *ctx, unsigned char* message, size_t length, unsigned char* signature) {
    // Sign message using RSA with SHA1 context
    int len = RSA_size(ctx->rsa);
    unsigned char *sig = malloc(len);
    if (!RSA_sign(NID_sha1, message, length, sig, len, ctx->rsa)) {
        ERR_print_errors_fp(stderr);
        free(sig);
        return;
    }
    memcpy(signature, sig, len);
    free(sig);
}

bool verify_sign(const crypt_context *ctx, const unsigned char* message, size_t length, const unsigned char* signature) {
    // Verify signature using RSA with SHA1 context
    int len = RSA_size(ctx->rsa);
    unsigned char *sig = malloc(len);
    if (!RSA_verify(NID_sha1, message, length, sig, len, ctx->rsa)) {
        ERR_print_errors_fp(stderr);
        free(sig);
        return false;
    }
    if (memcmp(signature, sig, len) != 0) {
        free(sig);
        return false;
    }
    free(sig);
    return true;
}
```

