#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Item {
    char *name;
    int value;
} Item;

typedef struct Node {
    Item item;
    struct Node *next;
    pthread_mutex_t mutex;
} Node;

Node* create_node(char *name, int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->item.name = name;
    node->item.value = value;
    node->next = NULL;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void delete_node(Node **head, Node *node) {
    if (*head == node) {
        *head = node->next;
        free(node);
    } else {
        Node *temp = *head;
        while (temp->next != node) temp = temp->next;
        temp->next = node->next;
        free(node);
    }
}

Node* resize_list(Node **head, size_t new_capacity) {
    if (new_capacity <= 0) return *head;

    Node *new_head = NULL, *temp = *head, *prev = NULL;
    for (size_t i = 0; i < new_capacity || temp != NULL; ++i) {
        if (temp == NULL) {
            temp = create_node("", 0);
            prev->next = temp;
            prev = temp;
            continue;
        }
        prev = temp;
        temp = temp->next;
    }

    *head = new_head;
    return *head;
}

void update_values(Node **head, unsigned int min, unsigned int max) {
    if (*head == NULL) return;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    Node *temp = *head;
    while (temp != NULL) {
        pthread_mutex_lock(&(temp->mutex));
        temp->item.value = rand() % (max - min + 1) + min;
        pthread_mutex_unlock(&(temp->mutex));
        temp = temp->next;
    }
    pthread_mutex_destroy(&lock);
}

void insert_item(Node **head, char *name, int value) {
    Node* new_node = create_node(name, value);
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    Node* temp = *head;
    while (temp->next != NULL) temp = temp->next;
    temp->next = new_node;
    pthread_mutex_destroy(&lock);
}

size_t get_collection_size(Node *head) {
    size_t count = 0;
    for (Node* temp = head; temp != NULL; temp = temp->next) ++count;
    return count;
}

void log_metrics(const char *msg, Node *head) {
    printf("%s", msg);
    size_t size = get_collection_size(head);
    printf("Size: %zu\n", size);
}

void integrity_check(Node *head) {
    if (head == NULL) return;

    Node* temp = head;
    while (temp != NULL) {
        Node* current = temp;
        temp = temp->next;

        pthread_mutex_lock(&(current->mutex));
        if (current->item.name == NULL || current->next == NULL) {
            printf("Integrity error: Corrupted node.\n");
            return;
        }
        pthread_mutex_unlock(&(current->mutex));
    }
}

void destroy_collection(Node **head) {
    Node *temp = *head, *next;
    while (temp != NULL) {
        next = temp->next;
        free(temp);
        temp = next;
    }
    *head = NULL;
}
```

