#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    char *key;
    double value;
    struct Record *next;
} Record;

Record* create_record(const char *key) {
    Record *new_record = (Record *) malloc(sizeof(Record));
    new_record->key = strdup(key);
    new_record->value = (double) rand() / RAND_MAX * 100.0; // Generate random value within [0, 100] range
    new_record->next = NULL;
    return new_record;
}

void resize(Record **head, size_t new_size) {
    Record *new_head = (Record *) realloc(*head, new_size * sizeof(Record));
    if (!new_head) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    *head = new_head;
}

Record* find(Record *head, const char *key) {
    for (Record *current = head; current != NULL; current = current->next) {
        if (strcmp(current->key, key) == 0) {
            return current;
        }
    }
    return NULL;
}

void insert(Record **head, Record *new_record) {
    if (!*head) {
        *head = new_record;
        return;
    }

    Record *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_record;
}

void delete(Record **head, const char *key) {
    if (!*head) {
        return;
    }

    if ((*head)->key == key) {
        Record *temp = *head;
        *head = (*head)->next;
        free(temp->key);
        free(temp);
        return;
    }

    Record *current = *head;
    while (current->next != NULL && current->next->key != key) {
        current = current->next;
    }

    if (current->next == NULL) {
        return;
    }

    Record *temp = current->next;
    current->next = current->next->next;
    free(temp->key);
    free(temp);
}

void manage_records(size_t initial_size, size_t records_count, double min_value, double max_value) {
    srand(time(NULL));
    Record *head = NULL;
    size_t capacity = initial_size;

    for (size_t i = 0; i < records_count; ++i) {
        if (capacity == i) {
            capacity *= 2;
            resize(&head, capacity);
        }

        Record *new_record = create_record(NULL);
        new_record->value = min_value + (max_value - min_value) * rand() / RAND_MAX;
        insert(&head, new_record);
    }

    // Perform operations on the dynamic collection here

    while (head != NULL) {
        Record *temp = head;
        head = head->next;
        free(temp->key);
        free(temp);
    }
}
