    User *current = *head;
    if (!*head) {
        *head = new_user;
        return *head;
    }

    User *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->key, new_user->key) == 0) {
            if (new_user->value > current->value)
                current->value = new_user->value;
            return *head;
        }
        prev = current;
        current = current->next;
    }

    prev->next = new_user;
    return *head;
