    User *new_user = (User*) malloc(sizeof(User));
    new_user->key = key;
    new_user->value = value;
    new_user->next = NULL;
    return new_user;
}

void delete_user(User **head, User *user) {
    if (*head == user) {
        *head = user->next;
    } else {
        User *current = *head;
        while (current->next != user) {
            current = current->next;
        }
        current->next = user->next;
    }
    free(user);
}

User* find_user(User **head, char *key) {
    User *current = *head;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void resize_list(User **head, int new_size) {
    User *new_head = malloc(new_size * sizeof(User));
    User **old_head = head, **new_tail = &new_head;
    for (int i = 0; i < new_size && *old_head != NULL; i++) {
        *new_tail = *old_head;
        old_head = &(*old_head)->next;
        new_tail = &(*new_tail)->next;
    }
    if (*old_head != NULL) {
        *new_tail = *old_head;
    }
    free(*head);
    *head = new_head;
}

void shuffle_values(User **head, int range_min, int range_max) {
    srand(time(NULL));
    User *current = *head;
    while (current != NULL) {
        double value = ((double) rand() / RAND_MAX) * (range_max - range_min) + range_min;
        current->value = value;
        current = current->next;
    }
}

