    password = json_string_nocopy("password", request, strlen("password"));
    sub_action = json_string_nocopy("sub_action", request, strlen("sub_action"));

    if (!json_object_has_member(request, "id") && !json_object_has_member(request, "sub_action")) {
        json_decref(root);
        return json_pack({"message", "error", "Missing required keys: id or sub_action."});
    }

    if (!json_object_has_member(request, "name") || !json_object_has_member(request, "email") || !json_object_has_member(request, "password")) {
        json_decref(root);
        return json_pack({"message", "error", "Missing required keys: name, email, or password."});
    }

    User *head = NULL;
    int new_size = 10; // Initial number of users

    if (json_object_has_member(request, "id")) {
        User *user = find_user(&head, json_string_value(id));
        if (!user) {
            json_decref(root);
            return json_pack({"message", "error", "User not found."});
        }

        if (json_object_has_member(request, "sub_action") && json_string_value(sub_action) == "delete") {
            delete_user(&head, user);
            json_decref(root);
            return json_pack({"message", "success"});
        }
    } else {
        if (head->next == NULL && head->value >= new_size) {
            resize_list(&head, new_size * 2);
            shuffle_values(head, 0, 100); // Update values with random numbers within [0, 100]
        }
    }

    User *new_user = create_user(json_string_value(email), rand() % 100 + 50);
    new_user->next = head;
    head = new_user;

    json_decref(root);
    return json_pack({"message", "success"});
}
