UserCollection* user_collection_init(int capacity) {
    UserCollection *coll = malloc(sizeof(UserCollection));
    coll->head = NULL;
    coll->tail = NULL;
    coll->capacity = capacity;
    coll->size = 0;
    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

User* user_create() {
