void user_collection_push(UserCollection *coll, User *user) {
    pthread_mutex_lock(&coll->lock);
    if (coll->size >= coll->capacity && coll->size > 0) {
        User *new_head = realloc(coll->head, sizeof(User) * (coll->capacity * 2));
        memmove(new_head + coll->capacity, coll->head, sizeof(User) * coll->capacity);
        free(coll->head);
        coll->head = new_head;
        coll->capacity *= 2;
