    if (!coll->head) {
        coll->head = user;
    } else {
        coll->tail->next = user;
    }
    coll->tail = user;
    coll->size++;
    pthread_mutex_unlock(&coll->lock);
}

User* user_collection_pop(UserCollection *coll) {
    User *temp = coll->head;
    if (!temp) return NULL;
    coll->head = temp->next;
    coll->size--;
    return temp;
}

