int json_validate(const char *json) {
    json_t *root = json_loads(json, JSON_DECODE_ANY);
    if (!root || !json_is_object(root)) return 0;

    const char *token_type = json_object_get(root, "token_type");
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    const char *access_token = json_string_value(json_object_get(root, "access_token"));
    size_t access_token_len = strlen(access_token);

    if (strlen(token_type) != 7 || strncmp(token_type, "Bearer", 7)) return false;
    if (expires_in <= 0 || access_token_len > 256) return false;
    const char *refresh_token = json_object_get_ex(root, "refresh_token");

