node* create_node(const char* name, int value) {
    node* new_node = (node*)malloc(sizeof(node));
    strncpy(new_node->data.name, name, sizeof(new_node->data.name));
    new_node->data.value = value;
    new_node->next = NULL;
    return new_node;
}

void resize_collection(node** collection, size_t* capacity, size_t* size) {
    if (*size >= *capacity) {
        *capacity *= 2;
        node** temp_collection = (node**)realloc(*collection, sizeof(node) * *capacity);
        if (!temp_collection) {
            fprintf(stderr, "Out of memory\n");
            return;
        }
        *collection = temp_collection;
    }
}

void initialize_collection(node** collection, size_t capacity, const char* name, int value, int range) {
    resize_collection(collection, &capacity, 0);
    for (size_t i = 0; i < capacity; ++i) {
        item new_item = {name, rand() % range};
        (*collection)[i] = create_node(new_item.name, new_item.value);
    }
}
