```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <picojson.h>

typedef struct {
    char name[256];
    time_t timestamp;
    int priority;
    enum { PENDING, IN_PROGRESS, COMPLETED } status;
} task;

struct collection {
    size_t capacity;
    size_t length;
    task* tasks;
};

void collection_init(struct collection *collection, size_t initial_capacity) {
    collection->capacity = initial_capacity;
    collection->length = 0;
    collection->tasks = malloc(initial_capacity * sizeof(task));
}

int collection_parse_json(const char* json, struct collection *collection) {
    picojson_value v;
    int ret = picojson_parse((const char*) json, &v);
    if (ret <= 0) {
        printf("Error parsing JSON: %s\n", picojson_error(ret));
        return 0;
    }

    if (!picojson_is_object(v)) {
        printf("JSON object expected.\n");
        return 0;
    }

    struct task new_task = {};
    const char *name, *due_date, *priority, *status;

    for (size_t i = 0; i < picojson_count(v); ++i) {
        const char* key = picojson_key(picojson_get(v, i));
        if (!strcmp(key, "task_name")) {
            ret = picojson_get_string(picojson_get(v, i), &new_task.name);
            if (ret <= 0) {
                printf("Error getting task name: %s\n", picojson_error(ret));
                return 0;
            }
        } else if (!strcmp(key, "due_date")) {
            ret = picojson_get_string(picojson_get(v, i), &due_date);
            if (ret <= 0) {
                printf("Error getting due date: %s\n", picojson_error(ret));
                return 0;
            }
        } else if (!strcmp(key, "priority")) {
            ret = picojson_get_number(picojson_get(v, i), (double*)&new_task.priority);
            if (ret <= 0) {
                printf("Error getting priority: %s\n", picojson_error(ret));
                return 0;
            }
            new_task.priority = (int)new_task.priority;
        } else if (!strcmp(key, "status")) {
            ret = picojson_get_string(picojson_get(v, i), &status);
            if (ret <= 0) {
                printf("Error getting status: %s\n", picojson_error(ret));
                return 0;
            }
            new_task.status = PENDING; // Default status
            if (!strcmp(status, "In Progress")) {
                new_task.status = IN_PROGRESS;
            } else if (!strcmp(status, "Completed")) {
                new_task.status = COMPLETED;
            } else {
                printf("Invalid status: '%s'\n", status);
                return 0;
            }
        }
    }

    collection_add(collection, &new_task);
    return 1;
}

void collection_sort(struct collection* collection) {
    // Insertion sort or another efficient sorting algorithm based on the number of tasks
    for (size_t i = 1; i < collection->length; ++i) {
        task temp = collection->tasks[i];
        size_t j = i - 1;
        while (j >= 0 && priority_compare(temp.priority, collection->tasks[j].priority)) {
            collection->tasks[j + 1] = collection->tasks[j];
            --j;
        }
        collection->tasks[j + 1] = temp;
    }
}

void priority_compare(int a, int b) {
    if (a < b) {
        printf("Task A is more urgent than Task B.\n");
    } else if (a > b) {
        printf("Task B is more urgent than Task A.\n");
    } else {
        printf("Tasks A and B have the same priority.\n");
    }
}

void collection_add(struct collection *collection, const task* new_task) {
    if (collection->length >= collection->capacity) {
        collection->capacity *= 2;
        collection->tasks = realloc(collection->tasks, collection->capacity * sizeof(task));
    }

    time_t now = time(NULL);
    new_task->timestamp = now;

    // Update priority based on timestamp
    int priority_offset = (now - new_task->timestamp) / TASK_LIFESPAN;
    new_task->priority += priority_offset * PRIORITY_DECREMENT;

    collection->tasks[collection->length] = *new_task;
    ++(collection->length);
    collection_sort(collection);
}

