```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char name[256];
    time_t timestamp;
    int priority;
} Task;

struct TaskCollection {
    size_t capacity;
    size_t size;
    Task* tasks;
};

// Function to initialize a new task collection with the given capacity
TaskCollection* task_collection_init(size_t capacity) {
    TaskCollection* tc = malloc(sizeof(TaskCollection));
    if (!tc) return NULL;
    tc->capacity = capacity;
    tc->size = 0;
    tc->tasks = calloc(capacity, sizeof(Task));
    if (!tc->tasks) {
        free(tc);
        return NULL;
    }
    return tc;
}

// Function to resize the task collection
void task_collection_resize(TaskCollection* tc, size_t new_capacity) {
    if (new_capacity <= tc->size) return;
    Task* temp = realloc(tc->tasks, new_capacity * sizeof(Task));
    if (!temp) {
        fprintf(stderr, "Failed to resize task collection\n");
        exit(EXIT_FAILURE);
    }
    tc->tasks = temp;
    tc->capacity = new_capacity;
}
```

