    int capacity;
    int num_states;
    Product **states;
    pthread_mutex_t mutex;
} FSA;

void InitializeFSA(FSA *fsa, int capacity) {
    fsa->capacity = capacity;
    fsa->num_states = 0;
    fsa->states = calloc(capacity, sizeof(Product*));
    fsa->mutex = PTHREAD_MUTEX_INITIALIZER;
