            product->price += (rand() % MAX_PRICE_VARIATION);

            pthread_mutex_lock(&fsa.mutex);
            if (!fsa.num_states || strcmp(product->key, fsa.states[0]->key)) {
                ResizeFSA(&fsa);
            }
            fsa.states[fsa.num_states++] = product;
            pthread_mutex_unlock(&fsa.mutex);

            SaveProduct(product); // Call your external inventory management function here
        } else if (sub_action == 'D') {
            int id = json_object_get_int(json_object_object_get(req, "id"));
            Product *product;

            pthread_mutex_lock(&fsa.mutex);
            for (int i = 0; i < fsa.num_states; ++i) {
                if (fsa.states[i]->key[0] == id) {
                    product = fsa.states[i];
                    memmove(fsa.states + i, fsa.states + i + 1, --fsa.num_states * sizeof(Product*));
                    free(product->info);
                    free(product);
                    break;
                }
            }
            pthread_mutex_unlock(&fsa.mutex);

            if (product) {
                DeleteProduct(product); // Call your external inventory management function here
            }
        }

        json_object *response = json_object_new_object();
        if (!product || !id) {
            json_object_object_add(response, "message", json_object_new_string("error"));
        } else {
            json_object_object_add(response, "message", json_object_new_string("success"));
        }
        printf("%s\n", json_object_to_json_string(response));
        gcry_cipher_free(response);
    }

    return 0;
}
```
