['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char name[256];
    int value;
    float priority;
} item;

// Custom serialization format (JSON-like)
#define SERIALIZATION_SIZE 256
void serialize(const item* item, char serialized[]) {
    snprintf(serialized, SERIALIZATION_SIZE, "{\"name\":\"%s\", \"value\":%d,\"priority\":%.2f}", item->name, item->value, item->priority);
}

void deserialize(item* item, const char serialized[]) {
    int start = 0;
    int end;
    if ((end = strcspn(serialized + start, "\":")) > SERIALIZATION_SIZE) return;
    memcpy(item->name, serialized + start, end);
    start += end;

    if ((end = strcspn(serialized + start, ",")) > SERIALIZATION_SIZE) return;
    sscanf(serialized + start, " %d", &item->value);
    start += end;

    if ((end = strcspn(serialized + start, "\"")) > SERIALIZATION_SIZE) return;
    item->priority = atof(serialized + start);
    start += end;
}

void updateValueAndPriority(item* items, size_t count, float weight) {
    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += items[i].priority * weight;
    }

    if (sum == 0.0f) return;

    for (size_t i = 0; i < count; ++i) {
        items[i].value = rand() % 100 + 1;
        items[i].priority = (items[i].priority * weight + 1.0f) / (sum + count);
    }
}

item* createItemList(size_t initialSize, size_t itemCount) {
    item* items = malloc(initialSize * sizeof(item));
    if (!items) return NULL;

    for (size_t i = 0; i < itemCount; ++i) {
        items[i].value = rand() % 100 + 1;
        strcpy(items[i].name, "Item"); // Default name
        items[i].priority = 1.0f / (itemCount + 1);
    }

    return realloc(items, itemCount * sizeof(item));
}

void destroyItemList(item* items, size_t count) {
    free(items);
}

void saveItemsToFile(const char fileName[], const item* items, size_t count) {
    FILE* file = fopen(fileName, "w");
    if (!file) return;

    for (size_t i = 0; i < count; ++i) {
        char serialized[SERIALIZATION_SIZE];
        serialize(&items[i], serialized);
        fprintf(file, "%s\n", serialized);
    }

    fclose(file);
}

void loadItemsFromFile(char fileName[], item* items, size_t count) {
    FILE* file = fopen(fileName, "r");
    if (!file) return;

    char line[SERIALIZATION_SIZE];
    for (size_t i = 0; i < count; ++i) {
        if (!fgets(line, sizeof(line), file)) break;

        item tmpItem;
        deserialize(&tmpItem, line);
        strcpy(items[i].name, tmpItem.name);
        items[i].value = tmpItem.value;
        items[i].priority = tmpItem.priority;
    }

    fclose(file);
}
```

