#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Item {
    char name[256];
    int value;
    float priority;
} Item;

typedef struct Collection {
    size_t capacity, size;
    Item* items;
} Collection;

Collection* create_collection(size_t initial_size) {
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) return NULL;
    collection->capacity = initial_size;
    collection->size = 0;
    collection->items = calloc(initial_size, sizeof(Item));
    if (!collection->items) {
        free(collection);
        return NULL;
    }
    return collection;
}

void resize_collection(Collection* collection, size_t new_capacity) {
    Item* temp = realloc(collection->items, new_capacity * sizeof(Item));
    if (!temp) return;
    collection->items = temp;
    collection->capacity = new_capacity;
}

void insert_item(Collection* collection, const char* name, int min_value, int max_value, float priority_weight) {
    if (collection->size == collection->capacity) resize_collection(collection, collection->capacity * 2);
    Item* item = &collection->items[collection->size];
    strcpy(item->name, name);
    item->value = rand() % (max_value - min_value + 1) + min_value;
    float sum = 0.0f, count = 0.0f;
    for (size_t i = 0; i < collection->size; ++i) {
        sum += collection->items[i].priority * priority_weight;
        count += priority_weight;
    }
    item->priority = sum / count + 1.0f; // Adding 1.0 to avoid division by zero
}

void save_collection(const Collection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    size_t version = 1; // Version number for serialization format compatibility
    fwrite(&version, sizeof(size_t), 1, file);
    fwrite(collection->items, sizeof(Item), collection->size, file);
    fclose(file);
}

Collection* load_collection(const char* filename) {
    Collection* collection = create_collection(8);
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t version;
    fread(&version, sizeof(size_t), 1, file);

    fread(collection->items, sizeof(Item), 8, file); // Load a default set of items (modify as needed based on the serialized format version)

    while (!feof(file)) {
        Item item;
        fread(&item, sizeof(Item), 1, file);
        insert_item(collection, item.name, 0, INT32_MAX, item.priority); // Handle missing or incompatible data (modify as needed based on the serialized format version)
    }
    fclose(file);
    return collection;
}
```

