typedef struct {
    int *tasks;
    size_t numTasks;
} Task;

typedef struct {
    Task **processors;
    size_t numProcessors;
    size_t maxMemoryUsage; // in bytes
    size_t totalAllocated; // in bytes
} ProcessorArray;

ProcessorArray* createProcessorArray(size_t numProcessors, size_t maxMemoryUsage) {
    if (numProcessors == 0 || maxMemoryUsage == 0)
        return NULL;

    ProcessorArray *result = malloc(sizeof(ProcessorArray));
    result->numProcessors = numProcessors;
    result->maxMemoryUsage = maxMemoryUsage;
    result->totalAllocated = 0;

    // Allocate memory for the array of processors
    result->processors = calloc(numProcessors, sizeof(Task*));
    if (!result->processors) {
        free(result);
        return NULL;
    }

    for (size_t i = 0; i < numProcessors; ++i) {
        // Allocate memory for the array of tasks for each processor
        result->processors[i] = calloc(numTasksPerProcessor(result), sizeof(Task));
        if (!result->processors[i]) {
            freeMemory(result);
            return NULL;
        }
    }

    return result;
}

size_t numTasksPerProcessor(const ProcessorArray *array) {
    size_t maxMemoryUsage = array->maxMemoryUsage / (sizeof(Task) * array->numProcessors);
    return (MAX_ALLOWABLE_TASKS - 1) < maxMemoryUsage ? MAX_ALLOWABLE_TASKS : maxMemoryUsage;
}

void initializeTasks(ProcessorArray *array, int seed) {
    for (size_t i = 0; i < array->numProcessors; ++i) {
        for (size_t j = 0; j < numTasksPerProcessor(array); ++j) {
            srand(seed + i * array->numProcessors + j);

            // Initialize int field with a random integer
            array->processors[i][j].tasks[0] = rand() % 2001 - 1000;

            // Initialize float field with a random floating-point number
            array->processors[i][j].tasks[1] = (float)(rand() % 2001) / 10.0 - 1000.0;

            // Initialize char field with a random character
            array->processors[i][j].tasks[2] = (char)(rand() % 26 + 'a');
        }
    }
}

void modifyTask(ProcessorArray *array, size_t processorIndex, size_t taskIndex, int fieldIndex, const void *value) {
    if (fieldIndex < 3 && array->processors[processorIndex][taskIndex].tasks) {
        switch (fieldIndex) {
            case 0:
                array->processors[processorIndex][taskIndex].tasks[0] = *(const int *)value;
                break;
            case 1:
                array->processors[processorIndex][taskIndex].tasks[1] = *(const float *)value;
                break;
            case 2:
                array->processors[processorIndex][taskIndex].tasks[2] = *(const char *)value;
                break;
        }
    }
}

void freeMemory(ProcessorArray *array) {
    for (size_t i = 0; i < array->numProcessors; ++i) {
        if (array->processors[i])
            free(array->processors[i]);
    }
    free(array->processors);
    free(array);
}
