typedef struct {
    int *tasks;
    size_t numTasks;
} Processor;

void initializeAndManageProcessors(Processor** processors, int numProcessors, size_t maxMemoryUsage) {
    const size_t taskSize = sizeof(int) + sizeof(float) + sizeof(char);
    size_t totalMemory = numProcessors * (sizeof(Processor) + numProcessors * taskSize);

    if (totalMemory > maxMemoryUsage * 1024) {
        char errorMessage[512];
        snprintf(errorMessage, sizeof(errorMessage), "Exceeded maximum memory usage (%zu KB requested, %zu KB allowed).", totalMemory / 1024, maxMemoryUsage * 1024);
        fprintf(stderr, "%s\n", errorMessage);
        exit(EXIT_FAILURE);
    }

    *processors = malloc(numProcessors * sizeof(Processor));

    if (!*processors) {
        perror("Failed to allocate memory for processors.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < numProcessors; ++i) {
        Processor* processor = *processors + i;
        processor->tasks = malloc(numProcessors * taskSize);
        processor->numTasks = 0;

        if (!processor->tasks) {
            perror("Failed to allocate memory for tasks.\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < numProcessors; ++i) {
        Processor* processor = *processors + i;

        for (size_t j = 0; j < numProcessors && processor->numTasks < maxMemoryUsage / taskSize; ++j) {
            int* task = (int*)((char*)processor->tasks + j * taskSize);
            float* tf = (float*)task + 1;
            char* tc = tf + 1;

            task[0] = rand() % 2001 - 1000;
            *tf = (rand() / (float)RAND_MAX) * 2000.0f - 1000.0f;
            *tc = (char)(rand() % 256);

            processor->tasks[processor->numTasks++] += taskSize;
        }
    }
}

void modifyTask(Processor* processor, size_t index, int value) {
    if (index >= processor->numTasks) return;

    int* task = (int*)processor->tasks + index;
    *task = value;
}

void cleanupProcessors(Processor** processors, int numProcessors) {
    for (int i = 0; i < numProcessors; ++i) {
        free((*processors)[i].tasks);
    }
    free(*processors);
}
