        fprintf(stderr, "Error: Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    Task* task = ((Processor*)0)->tasks + index;
    *value_i = task->value_i;
    *value_f = task->value_f;
    *value_c = task->value_c;

    task->value_i = *value_i;
    task->value_f = *value_f;
    task->value_c = *value_c;
}

