RequestHandler* initialize_data_structures(ServerConfiguration config) {
    ResourceManager* resourceManagers = malloc(config.numRequestHandlers * sizeof(ResourceManager));
    if (!resourceManagers) return NULL;

    for (size_t i = 0; i < config.numRequestHandlers; ++i) {
        ResourceManager* current = &resourceManagers[i];
        current->numRequestHandlers = config.minConnectionsPerHandler;
        current->maxConnectionsPerHandler = config.maxConnectionsPerHandler;

        ClientConnection** connections = malloc(current->numRequestHandlers * sizeof(ClientConnection*));
        if (!connections) {
            free(resourceManagers);
            return NULL;
        }

        srand(time(NULL) + i); // Use different seeds for each ResourceManager for better randomness

        for (size_t j = 0; j < current->numRequestHandlers; ++j) {
            connections[j] = malloc(sizeof(ClientConnection));
            if (!connections[j]) {
                free(resourceManagers);
