        fprintf(stderr, "Error: Allocated memory exceeds max limit\n");
        exit(1);
    }

    stream->packets = malloc(numStreams * sizeof(DataPacket*));
    for (size_t i = 0; i < numStreams; ++i) {
        stream->packets[i] = calloc(stream->maxMemoryUsage_MB / (numStreams * packetSize), packetSize);
        memset(stream->packets[i], 0, stream->maxMemoryUsage_MB / (numStreams * packetSize) * packetSize); // Initialize to zero

