FileStream* configureAndHandleFileStreams(size_t numStreams, size_t maxDiskUsageGB) {
    if (numStreams == 0 || maxDiskUsageGB == 0)
        return NULL;

    FileStream *stream = malloc(sizeof(FileStream));
    stream->packets = calloc(numStreams, sizeof(FilePacket));
    stream->numStreams = numStreams;
    stream->maxDiskUsageGB = maxDiskUsageGB;
    stream->totalUsedBytes = 0;

