    int fd = open(stream->packets[index].filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        perror("open");
        return;
    }
    stream->packets[index].fileDescriptor = fd;
    stream->packets[index].fileSize = newFileSize;
