    // Main loop to handle data source updates and logging
    while (1) {
        for (size_t i = 0; i < NUM_DATA_SOURCES; ++i) {
            processUpdate(dataSources[i]);
            log(getMemoryUsage());
        }
        usleep(1000000 / MAX_BANDWIDTH); // Sleep for a fraction of a second to respect the max bandwidth
    }

    // Free dynamically allocated memory when exiting main loop or receiving new data
