Record* read_records(const char *filename, size_t limit, size_t *keys, long *offsets, size_t *records) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file.");
        exit(EXIT_FAILURE);
    }

    Record **record_arr = malloc(limit * sizeof(Record*));
    long *offset_arr = malloc((limit + 1) * sizeof(long));
    size_t current_index = 0;
    size_t record_count = 0;

    long current_offset = 0;
    char line[256];

    while (fgets(line, sizeof(line), file) != NULL && record_count < limit) {
        int key, value;
        sscanf(line, "%d %d", &key, &value);
        if (record_count == 0) {
            current_offset = offsetof(Record, str);
            offset_arr[current_index] = current_offset;
        }

        Record *new_record = malloc(sizeof(Record));
        new_record->key = key;
        new_record->str = malloc((strlen(line) + 1) * sizeof(char));
        strcpy(new_record->str, line);
        record_arr[current_index] = new_record;

        current_offset += strlen(new_record->str) + current_index > 0 ? offset_arr[current_index - 1] : 0;
        current_index++;
        record_count++;
    }

    if (feof(file)) {
        printf("Reached end of file with %zu records read.\n", record_count);
    } else {
        perror("Error reading file.");
        exit(EXIT_FAILURE);
    }

    fclose(file);

    if (record_count > limit) {
        printf("Too many records read, maximum allowed is %zu.\n", limit);
        exit(EXIT_FAILURE);
    }

    *keys = keys_arr = calloc(current_index, sizeof(int));
    *offsets = offset_arr;
    *records = record_arr;

    srand_init(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < current_index; ++i) {
        (*keys)[i] = my_rand(1, INT_MAX);
        record_arr[i]->value = my_rand(1, INT_MAX);
    }

    return record_arr;
}

void free_memory(Record **record_arr, int keys[], long *offsets, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (record_arr[i]) {
            free(record_arr[i]->str);
            free(record_arr[i]);
        }
    }

    free(keys);
    free(offsets);
    free(record_arr);
}
