#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int value;
    char *str;
} Record;

#define KEY_LIMIT 10000
#define RANDOM_RANGE 100

void randomize(Record *record) {
    record->value = rand() % RANDOM_RANGE;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int offsets[KEY_LIMIT], keys[KEY_LIMIT], records_count = 0;
Record *records = NULL;

void free_memory() {
    for (int i = 0; i < records_count; ++i) {
        free(records[i].str);
    }
    free(records);
}

int read_data_source(FILE *fp) {
    int key, count = 0;
    while ((fscanf(fp, "%d %*s", &key) == 1 && count < KEY_LIMIT)) {
        if (count >= records_count) {
            records = realloc(records, sizeof(Record) * (records_count * 2));
        }
        records[count].str = strdup("");
        offsets[count] = records_count;
        keys[count++] = key;
    }
    return count;
}

void *data_manager(void *arg) {
    FILE *fp = (FILE *) arg;
    int num_records = read_data_source(fp);
    pthread_mutex_lock(&mutex);
    if (num_records > KEY_LIMIT) {
        free_memory();
        fprintf(stderr, "Number of records exceeds the limit\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    for (int i = 0; i < num_records; ++i) {
        randomize(&records[i]);
    }
    pthread_mutex_unlock(&mutex);
    free(fp);
    return NULL;
}

void manage_data(const char *filename, int concurrent_threads) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    pthread_t threads[concurrent_threads];
    for (int i = 0; i < concurrent_threads; ++i) {
        pthread_create(&threads[i], NULL, data_manager, fp);
    }

    for (int i = 0; i < concurrent_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_memory();
}
