#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    char *str;
    time_t timestamp;
} Record;

struct cache {
    size_t capacity;
    size_t size;
    Record *records;
    time_t last_accessed[0];
};

void *rand_between(void *v) {
    long int min = *(long *) v;
    long int max = *(long *)(v + sizeof(min));
    return (rand() % ((max - min) + 1)) + min;
}

struct cache *create_cache(size_t capacity) {
    struct cache *cache = malloc(sizeof(struct cache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->records = calloc(capacity, sizeof(Record) + sizeof(time_t));
    return cache;
}

void add_record(struct cache *cache, int key, char *str, time_t timestamp) {
    size_t index = key % cache->capacity;
    while (cache->records[index].key != 0 && cache->size > cache->capacity / 2) {
        index = (index + 1) % cache->capacity;
    }

    Record *record = &cache->records[index];
    record->key = key;
    record->str = strdup(str);
    record->timestamp = timestamp;

    qsort(cache->last_accessed, cache->size + 1, sizeof(time_t), (int (*)(const void *, const void *))cmp);
    cache->size++;
}

Record *get_record(struct cache *cache, int key) {
    size_t index = key % cache->capacity;
    while (cache->records[index].key != key) {
        index = (index + 1) % cache->capacity;
        if (index == cache->size) return NULL;
    }

    time_t now = time(NULL);
    cache->last_accessed[index] = now;
    return &cache->records[index];
}

void flush_cache(struct cache *cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        Record *record = &cache->records[i];
        free(record->str);
    }
    memset(cache->last_accessed, 0, sizeof(time_t) * (cache->capacity + 1));
}

void cmp(const void *a, const void *b) {
    return (*((time_t *) a) < *((time_t *) b)) ? -1 : ((*((time_t *) a) == *((time_t *) b)) ? 0 : 1);
}

void free_cache(struct cache *cache) {
    free(cache->records);
    free(cache);
}

Record *read_record(FILE *file, pthread_mutex_t *mutex) {
    char line[256];
    if (fgets(line, sizeof(line), file) == NULL) return NULL;

    int key, value;
    time_t timestamp;
    sscanf(line, "%d %d %ld", &key, &value, &timestamp);

    pthread_mutex_lock(mutex);
    Record *record = malloc(sizeof(Record) + sizeof(timestamp));
    record->key = key;
    record->str = strdup(&line[strlen(itoa(key)) + 1]); // exclude the integer part from the string copy
    record->timestamp = timestamp;
    pthread_mutex_unlock(mutex);

    return record;
}

void process_records(FILE *file, struct cache *cache, pthread_mutex_t *mutex, size_t max_records) {
    Record *record;
    while ((record = read_record(file, mutex)) != NULL) {
        add_record(cache, record->key, record->str, record->timestamp);
        if (cache->size >= max_records) break;

        // Implement custom pseudo-random number generator here
        int random_value = rand() % 100 + 1;
        record->value = random_value;
    }
}

void manage_data(FILE *file, pthread_mutex_t *mutex, size_t max_records, size_t cache_size) {
    struct cache *cache = create_cache(cache_size);

    process_records(file, cache, mutex, max_records);

    // Implement logging and periodic cache flushing here

    free_cache(cache);
}
