#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    char *value;
} Record;

typedef struct MemoryPool {
    void *data;
    size_t capacity;
    size_t size;
} MemoryPool;

MemoryPool memory_pool_init(size_t initial_size) {
    MemoryPool pool = {malloc(initial_size), initial_size, 0};
    return pool;
}

void *memory_pool_alloc(MemoryPool *pool) {
    if (pool->size >= pool->capacity) {
        pool->data = realloc(pool->data, pool->capacity * 2);
        pool->capacity *= 2;
    }
    void *mem = pool->data + pool->size;
    pool->size++;
    return mem;
}

void memory_pool_free(MemoryPool *pool) {
    free(pool->data);
}

Record *record_init() {
    Record *rec = (Record *)memory_pool_alloc(&g_memory_pool);
    rec->key = 0;
    rec->value = NULL;
    return rec;
}

unsigned int xorshift128plus(unsigned long *state) {
    unsigned long t;
    t = (*state) >> 17;
    *state ^= *state << 17 + t << 35 + 0x41C64E6D;
    return (*state) >> 18;
}

unsigned int random(unsigned long seed, unsigned int max) {
    static unsigned long state = 1;
    while (state >= max) {
        state = xorshift128plus(&state);
    }
    return state++;
}

void read_records(FILE *file, Record **records, int *keys, long *offsets, size_t capacity, int limit) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    MemoryPool memory_pool = memory_pool_init(capacity);

    if (!file || limit <= 0) {
        printf("Error: Invalid file or limit.\n");
        exit(1);
    }

    int n_records = 0;
    records = realloc(records, capacity * sizeof(Record *));
    keys = realloc(keys, capacity * sizeof(int));
    offsets = realloc(offsets, capacity * sizeof(long));

    Record *current_record;
    while (fscanf(file, "%d %d", &keys[n_records], &current_record->value) == 2 && n_records < limit - 1) {
        if (!current_record || !current_record->value) {
            printf("Error: Invalid record data.\n");
            exit(1);
        }
        current_record->key = keys[n_records];
        if (n_records >= capacity) {
            capacity *= 2;
            records = realloc(records, capacity * sizeof(Record *));
            keys = realloc(keys, capacity * sizeof(int));
            offsets = realloc(offsets, capacity * sizeof(long));
        }
        current_record = &records[n_records];
        pthread_mutex_lock(&mutex);
        records[n_records] = record_init();
        current_record = &records[n_records];
        offsets[n_records] = ftell(file);
        keys[n_records] = current_record->key;
        pthread_mutex_unlock(&mutex);
        current_record->value = strdup(current_record->value);
        current_record->int_field = random(seed, INT_MAX);
        n_records++;
    }

    if (ferror(file)) {
        printf("Error: File read error.\n");
        exit(1);
    }

    memory_pool_free(&memory_pool);
}

void free_records(Record **records, int *keys, long *offsets, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i]) {
            free(records[i]->value);
            free(records[i]);
        }
    }
    free(keys);
    free(offsets);
}
