#define MAX_MEMORY_USAGE (1024 * 1024 * 10) // 10MB max memory usage

typedef struct {
    long* offsets;
    int* keys;
    int* values;
    size_t num_records;
    pthread_mutex_t mutex;
} RecordSet;

// Callback function for custom random value generation
typedef int (*RandomGenerator)(void*, unsigned long);

RecordSet* create_record_set(size_t num_records, size_t offset_size, size_t key_size,
                              size_t value_size, RandomGenerator generator, void* userdata) {
    RecordSet* set = malloc(sizeof(RecordSet));
    if (!set) {
        perror("Failed to allocate RecordSet");
        return NULL;
    }

    pthread_mutex_init(&set->mutex, NULL);
    set->num_records = num_records;

    size_t record_size = offset_size + key_size + value_size;
    if (MAX_MEMORY_USAGE < num_records * record_size) {
        fprintf(stderr, "Memory usage exceeds the limit of %d bytes\n", MAX_MEMORY_USAGE);
        return NULL;
    }

    set->offsets = calloc(num_records, offset_size);
    if (!set->offsets) {
        perror("Failed to allocate offset array");
        free(set);
        return NULL;
    }

    set->keys = (int*)((char*)set->offsets + offset_size * num_records);
    set->values = (int*)((char*)set->keys + key_size * num_records);

    if (generator) {
        srandom(time(NULL));
        for (size_t i = 0; i < num_records; ++i) {
            set->values[i] = generator(userdata, i);
        }
    } else {
        // If no custom generator is provided, initialize values with random integers in [0, UINT_MAX]
        for (size_t i = 0; i < num_records; ++i) {
            set->values[i] = rand();
        }
    }

    return set;
}
