#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

typedef struct cache_node {
    record* data;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t lock;
} cache_node;

struct custom_callback {
    void (*generate)(int, double*, int*);
};

cache_node* create_cache(size_t threshold, size_t max_nodes) {
    cache_node* cache = (cache_node*)malloc(max_nodes * sizeof(cache_node));
    for (size_t i = 0; i < max_nodes; ++i) {
        cache[i].data = NULL;
        cache[i].capacity = 0;
        cache[i].allocated = 0;
        pthread_mutex_init(&(cache[i].lock), NULL);
    }
    return cache;
}

record* allocate_records(size_t size, custom_callback cb) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    if (cb.generate) {
        for (size_t i = 0; i < size; ++i) {
            cb.generate(i, &records[i].timestamp, &(records[i].key));
            records[i].offset = i;
        }
    } else {
        srand((unsigned int)time(NULL));
        for (size_t i = 0; i < size; ++i) {
            records[i].offset = i;
            records[i].key = rand() % INT_MAX;
            records[i].timestamp = ((double)rand()) / RAND_MAX;
        }
    }

    return records;
}

cache_node* find_cache(cache_node* cache, size_t key) {
    for (size_t i = 0; i < sizeof(cache) / sizeof(cache[0]); ++i) {
        if (!cache[i].data || cache[i].allocated == cache[i].capacity) continue;

        pthread_mutex_lock(&(cache[i].lock));
        if (!cache[i].data || cache[i].allocated == cache[i].capacity) {
            pthread_mutex_unlock(&(cache[i].lock));
            continue;
        }

        size_t used = 0;
        for (size_t j = 0; j < cache[i].allocated; ++j) {
            if (cache[i].data[j].key >= key) {
                used += j + 1;
                break;
            }
        }

        if (used == cache[i].allocated) {
            pthread_mutex_unlock(&(cache[i].lock));
            continue;
        }

        size_t available = cache[i].capacity - used;
        if (available >= size) {
            pthread_mutex_unlock(&(cache[i].lock));
            return &cache[i];
        }
    }

    return NULL;
}

record* allocate_from_cache(cache_node* cache, size_t size, custom_callback cb) {
    cache_node* target = find_cache(cache, 0);
    if (!target) {
        target = &cache[rand() % sizeof(cache) / sizeof(cache[0])];
        pthread_mutex_lock(&(target->lock));
        if (target->allocated + size > target->capacity) {
            pthread_mutex_unlock(&(target->lock));
            return allocate_records(size, cb);
        }
    }

    record* records = NULL;
    if (!cb.generate) {
        records = (record*)realloc(target->data, target->capacity + size * sizeof(record));
        if (!records) {
            perror("Memory reallocation failed");
            pthread_mutex_unlock(&(target->lock));
            return NULL;
        }
    } else {
        records = allocate_records(size, cb);
        if (!records) {
            pthread_mutex_unlock(&(target->lock));
            return NULL;
        }
    }

    target->data = records;
    target->allocated += size;
    pthread_mutex_unlock(&(target->lock));

    return records;
}
