} Record;

typedef struct CacheEntry {
    void* data;
    pthread_mutex_t lock;
    struct CacheEntry* next;
    time_t expiration;
} CacheEntry;

CacheEntry* cacheHead = NULL;
unsigned long memoryThreshold;
pthread_rwlock_t rwLock;

void log(const char* message) {
