    char *input_file = NULL;
    if (argc > 1 && strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [--help] [input_file]\n", argv[0]);
        return 0;
    }
    input_file = argc > 2 ? argv[2] : NULL;

    if (input_file != NULL) {
        int file_size, num_lines = 0, num_words = 0;
        char ch;
        struct stat st;
        FILE *fp = fopen(input_file, "r");

        if (!fp) return -1;
        if (fstat(fileno(fp), &st) != 0) {
            fclose(fp);
            return -1;
        }
        file_size = st.st_size;

        // Threaded approach to read the file line by line
        pthread_t threads[file_size];
        thread_data_t data[file_size];
        for (int i = 0; i < file_size; ++i) {
            data[i].tid = i;
            data[i].fd = fp;
            pthread_create(&threads[i], NULL, &read_line, &data[i]);
        }

        // Process the threads and collect results
        pthread_t *active = malloc(file_size * sizeof(pthread_t));
        memcpy(active, threads, file_size * sizeof(pthread_t));
        int num_threads = 0;
        while (num_threads < file_size) {
            pthread_t curr;
            pthread_t temp;
            for (int i = 0; i < file_size - num_threads; ++i) {
                if (active[i]) continue;
                active[num_threads] = threads[i];
                temp = active[file_size - num_threads--];
                pthread_detach(temp);
            }
            pthread_join(curr, NULL);
        }
    }

