public class BibleBookFrequencyAnalyzer {
    private final static Pattern OLD_TESTAMENT_BOOKS = Pattern.compile(
            "(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|" +
                    "1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song_of_Solomon|" +
                    "Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|" +
                    "Haggai|Zechariah|Malachi)", Pattern.CASE_INSENSITIVE);

