    private final ExecutorService executor;

    public BibleBookFrequencyAnalyzer(String databaseUrl, String user, String password, int maxSize) throws SQLException {
        this.dbManager = new DatabaseManager(databaseUrl, user, password);
        this.metadataQueue = new FileMetadataQueue();
        this.maxSize = maxSize;
        this.executor = Executors.newCachedThreadPool();
    }

