            if (!word.isEmpty()) {
                matcher = OLD_TESTAMENT_BOOKS.matcher(word);
                if (matcher.find()) {
                    bookCounts.putIfAbsent(matcher.group(), 0);
                    count++;
                    bookCounts.computeIfPresent(matcher.group(), (key, value) -> ++value);
