And the HashFileTask class:

```java
import java.io.*;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.concurrent.*;

public class HashFileTask extends RecursiveAction {
    private final InputStream inputStream;
    private final ByteBuffer buffer;
    private final MessageDigest md;
    private final int chunkSize;

    public HashFileTask(InputStream inputStream, ByteBuffer buffer, MessageDigest md, int chunkSize) {
        this.inputStream = inputStream;
        this.buffer = buffer;
        this.md = md;
        this.chunkSize = chunkSize;
    }

    @Override
    protected void compute() {
        byte[] data = new byte[chunkSize];
        int readBytes;
        while ((readBytes = inputStream.read(data)) != -1) {
            buffer.position(buffer.position() + readBytes);
            buffer.put(data, 0, readBytes);
            buffer.flip();
            md.update(buffer);
            buffer.clear();
            if (readBytes < chunkSize) {
                if (isDone()) {
                    // If there are no other pending subtasks and the current task is done, it means we have processed all chunks of this file and can return the result
                    setValue(null);
                } else {
                    // Otherwise, split the remaining work into smaller tasks and delegate them to child tasks
                    int remainingBytes = chunkSize - readBytes;
                    ByteBuffer remainderBuffer = buffer.slice();
                    remainderBuffer.clear();
                    for (int i = remainingBytes; i > 0; i -= Math.min(i, chunkSize)) {
                        HashFileTask childTask = new HashFileTask(inputStream, remainderBuffer, md, chunkSize);
                        childTask.fork();
                        remainderBuffer.position(remainingBytes - i);
                        remainderBuffer.get(data, 0, i);
                        remainingBytes -= i;
                    }
                }
            }
        }
    }
}
