            pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG ? "true" : "false");
    fclose(file);
}

void* create_pdu(void* arg) {
    int number = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)arg;
    bool log_enabled = *(bool*)(arg + 1);
    const char* log_file_path = *(const char**)(arg + 2);

    *pdus = malloc(number * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_t* mutexes = malloc(number * sizeof(pthread_mutex_t));
    if (!mutexes) {
        fprintf(stderr, "Mutex creation failed.\n");
        free(*pdus);
        return NULL;
    }

    for (int i = 0; i < number; ++i) {
        pthread_mutex_init(&mutexes[i], NULL);
        ((NFAPI_CRC_INDICATION_PDU_T*)(*pdus))[i].RX_UE_INFORMATION_TAG = i + 1;
        ((NFAPI_CRC_INDICATION_PDU_T*)(*pdus))[i].RNTI = rand();
        ((NFAPI_CRC_INDICATION_PDU_T*)(*pdus))[i].CRC_INDICATION_REL8_TAG = i + 1024;
        ((NFAPI_CRC_INDICATION_PDU_T*)(*pdus))[i].CRCFLAG = rand() % 2;

        if (log_enabled) {
            log_pdu(log_file_path, &((NFAPI_CRC_INDICATION_PDU_T*)(*pdus))[i]);
        }

        pthread_mutex_lock(&mutexes[i]);
    }

    return *pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T** pdus, int number) {
    for (int i = 0; i < number; ++i) {
        pthread_mutex_destroy(&((*pdus)[i].mutex));
    }
    free(*pdus);
    free(pdus);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdus(int number, bool log_enabled, const char* log_file_path) {
    pthread_t threads[number];
    NFAPI_CRC_INDICATION_PDU_T** pdus = NULL;
    void* results[number];

    for (int i = 0; i < number; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* temp_pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_pdus) {
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }

        temp_pdus->mutex = PTHREAD_MUTEX_INITIALIZER;
        results[i] = temp_pdus;
    }

    for (int i = 0; i < number; ++i) {
        pthread_create(&threads[i], NULL, create_pdu, &results[i]);
    }

    for (int i = 0; i < number; ++i) {
        pthread_join(threads[i], NULL);
    }

    pdus = malloc((number - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < number - 1; ++i) {
        pdus[i] = results[i];
    }

    free(results);

    return pdus;
}
