    int signalStrength;
    size_t rsiLength; // Length of RSI field in bytes
    char *rsiData; // Variable-length data field representing received signal indicators (RSI)
} FrameMetrics;

typedef struct BufferNode {
    FrameMetrics frameMetrics;
    struct BufferNode* next;
} BufferNode;

#define BUFFER_SIZE 1024 // Maximum buffer size, configurable
#define PRUNING_INTERVAL (60 * 60) // Pruning interval in seconds, configurable

// Function for dynamically allocating a new FrameMetrics structure with RSI field as a linked list
BufferNode* createFrameMetrics() {
    BufferNode* node = (BufferNode*) malloc(sizeof(BufferNode));
    if (!node) {
        fprintf(stderr, "Error: Allocation failure.\n");
        return NULL;
    }
    node->rsiData = NULL;
    node->next = NULL;
    return node;
}

// Function for initializing the RSI data field of FrameMetrics as a linked list
void initRSI(BufferNode* frame, const char *data, size_t length) {
    if (!frame || !data || length == 0)
        return;

    frame->rsiData = (char*) malloc(length);
    if (!frame->rsiData) {
        fprintf(stderr, "Error: Allocation failure.\n");
        return;
    }

    size_t i;
    for (i = 0; i < length; ++i) {
        frame->rsiData[i] = data[i];
    }
    frame->rsiLength = length;
}

// Function to manage the buffer, including insertion, deletion, and retrieval operations based on timestamp
BufferNode* manageBuffer(BufferNode** buffer, FrameMetrics* newFrame) {
    BufferNode *node, *temp, *prev;
    time_t currentTime = time(NULL);

    // Insert the new frame into the buffer if it's not full or older frames need to be pruned
    for (node = *buffer; node != NULL; node = node->next) {
        if (node->frameMetrics.timestamp <= newFrame->timestamp) {
            // Prune old frames if necessary
            if ((*buffer == node && (currentTime - PRUNING_INTERVAL >= node->frameMetrics.timestamp)) ||
                (node->next != NULL && (currentTime - PRUNING_INTERVAL >= node->next->frameMetrics.timestamp))) {
                temp = node->next;
                free(node->rsiData);
                free(node);
                node = temp;
            } else { // Move to the next position in the buffer if necessary
                prev->next = node->next;
                node->next = *buffer;
                *buffer = node;
                break;
            }
        }
    }

    // Insert the new frame at the end of the buffer
    if (node == NULL) {
        if (*buffer != NULL && currentTime - (*buffer)->frameMetrics.timestamp >= PRUNING_INTERVAL) {
            pruneBuffer(buffer);
        }
        node = newFrame;
        node->next = *buffer;
        *buffer = node;
    }

    return node;
}

// Function to prune old frames from the buffer
void pruneBuffer(BufferNode** buffer) {
    BufferNode* temp, *prev;
    time_t currentTime = time(NULL);

    for (temp = *buffer; temp != NULL; temp = temp->next) {
