```cpp
#include <iostream>
#include <list>
#include <memory>
#include <mutex>
#include <vector>
#include <boost/chrono.hpp>
#include <boost/log/trivial.hpp>
#include <boost/thread/mutex.hpp>

enum LoggingLevel { TRACE, DEBUG, INFO, WARN, ERROR };
std::atomic<size_t> maxBufferSize{1024}; // Maximum buffer size
std::chrono::steady_clock::time_point pruningInterval{std::chrono::seconds(5)}; // Pruning interval
LoggingLevel logLevel = INFO; // Logging level (change as needed)

class FrameMetrics {
public:
    std::chrono::steady_clock::time_point timestamp;
    int signalStrength;
    std::list<int> rsiData;
};

typedef std::shared_ptr<FrameMetrics> FrameMetricsPtr;
class FrameMetricsBuffer {
private:
    std::list<FrameMetricsPtr> buffer;
    boost::mutex mutex;
    std::chrono::steady_clock::time_point lastPruningTime{std::chrono::steady_clock::now()};

public:
    FrameMetricsBuffer(size_t maxSize) : maxSize(maxSize) {}

    void insert(FrameMetricsPtr data) {
        std::unique_lock<boost::mutex> lock(mutex);
        buffer.push_back(data);
        if (buffer.size() > maxSize) {
            auto it = buffer.begin();
            std::advance(it, maxSize);
            it = buffer.erase(it);
        }
        lastPruningTime = std::chrono::steady_clock::now();
        lock.unlock();
        if (logLevel >= TRACE) {
            BOOST_LOG_TRIVIAL(TRACE) << "Inserted FrameMetrics";
        }
    }

    FrameMetricsPtr getByTimestamp(const std::chrono::steady_clock::time_point& timestamp) {
        std::unique_lock<boost::mutex> lock(mutex);
        for (auto it = buffer.begin(); it != buffer.end(); ++it) {
            if ((*it)->timestamp == timestamp) {
                auto result = *it;
                it = buffer.erase(it);
                return result;
            }
        }
        lock.unlock();
        return nullptr;
    }

    bool prune() {
        std::unique_lock<boost::mutex> lock(mutex);
        if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastPruningTime).count() >=
            std::chrono::duration_cast<std::chrono::seconds>(pruningInterval).count()) {
            auto it = buffer.begin();
            while (it != buffer.end()) {
                if ((*it)->timestamp + pruningInterval < std::chrono::steady_clock::now()) {
                    it = buffer.erase(it);
                } else {
                    ++it;
                }
            }
            lastPruningTime = std::chrono::steady_clock::now();
            return true;
        }
        lock.unlock();
        return false;
    }
};
```

