    public static ConcurrentMap<String, Integer> extractBookNames(String text) {
        Pattern oldTestamentPattern = Pattern.compile("(^|\\s)(Joshua|Exodus|Leviticus|Numbers|Deuteronomy|Genesis|Ezra|Nehemiah|Job|Psalms|Proverbs|Isaiah|Jeremiah|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)$");
        return text.split("\\s+")
                .stream()
                .filter(oldTestamentPattern::matcher)
                .collect(Collectors.groupingBy(String::toLowerCase, Collectors.counting()));
    }

    public void hashFile(File file, Callback callback) {
        executor.submit(() -> {
            try {
                byte[] md5 = md5HashFunction.hashBytes(Files.readAllBytes(file.toPath())).asHexadecimalString();
                if (callback != null) {
                    callback.onProgress(md5);
                }
                return md5;
            } catch (Exception e) {
                if (callback != null) {
                    callback.onError(e);
                }
                throw new RuntimeException(e);
            }
        });
    }

    public interface Callback {
        void onProgress(String md5);
        void onError(Exception e);
    }

