        CsvWriter writer = new CsvWriterBuilder()
                .setAutoFlush(true)
                .build();
        try (writer.open()) {
            writer.writeRecord("Path", "Size", "LastModified", "MetadataVersion", "FileType", "Checksum");
            for (FileMetadata fileMetadata : fileMetadatas) {
                writer.writeRecord(fileMetadata.getPath(), fileMetadata.getSize(), fileMetadata.getLastModified(), fileMetadata.getMetadataVersion(), fileMetadata.getFileType(), fileMetadata.getChecksum());
            }
        }
    }
}
