```python
import hashlib
import os
import threading
import time
from queue import Queue

def md5(filepath):
    blockSize = 65536
    hasher = hashlib.md5()
    with open(filepath, "rb") as f:
        while True:
            data = f.read(blockSize)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def parallel_md5(filepaths, num_threads=4):
    q = Queue()
    results = []
    threadPool = [threading.Thread(target=md5, args=(filepath, )) for filepath in filepaths]

    def put_result(res):
        results.append(res)
        q.task_done()

    for t in threadPool:
        t.start()
        t.daemon = True
        t.join()

    for filepath in filepaths:
        q.put((filepath,))

    while not q.empty():
        filepath, = q.get()
        put_result(md5(filepath))

    return results
