import java.text.SimpleDateFormat;
import java.time.Instant;

public class ResourceMonitor {
    private final TreeMap<Long, Map<String, ArrayList<ResourceUsage>>> data = new TreeMap<>();
    private final SimpleDateFormat timestampFormatter = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    private final int maxSize;
    private final double verbosityLevel;
    private File exportFile;

    public ResourceMonitor(int maxSize, double verbosityLevel, File exportFile) {
        this.maxSize = maxSize;
        this.verbosityLevel = verbosityLevel;
        this.exportFile = exportFile;
    }

    public void insert(ResourceUsage usage) {
        // Insert the ResourceUsage object based on both timestamp and resource type
        Long timestamp = usage.getTimestamp().toEpochMilli();
        Map<String, ArrayList<ResourceUsage>> map = data.computeIfAbsent(timestamp, k -> new TreeMap<>());
        String key = usage.getType();
        ArrayList<ResourceUsage> list = map.computeIfAbsent(key, k -> new ArrayList<>());
        list.add(usage);

        // Prune if necessary
        prune(timestamp);
    }

    public ResourceUsage get(Long timestamp, String resourceType) {
        return data.getOrDefault(timestamp, new TreeMap<>()).getOrDefault(resourceType, new ArrayList<>()).get(0);
    }

    public void remove(Long timestamp, String resourceType) {
        // Remove the ResourceUsage object based on both timestamp and resource type
        data.get(timestamp).remove(resourceType).clear();
        prune(timestamp);
    }

    private void prune(Long timestamp) {
        while (data.size() > maxSize) {
            Long oldest = data.firstKey();
            if (oldest < timestamp) break;
            data.remove(oldest);
        }
    }

    // Add methods for filtering, exporting, serializing/deserializing, etc.
}
