    size_t words;
    size_t max_line_len;
    size_t word_counts[INT_MAX];
} Counter;

struct thread_data {
    char **lines;
    size_t start, end;
    pthread_mutex_t *mutex;
    Counter *counter;
};

Counter init_counter(void) {
    Counter counter = { 0 };
    for (size_t i = 0; i < INT_MAX; ++i)
        counter.word_counts[i] = 0;
    return counter;
}

void *process_lines(void *data) {
    struct thread_data *td = data;
    Counter *counter = td->counter;

    for (size_t i = td->start; i < td->end; ++i) {
        char **line = td->lines + i;
        size_t line_len = strlen(*line);
        if (line_len > counter->max_line_len)
            counter->max_line_len = line_len;

        const char *delim = " \t\n.,;:!?(){}[]\"'-";
        char *word = strtok(*line, delim);
        while (word != NULL) {
            ++counter->words;
            size_t word_len = strlen(word);
            if (word_len > counter->max_line_len)
                counter->max_line_len = word_len;

            pthread_mutex_lock(td->mutex);
            for (size_t j = 0; j < INT_MAX && counter->word_counts[j] != 0; ++j) {
                if (!strcasecmp(word, gettext(counter->word_counts[j].word)))
                    ++counter->word_counts[j].count;
            }
            pthread_mutex_unlock(td->mutex);

            word = strtok(NULL, delim);
