    if (stat(input_file, &st) == -1) {
        fprintf(stderr, _("Error: Cannot open file '%s'.\n"), input_file);
        return 1;
    }

    if (st.st_size > max_file_size) {
        fprintf(stderr, _("Error: File '%s' exceeds the maximum size limit of %lu bytes.\n"), input_file, max_file_size);
        return 1;
    }

    iconv_t ic = iconv_open("UTF-8", NULL);
    if (ic == (iconv_t)-1) {
