    iconv_close(ic);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Counter counter = init_counter();
    size_t num_threads = (num_lines + threads - 1) / threads;

    struct thread_data *tds = malloc(sizeof(struct thread_data) * threads);
    if (!tds) {
        fprintf(stderr, _("Error: Out of memory.\n"));
        free(lines);
        return 1;
    }

    for (size_t i = 0; i < threads; ++i) {
        tds[i].counter = &counter;
        tds[i].mutex = &mutex;
        tds[i].start = i * num_threads;
        tds[i].end = (i == threads - 1) ? num_lines : (i + 1) * num_threads;
        tds[i].lines = lines;
