    NetworkNode **arr = (NetworkNode**) malloc(sizeof(NetworkNode*) * size);
    if (!arr) return NULL;
    memset(arr, 0, sizeof(NetworkNode*) * size);
    for (size_t i = 0; i < size; ++i) {
        arr[i] = malloc(sizeof(NetworkNode));
        if (!arr[i]) return NULL;
        arr[i]->object = NULL;
        arr[i]->connections = initConnectionArray(10); // Initialize connections array with 10 elements
        if (!arr[i]->connections) return NULL;
        arr[i]->num_connections = 0;
        arr[i]->timeout_threshold = time(NULL);
    }
    return arr;
}

void setConnectionStatus(Connection *conn, enum status status) {
    conn->status = status;
}

time_t getCurrentTime() {
    return time(NULL);
}

// Function to check and clean up unused connections based on timeout threshold
void cleanupUnusedConnections(NetworkNode **networkNodes, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        NetworkNode *node = networkNodes[i];
        if (!node || !node->connections) continue;

        time_t currentTime = getCurrentTime();
        for (size_t j = 0; j < node->num_connections; ) {
            Connection *conn = node->connections[j];
            if (conn->timestamp + node->timeout_threshold < currentTime) {
                free(conn);
                memmove(&node->connections[j], &node->connections[j+1], sizeof(Connection*) * (node->num_connections - j - 1));
                --node->num_connections;
            } else {
                ++j;
            }
        }
    }
}
