['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <functional>

// Custom memory pool class for efficient allocation and deallocation
class MemoryPool {
public:
    MemoryPool(size_t capacity) : _capacity(capacity), _freeListHead(_freeListTail = nullptr) {}

    void* Alloc(size_t size) {
        if (_freeListHead && size <= _capacity) {
            void* block = _freeListHead;
            _freeListHead = _freeListHead->next;
            return block;
        }
        return operator new(size);
    }

    void Free(void* block, size_t size) {
        if (block && size <= _capacity) {
            new(block) char; // construct an empty object to zero the memory
            block->next = _freeListHead;
            _freeListTail = block;
        } else {
            operator delete(block);
        }
    }

private:
    struct FreeBlock {
        void* next;
        char data[1]; // make sure the size is correct for the memory pool
    };

    size_t _capacity;
    FreeBlock* _freeListHead, *_freeListTail;
};

// Customizable random number generator interface
