    Data* data = static_cast<Data*>(memoryPool.Alloc(sizeof(Data)));

    Record* recordArray = nullptr;
    if (config.recordCount > 0) {
        size_t recordSize = sizeof(Record) * config.recordCount;
        recordArray = static_cast<Record*>(memoryPool.Alloc(recordSize));
        for (size_t i = 0; i < config.recordCount; ++i) {
            new (recordArray + i) Record(); // zero-initialize each record
        }
    }

    int* dataArr = nullptr;
    if (config.randomGen) {
        dataArr = static_cast<int*>(memoryPool.Alloc(config.recordCount * config.keySize));
        for (size_t i = 0; i < config.recordCount * config.keySize; ++i) {
            dataArr[i] = config.randomGen();
        }
    } else if (config.sequence) {
        // Implement custom sequence generation logic here
    }

    if (!dataArr && recordArray) {
        memoryPool.Free(recordArray, sizeof(Record) * config.recordCount);
        recordArray = nullptr;
    }

    if (!dataArr) {
        data->records = nullptr;
        data->dataArray = nullptr;
    } else {
        data->records = recordArray;
        data->dataArray = dataArr;
    }

    return data;
}
