    double metric_value;
    time_t timestamp;
    char description[128];
    int metric_id;
} metric_entry;

struct collection {
    size_t capacity;
    size_t count;
    metric_entry *entries;
    pthread_mutex_t mutex;
    sqlite3 *db;
    char db_filename[256];
};

void create_collection(struct collection *coll, size_t initial_capacity) {
    coll->capacity = initial_capacity;
    coll->count = 0;
    coll->entries = malloc(initial_capacity * sizeof(metric_entry));
    if (!coll->entries) {
        fprintf(stderr, "Failed to allocate memory for collection\n");
        exit(1);
    }
    pthread_mutex_init(&coll->mutex, NULL);
}

void resize_collection(struct collection *coll, size_t new_capacity) {
    if (new_capacity <= coll->count) return;

    metric_entry *temp = realloc(coll->entries, new_capacity * sizeof(metric_entry));
    if (!temp) {
        fprintf(stderr, "Failed to resize collection\n");
        exit(1);
    }
    coll->entries = temp;
    coll->capacity = new_capacity;
}

void push_metric(struct collection *coll, const char *name, double value, time_t timestamp, const char *description) {
    if (coll->count == coll->capacity) resize_collection(coll, 2 * coll->capacity);

    pthread_mutex_lock(&coll->mutex);
    coll->entries[coll->count].metric_name[sizeof(coll->entries[coll->count].metric_name) - 1] = '\0';
    strcpy(coll->entries[coll->count].metric_name, name);
    coll->entries[coll->count].metric_value = value;
    coll->entries[coll->count].timestamp = timestamp;
    coll->entries[coll->count].description[sizeof(coll->entries[coll->count].description) - 1] = '\0';
    strcpy(coll->entries[coll->count].description, description);
    coll->entries[coll->count].metric_id = coll->count;
    coll->count++;
    pthread_mutex_unlock(&coll->mutex);
}

void persist_collection(struct collection *coll) {
    sqlite3_stmt *stmt;

    if (coll->db == NULL) return;

    char sql[512];
    snprintf(sql, sizeof(sql), "CREATE TABLE IF NOT EXISTS metrics ("
                                "id INTEGER PRIMARY KEY,"
                                "metric_name TEXT,"
                                "metric_value REAL,"
                                "timestamp INTEGER,"
                                "description TEXT);");
    if (sqlite3_exec(coll->db, sql, NULL, NULL, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to create table: %s\n", sqlite3_errmsg(coll->db));
        return;
    }

    snprintf(sql, sizeof(sql), "INSERT INTO metrics (id, metric_name, metric_value, timestamp, description) VALUES ("
                                "%d,'%s',%.2f,%.0f,'%s');",
             coll->entries[i].metric_id, coll->entries[i].metric_name, coll->entries[i].metric_value,
             (double)(coll->entries[i].timestamp / (60 * 60)), coll->entries[i].description);
    if (sqlite3_prepare(coll->db, sql, strlen(sql), &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(coll->db));
        return;
    }
    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(coll->db));
    }
    sqlite3_finalize(stmt);
}

void run_collection(struct collection *coll, const char *db_filename) {
    coll->db = sqlite3_open(db_filename);
    if (!coll->db) {
        fprintf(stderr, "Failed to open database: %s\n", sqlite3_errmsg(coll->db));
        exit(1);
    }
}
