public class ResourceManager {
 private static final Logger LOGGER = LoggerFactory.getLogger(ResourceManager.class);
 private ExecutorService executor;
 private ConcurrentSkipListMap<Priority, SortedSet<ResourceRequest>> requests;
 private double maxUtilizationThreshold;
 private int threadsCount;
 private AtomicInteger currentLoad;
 private final ObjectLock serializationLock = new ObjectLock();

 public ResourceManager(int threads, double maxUtilization) {
 this.threadsCount = threads;
 this.maxUtilizationThreshold = maxUtilization;
 this.currentLoad = new AtomicInteger(0);
 this.executor = Executors.newFixedThreadPool(threads);
 this.requests = new ConcurrentSkipListMap<Priority, SortedSet<ResourceRequest>>();

 for (Priority priority : Priority.values()) {
 this.requests.putIfAbsent(priority, new TreeSet<>());
 }

 executor.submit(() -> monitorAndLog());
 }

 public void insert(ResourceRequest request) {
 requests.get(request.getPriority()).add(request);
 updateLoad(request);
 }

 public ResourceRequest findLowestPriorityRequest() {
 return requests.firstKey().map(k -> requests.get(k).pollFirst()).orElse(null);
 }

 public void deleteByPriorityAndTimestamp(Priority priority, Instant timestamp) {
 for (ResourceRequest request : requests.get(priority)) {
 if (request.getTimestamp().isBefore(timestamp)) {
 requests.get(priority).remove(request);
 updateLoad(-request.getMemory());
 break;
 }
 }
 }

 public void rebalance() {
 while (getCurrentLoad() > maxUtilizationThreshold * 100) {
 ResourceRequest request = findLowestPriorityRequest();
 if (request != null) {
 deleteByPriorityAndTimestamp(request.getPriority(), request.getTimestamp());
 updateLoad(-request.getMemory());
 }
 }
 executor.execute(() -> rebalance());
 }

 public void serializeToStorage() {
 synchronized (serializationLock) {
 ObjectMapper mapper = new ObjectMapper();
 try {
 String json = mapper.writeValueAsString(requests);
 // Save the serialized data to a distributed storage system
 } catch (JsonProcessingException e) {
 LOGGER.error("Error serializing ResourceManager", e);
 }
 }
 }

 public void deserializeFromStorage() {
 synchronized (serializationLock) {
 ObjectMapper mapper = new ObjectMapper();
 try {
 requests = mapper.readValue((InputStream), ConcurrentSkipListMap.class);
 } catch (IOException e) {
 LOGGER.error("Error deserializing ResourceManager", e);
 }
 }
 }

 public void monitorAndLog() {
 while (true) {
 try {
 Thread.sleep(1000);
