#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int key;
    char* string;
    struct Record* next; // pointer to nested record
    int value;
} Record;

Record* read_records(const char* filename, size_t max_records) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    long* offsets = calloc(max_records + 1, sizeof(long));
    int* keys = malloc(max_records * sizeof(int));
    char** strings = malloc(max_records * sizeof(char*));
    Record** records = malloc(max_records * sizeof(Record*));
    size_t num_records = 0;

    long current_offset = 0;
    int line_number = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file) && line_number < max_records) {
        size_t field_count = sscanf(line, "%d %d %s", &keys[line_number], &((records[line_number] = malloc(sizeof(Record)))->key), strings + line_number);

        if (field_count == 3) {
            offsets[line_number] = current_offset;
            records[line_number]->string = strdup(strings[line_number]);
            current_offset += strlen(strings[line_number]) + 1;

            if (sscanf(strings[line_number], "%d", &((records[line_number])->value)) == 1) {
                line_number++;
                continue;
            }

            // handle nested records
            int depth = sscanf(strings[line_number], "%d%n", &(records[line_number]->depth), strings + line_number);
            if (depth == 1 && records[line_number]->depth > 0) {
                long next_offset = current_offset;
                size_t i;
                for (i = line_number + 1; i < num_records && records[i] != NULL; ++i) {
                    if (offsets[i] >= next_offset) {
                        break;
                    }
                }
                memmove(strings + i, strings + line_number + 1, (num_records - line_number) * sizeof(char*));
                records[i] = NULL;
                num_records++;
                records[line_number]->next = records + i;
            }
        } else {
            fprintf(stderr, "Error parsing line %zu: %s\n", line_number, line);
            break;
        }

        line_number++;
    }

    fclose(file);
    if (line_number > max_records) {
        perror("Too many records");
        return NULL;
    }

    for (size_t i = 0; i < line_number; ++i) {
        set_pseudo_random(records[i]->value, 10);
    }

    return records;
}

void set_pseudo_random(int* value, int max) {
    static unsigned long seed = time(NULL);

    *value = (seed = (seed * 25214933 + 3644093)) % max;
}

void free_records(Record** records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->string);
            free(records[i]);
        }
    }
}
