Record* read_records(FILE *file, size_t max) {
    Record *records = malloc(max * sizeof(Record));
    if (!records) {
        perror("Memory allocation failure");
        return NULL;
    }

    int line_count = 0;
    for (size_t i = 0; i < max && fscanf(file, "%d%s", &records[i].key, records[i].str) == 2; ++i) {
        records[i].next = line_count + (line_count < i ? ++read_records(file, max - line_count) : NULL);
        line_count++;
    }
    return records;
}

void free_record(Record *record) {
    free(record->str);
    free(record);
}

void free_records(Record **records) {
    if (!*records) {
        return;
    }
    free_records(&(*records)->next);
    free_record(*records);
    *records = NULL;
}

long *allocate_long_array(size_t n) {
    long *array = malloc(n * sizeof(long));
    if (!array) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    return array;
}

int *allocate_int_array(size_t n) {
