    if (!array) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    return array;
}

Record **allocate_record_array(size_t n) {
    Record **array = malloc(n * sizeof(Record*));
    if (!array) {
        perror("Memory allocation failure");
