typedef struct MemoryBlock {
    void *data;
    size_t capacity;
    size_t used;
} MemoryBlock;

MemoryBlock memory_block; // Global memory pool
pthread_rwlock_t rwlock; // Read-write lock for concurrent access

void read_metrics(const char *filename, size_t limit) {
    gzFile file = gzopen(filename, "rb");
    if (!file) return;

    Metric metric;
    size_t num_metrics = 0;

    while (num_metrics < limit && gzgets(file, &metric.tag + sizeof(metric.tag) - 1, 256) &&
           sscanf(&metric.tag[0], "%lld %f", &metric.timestamp, &metric.value) == 2) {
        num_metrics++;
    }

    if (num_metrics > limit) {
        fprintf(stderr, "Error: number of metrics exceeds the specified limit.\n");
        return;
    }

    // Initialize data structures based on input
    // ...

    gzclose(file);
}

void *memory_alloc(size_t size) {
    if (memory_block.used + size > memory_block.capacity) {
        void *new_data = mmap(NULL, memory_block.capacity * 2, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_data == MAP_FAILED) {
            perror("Error: Failed to allocate memory.");
            return NULL;
        }

        memory_block.capacity *= 2;
        memory_block.data = realloc(memory_block.data, memory_block.capacity);
        if (!memory_block.data) {
            perror("Error: Failed to resize memory.");
            munmap(new_data, memory_block.capacity * 2);
            return NULL;
        }

        memory_block.data = new_data;
    }

    void *ptr = memory_block.data + memory_block.used;
    memory_block.used += size;

    return ptr;
}

void memory_free(void *ptr) {
    if (ptr >= memory_block.data && ptr < (memory_block.data + memory_block.used)) {
        memset(ptr, 0, memory_block.used - memory_block.capacity); // Zero out freed memory to avoid fragmentation
        memory_block.used -= sizeof(Metric);
    }
}

// API functions for querying and iterating metrics
// ...

int main() {
    // Initialize read-write lock and memory pool
    pthread_rwlock_init(&rwlock, NULL);
    memory_block.data = calloc(1, 4096);
    if (!memory_block.data) {
        perror("Error: Failed to initialize memory.");
        return 1;
    }
    memory_block.capacity = 4096;
    memory_block.used = 0;

    // Read metrics from compressed log file and process them
    read_metrics("metrics.log.gz", 1000);

    // Use the API functions to query and iterate over metrics as needed
    // ...

    pthread_rwlock_destroy(&rwlock);
    free(memory_block.data);
    return 0;
}
