#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#define MAX(x, y) ((x > y) ? (x) : (y))

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    Node* head;
    Node* tail;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
};

void init_list(struct list* list, size_t capacity) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = capacity;
    pthread_mutex_init(&(list->lock), NULL);
}

bool is_full(struct list* list) {
    return (list->size == list->capacity);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("malloc failed");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void append(struct list* list, const NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&(list->lock));
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&(list->lock));
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    ++(list->size);
    pthread_mutex_unlock(&(list->lock));
}

void resize_if_necessary(struct list* list, size_t capacity) {
    if (is_full(list)) {
        pthread_mutex_lock(&(list->lock));
        Node** temp = realloc(list->head, sizeof(Node)*capacity);
        if (!temp) {
            perror("realloc failed");
            pthread_mutex_unlock(&(list->list->lock));
            return;
        }
        list->head = temp;
        for (size_t i = list->capacity; i < capacity; ++i) {
            list->head[i] = malloc(sizeof(Node));
            if (!list->head[i]) {
                perror("malloc failed");
                pthread_mutex_unlock(&(list->lock));
                return;
            }
            list->head[i]->next = NULL;
        }
        list->capacity = capacity;
        pthread_mutex_unlock(&(list->lock));
    }
}

void add(struct list* list, const NFAPI_CRC_INDICATION_PDU_T data) {
    resize_if_necessary(list, MAX(list->size + 1, 2 * list->capacity));
    append(list, data);
}
