    if (nfapi_crc_list_is_full(list)) return false;

    pthread_mutex_lock(&list->mutex);

    list->data[list->size] = *pdu;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_list_find(const NFAPI_CRC_LIST_T *list, int rnti) {
    if (!list || !list->data) return NULL;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = &list->data[i];
            pthread_mutex_unlock(&list->mutex);
            return result;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

bool nfapi_crc_list_remove(NFAPI_CRC_LIST_T *list, int rnti) {
    if (!list || !list->data) return false;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            size_t j;
            for (j = i + 1; j < list->size; ++j) {
                list->data[j - 1] = list->data[j];
            }
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return false;
}
