            if (buffer->length == BUFFER_SIZE) {
                size_t to_remove = (BUFFER_SIZE - buffer->capacity) / 2;
                memmove(buffer->frames, buffer->frames + to_remove, (buffer->length - to_remove) * sizeof(FrameMetrics));
                buffer->length -= to_remove;
            }
        }

        buffer->frames[buffer->length] = frame;
        ++buffer->length;
        sem_post(&buffer_mutex);
    }
