pthread_mutex_t sequence_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long total_allocated = 0;
unsigned long max_allocation = 10000000UL; // Define this dynamically based on system resources

void init_sequence(SequenceElement* sequence, int min, int max) {
    for (int i = 0; i < array_size; ++i) {
        sequence[i].value = rand() % (max - min + 1) + min;
    }
}

Record* allocate_records(size_t n, void (*init)(Record*)) {
    Record *records = NULL;

    pthread_mutex_lock(&sequence_mutex);
    if (total_allocated + n > max_allocation) {
        pthread_mutex_unlock(&sequence_mutex);
        return NULL;
    }
    total_allocated += n;
    records = malloc(n * sizeof(Record));
    if (!records) {
        total_allocated -= n;
        pthread_mutex_unlock(&sequence_mutex);
        return NULL;
    }
    for (size_t i = 0; i < n; ++i) {
        if (init) init(&records[i]);
        records[i].offset = (long)total_allocated + i;
        records[i].key = sequence[i % array_size].value;
        records[i].timestamp = time(NULL);
    }
    pthread_mutex_unlock(&sequence_mutex);

    return records;
}

