    long offset;
    int key;
    unsigned char status;
};

template<typename T>
class Cache {
private:
    std::vector<std::unique_ptr<Record>> records;
    std::vector<Record*> cache;
    size_t totalSize = 0;
    size_t cacheCapacity = 100;
    const size_t recordSize = sizeof(Record);

public:
    Cache(size_t initialSize) {
        if (initialSize + records.size() > MAX_MEMORY)
            throw std::runtime_error("Memory limit exceeded");
        for (size_t i = 0; i < initialSize; ++i)
            allocateRecord();
    }

    Record* get(int key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(records.begin(), records.end(), [&](const auto& r) { return r->key == key; });
        if (it != records.end())
            return *it;

        Record* record = nullptr;
        if (!cache.empty() && cache.back()->key == key)
            record = cache.back();
        if (!record) {
            record = allocateRecord();
            if (record)
                records.push_back(std::move(record));
        }
        return record;
    }

    void put(Record* record) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find(cache.begin(), cache.end(), record);
        if (it != cache.end())
            return;

        if (cache.size() >= cacheCapacity) {
            Record* leastRecentlyUsed = *cache.begin();
            for (auto it = cache.begin(); it != --cache.end(); ++it)
                leastRecentlyUsed = (*it)->key < leastRecentlyUsed->key ? *it : leastRecentlyUsed;
            delete leastRecentlyUsed;
            cache.erase(cache.begin());
        }
        cache.push_back(record);
    }

    void allocateRecord() {
        Record* record = new Record();
        record->offset = dist(gen);
        record->key = dist(gen);
        record->status = static_cast<unsigned char>(dist(gen) % 3); // Status flag can be 0,1 or 2
        totalSize += recordSize;
    }
};
```

This implementation dynamically allocates records with the specified structure and manages a cache for frequently accessed records. It also includes random number generation and basic thread-safety mechanisms. To extend this code to meet all of your requirements, you can build upon this base implementation by adding features such as logging, error handling, customizable initialization patterns, and integration with external libraries as needed.']

