typedef struct MAC_PDU {
    struct L2_HEADER l2;
    struct L3_HEADER l3;
    uint8_t payload[MAX_PAYLOAD_SIZE];
} MAC_PDU;

typedef struct CacheEntry {
    size_t index;
    pthread_rwlock_t lock;
    bool is_cached;
} CacheEntry;

struct NetworkInterface {
    MAC_PDU* mac_pdu_array;
    size_t capacity;
    size_t count;
    CacheEntry* cache;
    size_t cache_size;
    size_t cache_hit_count;
    pthread_mutex_t log_mutex;
};

void validate_l2_header(const struct L2_HEADER* l2) {
    // Your validation logic here, ensuring that the header adheres to standard Ethernet frame formats.
}

NetworkInterface* create_network_interface() {
    size_t total_size = sizeof(MAC_PDU) * 500000 + sizeof(CacheEntry) * 1024; // Adjust cache_size as needed
    void* mem = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    NetworkInterface* ni = (NetworkInterface*)mem;
    ni->capacity = 500000;
    ni->count = 0;
    ni->cache = ((MAC_PDU*)((char*)ni + sizeof(NetworkInterface))) + ni->capacity; // Adjust offset as needed
    ni->cache_size = 1024;
    ni->cache_hit_count = 0;

    for (size_t i = 0; i < ni->capacity; ++i) {
        ((MAC_PDU*)((char*)ni->mac_pdu_array + i))->l2.ether_dhost[ETH_ALEN] = 0xff; // Fill with broadcast address initially
    }

    for (size_t i = 0; i < ni->cache_size; ++i) {
        ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))->index = i * ni->capacity;
        ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))->is_cached = false;
        pthread_rwlock_init(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].lock, NULL);
    }

    ni->log_mutex = PTHREAD_MUTEX_INITIALIZER;

    return ni;
}

MAC_PDU* get_or_create_mac_pdu(NetworkInterface* ni, const struct L2_HEADER* l2) {
    validate_l2_header(l2);

    for (size_t i = 0; i < ni->capacity; ++i) {
        if (memcmp(((MAC_PDU*)((char*)ni->mac_pdu_array + i))->l2.ether_dhost, l2->ether_dhost, ETH_ALEN) == 0 &&
            memcmp(((MAC_PDU*)((char*)ni->mac_pdu_array + i))->l2.ether_shost, l2->ether_shost, ETH_ALEN) == 0) {
            // Found a match in the array, return it
            return ((MAC_PDU*)((char*)ni->mac_pdu_array + i));
        }
    }

    // No match found, search the cache
    for (size_t i = 0; i < ni->cache_size; ++i) {
        pthread_rwlock_rdlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].lock);

        if (!((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].is_cached ||
            memcmp(((MAC_PDU*)(((char*)ni->mac_pdu_array + ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].index)))->l2.ether_dhost, l2->ether_dhost, ETH_ALEN) != 0 ||
            memcmp(((MAC_PDU*)(((char*)ni->mac_pdu_array + ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].index)))->l2.ether_shost, l2->ether_shost, ETH_ALEN) != 0) {
            pthread_rwlock_unlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].lock);
            continue;
        }

        // Found a match in the cache, update its reference count and return it
        ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].is_cached = true;
        pthread_rwlock_unlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].lock);
        return ((MAC_PDU*)(((char*)ni->mac_pdu_array + ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[i].index)));
    }

    // No match found in the cache either, create a new MAC_PDU and add it to the array and the cache
    MAC_PDU* mac_pdu = ((MAC_PDU*)((char*)ni->mac_pdu_array + ni->count));
    memcpy(mac_pdu->l2.ether_dhost, l2->ether_dhost, ETH_ALEN);
    memcpy(mac_pdu->l2.ether_shost, l2->ether_shost, ETH_ALEN);

    ni->count++;

    // Check if the cache is full and evict an entry if necessary
    if (ni->cache_hit_count + 1 >= ni->cache_size) {
        size_t index = ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[ni->cache_hit_count / ni->cache_size]->index;
        pthread_rwlock_wrlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].lock);

        ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].is_cached = false;
        ni->cache_hit_count--;

        pthread_rwlock_unlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].lock);
    }

    // Add the new MAC_PDU to the cache
    size_t index = ni->count % ni->cache_size;
    pthread_rwlock_wrlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].lock);

    ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].index = ni->count;
    ((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].is_cached = true;
    ni->cache_hit_count++;
    pthread_rwlock_unlock(&((CacheEntry*)((char*)ni + sizeof(NetworkInterface)))[index].lock);

    return mac_pdu;
}
