#include <unistd.h>

#define MAX_CONNECTIONS 100
#define TIMEOUT 5

typedef struct {
    int sockfd;
    time_t last_used;
} Connection;

typedef struct Pool {
    Connection connections[MAX_CONNECTIONS];
    pthread_mutex_t mutex;
    int num_connections;
    bool fallback;
    char *fallback_host;
    int fallback_port;
} Pool;

Pool *create_pool(const char *host, int port, bool fallback, const char *fallback_host, int fallback_port) {
    Pool *pool = malloc(sizeof(Pool));
    pool->num_connections = 0;
    pool->fallback = fallback;
    pool->fallback_host = fallback_host;
    pool->fallback_port = fallback_port;

    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

Connection *acquire_connection(Pool *pool) {
    Connection *conn;

    pthread_mutex_lock(&pool->mutex);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!pool->connections[i].sockfd || time(NULL) - pool->connections[i].last_used > TIMEOUT * TIMEOUT) {
            conn = &pool->connections[i];
            conn->sockfd = establish_connection(pool->fallback ? pool->fallback_host : host, pool->fallback ? pool->fallback_port : port);
            if (conn->sockfd > 0) {
                conn->last_used = time(NULL);
                pool->num_connections++;
                break;
            }
        }
    }

    pthread_mutex_unlock(&pool->mutex);

    if (!conn) {
        perror("No available connection found.");
        exit(1);
    }

    return conn;
}

void release_connection(Pool *pool, Connection *conn) {
    pthread_mutex_lock(&pool->mutex);
    conn->last_used = time(NULL);
    pool->num_connections--;
    pthread_mutex_unlock(&pool->mutex);
}

void cleanup_pool(Pool *pool) {
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool->connections[i].sockfd > 0) {
            close(pool->connections[i].sockfd);
        }
    }
}

