public class ProfileUpdater {
    private static final int MAX_BATCH_SIZE = 5000;
    private static final Pattern USER_ID_PATTERN = Pattern.compile("^[a-zA-Z0-9]{12}$");
    private static final Pattern URL_PATTERN = Pattern.compile("(https?|ftp)://([-A-Z0-9@:%._\\+~#=]{1,256}\\.[a-z]{2,})");
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[\\w-\\.]+@([\\w-]+\\.)+[a-zA-Z]{2,4}$");
    private static final Pattern PHONE_NUMBER_PATTERN = Pattern.compile("-?(\\d{3})[-. ]?(\\d{3})[-. ]?\\d{4}");

    private static ConcurrentLinkedQueue<UserProfileUpdate> updateQueue = new ConcurrentLinkedQueue<>();
    private static Map<String, File> validFiles = new HashMap<>();
    private static Logger logger;

    public void processUpdates(byte[] inputData) {
        try {
            UserProfileBatch batch = UserProfileBatch.parseFrom(inputData);

            for (UserProfileUpdate update : batch.getUserProfilesList()) {
                if (!processUpdate(update)) {
                    continue;
                }
                updateQueue.add(update);
            }

            processQueue();
        } catch (Exception e) {
            logger.error("Error processing updates: " + e.getMessage());
        }
    }

    public void validateFiles(List<String> filePaths) {
        List<File> validFilesTemp = new ArrayList<>();
        for (String path : filePaths) {
            File file = new File(path);
            if (!file.exists() || !file.isFile() || !file.canRead()) {
                logger.error("Invalid or inaccessible file: " + path);
                continue;
            }
            validFilesTemp.add(file);
        }
        validFiles.putAll(validFilesTemp.stream().collect(HashMap::new, (m, k) -> m.put(k.getAbsolutePath(), k), HashMap::putAll));
    }

    private boolean processUpdate(UserProfileUpdate update) {
        // Validate user_id, display_name, profile_picture_url, bio, location fields
        if (!USER_ID_PATTERN.matcher(update.getUserId()).matches() || update.getUserId().length() != 12) {
            logger.error("Invalid user ID: " + update.getUserId());
            return false;
        }

        if (update.getDisplayName().length() > 50) {
            logger.error("Invalid display name length: " + update.getDisplayName().length());
            return false;
        }

        Matcher urlMatcher = URL_PATTERN.matcher(update.getProfilePictureUrl());
        if (!urlMatcher.matches()) {
            logger.error("Invalid profile picture URL: " + update.getProfilePictureUrl());
            return false;
        }

        if (update.getBio().length() > 160) {
            logger.error("Invalid bio length: " + update.getBio().length());
            return false;
        }

        if (update.getLocation().length() > 50) {
            logger.error("Invalid location length: " + update.getLocation().length());
            return false;
        }

        // Optional fields validation
        if (update.getBirthDate() != null && !isValidDate(update.getBirthDate())) {
            logger.error("Invalid birth date format: " + update.getBirthDate());
            return false;
        }

        if (update.getEmail() != null && !EMAIL_PATTERN.matcher(update.getEmail()).matches()) {
            logger.error("Invalid email: " + update.getEmail());
            return false;
        }

        if (update.getPhoneNumber() != null && !PHONE_NUMBER_PATTERN.matcher(update.getPhoneNumber()).matches()) {
            logger.error("Invalid phone number format: " + update.getPhoneNumber());
            return false;
        }

        // JSON validation for privacy_settings
        if (update.getPrivacySettings() != null && !isValidJson(update.getPrivacySettings())) {
            logger.error("Invalid privacy settings: " + update.getPrivacySettings());
            return false;
        }

        return true;
    }

    // Helper methods for validation and logging...
}
