    int ret = 0;

    parse_json(args->rules, &json);
    if (!json) {
        log("Error: Invalid transformation rules.");
        return false;
    }

    // Validate OAuth2 response
    if (!json_object_get_string(json, "access_token") ||
        !json_object_get_int(json, "expires_in") ||
        !strcmp(json_object_get_string(json, "token_type"), "Bearer") ||
        json_object_get_int(json, "expires_in") <= 0) {
        log("Error: Invalid OAuth2 response.");
        ret = false;
        goto cleanup;
    }

    // Use TLS if required
    if (args->use_tls) {
        SSL *ssl = tls_init();

        // Connect to server and send access token
        int sockfd = connect_to_server("remote_server_endpoint", ssl);
        if (sockfd < 0) {
            log("Error: Failed to connect to server.");
            ret = false;
            goto cleanup;
        }

        // Send access token and receive response
        send(sockfd, json_object_to_json_string(json), strlen(json_object_to_json_string(json)), 0);

        char buffer[4096];
        memset(buffer, 0, sizeof(buffer));
        ssize_t n = recv(sockfd, buffer, sizeof(buffer), 0);
        if (n <= 0) {
            log("Error: Failed to receive response from server.");
            ret = false;
            goto cleanup;
        }

        json_object *response_json = json_tokener_parse(buffer);
        if (!response_json || !json_object_get_string(response_json, "error")) {
            log("Error: Invalid or unexpected response from server.");
            ret = false;
            goto cleanup;
        }

        // Close the connection and clean up
        close(sockfd);
        SSL_free(ssl);
    }

    // Read input file, process contents, write output file
    FILE *in = fopen(args->input_file, "rb");
    if (!in) {
        log("Error: Failed to open input file.");
        ret = false;
        goto cleanup;
    }

    void *data;
    size_t size;
    read_file(in, &data, &size);

    process_binary_data(data, size, args->rules);

    write_file(args->output_file, data, size);
    fclose(in);
    free(data);
    ret = true;

cleanup:
    json_object_put(json);
    return ret;
}

