struct TransactionFrame {
    std::string transaction_id;
    std::string sender_account;
    std::string receiver_account;
    int amount;
    std::string currency;
    std::string transaction_status;
    double transaction_fee;
    std::string reference_number;
    nlohmann::json error_logs;
};

struct TransactionFrameChunk {
    size_t start;
    size_t end;
    std::vector<boost::intrusive_ptr<TransactionFrame>> frames;
};

class TransactionFrameManager {
private:
    static constexpr size_t CHUNK_SIZE = 1024;
    static constexpr size_t INITIAL_CAPACITY = 64;
    std::atomic<size_t> num_frames_{0};
    std::vector<boost::intrusive_ptr<TransactionFrameChunk>> chunks_;
    mutex data_mutex;
    condition_variable cv_data;

public:
    TransactionFrameManager(size_t capacity = INITIAL_CAPACITY) {
        resize(capacity);
    }

    void resize(size_t capacity) {
        if (capacity == 0)
            throw std::invalid_argument("Initial capacity cannot be zero.");

        while (num_frames_ + CHUNK_SIZE > capacity)
            chunks_.pop_back();

        if (num_frames_ + CHUNK_Size <= capacity) {
            TransactionFrameChunk chunk;
            chunk.start = num_frames_;
            chunk.end = num_frames_ + CHUNK_Size;
            chunks_.push_back(std::move(chunk));
            ++num_frames_;
        }
    }

    void insert(const TransactionFrame& tf) {
        auto it = std::lower_bound(chunks_[0].frames.begin(), chunks_[0].frames.end(), tf,
                                   [](const auto& a, const auto& b) { return a->transaction_id < b->transaction_id; });
        if (it == chunks_[0].frames.end()) {
            it = chunks_[0].frames.emplace(it, std::make_shared<TransactionFrame>(tf));
        } else {
            // Ensure unique transaction_id
            while (it != chunks_[0].frames.end() && it->get()->transaction_id == tf.transaction_id) {
                ++it;
            }
            it = chunks_[0].frames.insert(it, std::make_shared<TransactionFrame>(tf));
        }
        resize((size_t)(num_frames_ + 1));
    }

    // ... Implement deletion and retrieval operations based on transaction_id

private:
    static size_t chunkFor(size_t id) { return id / CHUNK_SIZE; }
    static size_t offsetFor(size_t id) { return id % CHUNK_SIZE; }
};

