#define MAX_CONCURRENT 10000

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct list {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
};

void* create_and_populate(void* arg) {
    struct list* list = (struct list*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    // Populate the structure with random data
    pdu->tag.rnti = rand();
    pdu->rnti = (RNTI)pdu->tag.rnti;
    pdu->crc_indication.crci = rand() % 32;
    pdu->crc_indication.cfi = rand() % 4;
    pdu->crcflag = rand() % 2;

    pthread_mutex_lock(&list->lock);
    if (list->count < list->capacity) {
        list->data[list->count++] = *pdu;
    } else {
        free(pdu);
    }
    pthread_mutex_unlock(&list->lock);

    return NULL;
}

void manage_list(struct list* list, size_t capacity) {
    if (!list || capacity <= 0) return;

    list->capacity = capacity;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!list->data) return;

    pthread_mutex_init(&list->lock, NULL);
    pthread_t threads[MAX_CONCURRENT];

    for (size_t i = 0; i < MAX_CONCURRENT; ++i) {
        if (pthread_create(&threads[i], NULL, create_and_populate, list)) break;
    }

    for (size_t i = 0; i < MAX_CONCURRENT; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```
