struct stats {
    size_t lines;
    size_t max_len;
    size_t min_len;
};

void print_usage(const char *prog_name);
int process_file(const char *filename, struct stats *stats, int compressed, const char *format);
void merge_stats(struct stats *a, struct stats *b, const char *format);

static const char *prog_name;
static int verbose = 0;
static char outfile[256] = {0};
static char format_str[256] = "%d lines, %d shortest, %d longest";
static struct stats file_stats[256], total_stats;
sem_t log_lock;
void (*custom_comparator)(size_t *, size_t *);
char delimiter = '\n';

void print_log(const char *message) {
    sem_wait(&log_lock);
    fprintf(stderr, "%s\n", message);
    sem_post(&log_lock);
}

int main(int argc, char **argv) {
    prog_name = argv[0];
    int opt;
    while ((opt = getopt(argc, argv, "cso:f:vmhM:")) != -1) {
        switch (opt) {
            case 'c':
                // Compress mode
                break;
            case 's':
                // Semicolon delimiter
                delimiter = ';';
                break;
            case 'o':
                strcpy(outfile, optarg);
                break;
            case 'f':
                strcpy(format_str, optarg);
                break;
            case 'v':
                verbose++;
                break;
            case 'm':
                // Merge mode
                break;
            case 'h':
            case 'M':
                print_usage(prog_name);
                return EXIT_SUCCESS;
            default:
                print_usage(prog_name);
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        // Print usage without files
        print_usage(prog_name);
        return EXIT_SUCCESS;
    }

    sem_init(&log_lock, 0, 1);

    // Handle directories
    DIR *dir = opendir(argv[optind]);
    if (dir) {
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", argv[optind], entry->d_name);
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
                continue;
            }
            struct stat file_stat;
            if (lstat(path, &file_stat) != 0) {
                print_log("Error: Cannot access path.");
                return EXIT_FAILURE;
            }

            if (S_ISDIR(file_stat.st_mode)) {
                process_directory(path);
            } else if (S_ISREG(file_stat.st_mode)) {
                process_file(path, &file_stats[optind - argc + 1], verbose > 0, format_str);
            }
        }
        closedir(dir);
    } else {
        for (int i = optind; i < argc; ++i) {
            process_file(argv[i], &file_stats[optind - argc + 1 - argc + i], verbose > 0, format_str);
        }
    }

    if (merge_mode()) {
        merge_stats(&total_stats, &file_stats[0], format_str);
    }

    sem_destroy(&log_lock);

    // Output or print usage if necessary
    if (strlen(outfile)) {
        int fd = open(outfile, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (fd != -1) {
            dup2(fd, STDOUT_FILENO);
            close(fd);
        } else {
            print_log("Error: Cannot open output file.");
            return EXIT_FAILURE;
        }
    } else {
        if (merge_mode()) {
            printf("\nAggregated Statistics:\n");
        }
        for (int i = 0; i < optind - argc + 1; ++i) {
            print_file_stats(&file_stats[i], format_str);
        }
    }

    return EXIT_SUCCESS;
}
