    // Allocate initial capacity based on server configuration.
    rm->capacity = sc->max_connections / 10; // Placeholder value.
    return rm;
}

ServerConfiguration* create_server_configuration() {
    ServerConfiguration* sc = malloc(sizeof(ServerConfiguration));
    if (!sc) return NULL;

    sc->max_connections = 1000;
    sc->min_int = 0;
    sc->max_int = 1000;
    sc->min_float = 0.0;
    sc->max_float = 100.0;
    sc->default_config_char = 'D';
    return sc;
}

RequestHandler** reallocate_request_handlers(ResourceManager* rm, size_t new_capacity) {
    RequestHandler** handlers = realloc(rm->handlers, new_capacity * sizeof(RequestHandler*));
    if (!handlers) return NULL;

    memset(&handlers[rm->count], 0, (new_capacity - rm->capacity) * sizeof(RequestHandler*));
    rm->capacity = new_capacity;
    return handlers;
}

int main(int argc, char* argv[]) {
    ServerConfiguration* sc = create_server_configuration();
    if (!sc) {
        fprintf(stderr, "Error: Failed to allocate memory for server configuration.\n");
        return 1;
    }

    int opt;
    while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
        switch (opt) {
            case 'c':
                sc->max_connections = atoi(optarg);
                break;
            case 's':
                sc->min_int = atoi(optarg);
                sc->max_int = atoi(optarg + 2);
                break;
            case 'o':
                // Handle output file.
                break;
            default:
                fprintf(stderr, "Usage: %s [options]\n", argv[0]);
                return 1;
        }
    }

    ResourceManager* rm = create_resource_manager(sc);
    if (!rm) {
        free(sc);
        fprintf(stderr, "Error: Failed to allocate memory for resource manager.\n");
        return 1;
    }

    FILE* input_file = argc > optind ? fopen(argv[optind], "r") : stdin;
    if (!input_file) {
        fprintf(stderr, "Error: Failed to open input file.\n");
        free(sc);
        free(rm);
        return 1;
    }

    char line[256];
    size_t line_count = 0;
    while (fgets(line, sizeof(line), input_file)) {
        ++line_count;
    }

    if (!feof(input_file)) {
        fprintf(stderr, "Error: Unexpected end of file.\n");
        free(sc);
        free(rm);
        fclose(input_file);
        return 1;
    }

    fseek(input_file, 0, SEEK_SET); // Reset file position to beginning.
    RequestHandler** handlers = rm->handlers;

    while (fgets(line, sizeof(line), input_file)) {
        ClientConnection* cc = create_client_connection(sc);
        if (!cc) {
            free(sc);
            free(rm);
            fclose(input_file);
            return 1;
        }

        // Assign ID to the new connection and add it to the appropriate RequestHandler object.
        cc->id = handlers[line_count]->count++;
        handlers[line_count]->connections = realloc(handlers[line_count]->connections, ++handlers[line_count]->capacity * sizeof(ClientConnection));
        handlers[line_count]->connections[cc->id] = cc;
    }

    fclose(input_file);

    // Print the number of lines and connections.
    printf("Number of lines: %zu\n", line_count);
    printf("Total connections: %zu\n", rm->count);

    free(sc);
    free(rm);
    return 0;
}
