// Custom Memory Pool Allocator
class MemoryPool {
public:
    void* allocate(size_t size) {
        // Dynamic scaling based on current load
        if (free_memory_pool_.empty()) {
            if (num_allocated_ <= max_allocated_) {
                num_allocated_ += chunk_size_;
                allocated_memory_.push_back(std::unique_ptr<char[]>(new char[chunk_size_]));
            }
        }
        void* memory = free_memory_pool_.front();
        free_memory_pool_.pop_front();
        return memory;
    }

    void deallocate(void* ptr, size_t) {
        free_memory_pool_.push_back(static_cast<char*>(ptr));
    }

private:
    std::deque<void*> free_memory_pool_;
    std::vector<std::unique_ptr<char[]>> allocated_memory_;
    std::mutex mtx;
    size_t num_allocated_{0};
    static constexpr size_t chunk_size_{4096}; // Adjust as needed for your use case
    static constexpr size_t max_allocated_{1048576}; // Maximum allocated memory, adjustable based on requirements
};

struct Item {
    std::string name;
    int value;
};

class DynamicCollection {
public:
    explicit DynamicCollection(size_t initial_capacity)
        : collection_(MemoryPool::allocate),
          num_items_{0},
          max_value_{0},
          avg_value_{0.0},
          updated_items_{0} {}

    void addItem(const std::string& name, int min_value, int max_value) {
        auto it = std::find_if(collection_.begin(), collection_.end(),
                               [name](const Item* item) { return item->name == name; });

        if (it != collection_.end()) {
            (*it)->value = randomNumber(min_value, max_value);
            ++updated_items_;
        } else {
            if (collection_.size() >= num_items_) {
                resize();
            }
            Item* newItem = MemoryPool::allocate;
            new (newItem) Item{name, randomNumber(min_value, max_value)};
            collection_.push_back(newItem);
            ++num_items_;
        }
