        auto newCapacity = collection_.size() * 2;
        auto* newCollection = MemoryPool::allocate(newCapacity * sizeof(Item*));
        std::memcpy(newCollection, collection_.data(), collection_.size() * sizeof(Item*));
        free_memory_pool_.push_back(collection_);
        collection_.reset(new Collection(newCapacity));
    }

    int randomNumber(int min, int max) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        return uniform_int_distribution<int>(min, max)(gen);
    }

    std::unique_ptr<Item*> collection_; // Managed by the custom memory pool allocator
