    SimpleMemPool memPool; // Use a SimpleMemPool for demonstration purposes
    Data data(&memPool, nullptr);

    size_t numRecords = 10;
    auto recordInitSeq = []() { return {0, 1, 3.14}; }; // Custom initialization sequence for records
    data.allocateRecords(numRecords, recordInitSeq);

    size_t numElements = 100;
    auto randomArray = data.allocateRandomArray(numElements, 100);

    // ... Access the allocated memory here
}
