[' Here is a C++11 solution using `std::vector` for efficient memory management and `std::mutex` for thread safety. The function `populateDLSRBConfigurationList` takes an output reference to a `std::vector<DL_SRB_CONFIGURATION>`, an optional maximum number of entries, and returns a status indicating success or failure.

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <memory>

struct DL_SRB_CONFIGURATION {
    uint32_t SRB_ID;
    uint16_t PDCP_SN;
    enum class SN_STATE : int8_t { UNKNOWN, ACTIVE, INACTIVE } SN_State;
};

struct Status {
    bool success = true;
    std::string message;
};

std::unique_ptr<Status> populateDLSRBConfigurationList(std::vector<DL_SRB_CONFIGURATION>& configurations, size_t maxSize = 2048) {
    auto status = std::make_unique<Status>();
    std::mutex mtx;
    configurations.reserve(maxSize);

    std::thread workers[std::thread::hardware_concurrency()];

    auto generateConfiguration = [&](DL_SRB_CONFIGURATION& config) {
        // Generate a configuration and fill it with appropriate data.
        config.SRB_ID = rand();
        config.PDCP_SN = rand() % 65536;
        config.SN_State = DL_SRB_CONFIGURATION::SN_STATE::UNKNOWN;
    };

    for (size_t i = 0; i < maxSize; ++i) {
        DL_SRB_CONFIGURATION config;
        std::unique_lock<std::mutex> lock(mtx);
        configurations.push_back(config);
        lock.unlock();

        workers[i % std::thread::hardware_concurrency()] = std::thread(generateConfiguration, std::ref(config));
    }

    for (auto& worker : workers) {
        if (worker.joinable())
            worker.detach();
    }

    // Collect and process the results from each thread.
    for (auto& worker : workers) {
        if (worker.joinable())
            worker.join();
    }

    if (configurations.size() != maxSize) {
        status->success = false;
        status->message = "Not all configurations were generated.";
    }

    return status;
}
```

Unit tests for the function can be implemented using a testing framework like Google Test or Catch2, stress-testing can be achieved by increasing the number of threads and/or entries in the test cases. A test case might look something like this:

```cpp
TEST(PopulateDLSRBConfigurationListTest, Basic) {
    std::vector<DL_SRB_CONFIGURATION> configurations;
    auto status = populateDLSRBConfigurationList(configurations);

    EXPECT_TRUE(status->success);
    EXPECT_EQ(configurations.size(), 2048);
}
