        if (list[i].SRB_ID == srb_id) {
            // Move all elements after the deleted one to fill the gap
            for (; i + 1 < current_entries; ++i) list[i] = list[i+1];
            --current_entries;
            pthread_mutex_unlock(&list_lock);
            free(temp);
            return;
        }
    }
    pthread_mutex_unlock(&list_lock);

    // If the item was not found, log a conflict and return without modifying the list
    log_conflict();
}

bool expand_list() {
    DL_SRB_CONFIGURATION* temp;

    if (!max_entries) return false;

    temp = realloc(list, (max_entries + chunk_size) * sizeof(DL_SRB_CONFIGURATION));
    if (!temp) return false; // Return failure on out-of-memory condition

    list = temp;
    max_entries += chunk_size;
    return true;
}

void test_batch_insertion() {
    int i;
    for (i = 0; i < 1024 * 1024; ++i) insert((DL_SRB_CONFIGURATION){.SRB_ID = i, .PDCP_SN = -1, .SN_STATE = FREE});
}

void test_batch_deletion() {
    int i;
    for (i = 0; i < current_entries; ++i) delete(list[i].SRB_ID);
}
