    MAC_RX_STATS_RECORD_T* data;
    struct MemoryPoolNode_t* next;
} MemoryPoolNode_t;

MemoryPoolNode_t* head = NULL;
MemoryPoolNode_t* tail = NULL;

void init_memory_pool(size_t n) {
    for (size_t i = 0; i < n; ++i) {
        MemoryPoolNode_t* new_node = (MemoryPoolNode_t*) mmap(NULL, sizeof(MAC_RX_STATS_RECORD_T), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (!new_node) {
            // Handle mmap failure
        }
        new_node->data = (MAC_RX_STATS_RECORD_T*) new_node;
        new_node->next = NULL;
        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = tail->next;
        }
    }
}

MAC_RX_STATS_RECORD_T* get_from_memory_pool() {
    if (!head) return NULL;
    MemoryPoolNode_t* node = head;
    head = head->next;
    return node->data;
}

