#define MAX_LIST_SIZE 4096
sem_t list_mutex;
int list_size = 0;
PHY_RX_FRAME_INFO* list;

void log(const char* message) {
    // Replace with your preferred logging mechanism
    fprintf(stderr, "[LOG]: %s\n", message);
}

void resize_list(int new_size) {
    if (new_size > MAX_LIST_SIZE) {
        log("Error: Exceeded maximum list size.");
        return;
    }

    PHY_RX_FRAME_INFO* temp = realloc(list, new_size * sizeof(PHY_RX_FRAME_INFO));
    if (!temp) {
        log("Error: Failed to allocate memory for resizing list.");
        return;
    }
    list = temp;
}

void add_to_list(const PHY_RX_FRAME_INFO* frame_info) {
    sem_wait(&list_mutex);
    if (list_size >= MAX_LIST_SIZE) {
        log("Error: List is full. Cannot add more frames.");
        sem_post(&list_mutex);
        return;
    }
    list[list_size] = *frame_info;
    list_size++;
    sem_post(&list_mutex);
}

PHY_RX_FRAME_INFO* get_from_list(unsigned int index) {
    if (index >= MAX_LIST_SIZE || index >= list_size) {
        log("Error: Index out of bounds.");
        return NULL;
    }

    sem_wait(&list_mutex);
    PHY_RX_FRAME_INFO* frame = &list[index];
    sem_post(&list_mutex);

    return frame;
}

void initialize() {
    resize_list(16); // Initialize with a small list size to minimize memory footprint
    list_size = 0;
    list = realloc(list, MAX_LIST_SIZE * sizeof(PHY_RX_FRAME_INFO));
    if (!list) {
        log("Error: Failed to allocate initial memory for the list.");
        return;
    }
    sem_init(&list_mutex, 0, 1); // Initializing the mutex with a value of 1 allows only one thread to access the list at any given time.
}
