// Pool allocator function for thread-safe memory allocation
void* pool_alloc(size_t size) {
    pthread_mutex_t *mutex = (pthread_mutex_t*) __builtin_offsetof(Pool, mutex);
    void *ptr;

    if (__sync_bool_compare_and_swap(&pool->next_block, pool->free_block, NULL)) {
        ptr = pool->base + pool->free_block;
        pool->free_block += size;
    } else {
        ptr = malloc(size);
        if (ptr == NULL) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
    }

    return ptr;
}

// Pool deallocation function for thread-safe memory deallocation
void pool_free(void *ptr) {
    if (ptr >= pool->base && ptr < pool->base + pool->size) {
        pool->free_block += ptr - (pool->base + pool->free_blocks[0]);
        __sync_fetch_and_add(&pool->num_free_blocks, 1);
    } else {
        free(ptr);
    }
}

// Custom pool data structure
typedef struct Pool {
    void *base;
    size_t size;
    void *free_block; // pointer to the next free block in the pool
    size_t free_blocks[128]; // an array of pointers to blocks that are currently free and ready for reuse.
    pthread_mutex_t mutex;
    int num_free_blocks;
} Pool;

// Function to create a new dynamic collection of items with a given initial size and seed for the random number generator
Item* create_collection(size_t initial_size, int range_min, int range_max, int seed) {
    srand(seed);
    // Initialize pool allocator
    Pool *pool = malloc(sizeof(Pool));
    pool->base = malloc(initial_size * sizeof(Item));
    pool->size = initial_size;
    pool->free_block = NULL;
    pool->num_free_blocks = 0;
    for (int i = 0; i < initial_size; ++i) {
        pool->free_blocks[i] = (char*)(pool->base + i);
    }
    pthread_mutex_init(&pool->mutex, NULL);

    Item *collection = calloc(initial_size, sizeof(Item));

    for (size_t i = 0; i < initial_size; ++i) {
        collection[i].name[0] = '\0';
        collection[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    return collection;
}

// Function to dynamically resize the collection based on the number of items in it. The pool allocator will be used for memory allocation.
void resize_collection(Item **collection, size_t *size) {
    // Calculate new size
    const int capacity = *size * 2;
    void *new_block = pool_alloc(capacity * sizeof(Item));
    if (new_block == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    // Copy existing items to the new block and update pointers
    for (size_t i = 0; i < *size; ++i) {
        memcpy((char*)new_block + i * sizeof(Item), collection[i], sizeof(Item));
    }
    *collection = (Item*)new_block;
    *size = capacity;
}

// Function to serialize the collection to a file
void serialize(FILE *file, Item *collection, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        fwrite(collection[i].name, sizeof(char), strlen(collection[i].name) + 1, file);
        fwrite(&(collection[i].value), sizeof(int), 1, file);
    }
}

// Function to deserialize the collection from a file
void deserialize(FILE *file, Item *collection, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        fread(collection[i].name, sizeof(char), strlen(collection[i].name) + 1, file);
        fread(&(collection[i].value), sizeof(int), 1, file);
    }
}
