// Custom thread-safe memory pool
typedef struct MemoryBlock {
    void* data;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

MemoryBlock* memory_pool = NULL;
pthread_mutex_t memory_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* pool_allocate(size_t size) {
    pthread_mutex_lock(&memory_pool_mutex);
    MemoryBlock* current = memory_pool;
    if (!current) {
        current = malloc(sizeof(MemoryBlock));
        current->data = NULL;
        current->size = 0;
        current->next = NULL;
        memory_pool = current;
    } else {
        while (current->next && current->next->size >= size) {
            current = current->next;
        }
    }

    if (!current->data || current->size < size) {
        current->data = malloc(size);
        current->size = size;
    }

    void* result = current->data;
    current->data += size;
    current->size -= size;

    pthread_mutex_unlock(&memory_pool_mutex);

    return result;
}

void pool_free(void* ptr) {
    pthread_mutex_lock(&memory_pool_mutex);

    MemoryBlock* block = (MemoryBlock*)((uintptr_t)ptr - sizeof(MemoryBlock));
    block->data -= sizeof(MemoryBlock);
    block->size += sizeof(MemoryBlock) + ((uintptr_t)ptr & (sizeof(void*) - 1));

    if (!block->next) {
        memory_pool = block;
    } else {
        block->next->size += block->size;
        free(block);
    }

    pthread_mutex_unlock(&memory_pool_mutex);
}

void garbage_collection() {
    pthread_mutex_lock(&memory_pool_mutex);

    MemoryBlock* current = memory_pool;
    while (current) {
        MemoryBlock* next = current->next;
        if (!current->data || current->size <= sizeof(MemoryBlock)) {
            current->data = NULL;
            current->size = 0;
            free(current);
            current = next;
        } else {
            current = next;
        }
    }

    pthread_mutex_unlock(&memory_pool_mutex);
}

