struct PoolAllocator {
    void *pool;
    size_t size;
    size_t count;
};

void pool_init(struct PoolAllocator* alloc, size_t size, size_t num) {
    alloc->size = size;
    alloc->count = num;
    alloc->pool = malloc(alloc->size * alloc->count);
}

void* pool_malloc(struct PoolAllocator* alloc) {
    if (alloc->count > 0) {
        void *ptr = (char *) alloc->pool + alloc->size * (--alloc->count);
        memset(ptr, 0, alloc->size);
        return ptr;
    }
    void *new_pool = realloc(alloc->pool, alloc->size * (2 * alloc->count));
    if (!new_pool) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    alloc->pool = new_pool;
    alloc->count *= 2;
    return (char *) alloc->pool + alloc->size * (--alloc->count);
