            logs[tenantId].push_back({std::chrono::system_clock::now(), level, message, tenantId});
            totalSize += sizeof(LogEntry);
        } else {
            it->second.push_back({std::chrono::system_clock::now(), level, message, tenantId});
            totalSize += sizeof(LogEntry);
            if (totalSize > maxSizePerTenant * logs.size()) {
