#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char name[256];
    int value;
} Item;

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

struct PoolAllocator {
    Node** nodes;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
};

void pool_init(struct PoolAllocator* alloc, size_t initial_capacity) {
    alloc->nodes = calloc(initial_capacity, sizeof(Node*));
    alloc->capacity = initial_capacity;
    alloc->used = 0;
    pthread_mutex_init(&alloc->lock, NULL);
}

Node* pool_allocate(struct PoolAllocator* alloc) {
    pthread_mutex_lock(&alloc->lock);
    if (alloc->used < alloc->capacity) {
        size_t index = alloc->used++;
        Node* node = &alloc->nodes[index];
        node->next = NULL;
        pthread_mutex_unlock(&alloc->lock);
        return node;
    }
    pthread_mutex_unlock(&alloc->lock);

    // Allocate memory dynamically if the pool is full
    Node* node = malloc(sizeof(Node));
    node->next = NULL;
    alloc->used++;
    return node;
}

void pool_free(struct PoolAllocator* alloc, void* pointer) {
    pthread_mutex_lock(&alloc->lock);
    Node* node = (Node*)pointer;
    node->next = alloc->nodes[--alloc->used];
    pthread_mutex_unlock(&alloc->lock);
}

void pool_garbage_collect(struct PoolAllocator* alloc) {
    // Implement your garbage collection strategy here
}

typedef struct Collection {
    struct PoolAllocator alloc;
    Node** head;
    size_t item_size;
