    size_t total_ops;
} Collection;

void collect_init(Collection* coll, size_t item_size, size_t max_items) {
    pool_init(&coll->alloc, 16);
    coll->head = calloc(max_items, sizeof(Node*));
    coll->item_size = item_size;
    coll->max_items = max_items;
    coll->total_ops = 0;
}

void collect_free(Collection* coll) {
    free(coll->head);
    pool_garbage_collect(&coll->alloc);
}

Node* new_item(const char* name, int range_min, int range_max) {
    Node* item = pool_allocate(&coll->alloc);
    strncpy(item->item.name, name, sizeof(item->item.name));
    item->item.value = rand() % (range_max - range_min + 1) + range_min;
    return item;
}

void collect_insert(Collection* coll, Node* item) {
    size_t index = hash(item->item.name) % coll->max_items;
    pthread_mutex_lock(&coll->alloc.lock);
    item->next = coll->head[index];
    coll->head[index] = item;
    pthread_mutex_unlock(&coll->alloc.lock);
    ++coll->total_ops;
}

// Custom hash function for simple linear probing
size_t hash(const char* key, size_t table_size) {
    uint32_t hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % table_size;
}

