struct Collection* create_collection(unsigned long initial_capacity) {
    struct Collection* collection = mmap(NULL, sizeof(struct Collection), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!collection) return NULL;
    memset(collection, 0, sizeof(struct Collection));

    collection->pool_ptr = mmap(NULL, initial_capacity * sizeof(Item), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!collection->pool_ptr) {
        free(collection);
        return NULL;
