    strcpy(new_item->name, name);
    new_item->value = value;
    new_item->next = collection->head;
    collection->head = new_item;
    collection->total_size++;

    if (collection->capacity <= collection->total_size) {
        unsigned long new_capacity = collection->capacity * 2;
        void* new_pool_ptr = mremap(collection->pool_ptr, collection->pool_size, new_capacity * sizeof(Item), MREMAP_MAYMOVE);
        if (!new_pool_ptr) {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->pool_ptr = new_pool_ptr;
        collection->pool_size = new_capacity * sizeof(Item);
    }

    pthread_mutex_unlock(&collection->lock);
}

