#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Item {
    char name[256];
    int value;
    double timestamp;
} Item;

struct PoolAllocator {
    void* pool;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t lock;
};

void* pool_alloc(struct PoolAllocator* allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);
    void* result = (char*)allocator->pool + allocator->allocated;
    allocator->allocated += size;
    pthread_mutex_unlock(&allocator->lock);
    return result;
}

void pool_free(struct PoolAllocator* allocator, void* ptr) {
    pthread_mutex_lock(&allocator->lock);
    allocator->allocated -= ptr - (char*)allocator->pool;
    pthread_mutex_unlock(&allocator->lock);
}

void pool_init(struct PoolAllocator* allocator, size_t capacity) {
    allocator->capacity = capacity;
    allocator->allocated = 0;
    allocator->pool = malloc(capacity);
    if (!allocator->pool) {
        fprintf(stderr, "Failed to allocate memory for pool\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&allocator->lock, NULL);
}

void pool_destroy(struct PoolAllocator* allocator) {
    free(allocator->pool);
    pthread_mutex_destroy(&allocator->lock);
}

Item* item_new() {
    return (Item*)pool_alloc(&gPool, sizeof(Item));
}

void item_free(Item* item) {
    pool_free(&gPool, item);
}

struct DynamicCollection {
    Item** items;
    size_t capacity;
    size_t count;
    struct PoolAllocator allocator;
};

void dc_init(struct DynamicCollection* collection, size_t initial_capacity, size_t range) {
    collection->items = (Item**)pool_alloc(&gPool, initial_capacity * sizeof(Item*));
    collection->capacity = initial_capacity;
    collection->count = 0;

    srand((unsigned int)time(NULL));

    pool_init(&collection->allocator, initial_capacity * sizeof(Item));
}

void dc_destroy(struct DynamicCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        item_free(collection->items[i]);
    }
    free(collection->items);
    pool_destroy(&collection->allocator);
}

void dc_resize(struct DynamicCollection* collection, size_t new_capacity) {
    if (new_capacity <= collection->count) return;

    Item** new_items = (Item**)pool_alloc(&gPool, new_capacity * sizeof(Item*));
    for (size_t i = 0; i < collection->count; ++i) {
        new_items[i] = collection->items[i];
    }
    pool_free(&gPool, collection->items);
    collection->items = new_items;
    collection->capacity = new_capacity;
}

void dc_insert(struct DynamicCollection* collection, const char* name, int min, int max) {
    if (collection->count == collection->capacity) {
        dc_resize(collection, collection->capacity * 2);
    }

    Item* item = item_new();
    strcpy(item->name, name);
    item->value = rand() % (max - min + 1) + min;
    item->timestamp = time(NULL);
    collection->items[collection->count++] = item;
}

void dc_serialize(const struct DynamicCollection* collection, FILE* file) {
    fwrite(&collection->capacity, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(collection->items[i]->name, sizeof(char), strlen(collection->items[i]->name)+1, file);
        fwrite(&collection->items[i]->value, sizeof(int), 1, file);
        fwrite(&collection->items[i]->timestamp, sizeof(double), 1, file);
    }
}

void dc_deserialize(struct DynamicCollection* collection, FILE* file) {
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);
    dc_resize(collection, capacity);

    for (size_t i = 0; i < capacity; ++i) {
        Item* item = collection->items[i];
        size_t name_len;
        fread(&name_len, sizeof(size_t), 1, file);
        fread(item->name, sizeof(char), name_len, file);
        fread(&item->value, sizeof(int), 1, file);
        fread(&item->timestamp, sizeof(double), 1, file);
    }
}
```

