struct LogEntry : public std::chrono::system_clock::time_point, boost::serializable
{
    LogEntry(LogLevel::LogLevel l, const std::string& msg) : level_(l), message_(msg) {}
    LogLevel::LogLevel level_;
    std::string message_;

    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive& ar, const unsigned int version)
    {
        ar & *this->level_ & this->message_;
    }
};

struct FilterPredicate
{
    virtual bool operator()(const LogEntry& entry) const = 0;
};

class LogManager
{
private:
    std::atomic<size_t> maxSize_{1000};
    std::unordered_map<LogLevel::LogLevel, std::vector<LogEntry>> data_;
    mutable boost::mutex mtx_;
    size_t prunedCount_{0};
    size_t totalMemoryUsage_{0};
    std::string outputFilePath_{"logs.xml"};
    FilterPredicate* filterPredicate_{nullptr};
    bool isFilteringEnabled_{false};
    bool verboseConsoleLogging_{true};
    bool verboseFileLogging_{true};

public:
    void setMaxSize(size_t maxSize) { maxSize_ = maxSize; }
    size_t getMaxSize() const { return maxSize_; }

    void addEntry(const LogLevel::LogLevel level, const std::string& msg)
    {
        LockGuard lock(mtx_);
        auto it = data_.find(level);
        if (it == data_.end())
            it = data_.emplace(level, std::vector<LogEntry>()).first;
        it->second.push_back(LogEntry(level, msg));
        prune();
    }

    void search(const LogLevel::LogLevel level) const
    {
        LockGuard lock(mtx_);
        auto it = data_.find(level);
        if (it != data_.end())
            for (const auto& entry : it->second)
                std::cout << *entry << '\n';
    }

    void deleteEntry(const LogLevel::LogLevel level, const std::string& msg)
    {
        LockGuard lock(mtx_);
        for (auto& vec : data_)
        {
            auto it = std::find_if(vec.second.begin(), vec.second.end(),
                [level,msg](const LogEntry& entry){ return entry.level_ == level && entry.message_ == msg; });
            if (it != vec.second.end())
                vec.second.erase(it);
        }
        prune();
    }

    void setFilterPredicate(FilterPredicate* predicate) { filterPredicate_ = predicate; isFilteringEnabled_ = true; }
    void disableFiltering() { filterPredicate_ = nullptr; isFilteringEnabled_ = false; }

    // Implement pruning, serialization, deserialization, logging to console and file, thread safety, etc.
};

