void parseFile(const std::string &path, size_t chunkSize) {
    std::ifstream file(path);
    if (!file) {
        std::cerr << "Error: Cannot open file '" << path << "'" << std::endl;
        return;
    }

    int lineNum = 0;
    size_t pos = 0;
    while (pos < file.tellg()) {
        lines.push_back(std::string());
        if (lineNum + 1 >= chunkSize) {
            processLine(lines[lineNum]);
            lineNum = 0;
            mtx.lock();
            for (auto &l : lines)
                processLine(l);
            mtx.unlock();
        }

        pos = file.tellg();
        file.seekg(pos + 1, std::ios_base::cur);
        if (!file.getline(&lines[lineNum][0], lines.size(), '\n')) {
            processLine(lines[lineNum]);
            lineNum = 0;
        } else {
            ++lineNum;
        }
    }
