    uuid_parse_t parsed_uuid;
    uuid_unparse_t unparsed_uuid;

    uuid_parse(&parsed_uuid, UUID_ZERO); // Generate a new UUID if none is provided
    uuid_unparse(uuid, &unparsed_uuid);

    char* uuid_ptr = (char*)malloc(strlen(uuid) + 1);
    strcpy(uuid_ptr, uuid);
