    // Handle invalid input parameters
    if (!input || size_limit < 1 || !buffer || buffer_size < strlen(input)) return NULL;

    // Allocate memory for the unique identifier and concatenated string
    char* result = (char*)malloc(strlen(input) + size_limit + 1);
    if (!result) return NULL;

    // Copy input to result, excluding size limit
    strncpy(result, input, strlen(input) < size_limit ? strlen(input) : size_limit - 1);
    result[strlen(input)] = '\0'; // Ensure null-terminated string

    // Append unique identifier if input does not exceed the specified size limit
    if (strlen(result) + sizeof("UUID") < size_limit) {
        strcat(result, generate_uuid());
    }

    // Handle buffer overflow and efficient memory management
    if (strlen(result) > buffer_size - 1) {
        free(result);
        return NULL;
    }

    // Copy result to buffer if provided
    if (buffer) {
        strncpy(buffer, result, buffer_size - 1);
        buffer[buffer_size - 1] = '\0';
    }

    log_function_call();

    return result;
}
