    memcpy(new_list, states, num_states * sizeof(FSA_Node*));
    new_list[num_states] = NULL;
    free(states);
    current = new_list;
    for (int i = 0; i < num_states - 1; ++i) {
        current->next = states[current->state + 1];
        current = current->next;
    }
    current->next = states[current->state];
    return new_list;
