    int num_states;
    int** transitions;
} FSA;

typedef struct _StateList {
    int* states;
    struct _StateList* next;
    pthread_mutex_t lock;
} StateList;

StateList* processFSAStr(char* str, size_t limit, char* buffer, int* states, int num_states, FSA* fsa, int last_state) {
    if (!str || !fsa || !states || !num_states || num_states <= 0 || last_state < 0 || limit <= 0) return NULL;

    pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    int* state_counts = calloc(num_states, sizeof(int));
    if (!state_counts) return NULL;

    unsigned char* decompressed_str = NULL;
    size_t decompressed_len = 0;
    if (is_compressed(str)) {
        unsigned long decompressed_len_estimate;
        decompress((Bytef)str, strlen(str), &decompressed_str, &decompressed_len_estimate);
        decompressed_str = mmap(NULL, decompressed_len_estimate, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (!decompressed_str) {
            free(state_counts);
            return NULL;
        }
        decompress((Bytef)str, strlen(str), (Bytef)decompressed_str, &decompressed_len);
    } else {
        decompressed_str = strdup(str);
        if (!decompressed_str) {
            free(state_counts);
            return NULL;
        }
    }

    char* processed_str = malloc(limit + strlen(decompressed_str) + 16); // Allow for UUID or timestamp
    if (!processed_str) {
        if (buffer) {
            strncpy(buffer, decompressed_str, limit - 1);
            buffer[limit - 1] = '\0';
        }
        free(decompressed_str);
        free(state_counts);
        return NULL;
    }

    if (strlen(decompressed_str) + 16 > limit) {
        free(processed_str);
        if (buffer) {
            strncpy(buffer, decompressed_str, limit - 1);
            buffer[limit - 1] = '\0';
        }
        free(decompressed_str);
        free(state_counts);
        return NULL;
    }

    strncat(processed_str, decompressed_str, limit - strlen(decompressed_str) - 1);
    uuid_t uuid;
    uuid_generate(uuid);
    snprintf(processed_str + strlen(decompressed_str), 16, "%08x-%04x-%04x-%04x-%08x",
             uuid_time_low(uuid), uuid_time_mid(uuid),
             uuid_time_hi_and_version(uuid), uuid_clock_seq_high_and_stream(uuid), uuid_clock_seq_low(uuid));

    int current_state = 0;
    for (size_t i = 0; i < strlen(processed_str); ++i) {
        pthread_mutex_lock(&log_lock);
        state_counts[fsa->transitions[current_state][fsa->last_state]]++;
        pthread_mutex_unlock(&log_lock);
        current_state = fsa->transitions[current_state][processed_str[i]];
    }

    int* states_list = malloc((strlen(processed_str) + 1)*sizeof(int));
    if (!states_list) {
        free(processed_str);
        free(decompressed_str);
        free(state_counts);
        return NULL;
    }

    int* cursor = states_list;
    *cursor++ = current_state;
    int last_read_state = current_state;
    for (int i = strlen(processed_str) - 1; i >= 0; --i) {
        last_read_state = fsa->transitions[last_read_state][processed_str[i]];
        *cursor++ = last_read_state;
    }

    StateList* state_list = malloc(sizeof(StateList));
    if (!state_list) {
        free(states_list);
        free(decompressed_str);
        free(processed_str);
        free(state_counts);
        return NULL;
    }

    state_list->states = states_list;
    state_list->next = NULL;
    pthread_mutex_init(&state_list->lock, NULL);

    int* current = fsa->states;
    for (int i = 0; i < last_state + 1; ++i) {
        if (*current++ == last_state) {
            state_list->next = malloc(sizeof(StateList));
            if (!state_list->next) {
                free(states_list);
                free(decompressed_str);
                free(processed_str);
                free(state_counts);
                free(state_list);
                return NULL;
            }
            state_list->next->states = states_list;
            state_list = state_list->next;
            pthread_mutex_init(&state_list->lock, NULL);
        }
    }

    fsa->states[last_state] = (int)state_list - (int)state_list->states;

    StateList** cursor_ptr = &fsa->states[last_state];
    while (*cursor_ptr) {
        cursor_ptr = &(*cursor_ptr)->next;
    }
    *cursor_ptr = state_list;

    free(decompressed_str);
    free(processed_str);
    free(state_counts);

    return state_list->states;
}
