User* create_user(const char *name, const char *email, const char *password) {
    User *user = (User *)malloc(sizeof(User));
    if (!user) return NULL;

    // Ensure string limits and prevent null values
    size_t len = strlen(name);
    if (len > 255 || !name || !email || !password) {
        free(user);
        return NULL;
    }

    strcpy(user->key, name);
    if (strlen(user->key) >= len) user->key[len] = '/';

    // Generate random value within specified range
    user->value = (double)((rand() << 16) | rand()) / (RAND_MAX / 100.0);

    return user;
}

struct UserCollection* create_user_collection(unsigned int initial_capacity) {
    struct UserCollection *collection = (struct UserCollection *)malloc(sizeof(struct UserCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->users = (User **)calloc(initial_capacity, sizeof(User *));
    if (!collection->users) {
        free(collection);
        return NULL;
    }

    return collection;
}

void resize_user_collection(struct UserCollection *collection) {
    struct UserCollection temp = *collection;
    unsigned int new_capacity = temp.capacity * 2;
    User **new_users = (User **)realloc(temp.users, new_capacity * sizeof(User *));

    if (!new_users) {
        free(temp.users);
        free(collection);
        return;
    }

    temp.users = new_users;
    temp.capacity = new_capacity;
    *collection = temp;
}

void append_user(struct UserCollection *collection, User *user) {
    if (collection->size >= collection->capacity) resize_user_collection(collection);

    user->next = collection->users[collection->size];
    collection->users[collection->size++] = user;
}

User* get_user(struct UserCollection *collection, const char *key) {
    for (unsigned int i = 0; i < collection->size; ++i) {
        if (!strcmp(collection->users[i]->key, key)) return collection->users[i];
    }

    return NULL;
}

void delete_user(struct UserCollection *collection, const char *key) {
    User **prev = &collection->users[0];

    for (unsigned int i = 0; i < collection->size; ++i) {
        if (!strcmp((*prev)->key, key)) {
            User *user = *prev;
            *prev = user->next;
            free(user);
            --collection->size;
            break;
        }

        prev = &(*prev)->next;
    }
}

