public class CommandExecutor {
    private static final String SUFFIX = "-appended";
    private static final AtomicLong callCounter = new AtomicLong();
    private static final long MAX_COMMAND_LENGTH = 1024 * 64; // Maximum command length in bytes (can be adjusted)

    public String executeCommandWithSafety(String input, int sizeLimit, int maxBufferSize, byte[] buffer, String command, File workingDirectory) {
        if (input == null || command == null || workingDirectory == null) {
            throw new IllegalArgumentException("Invalid input parameters.");
        }

        if (sizeLimit < 0 || maxBufferSize < 0) {
            throw new IllegalArgumentException("Size limit and maximum buffer size must be non-negative.");
        }

        if (buffer != null && buffer.length < maxBufferSize) {
            return null;
        }

        String appendedInput = input + SUFFIX;
        if (appendedInput.length() <= sizeLimit && (buffer == null || appendedInput.getBytes(StandardCharsets.UTF_8).length <= maxBufferSize)) {
            // Optimized path for small strings
            if (buffer != null) {
                System.arraycopy(appendedInput.getBytes(), 0, buffer, 0, appendedInput.length());
                return buffer;
            } else {
                return appendedInput;
            }
        } else {
            // Fallback path for large strings
            if (buffer != null && appendedInput.getBytes(StandardCharsets.UTF_8).length <= maxBufferSize) {
                System.arraycopy(appendedInput.getBytes(), 0, buffer, 0, appendedInput.length());
                return buffer;
            } else {
                return null;
            }
        }
    }

    public Process executeCommand(String command, File workingDirectory) throws IOException, InterruptedException {
        // Delete file if it exists before executing the command
        if (workingDirectory.exists()) {
            workingDirectory.delete();
        }

        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        processBuilder.directory(workingDirectory);

        Process process = processBuilder.redirectInput(Redirect.inherit).redirectErrorStream(true).start();

        // Execute command and read output/error streams
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        StringBuilder output = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        // Logging and exception handling omitted for brevity

        process.waitFor();
        return process;
    }
}
