    uint16_t RNTI;
    union {
        struct {
            uint8_t CRCFLAG : 1;
        } _field1;
        uint8_t byte;
    };
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct arena {
    void *start, *end;
};

static struct arena *arena_pool = NULL;

void *arena_alloc(size_t size) {
    if (!arena_pool) {
        arena_pool = mmap(NULL, 1 << 20, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (arena_pool == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }
    void *ptr = arena_pool + (arena_pool - (void *)arena_pool->start) - size;
    if (ptr < arena_pool->start || ptr >= arena_pool->end) {
        perror("Out of memory in arena");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

bool is_valid_tag(uint32_t tag, void (*validation_cb)(uint32_t)) {
    if (validation_cb)
        return validation_cb(tag);
    return true;
}

bool is_unique_rnti(uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T** list, size_t* count) {
    for (size_t i = 0; i < *count; ++i) {
        if ((*list)[i].RNTI == rnti)
            return false;
    }
    *count += 1;
    return true;
}

void populateNfaapiCrcList(NFAPI_CRC_INDICATION_PDU_T** list, size_t* count, uint32_t start_tag, void (*validation_cb)(uint32_t), size_t max_size) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    *list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        perror("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }

    arena_pool->start = *list;
    arena_pool->end = *list + max_size;

    pthread_t threads[max_size];
    size_t thread_index = 0;

    for (size_t i = 0; thread_index < max_size && count[0] < max_size; ++i) {
        if (is_unique_rnti(i, list, count)) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = arena_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_create(&threads[thread_index++], NULL, (void*(*)(void*))[](void *arg) {
                NFAPI_CRC_INDICATION_PDU_T *pdu = arg;
                while (true) {
                    if (!is_valid_tag(start_tag + count[0], validation_cb)) continue;

                    pdu->RX_UE_INFORMATION_TAG = start_tag + count[0];
                    pdu->RNTI = i;
                    pdu->_field1.CRCFLAG = (rand() % 2) ? 1 : 0;
                    pdu->CRC_INDICATION_REL8_TAG = htonl(i << 3 | pdu->_field1.CRCFLAG);
                    pthread_mutex_lock(&lock);
                    (*list)[count[0]] = *pdu;
                    pthread_mutex_unlock(&lock);
                    break;
                }
                return NULL;
            }, &pdu);
        }
    }

    for (size_t i = 0; i < thread_index; ++i) {
        pthread_join(threads[i], NULL);
