typedef void* MEM_POOL;
typedef struct {
    MEM_POOL pool;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

void nfapi_crc_list_init(NFAPI_CRC_LIST_T* list, MEM_POOL pool, size_t capacity) {
    if (!list || !pool) return;

    list->pool = pool;
    list->size = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_list_push(NFAPI_CRC_LIST_T* list) {
    if (!list || list->count >= list->size) return NULL;

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)pthread_getspecific(list->pool);

    if (!pdus || list->count >= list->size) {
        void* new_pool;
        if (pthread_key_create(&list->pool, &new_pool) != 0) {
            pthread_mutex_unlock(&list->mutex);
            return NULL;
        }
        list->pool = new_pool;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = pdus + list->count++;
    generate_crc_indication(pdu->crc_indication);

    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

bool nfapi_crc_list_is_unique(NFAPI_CRC_LIST_T* list, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdus[i].rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool populateNfaapiCrcList(NFAPI_CRC_LIST_T* list, validate_callback validate) {
    if (!list || !validate) return false;

    bool success = true;
    while (success) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = nfapi_crc_list_push(list);
        if (!pdu) break;

        success = nfapi_crc_list_is_unique(list, pdu->rnti);
        if (success && validate(pdu->tag, pdu->rnti)) {
            log_success();
        } else {
            free(pdu);
            success = false;
        }
    }

    return true;
}
