int processFSAStr(char* str, size_t size_limit, char* buffer, int* states, int num_states, struct FSA* fsa, int last_state, int* error) {
    *error = NO_ERROR;

    // Check for invalid parameters
    if (size_limit < 0 || !str || !fsa || last_state >= fsa->states_count || fsa->states_count <= 0) {
        *error = INVALID_PARAM;
        return NULL;
    }

    // Handle string size limit and buffer management
    if (strlen(str) + 1 > size_limit && !buffer) {
        *error = SIZE_LIMIT_EXCEEDED;
        return NULL;
    }

    char* result = buffer;
    if (!result && strlen(str) + 1 > size_limit) {
        result = malloc((strlen(str) + 1 + sizeof(uuid_t)) > size_limit ? size_limit : strlen(str) + 1 + sizeof(uuid_t));
        if (!result) {
            *error = MEMORY_ALLOCATION_FAILURE;
            return NULL;
        }
    }

    // Append unique identifier to the string (e.g., timestamp or UUID)
    strcat(result, ""); // Empty string for UUID
    uuid_generate(result);

    int state = fsa->initial_states[0];
    for (size_t i = 0; i < strlen(str); ++i) {
        int next_state = -1;
        for (int j = 0; j < fsa->states_count; ++j) {
            if (fsa->transitions[state][j] == str[i]) {
                next_state = j;
                break;
            }
        }
        state = next_state != -1 ? next_state : state;
    }
    int* new_states_list = malloc((last_state + 1 - state) * sizeof(int));
    if (!new_states_list) {
        free(result);
        *error = MEMORY_ALLOCATION_FAILURE;
        return NULL;
    }

    int current_state = state;
    new_states_list[0] = current_state;
    for (int i = 1; i < last_state + 1 - state; ++i) {
        current_state = fsa->transitions[current_state][new_states_list[i-1]];
        new_states_list[i] = current_state;
    }

    // Update the 'next' pointer of the last state in the list
    if (fsa)
        fsa->transitions[last_state][new_states_list[last_state + 1 - state - 1]] = new_states_list;

    return new_states_list;
}
