}

// Cache for frequently accessed DataPacket values.
GHashTable *dataPacketCache;

// Function to allocate and process streams with specified constraints.
void allocateAndProcessStreams(size_t numStreams, size_t bufferSize, size_t maxMemoryUsage, uint32_t seed) {
    // Initialize cache if not already done.
    if (!dataPacketCache) dataPacketCache = g_hash_table_new_full(g_int_hash, g_int_equal, free, NULL);

    // Check for invalid input values.
    if (numStreams <= 0 || maxMemoryUsage <= 0) {
        fprintf(stderr, "Invalid inputs: numStreams=%zu, maxMemoryUsage=%zu\n", numStreams, maxMemoryUsage);
        exit(EXIT_FAILURE);
    }

    // Calculate maximum allowed memory per DataStream.
    size_t memPerStream = (maxMemoryUsage * (1024 * 1024)) / numStreams;

    // Allocate and initialize an array of DataStream objects.
    DataStream* streams = malloc(numStreams * sizeof(DataStream));
    for (size_t i = 0; i < numStreams; ++i) {
        streams[i].capacity = bufferSize > memPerStream ? bufferSize : memPerStream;
        streams[i].length = 0;
        streams[i].buffer = calloc(streams[i].capacity, sizeof(DataPacket));
    }

    // Initialize the timestamp and random value of each DataPacket.
    pthread_t threads[numStreams];
    for (size_t i = 0; i < numStreams; ++i) {
        if (pthread_create(&threads[i], NULL, processDataStream, &streams[i])) {
            fprintf(stderr, "Failed to create thread: %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish.
    for (size_t i = 0; i < numStreams; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory.
    for (size_t i = 0; i < numStreams; ++i) {
        free(streams[i].buffer);
    }
    free(streams);
}

// Function to process a single DataStream.
void* processDataStream(void *arg) {
    DataStream *ds = (DataStream *) arg;
    while (ds->length < ds->capacity) {
        DataPacket *dp = initializeDataPacket();
        // Optionally validate DataPacket values against a provided checksum algorithm.
        if (!validateDataPacket(dp)) continue;

        // Cache the DataPacket to improve lookup performance.
        g_hash_table_insert(dataPacketCache, dp->timestamp, dp);

        ds->buffer[ds->length++] = dp;
    }
    return NULL;
}

// Cleanup function to release all allocated memory.
void cleanup() {
    // Free cache and its elements before the DataStream array to handle dangling pointers properly.
    g_hash_table_destroy(dataPacketCache);
    // Release the memory of each DataStream and the DataStream array itself.
}
