} FrameMetrics;

struct CacheNode {
    FrameMetrics *frame_metrics;
    struct CacheNode *next;
};

static FrameMetrics **buffer; // Dynamically allocated array of FrameMetrics pointers
static struct CacheNode *cache; // LRU cache
static size_t buffer_size, cache_size;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
