void prune_buffer() {
    FrameMetrics **current = buffer;
    FrameMetrics *tmp;
    while (*current && ((*current)->timestamp + DELTA_T < time(NULL))) {
        tmp = *current;
        *current = (*current)->next;
        free(tmp->rsi_data);
        free(tmp);
        current = &(*current);
    }
}

void insert(FrameMetrics *frame_metrics) {
    pthread_mutex_lock(&mutex);
    FrameMetrics **slot = buffer + (frame_metrics->timestamp % buffer_size);
    FrameMetrics *tmp = *slot;
    *slot = frame_metrics;
    frame_metrics->next = tmp;

    if (!cache || (frame_metrics->timestamp > cache->frame_metrics->timestamp)) {
        struct CacheNode *new_node = malloc(sizeof(struct CacheNode));
        new_node->frame_metrics = frame_metrics;
        new_node->next = cache;
        cache = new_node;
    } else {
        struct CacheNode *current = cache;
        while (current->next && current->next->frame_metrics->timestamp > frame_metrics->timestamp)
            current = current->next;
        current->next = malloc(sizeof(struct CacheNode));
        current->next->frame_metrics = frame_metrics;
        current->next->next = cache;
        cache = current->next;
    }

    prune_buffer();
    pthread_mutex_unlock(&mutex);
}

FrameMetrics* find(time_t timestamp) {
    pthread_mutex_lock(&mutex);
    struct CacheNode *current = cache;
    while (current) {
        if (current->frame_metrics->timestamp == timestamp) {
            FrameMetrics *tmp = current->frame_metrics;
            pthread_mutex_unlock(&mutex);
            return tmp;
        }
        current = current->next;
    }

    FrameMetrics **slot = buffer + (timestamp % buffer_size);
    FrameMetrics *frame_metrics = *slot;
    pthread_mutex_unlock(&mutex);

    while (frame_metrics) {
        if (frame_metrics->timestamp == timestamp)
            return frame_metrics;
        frame_metrics = frame_metrics->next;
    }

    return NULL;
}

