[' ```c
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _NFAPI_CRC_LIST_T {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* nfapi_crc_list_create(size_t initial_capacity, size_t max_elements) {
    if (initial_capacity == 0 || max_elements == 0)
        return NULL;

    NFAPI_CRC_LIST_T* list = malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list)
        return NULL;

    list->size = 0;
    list->capacity = initial_capacity;
    list->elements = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void nfapi_crc_list_destroy(NFAPI_CRC_LIST_T* list) {
    if (!list)
        return;

    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void nfapi_crc_list_resize(NFAPI_CRC_LIST_T* list, size_t new_capacity) {
    if (new_capacity <= list->size)
        return;

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        fprintf(stderr, "Failed to reallocate memory\n");
        return;
    }

    list->elements = temp;
    list->capacity = new_capacity;
}

bool nfapi_crc_list_add(NFAPI_CRC_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity)
        nfapi_crc_list_resize(list, list->capacity * 2);

    memcpy(&list->elements[list->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool nfapi_crc_list_remove_by_rnti(NFAPI_CRC_LIST_T* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);

    size_t i;
    for (i = 0; i < list->size; ++i) {
        if (list->elements[i].RNTI == rnti) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return true;
}

const NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_list_find_by_rnti(const NFAPI_CRC_LIST_T* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);

    size_t i;
    for (i = 0; i < list->size; ++i) {
        if (list->elements[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, &list->elements[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->mutex);
            return result;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}
```

