        char c;
        iss >> std::get_time(&time, "%Y-%m-%d %H:%M:%S", &c);
    }

    friend std::ostream& operator<<(std::ostream& os, const Timestamp& ts) {
        char* dtf = new char[25];
        strftime(dtf, 25, "%Y-%m-%d %H:%M:%S", localtime(&ts.time));
