    static const int MAX_MEMORY_USAGE = 100 * 1024 * 1024; // 100MB
    std::unordered_map<LogLevel::Type, std::multimap<Timestamp, LogEntry>> logCollection;
    std::vector<NFAPI_CRCI_INDICATION_PDU_T> crcIndicationArray;
    int crcIndicationArrayIndex = 0;

public:
    void insert(LogLevel::Type level, const Timestamp& timestamp, const std::string& message) {
        logCollection[level].insert(std::make_pair(timestamp, LogEntry(level, timestamp, message)));
        prune();
    }

    LogEntry* find(LogLevel::Type level, const Timestamp& timestamp) {
        auto it = logCollection.find(level);
        if (it != logCollection.end()) {
            for (auto jt = it->second.lower_bound(timestamp); jt != it->second.end() && jt->first <= timestamp; ++jt) {
                if (jt->first == timestamp)
                    return &(*jt);
            }
        }
        return nullptr;
    }

    void remove(LogLevel::Type level, const Timestamp& timestamp) {
        auto it = logCollection.find(level);
        if (it != logCollection.end()) {
            auto jt = it->second.find(timestamp);
            if (jt != it->second.end())
                it->second.erase(jt);
        }
    }

    void prune() {
        for (auto& levelLogs : logCollection) {
            levelLogs.second.erase(levelLogs.second.begin(), std::prev(levelLogs.second.end(), MAX_SIZE));
        }
    }

    void serializeToDisk() {
        std::ofstream file("logs.dat", std::ios::binary);
        boost::archive::text_oarchive oa(file);
        oa & BOOST_SERIALIZATION_NVP(logCollection) & BOOST_SERIALIZATION_NVP(crcIndicationArray);
    }

    void deserializeFromDisk() {
        std::ifstream file("logs.dat", std::ios::binary);
        boost::archive::text_iarchive ia(file);
        ia & BOOST_SERIALIZATION_NVP(logCollection) & BOOST_SERIALIZATION_NVP(crcIndicationArray);
    }

    void allocateCrcIndications() {
        if (static_cast<size_t>(crcIndicationArray.size()) + sizeof(NFAPI_CRCI_INDICATION_PDU_T) > MAX_MEMORY_USAGE)
            throw std::runtime_error("Memory allocation failure.");

        for (auto& pdu : crcIndicationArray) {
            pdu.RNTI = rand();
            pdu.CRCFLAG = static_cast<uint8_t>(rand() % 2);
        }
    }

    void validateAndInsertCrcIndication(const NFAPI_CRCI_INDICATION_PDU_T& pdu, std::function<bool(const NFAPI_CRCI_INDICATION_PDU_T&)> checksum) {
        if (!checksum(pdu))
            throw std::runtime_error("Invalid CRC indication.");

        crcIndicationArray[crcIndicationArrayIndex++] = pdu;
    }
};
```

