#include <boost/serialization/access.hpp>
#include <boost/serialization/unordered_map.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/utility.hpp>
#include <boost/serialization/split_freeze.hpp>
#include <boost/crc.hpp>

namespace serialization {
    template<class Archive> void serialize(Archive& ar, LogEntry& entry, const unsigned int version) {
        ar & entry.level;
        ar & entry.timestamp;
        ar & entry.message;
    }
}

struct RX_UE_INFORMATION_TAG {};
struct RNTI {};
struct CRC_INDICATION_REL8_TAG { bool CRCFLAG; };

class LogEntry {
public:
    enum class Level { DEBUG, INFO, WARNING, ERROR };
    Level level;
    time_t timestamp;
    std::string message;

    LogEntry(Level level, const time_t& timestamp, const std::string& message) : level(level), timestamp(timestamp), message(message) {}
};

class LogManager {
private:
    static constexpr size_t MAX_SIZE = 1000;
    static constexpr size_t MEMORY_LIMIT = 10 * 1024 * 1024; // 10 MB
    std::unordered_map<std::pair<Level, time_t>, LogEntry> logEntries;
    std::vector<NFAPI_CRCI_PDU_T> crcIndications;
    boost::crc_32_type checksumAlgorithm;

public:
    void insert(const LogEntry& entry) {
        if (logEntries.size() >= MAX_SIZE) {
            auto it = logEntries.begin();
            while (it != logEntries.end()) {
                if (entry.timestamp > it->second.timestamp) {
                    it = logEntries.erase(it);
                } else {
                    ++it;
                }
            }
        }

        auto [level, timestamp] = std::make_pair(entry.level, entry.timestamp);
        if (logEntries.find(level, timestamp) == logEntries.end()) {
            logEntries[level, timestamp] = entry;
            maintainMemoryUsage();
        }
    }

    LogEntry* find(const Level& level, const time_t& timestamp) {
        auto it = logEntries.find(std::make_pair(level, timestamp));
        return (it != logEntries.end()) ? &it->second : nullptr;
    }

    void erase(LogEntry* entry) {
        if (entry == nullptr) {
            std::cerr << "Cannot erase a null LogEntry pointer." << std::endl;
            return;
        }

        auto it = logEntries.find(std::make_pair(entry->level, entry->timestamp));
        if (it != logEntries.end()) {
            logEntries.erase(it);
            maintainMemoryUsage();
        } else {
            std::cerr << "LogEntry not found." << std::endl;
        }
    }

    void serializeToDisk() {
        std::ofstream file("logs.dat", std::ios::binary | std::ios::out | std::ios::trunc);
        boost::serialization::split_freeze(file, this, version());
    }

    void deserializeFromDisk() {
        std::ifstream file("logs.dat", std::ios::binary | std::ios::in);
        if (!file) {
            std::cerr << "Cannot open logs.dat for reading." << std::endl;
            return;
        }

        boost::serialization::split_freeze(file, this, version());
    }

    void maintainMemoryUsage() {
        if (crcIndications.size() > MEMORY_LIMIT / sizeof(NFAPI_CRCI_PDU_T)) {
            crcIndications.resize((crcIndications.size() * 3) / 4);
        }
    }

    void validateCRCIndicator(const NFAPI_CRCI_PDU_T& indication, uint32_t checksum) {
        if (!indication.CRCFLAG || checksum != checksumAlgorithm.result(reinterpret_cast<const char*>(&indication), sizeof(indication))) {
            std::cerr << "Invalid CRC indicator detected." << std::endl;
        }
    }

private:
    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive& ar, const LogManager&, const unsigned int) {
        ar & logEntries;
        ar & crcIndications;
    }

    template<class Archive> void serialize(Archive& ar, LogManager&, unsigned int version) {
        ar & boost::serialization::base_object<LogManager>(this);
        ar & checksumAlgorithm;
    }
};
```

