#include <boost/serialization/vector.hpp>
#include <boost/serialization/unordered_map.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>
#include <fstream>

class LogEntry {
public:
    enum class Level { DEBUG, INFO, WARNING, ERROR };
    explicit LogEntry(Level level, const std::string& message) : level(level), timestamp(std::time(0)), message(message) {}

    Level get_level() const { return level; }
    time_t get_timestamp() const { return timestamp; }
    const std::string& get_message() const { return message; }

private:
    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive & ar, const unsigned int version) {
        ar & level & timestamp & message;
    }

    Level level;
    time_t timestamp;
    std::string message;
};

struct LogManagerData {
    std::unordered_map<Level, std::vector<LogEntry>> entries;
    size_t max_size;
};

class LogManager {
public:
    explicit LogManager(const std::string& data_file, size_t max_size) : data(max_size), load_mutex(), save_mutex() {
        if (loadFromFile(data_file)) {
            prune();
        }
    }

    void insert(LogEntry entry) {
        std::unique_lock<std::mutex> lock(insert_mutex);
        data.entries[entry.get_level()].emplace_back(entry);
        prune();
    }

    std::vector<LogEntry> searchByLevel(LogEntry::Level level) const {
        std::unique_lock<std::mutex> lock(search_mutex);
        return data.entries.at(level);
    }

    void searchByTimestamp(time_t timestamp) const {
        for (auto& pair : data.entries) {
            for (const auto& entry : pair.second) {
                if (entry.get_timestamp() == timestamp) {
                    std::cout << "Level: " << static_cast<int>(entry.get_level()) << ", Message: " << entry.get_message() << "\n";
                }
            }
        }
    }

    void removeByLevel(LogEntry::Level level) {
        std::unique_lock<std::mutex> lock(remove_mutex);
        data.entries[level].clear();
        prune();
    }

    ~LogManager() { saveToFile("data.txt"); }

private:
    bool loadFromFile(const std::string& file) {
        std::ifstream ifs(file, std::ios::binary);
        if (!ifs) return false;

        LogManagerData data;
        boost::archive::text_iarchive ia(ifs);
        ia & data;

        this->data = std::move(data);
        return true;
    }

    void saveToFile(const std::string& file) {
        std::ofstream ofs(file, std::ios::binary | std::ios::trunc);
        if (!ofs) return;

        boost::archive::text_oarchive oa(ofs);
        oa & this->data;
    }

    void prune() {
        size_t size = 0;
        for (auto& pair : data.entries) {
            size += pair.second.size();
        }
        if (size > data.max_size) {
            for (auto it = data.entries.begin(); size - data.max_size > it->second.size(); ++it) {
                it->second.pop_back();
            }
        }
    }

    std::mutex insert_mutex, search_mutex, remove_mutex, load_mutex, save_mutex;
    LogManagerData data;
};
```

