#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <async_logger.h> // External logging service header

typedef enum {
    LOG_LEVEL_ERROR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_TRACE,
    NUM_LOG_LEVELS
} LogLevel;

struct LogConfig {
    const char *logfile;
    sem_t lock;
    struct timespec last_log[NUM_LOG_LEVELS];
};

static inline bool log_is_rate_limited(const struct LogConfig *config, LogLevel level) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    time_t seconds_since_last = now.tv_sec - config->last_log[level].tv_sec;
    long nanoseconds_since_last = now.tv_nsec - config->last_log[level].tv_nsec;

    if (seconds_since_last >= 1 || (nanoseconds_since_last > 1000000000L / rate_limits[level])) {
        config->last_log[level] = now;
        return false;
    }

    return true;
}

void log_error(const struct LogConfig *config, const char *format, ...) {
    if (log_is_rate_limited(config, LOG_LEVEL_ERROR)) return;

    va_list args;
    va_start(args, format);

    char *message = malloc(1024);
    vsnprintf(message, 1023, format, args);
    message[1023] = '\0'; // Ensure null termination

    async_log_error(config->logfile, message);

    free(message);
    va_end(args);
}

void init_logger(struct LogConfig *config, const char *logfile) {
    sem_init(&config->lock, 0, 1);
    config->logfile = logfile;
    memset(config->last_log, 0, sizeof(config->last_log));
}
```

