static struct config config;

struct log_message {
    char message[1025];
    uint64_t timestamp;
    enum log_level level;
    void* tags; // User-defined tags
};

// Thread-safe configuration accessor functions
void config_init() {
    pthread_mutex_init(&config_mutex, NULL);
}

void config_set(struct config new_config) {
    pthread_mutex_lock(&config_mutex);
    config = new_config;
    pthread_mutex_unlock(&config_mutex);
}

struct config config_get() {
    struct config temp;
    pthread_mutex_lock(&config_mutex);
    temp = config;
    pthread_mutex_unlock(&config_mutex);
    return temp;
}

// Thread-safe logging function
void log(enum log_level level, const char* format, ...) {
    struct log_message msg;
    va_list args;
    time_t rawtime;
    struct tm* timeinfo;
    sem_wait(&rate_limiter); // Rate limiting

    if (time(NULL) - msg.timestamp > 1) {
        msg.timestamp = time(NULL);
        memset(&msg, 0, sizeof(msg));
    } else {
        return; // Drop duplicate log entries
    }

    rawtime = msg.timestamp;
    timeinfo = localtime(&rawtime);
    snprintf(msg.message, sizeof(msg.message), "%.2d:%.2d:%.2d %.4s [%s] ",
             timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
             asctime(timeinfo), config.log_format);

    va_start(args, format);
    vsnprintf(msg.message + strlen(msg.message), sizeof(msg.message) - strlen(msg.message), format, args);
    va_end(args);

    msg.level = level;
    msg.tags = config.tags; // Set user-defined tags

    // Enqueue the log message for asynchronous delivery using the logging service
    log_service_enqueue(&msg);
}

void setup() {
    config_init();
    // Configure logging thresholds, levels, formats, and filters based on command-line flags or environment variables
    config_set(/* Your configuration initialization logic here */);

    sem_init(&rate_limiter, 0, config.log_throttle);
}
