// Custom logging service API (asynchronous message delivery)
typedef void (*LogServiceFunc)(const char* message);
LogServiceFunc g_logService;

// Rate limiting parameters
#define MAX_LOG_RATE 100
#define SLIDING_WINDOW_SIZE 60
sem_t rateLimiter;
unsigned int logCount = 0, logRate = 0, timestamp = 0;

void errorLog(const char* format, ...) {
    // Memory management: dynamically allocate strings for logging
    static size_t bufferSize = 1024;
    static char messageBuffer[bufferSize];
    va_list args;
    char *message = messageBuffer;

    // Performance optimization: limit the number of string operations
    if (bufferSize <= strlen(messageBuffer)) {
        bufferSize *= 2;
        message = realloc(message, bufferSize);
        if (!message) {
            fprintf(stderr, "Error: Out of memory\n");
            return;
        }
        messageBuffer = message;
    }

    // Thread safety and rate limiting: acquire the semaphore
    sem_wait(&rateLimiter);

    // Handle variable arguments using va_start and va_end
    va_start(args, format);
    vsnprintf(message, bufferSize - 1, format, args);
    message[bufferSize - 1] = '\0';
    va_end(args);

    // Calculate the current log rate and adjust it based on system load
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    double sysLoad = (double)usage.ru_utime.tv_sec + usage.ru_utime.tv_usec / 1000000;
    logRate = sysLoad > 1.0 ? MAX_LOG_RATE / sysLoad : MAX_LOG_RATE;

    // Log message if the rate limit is not exceeded
    if (++logCount < logRate) {
        timestamp = time(NULL);
        g_logService(message);
    } else {
        free(message);
    }

    // Reset log counters and release the semaphore
    logCount = logRate == 0 ? 0 : (timestamp - timestamp % SLIDING_WINDOW_SIZE) / SLIDING_WINDOW_SIZE;
    sem_post(&rateLimiter);
}

// Initialize the rate limiting mechanism
void initRateLimiting() {
    sem_init(&rateLimiter, 0, SLIDING_WINDOW_SIZE * MAX_LOG_RATE / logRate);
}
```

