#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct ConnectionMetrics {
    int id;
    time_t last_active;
    double bandwidth_usage;
    int error_count;
} ConnectionMetrics;

struct NetworkConnectionMonitor {
    ConnectionMetrics** connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    double bandwidth_threshold;
    void (*alert_callback)(int id);
};

void network_connection_monitor_init(struct NetworkConnectionMonitor* ncm, size_t buffer_size, double bandwidth_threshold, void (*alert_callback)(int)) {
    ncm->connections = malloc(buffer_size * sizeof(ConnectionMetrics*));
    ncm->capacity = buffer_size;
    ncm->size = 0;
    ncm->bandwidth_threshold = bandwidth_threshold;
    ncm->alert_callback = alert_callback;
    pthread_mutex_init(&ncm->lock, NULL);
}

void network_connection_monitor_deinit(struct NetworkConnectionMonitor* ncm) {
    for (size_t i = 0; i < ncm->size; ++i)
        free(ncm->connections[i]);
    free(ncm->connections);
    pthread_mutex_destroy(&ncm->lock);
}

void* network_connection_monitor_process_entry(void* data) {
    struct NetworkConnectionMonitor* ncm = (struct NetworkConnectionMonitor*)data;
    ConnectionMetrics* entry = (ConnectionMetrics*)data;
    time_t now = time(NULL);

    pthread_mutex_lock(&ncm->lock);

    if (entry->bandwidth_usage > ncm->bandwidth_threshold) {
        if (ncm->alert_callback)
            ncm->alert_callback(entry->id);
    }

    bool found = false;
    size_t i;
    for (i = 0; i < ncm->size; ++i) {
        if (ncm->connections[i]->id == entry->id) {
            found = true;
            break;
        }
    }

    if (!found) {
        if (ncm->size >= ncm->capacity) {
            ConnectionMetrics** new_connections = realloc(ncm->connections, sizeof(ConnectionMetrics*) * (ncm->capacity * 2));
            if (!new_connections) {
                pthread_mutex_unlock(&ncm->lock);
                return NULL;
            }
            ncm->connections = new_connections;
            ncm->capacity *= 2;
        }
        ncm->connections[ncm->size++] = entry;
    } else {
        // update the existing entry
    }

    if (now - entry->last_active > 60) { // prune inactive connections every minute
        size_t j;
        for (j = 0; j < ncm->size; ++j) {
            if (!ncm->connections[j]->last_active || now - ncm->connections[j]->last_active > 60) {
                free(ncm->connections[j]);
                memmove(&ncm->connections[j], &ncm->connections[j+1], (ncm->size-j-1)*sizeof(ConnectionMetrics*));
                --ncm->size;
            }
        }
    }

    pthread_mutex_unlock(&ncm->lock);
    return NULL;
}

void network_connection_monitor_insert(struct NetworkConnectionMonitor* ncm, ConnectionMetrics* entry) {
    void* thread_data = entry;
    pthread_t thread;
    pthread_create(&thread, NULL, network_connection_monitor_process_entry, thread_data);
}

void network_connection_monitor_remove(struct NetworkConnectionMonitor* ncm, int id) {
    ConnectionMetrics dummy = {id, time(NULL), 0, 0};
    void* thread_data = &dummy;
    pthread_t thread;
    pthread_create(&thread, NULL, network_connection_monitor_process_entry, thread_data);
}

ConnectionMetrics* network_connection_monitor_find(const struct NetworkConnectionMonitor* ncm, int id) {
    ConnectionMetrics* entry = NULL;
    pthread_mutex_lock(&ncm->lock);

    for (size_t i = 0; i < ncm->size; ++i) {
        if (ncm->connections[i]->id == id) {
            entry = ncm->connections[i];
            break;
        }
    }

    pthread_mutex_unlock(&ncm->lock);
    return entry;
}

void read_and_print(const char* filename) {
    FILE* file = fopen(filename, "r");
    char line[1024];
    size_t line_len;

    if (!file)
        return;

    while (getline(&line, sizeof(line), file) != EOF) {
        line_len = strlen(line);
        char* token = strtok(line, ",");
        if (!token)
            continue;

        double average = 0;
        size_t tokens_count = 1;
        char* current_token = token;
        while ((token = strtok(NULL, ","))) {
            ++tokens_count;
            average += atof(token);
        }

        average /= tokens_count - 1;

        void* line_data = malloc(line_len + 2); // +2 for \0 and '\n'
        memcpy(line_data, line, line_len+1);
        ((char*)line_data)[line_len] = '\n';

        printf("%s\n", line_data);

        free(line_data);
    }

    fclose(file);
}
