    if (it == cacheMap.end()) {
        // Log insertion operation metadata
        cacheMap.emplace(event.type, std::list<AuditEvent>{ event });
    } else {
        it->second.push_back(event);
        // Eviction policies based on LRU mechanism

        // Log insertion operation metadata
    }

    if (cacheMap.size() > maxSize) prune();
}

std::list<AuditEvent> AuditLogManager::search(AuditEvent::EventType type, const boost::posix_time::ptime& timestamp, int userID, const std::string& correlationID) const {
    auto it = cache->find(type);
    if (it == cache->end()) return {};

    std::list<AuditEvent> results;
    for (const auto& event : it->second) {
        if ((event.timestamp == timestamp && event.userID == userID && event.correlationID == correlationID) ||
            (!timestamp && !userID && !correlationID)) {
