    }
}

void AuditLogManager::prune() {
    for (auto& pair : *cache) {
        if (pair.second.size() < maxSize / 2) continue;

        std::list<AuditEvent> toRemove;
        auto it = pair.second.begin();
        while (toRemove.size() + pair.second.size() > maxSize && it != pair.second.end()) {
            // LRU eviction policy based on timestamps
            it = pair.second.erase(it);
            toRemove.push_back(*it);
        }

        // Log pruning operation metadata
    }
