#include <pthread.h>
#include <time.h>

typedef struct FrameMetrics {
    time_t timestamp;
    int signal_strength;
    char* rsi; // Variable-length data field representing received signal indicators (RSI)
} FrameMetrics;

#define BUFFER_SIZE 1024
#define PRUNING_INTERVAL 60 // seconds

static FrameMetrics* buffer;
static size_t count = 0;
static size_t capacity = BUFFER_SIZE;
static time_t pruning_time = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_frame_buffer() {
    buffer = malloc(sizeof(FrameMetrics) * capacity);
    if (!buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for FrameMetrics buffer\n");
        exit(1);
    }
}

void delete_expired_entries() {
    time_t current_time = time(NULL);

    if (current_time < pruning_time) return;

    pthread_mutex_lock(&mutex);
    size_t i, j = 0;

    for (i = 0; i < count; ++i) {
        if (buffer[i].timestamp + PRUNING_INTERVAL > current_time) {
            buffer[j] = buffer[i];
            ++j;
        }
    }

    count = j;
    pruning_time = current_time + PRUNING_INTERVAL;
    pthread_mutex_unlock(&mutex);
}

void insert_frame_metrics(const FrameMetrics* metrics) {
    pthread_mutex_lock(&mutex);

    if (count == capacity) {
        capacity *= 2;
        FrameMetrics* tmp = realloc(buffer, sizeof(FrameMetrics) * capacity);

        if (!tmp) {
            fprintf(stderr, "Error: Failed to resize FrameMetrics buffer\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        buffer = tmp;
    }

    buffer[count] = *metrics;
    ++count;

    pthread_mutex_unlock(&mutex);
}

FrameMetrics* get_frame_metrics(time_t timestamp) {
    size_t i;

    for (i = 0; i < count; ++i) {
        if (buffer[i].timestamp == timestamp) return &buffer[i];
    }

    return NULL;
}
