} FrameMetrics;

struct FrameBuffer {
    FrameMetrics** data;
    size_t capacity;
    size_t length;
    pthread_mutex_t buffer_lock;
};

FrameBuffer* frame_buffer_init(size_t initial_capacity) {
    FrameBuffer* buffer = malloc(sizeof(FrameBuffer));
    buffer->data = calloc((initial_capacity), sizeof(FrameMetrics*));
    buffer->capacity = initial_capacity;
    buffer->length = 0;
    pthread_mutex_init(&buffer->buffer_lock, NULL);
    return buffer;
}

void frame_buffer_destroy(FrameBuffer* buffer) {
