            free(buffer->data[i]->rsi);
            free(buffer->data[i]->metadata);
            free(buffer->data[i]);
        }
    }
    free(buffer->data);
    free(buffer);
}

void inc_ref_count(FrameMetrics* frame) {
    ++frame->ref_count;
}

int dec_ref_count(FrameMetrics* frame) {
    if (--frame->ref_count == 0) {
        return 1;
    }
    return 0;
}

FrameMetrics* acquire_frame(FrameBuffer* buffer, time_t timestamp) {
    FrameMetrics* frame = NULL;
    for (size_t i = 0; i < buffer->length; ++i) {
        if (!buffer->data[i]) continue;
        pthread_mutex_lock(&buffer->data[i]->lock);
        if (buffer->data[i]->timestamp == timestamp && buffer->data[i]->ref_count > 0) {
            inc_ref_count(buffer->data[i]);
            frame = buffer->data[i];
            break;
        }
        pthread_mutex_unlock(&buffer->data[i]->lock);
    }
    if (!frame) {
        FrameMetrics* new_frame = malloc(sizeof(FrameMetrics));
        memset(new_frame, 0, sizeof(FrameMetrics));
        new_frame->timestamp = timestamp;
        new_frame->signal_strength = 0;
        asprintf(&(new_frame->rsi), "");
        asprintf(&(new_frame->metadata), "");
        new_frame->ref_count = 1;
        pthread_mutex_init(&new_frame->lock, NULL);
        frame = new_frame;
    }
    return frame;
}

void release_frame(FrameBuffer* buffer, FrameMetrics* frame) {
    if (dec_ref_count(frame)) {
        pthread_mutex_lock(&buffer->buffer_lock);
        size_t i = 0;
        for (; i < buffer->length; ++i) {
            if (!buffer->data[i]) continue;
            pthread_mutex_lock(&buffer->data[i]->lock);
            if (buffer->data[i] == frame) {
                buffer->data[i] = NULL;
                break;
            }
            pthread_mutex_unlock(&buffer->data[i]->lock);
        }
        if (i == buffer->length) {
            // Not found, assume it's a stale reference and remove it.
            free(frame->rsi);
            free(frame->metadata);
            free(frame);
        }
        pthread_mutex_unlock(&buffer->buffer_lock);
    }
}

void prune_old(FrameBuffer* buffer) {
    time_t now = time(NULL);
    size_t new_length = 0;
    pthread_mutex_lock(&buffer->buffer_lock);
    for (size_t i = 0; i < buffer->length; ++i) {
        if (!buffer->data[i]) continue;
        if (buffer->data[i]->timestamp + buffer->capacity <= now) {
            free(buffer->data[i]->rsi);
            free(buffer->data[i]->metadata);
            free(buffer->data[i]);
            buffer->data[i] = NULL;
        } else {
            buffer->data[new_length++] = buffer->data[i];
        }
    }
    buffer->length = new_length;
    if (buffer->capacity > buffer->length) {
        FrameMetrics** tmp = realloc(buffer->data, buffer->capacity - buffer->length);
        if (!tmp) {
            // Handle allocation failure gracefully.
        } else {
            buffer->data = tmp;
        }
    }
    pthread_mutex_unlock(&buffer->buffer_lock);
}
```

