} FrameMetrics;

struct MetricsBuffer {
    FrameMetrics* metrics;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void randomize(float *value, float min, float max) {
    *value = ((double)rand() / RAND_MAX) * (max - min) + min;
}

FrameMetrics* create_metric() {
    FrameMetrics* metric = malloc(sizeof(FrameMetrics));
    if (!metric) return NULL;
    randomize(&(metric->signal_strength), 0.0, 1.0); // Set signal strength randomly within [0, 1]
    return metric;
}

struct MetricsBuffer* create_buffer(size_t capacity) {
    struct MetricsBuffer* buffer = malloc(sizeof(struct MetricsBuffer));
    if (!buffer) return NULL;
    buffer->metrics = calloc(capacity, sizeof(FrameMetrics));
    if (!buffer->metrics) {
        free(buffer);
        return NULL;
    }
    buffer->capacity = capacity;
    buffer->size = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void delete_metric_at(struct MetricsBuffer* buffer, size_t index) {
    if (index >= buffer->size || index < 0) return;
    pthread_mutex_lock(&buffer->lock);
    FrameMetrics* metric = &buffer->metrics[index];
    free(metric);
    memmove(&buffer->metrics[index], &buffer->metrics[index + 1], (buffer->size - index - 1) * sizeof(FrameMetrics));
    buffer->size--;
    pthread_mutex_unlock(&buffer->lock);
}

void prune_old_entries(struct MetricsBuffer* buffer, time_t current_timestamp, size_t keep_entries) {
    if (keep_entries > buffer->size) keep_entries = buffer->size;
    pthread_mutex_lock(&buffer->lock);
    size_t to_delete = buffer->size - keep_entries;
    for (size_t i = 0; i < to_delete; ++i) {
        delete_metric_at(buffer, i);
    }
    pthread_mutex_unlock(&buffer->lock);
}

FrameMetrics* find_by_timestamp(const struct MetricsBuffer* buffer, time_t timestamp) {
    for (size_t i = 0; i < buffer->size; ++i) {
        if (buffer->metrics[i].timestamp == timestamp) return &buffer->metrics[i];
    }
    return NULL;
}

void insert(struct MetricsBuffer* buffer, FrameMetrics metric) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size >= buffer->capacity) { // Resize if capacity is reached
        FrameMetrics** new_metrics = realloc(buffer->metrics, sizeof(FrameMetrics) * (buffer->capacity * 2));
        if (!new_metrics) {
            pthread_mutex_unlock(&buffer->lock);
            return;
        }
        buffer->metrics = new_metrics;
        buffer->capacity *= 2;
    }
    metric.timestamp = time(NULL);
    randomize(&(metric.signal_strength), 0.0, 1.0); // Set signal strength randomly within [0, 1]
    buffer->metrics[buffer->size++] = metric;
    pthread_mutex_unlock(&buffer->lock);
}

