}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(const char* str, size_t limit, char* buffer) {
    size_t len = strlen(str);
    if (len > limit || limit <= 0)
        return NULL;

    // Add unique identifier to the string if a buffer is not provided
    if (!buffer) {
        char *unique_id = generate_unique_id();
        size_t new_len = len + strlen(unique_id);
        if (new_len > limit) {
            free(unique_id);
            return NULL;
