struct Device {
    std::string id;
    std::string type;
    bool status;
    std::string configuration_data;
    std::chrono::time_point<std::chrono::steady_clock> last_update;

    Device(const std::string& id, const std::string& type, bool status, const std::string& config)
        : id{ id }, type{ type }, status{ status }, configuration_data{ config }, last_update{ std::chrono::steady_clock::now() } {}
};

class DeviceList {
private:
    static constexpr size_t max_devices = 1000;
    std::vector<std::shared_ptr<Device>> devices_;
    std::unordered_map<std::string, size_t> id_index_;
    mutable std::mutex mtx_;
    size_t num_calls_{ 0 };

public:
    DeviceList() = default;

    void add(const std::string& id, const std::string& type, bool status, const std::string& config) {
        std::scoped_lock lock(mtx_);
        if (id.empty()) throw std::invalid_argument{"Invalid device ID"};
        auto it = id_index_.find(id);
        size_t index;
        if (it != id_index_.end())
            index = it->second;
        else {
            if (devices_.size() == max_devices) {
                auto oldest_device = devices_.begin();
                std::advance(oldest_device, max_devices / 2); // Remove the oldest device approximately
                it = id_index_.find((*oldest_device)->id);
                index = it->second;
                devices_.erase(oldest_device);
                id_index_.erase(it);
            }
            index = devices_.size();
            devices_.emplace_back(std::make_shared<Device>(id, type, status, config));
            id_index_[id] = index;
        }
        (*devices_[index])->status = status;
        if (!config.empty())
            (*devices_[index])->configuration_data = config;
        (*devices_[index])->last_update = std::chrono::steady_clock::now();
    }

    void logCalls() {
        ++num_calls_;
        if (num_calls_ % 10000 == 0)
            std::cout << "Device list has been called " << num_calls_ << " times.\n";
    }
};

void processEvent(const std::string& event_data, DeviceList& device_list) {
    std::istringstream iss{ event_data };
    if (!iss) throw std::invalid_argument{"Invalid input format"};

    std::string id, type;
    bool status;
    std::string config_data;

    std::getline(iss >> std::ws, id, ':');
    if (id.empty()) throw std::invalid_argument{"Missing device ID"};

    std::getline(iss >> std::ws, type, ':');
    if (type.empty()) throw std::invalid_argument{"Missing device type"};

    iss >> status;

    if (iss >> config_data) {} // consume leftover data
    else {
        config_data = ""; // set configuration data to an empty string if not present
    }

    device_list.logCalls();
    device_list.add(id, type, status, config_data);
}

