#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

void* generateRNTIs(void* arg) {
    pthread_mutex_t* mutex = (pthread_mutex_t*)arg;
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
    srand(pthread_self());

    while (true) {
        pthread_mutex_lock(mutex);
        uint16_t rnti = rand() % 0x7FFF; // Maximum RNTI value is 0x7FFF
        bool collision = false;

        for (size_t i = 0; i < pthread_getthread_np(); ++i) {
            if (i != pthread_self() && ((pthread_t*)arg)[i]->RNTI == rnti) {
                collision = true;
                break;
            }
        }

        if (!collision) {
            ((pthread_t*)arg)->RNTI = rnti;
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        pthread_mutex_unlock(mutex);
    }

    return NULL;
}

void generateNFAPICRCINDICATIONPDUList(size_t count, NFAPI_CRC_INDICATION_PDU_T** list) {
    if (!list || !count) {
        return;
    }

    pthread_t* thread_handles = malloc(sizeof(pthread_t) * (pthread_getthread_np() + 1));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < count; ++i) {
        ((NFAPI_CRC_INDICATION_PDU_T*)list[i])->RX_UE_INFORMATION_TAG = rand();
        ((NFAPI_CRC_INDICATION_PDU_T*)list[i])->CRC_INDICATION_REL8_TAG[0] = rand() & 0xFF;
        ((NFAPI_CRC_INDICATION_PDU_T*)list[i])->CRC_INDICATION_REL8_TAG[1] = rand() & 0xFF;
        ((NFAPI_CRC_INDICATION_PDU_T*)list[i])->CRC_INDICATION_REL8_TAG[2] = rand() & 0xFF;
        ((NFAPI_CRC_INDICATION_PDU_T*)list[i])->CRC_INDICATION_REL8_TAG[3] = rand() & 0xFF;

        pthread_create(&thread_handles[pthread_getthread_np()], NULL, generateRNTIs, &mutex);
    }

    for (size_t i = 0; i < pthread_getthread_np(); ++i) {
        void* status;
        pthread_join(thread_handles[i], &status);

        if (list[i]->RNTI == 0) {
            free(thread_handles);
            return;
        }
    }

    free(thread_handles);
}
```

