#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
static size_t capacity = 0;
static size_t count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populateNFAPIArray(size_t N) {
    if (N > capacity) {
        // Resize array if needed
        if (capacity == 0) {
            capacity = N;
            array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
        } else {
            NFAPI_CRCI_INDICATION_PDU_T* newArray = malloc(sizeof(NFAPI_CRCI_INDICATION_PDU_T) * (capacity + N));
            memcpy(newArray, array, sizeof(NFAPI_CRCI_INDICATION_PDU_T) * capacity);
            free(array);
            array = newArray;
            capacity += N;
        }
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = count; i < count + N && i < capacity; ++i) {
        uint16_t rnti = 0; // Initialize RNTI to avoid collisions with previous values
        while (i != count && array[i].RNTI == rnti) {
            rnti++;
        }
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 16;
        array[i].CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&mutex);
}
