import os
import hashlib
from concurrent.futures import ThreadPoolExecutor

def file_hash(filename):
    if os.path.getsize(filename) > (10 * (1024 ** 3)):
        # Process in parallel to improve performance
        chunk_size = int(os.path.getsize(filename) / 5)
        with ThreadPoolExecutor() as executor:
            hashes = [hashlib.md5(open(filename, 'rb').read(chunk_size)).hexdigest() for _ in range(5)]
        return hash(''.join(hashes))
    else:
        with open(filename, 'rb') as file:
            return hashlib.md5(file.read()).hexdigest()
