3. Python File Hashing Utility (Using multiprocessing for parallel processing)

```python
import hashlib
import os
from concurrent.futures import ProcessPoolExecutor

def file_hash(filepath, chunksize=65536):
    with open(filepath, 'rb') as f:
        hasher = hashlib.md5()
        for chunk in iter(lambda: f.read(chunksize), b''):
            hasher.update(chunk)
        return hasher.hexdigest()

def process_files_in_parallel(filepaths, num_workers=os.cpu_count() * 2):
    with ProcessPoolExecutor(max_workers=num_workers) as executor:
        results = [executor.submit(file_hash, fp) for fp in filepaths]
        return [res.result() for res in results]
