}

void* checkRNTICollision(void* data) {
    NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*)data;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t index = 0;

    for (; index < N; ++index) {
        if (current == array + index || current->RNTI == (array + index)->RNTI) {
            break;
        }
    }

    if (index == N) {
        // No collision, continue with the next structure.
        return NULL;
    }

    // Collision detected, replace the current RNTI and repeat the check.
    current->RNTI = generateUniqueRNTI();
    pthread_mutex_lock(&mutex);
    for (index = 0; index < N; ++index) {
        if (current == array + index || current->RNTI == (array + index)->RNTI) {
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    if (index == N) {
        // No collision after replacement, continue with the next structure.
        return NULL;
    } else {
        // Recursively check for a collision again.
        pthread_cleanup_push(free(current), NULL);
        current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *current = *((NFAPI_CRC_INDICATION_PDU_T*)data);
        return checkRNTICollision(current);
    }
}
