```python
import hashlib
import os
from concurrent.futures import ProcessPoolExecutor

def md5_hash(file):
    hasher = hashlib.md5()
    with open(file, 'rb') as f:
        chunksize = 64 * (1024 ** 2)
        while True:
            data = f.read(chunksize)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def parallel_process(files, num_workers=os.cpu_count()):
    with ProcessPoolExecutor(max_workers=num_workers) as executor:
        futures = [executor.submit(md5_hash, file) for file in files]
        return [f.result() for f in futures]
