def md5_file(filename, chunksize=65536, progress_cb=None):
    block_size = 65536
    hasher = hashlib.md5()
    with open(filename, "rb") as f:
        while True:
            data = f.read(block_size)
            if not data:
                break
            hasher.update(data)
            if progress_cb:
                progress_cb((len(data), len(filename)))
    return hasher.hexdigest()
