void USession_Insert(Node** list, const struct UserSession* userSession) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return;

    newNode->UserSession = *userSession;
    newNode->next = NULL;

    if (*list == NULL) {
        *list = newNode;
        (*list)->prev = NULL;
    } else {
        (*list)->prev->next = newNode;
        newNode->prev = (*list)->prev;
        (*list)->prev = newNode;
    }

    ++(*list)->size;
}

void USession_Delete(Node** list, Node* nodeToRemove) {
    if (nodeToRemove == NULL || *list == NULL) return;

    if (nodeToRemove == (*list)) {
        (*list) = nodeToRemove->next;
        if ((*list) != NULL) (*list)->prev = NULL;
    } else {
        nodeToRemove->prev->next = nodeToRemove->next;
        if (nodeToRemove->next != NULL) nodeToRemove->next->prev = nodeToRemove->prev;
    }

    free(nodeToRemove);
    --(*list)->size;
}

struct UserSession* USession_RetrieveById(const Node* list, unsigned long userId) {
    for (Node* current = list->head; current != NULL; current = current->next) {
        if (current->UserSession.userId == userId) return &current->UserSession;
    }
    return NULL;
}
