class LogManager {
public:
    LogManager(size_t max_size) : _maxSize(max_size), _pruneInterval(10 * 60 * 1000) {} // 10 minutes interval for pruning

    void insert(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = _entriesByLevel.emplace(entry.level, std::unordered_map<Timestamp, LogEntry>());
        it.first->second.emplace(entry.ts, entry);

        prune();
        lock.unlock();
