    bool CRCFLAG;
    char* str; // Dynamically processed string
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateList(int N, size_t size_limit, const char* input_str, size_t buffer_size) {
    if (N <= 0) return NULL;

    setlocale(LC_CTYPE, ""); // For internationalized strings support

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_init(&mutex, NULL);

    int i;
    char* str;
    for (i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);

        // Generate unique RX_UE_INFORMATION_TAG and RNTI values
        list[i].RX_UE_INFORMATION_TAG = i;
        list[i].RNTI = (uint16_t)(time(NULL) % 0xFFFF);

        // Randomly set CRCFLAG value
        list[i].CRCFLAG = rand() % 2;

        // Generate the dynamically processed string
        if (buffer_size > 0) {
            str = (char*)malloc(buffer_size);
            if (!str) {
                pthread_mutex_unlock(&mutex);
                continue;
            }
        } else {
            str = NULL;
        }

        // Process the input string, ensuring it fits within the buffer (if provided) and appending a unique identifier
        int len = wcslen(input_str);
        if (len > size_limit) {
            pthread_mutex_unlock(&mutex);
            if (buffer_size > 0) free(str);
            continue;
        }

        wcscpy_s(str, size_limit, input_str);
        char timestamp[24];
        sprintf_s(timestamp, sizeof(timestamp), "%llu", time(NULL));
        wcscat_s(str, size_limit - len + strlen(timestamp) + 1, timestamp);

        list[i].str = str;

        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);

    return list;
}
