typedef struct {
    int event_id;
    char source_name[64];
    char message_text[1024];
} LOG_EVENT_RECORD_T;

struct log_counter {
    int count;
    int id;
};

typedef struct log_counter COUNT_T;
COUNT_T* create_count() {
    return calloc(1, sizeof(COUNT_T));
}

void destroy_count(COUNT_T *count) {
    if (count != NULL) {
        free(count);
    }
}

typedef struct thread_data {
    COUNT_T* count;
    LOG_EVENT_RECORD_T log_event;
} THREAD_DATA_T;

void* process_log_entry(void *arg) {
    THREAD_DATA_T *data = arg;
    pthread_mutex_lock(&data->log_event.mutex);
    strncpy(data->log_event.message_text, data->log_event.message_text, sizeof(data->log_event.message_text) - 1);
    pthread_mutex_unlock(&data->log_event.mutex);

    char *pos = data->log_event.message_text;
    char timestamp[20];
    sprintf(timestamp, "%lu", (unsigned long)time(NULL));

    size_t len = strlen(pos);
    if ((len + strlen(timestamp)) > sizeof(data->log_event.message_text) - 1) {
        // Truncate message or return NULL when buffer overflow occurs
        data->log_event.message_text[0] = '\0';
        return NULL;
    }

    strcat(pos, " [");
    strncat(pos, timestamp, strlen(timestamp));
    strcat(pos, "] ");

    ++data->count->count;

    return &data->log_event;
}

int main(int argc, char **argv) {
    setlocale(LC_ALL, "");

    int M = argc > 1 ? atoi(argv[1]) : 0;
    int max_message_size = argc > 2 ? atoi(argv[2]) : 1024;
    char *input_file = argc > 3 ? argv[3] : NULL;

    FILE *file = input_file != NULL ? fopen(input_file, "r") : stdin;

    int line_count = 0;
    int event_count = 0;
    LOG_EVENT_RECORD_T events[M];

    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    while (!feof(file)) {
        line_count++;

        char line[4096];
        size_t bytes = fread(line, 1, sizeof(line), file);
        if (bytes <= 0) break;

        if (strlen(line) > max_message_size) {
            fprintf(stderr, "Message too long: %s\n", line);
            continue;
        }

        int found = -1;
        for (int i = 0; i < event_count && found == -1; ++i) {
            if (events[i].event_id == -1) { // Unassigned log record
                found = i;
                continue;
            }
            if (strcmp(line, events[i].message_text) == 0) {
                events[found].count += events[i].count;
                events[i].count = 0;
                found = -1;
                memset(&events[i], 0, sizeof(LOG_EVENT_RECORD_T));
            }
        }

        if (found == -1) { // Unique event
            if (event_count >= M) {
                LOG_EVENT_RECORD_T *min = events;
                for (int i = 1; i < M; ++i) {
                    min = events[i].count < min->count ? &events[i] : min;
                }
                memset(min, 0, sizeof(LOG_EVENT_RECORD_T));
            }

            events[event_count].event_id = -1;
            strncpy(events[event_count].message_text, line, max_message_size);
            events[event_count].mutex = PTHREAD_MUTEX_INITIALIZER;
            ++event_count;
        }
    }

    fclose(file);

    COUNT_T top_10[10];
    int sorted_indexes[10][2];
    int index = 0;
    for (int i = 0; i < event_count; ++i) {
        if (events[i].event_id == -1) continue;
        COUNT_T *count = &top_10[index];

        if (count->count < events[i].count) {
            if (index != 0) memmove(&top_10[0], &top_10[1], sizeof(COUNT_T) * index);
            count = &top_10[index++];
        }

        count->id = events[i].event_id;
        count->count = events[i].count;
    }

    qsort(sorted_indexes, index, sizeof(sorted_indexes[0]), (int(*)(const void*, const void*))compare);

    printf("Top 10 most frequent event IDs:\n");
    for (int i = 0; i < index && i < 10; ++i) {
        LOG_EVENT_RECORD_T *event = &events[sorted_indexes[i][0]];
        printf("%d: %d (%s)\n", event->event_id, event->count, event->source_name);
    }

    return EXIT_SUCCESS;
}

int compare(const void *a, const void *b) {
    COUNT_T *aa = a;
    COUNT_T *bb = b;
    if (aa->count < bb->count)
        return -1;
    else if (aa->count > bb->count)
        return 1;
    else
        return 0;
}
```

