char* modify_filename(const char* filename) {
    int vowel_count = 0, special_count = 0, extension_length = 0, i;
    const char *special_chars = "@#$%&*()+,-./:;<=>?[]{}|\\^`~!";
    size_t filename_len = strlen(filename);

    for (i = 0; i < filename_len; ++i) {
        if (isalpha(filename[i]) && islower(filename[i]) && strchr(vowels, filename[i]))
            ++vowel_count;
        if (strchr(special_chars, filename[i]))
            ++special_count;
    }

    extension_length = vowel_count / 2 + ((vowel_count % 2) != 0 ? 1 : 0);
    extension_length += special_count > 5 ? 2 : 0;

    char* new_filename = (char*)malloc(filename_len + extension_length + 4); // 4 for "@#$" sequence and null terminator
    memset(new_filename, 0, filename_len + extension_length + 4);

    int j = 0;
    for (i = 0; i < filename_len && j < filename_len + extension_length + 4; ++i) {
        if (filename[i] == ' ')
            continue;

        new_filename[j++] = filename[i];
    }

    for (i = 0; i < extension_length && j < filename_len + extension_length + 4; ++i) {
        if (i >= vowel_count / 2)
            new_filename[j++] = special_chars[(extension_length - i - 1) % strlen(special_chars)] @ "@#$"[i % 3];
    }

    return new_filename;
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        (*list)[i].rxi_tag = rand() % 0xFFFF + 1;
        (*list)[i].rnti = rand() % 0x8000 + 1;
        (*list)[i].crcflag = (rand() % 2) == 1;
    }
}

char* create_and_populate(const char* filename, int N) {
    char* new_filename = modify_filename(filename);
    NFAPI_CRC_INDICATION_PDU_T* list;
    populate_list(&list, N);

    char filename_with_extension[100];
    sprintf(filename_with_extension, "%s.%s", new_filename, ".bin");

    free(new_filename); // Free the temporary new_filename since we're using a copy for the final filename
    return filename_with_extension;
}
