// Function to generate a new extension based on the filename rules
char* generate_extension(const char* filename) {
    int vowel_count = 0, special_count = 0, extension_len = 0, i;
    for (i = 0; filename[i]; ++i) {
        if (islower(filename[i]) && isalpha(filename[i])) {
            switch (tolower(filename[i])) {
                case 'a':
                case 'e':
                case 'i':
                case 'o':
                case 'u':
                    ++vowel_count;
                    break;
                default:
                    if (isalnum(filename[i]) || filename[i] == '_') continue;
                    ++special_count;
            }
        }
    }
    extension_len = vowel_count > 0 ? vowel_count / 4 : 1;
    if (special_count > 5) extension_len += 2;
    if (vowel_count < 4) extension_len++;

    char* extension = malloc(extension_len + 1);
    if (!extension) return NULL;
    memset(extension, 0, extension_len + 1);

    int pos = 0;
    for (i = 0; filename[i]; ++i) {
