    // Handle edge cases: remove leading spaces and trailing spaces
    char* new_filename_ptr = new_filename;
    while (isspace(*new_filename_ptr)) ++new_filename_ptr;
    size_t new_filename_length2 = strlen(new_filename_ptr);
