// Function to handle filename modification and extension generation
void modifyFileName(char* filename, size_t* len) {
    size_t vowelCount = countVowels(filename);
    size_t extLen = vowelCount > 0 ? (vowelCount > 5 ? vowelCount / 4 + 2 : vowelCount / 4 + 1) : 3;
    size_t specialCharCount = 0;
    for (size_t i = 0; filename[i]; ++i) {
        if (isalpha(filename[i]) || isdigit(filename[i])) continue;
        ++specialCharCount;
    }
    if (specialCharCount > 5) extLen += 2;
    if (vowelCount < 4) extLen++;

    size_t newLen = strlen(filename) + extLen;
    if (newLen > 150) {
        // Handle error or truncate filename as needed
        fprintf(stderr, "Filename too long: %s\n", filename);
        return;
    }

    char* newExt = malloc(extLen + 1);
    memset(newExt, 0, extLen + 1);
    for (size_t i = 0; vowelCount > 0; --vowelCount) {
        if (isalpha(filename[i])) newExt[i] = tolower(filename[i]);
    }
    if (extLen - vowelCount >= 2) {
        snprintf(newExt + vowelCount, extLen - vowelCount, "%02d", specialCharCount);
    }
    strcat(newExt, filename + strlen(filename));

    free(filename);
    *len = strlen(newExt);
    memcpy(filename, newExt, *len);
}

// Function to generate NFAPI_CRC_INDICATION_PDU_T structures
void generateStructures(size_t n, FILE* out) {
    // Implement RNTIs frequency tracking, CRCFLAG validation, and logging here.

    RNTI rntis[UINT16_MAX]; // Assuming RNTI is a 16-bit integer
    memset(rntis, 0, sizeof(rntis));

    for (size_t i = 0; i < n; ++i) {
        uint32_t tag = generateUniqueTag();
        RX_UE_INFORMATION_TAG rxUETag = tag;
        uint16_t rnti = findMinRNTI(rntis);
        CRCFLAG crcFlag = rand() % 2; // Generate a random CRCFLAG value

        NFAPI_CRC_INDICATION_PDU_T pdu;
        memset(&pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu.header.present = NFAPI_CRC_INDICATION_HEADER_PR;
        pdu.header.criticalExtensionPresent = false;
        pdu.crcIndicationRel8Tag.present = CRCI_REL8_TAG_PR;
        pdu.crcIndicationRel8Tag.rnti = rnti;
        pdu.crcIndicationRel8Tag.crcFlag = crcFlag;
        pdu.rxUEInformationTag = rxUETag;

        fwrite(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, out);
        rntis[rnti]++; // Update RNTI frequency count
    }
}
