typedef struct {
    PDU_TYPE pdu_type;
    uint32_t sequence_number;
    BSSP_PDU_RX_T *pdu;
} NFAPI_MESSAGE_T;

struct batch {
    size_t max_messages;
    size_t total_memory_limit;
    size_t num_messages;
    NFAPI_MESSAGE_T *messages;
    sem_t semaphore;
};

bool validate_rrc_message(const RRC_MESSAGE *rrc_message);
void init_bssp_pdu(BSSP_PDU_RX_T *pdu, UE_ID *ue_id, RRC_MESSAGE *rrc_message);

struct batch *init_batch(size_t max_messages, size_t total_memory_limit) {
    struct batch *batch = malloc(sizeof(struct batch));
    if (!batch) return NULL;

    batch->max_messages = max_messages;
    batch->total_memory_limit = total_memory_limit;
    batch->num_messages = 0;
    batch->messages = NULL;
    sem_init(&batch->semaphore, 0, max_messages);

    return batch;
}

void destroy_batch(struct batch *batch) {
    if (!batch) return;

    for (size_t i = 0; i < batch->num_messages; ++i) {
        free(batch->messages[i].pdu);
    }
    free(batch->messages);
    sem_destroy(&batch->semaphore);
    free(batch);
}

NFAPI_MESSAGE_T *init_message(struct batch *batch) {
    if (batch->num_messages >= batch->max_messages) return NULL;

    size_t total_memory = sizeof(NFAPI_MESSAGE_T) + sizeof(BSSP_PDU_RX_T);

    if (total_memory > batch->total_memory_limit - (batch->total_memory_usage + batch->num_messages * sizeof(NFAPI_MESSAGE_T))) return NULL;

    NFAPI_MESSAGE_T *message = &batch->messages[batch->num_messages];
    message->pdu_type = INVALID_PDU_TYPE;
    message->sequence_number = 0;

    sem_wait(&batch->semaphore);
    batch->total_memory_usage += total_memory;

    message->pdu = malloc(sizeof(BSSP_PDU_RX_T));
    if (!message->pdu) {
        batch->total_memory_usage -= total_memory;
        sem_post(&batch->semaphore);
        return NULL;
    }

    init_bssp_pdu(message->pdu, &message->ue_id, &message->rrc_message);

    if (!validate_rrc_message(&message->rrc_message)) {
        free(message->pdu);
        message->pdu = NULL;
        batch->total_memory_usage -= total_memory;
        sem_post(&batch->semaphore);
        return NULL;
    }

    message->pdu_type = VALID_PDU_TYPE;
    ++batch->num_messages;

    return message;
}

void init_bssp_pdu(BSSP_PDU_RX_T *pdu, UE_ID *ue_id, RRC_MESSAGE *rrc_message) {
    pdu->ue_id = *ue_id;
    pdu->rrc_message = *rrc_message;
}

bool validate_rrc_message(const RRC_MESSAGE *rrc_message) {
