using boost::asio::steady_timer;
using namespace boost::log;
using namespace std;

constexpr size_t BUFFER_SIZE = 1024;
constexpr size_t RSI_LIMIT = 100;

struct FrameMetrics {
    time_t timestamp;
    int signalStrength;
    string rsiData;
};

using FrameMetricsPool = boost::pool::object_pool<FrameMetrics>;
FrameMetricsPool frameMetricsPool(BUFFER_SIZE);

class FrameBuffer {
public:
    FrameBuffer() : m_timer(io), m_pruningTimer(io) {}

    void insert(const FrameMetrics& data) {
        // Compress RSI data if necessary
        string compressedRsi;
        if (data.rsiData.size() > RSI_LIMIT) {
            compress(data.rsiData.data(), data.rsiData.size(), &compressedRsi);
            data.rsiData = move(compressedRsi);
        }

        // Insert the FrameMetrics into the buffer using a mutex for thread safety
        unique_lock<mutex> lock(m_mutex);
        m_buffer.push_back(data);

        if (m_buffer.size() > BUFFER_SIZE) {
            pop_front(m_buffer);
        }
    }

    FrameMetrics* find(time_t timestamp) {
        unique_lock<mutex> lock(m_mutex);
        auto it = find_if(m_buffer.begin(), m_buffer.end(), [=](const FrameMetrics& data) { return data.timestamp == timestamp; });
        if (it != m_buffer.end()) {
            return &*it;
        }
        return nullptr;
    }

    void remove(time_t timestamp) {
        unique_lock<mutex> lock(m_mutex);
        auto it = find_if(m_buffer.begin(), m_buffer.end(), [=](const FrameMetrics& data) { return data.timestamp == timestamp; });
        if (it != m_buffer.end()) {
            m_buffer.erase(it);
        }
    }

    void startPruning() {
        steady_timer pruningTimer(io, 60s); // Prune every 60 seconds
        pruningTimer.async_wait([this](const boost::system::error_code& error) {
            if (!error) {
                unique_lock<mutex> lock(m_mutex);
                while (m_buffer.size() > BUFFER_SIZE / 2) {
                    pop_back(m_buffer);
                }
                pruningTimer.expires_from_now(60s);
                pruningTimer.async_wait(boost::bind(&FrameBuffer::startPruning, this));
            }
        });
    }

private:
    void compress(const char* src, size_t length, string* dst) {
        // Compress data using zlib
        z_stream strm;
        memset(&strm, 0, sizeof(strm));
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;
        strm.avail_in = length;
        strm.next_in = const_cast<char*>(src);
        strm.avail_out = dst->capacity();
        strm.next_out = &((*dst)[0]);

        int err = deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFLATE_STREAM, -15, 8, Z_DEFAULT_STRATEGY);
        if (err != Z_OK) {
            throw std::runtime_error("Decompression failed");
        }

        int ret;
        do {
            ret = deflate(&strm, Z_NO_FLUSH);
            (*dst).resize((*dst).size() + strm.total_out);
            memcpy(&(*dst)[(*dst).size() - strm.total_out], strm.next_out, strm.total_out);
        } while (ret != Z_STREAM_END);

        deflateEnd(&strm);
    }

    mutable boost::mutex m_mutex;
    steady_timer m_timer; // Performance monitoring timer
    steady_timer m_pruningTimer; // Pruning timer
    vector<FrameMetrics> m_buffer;
};

int main() {
    log4cxx::BasicConfigurator config;
    config.setRootLevel(log4cxx::Priority::DEBUG);
    config.configure();

    FrameBuffer buffer;
    buffer.startPruning();

    // Insert data into the buffer
    auto data1 = frameMetricsPool.construct();
    data1->timestamp = time(nullptr);
    data1->signalStrength = 85;
    data1->rsiData = "01010101";
    buffer.insert(*data1);

    auto data2 = frameMetricsPool.construct();
    data2->timestamp = time(nullptr) + 60; // Timestamp for the next second
    data2->signalStrength = 90;
    data2->rsiData = "11111111";
    buffer.insert(*data2);

    FrameMetrics* found = buffer.find(data1->timestamp);
    if (found) {
        BOOST_LOG_TRIVIAL(info) << "Found data with timestamp: " << found->timestamp;
    } else {
        BOOST_LOG_TRIVIAL(error) << "Data not found";
    }

    buffer.remove(data1->timestamp);

    // Simulate an allocation failure
    frameMetricsPool.construct(); // This will throw an exception
}
