typedef struct Node {
    int value;
    size_t compressed_size;
    char *compressed_data;
    struct Node *next;
} Node;

struct MemoryPool {
    Node **array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    int max_value;
    uLong compression_level;
};

void log_error(const char *message) {
    // Implement logging function to an external system with configurable levels and formats.
}

void compress(char *data, size_t length, char **compressed_data, size_t *compressed_size) {
    // Implement lightweight compression algorithm here.
}

int find_largest(const struct MemoryPool *pool) {
    int largest = INT_MIN;
    const Node *current = pool->array[0];
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (current->value > largest && current->value <= pool->max_value)
            largest = current->value;
        current = current->next;
    }
    pthread_mutex_unlock(&pool->lock);
    return largest;
}

void insert(struct MemoryPool *pool, int value) {
    if (value > pool->max_value) {
        compress((char *)&value, sizeof(int), &(pool->array[0]->compressed_data), &(pool->array[0]->compressed_size));
        value = uncompress((Bytef)(pool->array[0]->compressed_data), pool->array[0]->compressed_size, (Bytef)&value);
    }
    pthread_mutex_lock(&pool->lock);
    Node *current = pool->array[0];
    for (size_t i = 0; i < pool->size; ++i) {
        if (current->next == NULL || current->next->value >= value) {
            current->next = malloc(sizeof(Node));
            current->next->value = value;
            current->next->compressed_data = NULL;
            current->next->compressed_size = 0;
            current->next->next = NULL;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&pool->lock);
}

void delete(struct MemoryPool *pool, int value) {
    pthread_mutex_lock(&pool->lock);
    Node **current = &pool->array[0];
    Node *prev = NULL;
    for (size_t i = 0; i < pool->size; ++i) {
        if ((*current)->value == value) {
            if (prev != NULL)
                prev->next = (*current)->next;
            else
                *current = (*current)->next;
            free((*current));
            break;
        }
        prev = current;
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&pool->lock);
}

struct MemoryPool *create_memory_pool(size_t capacity, int max_value, uLong compression_level) {
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    pool->array = malloc(capacity * sizeof(Node*));
    pool->capacity = capacity;
    pool->size = 0;
    pool->max_value = max_value;
    pool->compression_level = compression_level;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(struct MemoryPool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        Node *current = pool->array[i];
        Node *tmp;
        while (current != NULL) {
            tmp = current;
            current = current->next;
            free(tmp);
        }
    }
    free(pool->array);
    free(pool);
}

#define MAX_THREADS 10
void* worker_function(void *arg) {
    struct MemoryPool *pool = arg;
    // Implement concurrent operation logic here.
}

int main() {
    struct MemoryPool *pool = create_memory_pool(10, INT_MAX, Z_BEST_SPEED);
    pthread_t threads[MAX_THREADS];
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        int ret = pthread_create(&threads[i], NULL, worker_function, pool);
        if (ret != 0) {
            log_error("Thread creation failed.");
            return 1;
        }
    }
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
    destroy_memory_pool(pool);
    return 0;
}
