  } catch (err) {
    res.status(500).send(err.message);
  }
});

// Delete a user profile by ID
router.delete('/:id', async (req, res) => {
  try {
    const userId = req.params.id;
    const result = await User.findByIdAndRemove(userId);
    if (!result) return res.status(404).send('User not found.');
    res.send(`Deleted user with ID: ${userId}`);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

// Retrieve activity history for a user by ID, with pagination support
router.get('/:id/history', async (req, res) => {
  try {
    const userId = req.params.id;
    const page = parseInt(req.query.page || '1');
    const limit = parseInt(req.query.limit || 10);

    const userActivities = await User.findById(userId)
      .populate({ path: 'activities', options: { skip: (page - 1) * limit, limit } })
      .exec();

    if (!userActivities) return res.status(404).send('User not found.');

    const activities = userActivities.activities;
    const totalPages = Math.ceil(activities.length / limit);

    res.send({ activities, totalPages });
  } catch (err) {
    res.status(500).send(err.message);
  }
});
