#define MAX_NAME_LEN 150
#define MAX_LIST_SIZE 100
#define VOWELS "aeiouAEIOU"

typedef struct LTE_Uplink_NAS_Transport_PDU_T {
    unsigned int UE_ID;
    char NAS_Message[256];
    RRC_Connection_Reconfiguration rrc;
} LTE_Uplink_NAS_Transport_PDU_T;

LTE_Uplink_NAS_Transport_PDU_T* create_list(char* filename) {
    int vowel_count = 0, special_count = 0, len = strlen(filename), extension_len = 0, i;
    LTE_Uplink_NAS_Transport_PDU_T *list = malloc(MAX_LIST_SIZE * sizeof(LTE_Uplink_NAS_Transport_PDU_T));
    char *new_filename = malloc(MAX_NAME_LEN);

    for (i = 0; filename[i]; i++) {
        if (strchr(VOWELS, filename[i])) vowel_count++;
        if (!issalnum((unsigned char)filename[i]) && !isspace((unsigned char)filename[i])) special_count++;
    }

    extension_len = vowel_count > 5 ? (vowel_count / 2) : ((vowel_count < 4) ? extension_len + 1 : vowel_count - 5);

    if (special_count > 5) extension_len += 2;

    sprintf(new_filename, "%.*s_%ddd%s", len - special_count - (int)(strlen(VOWELS) * extension_len), trim(filename), extension_len, ".txt");

    for (i = 0; i < MAX_LIST_SIZE; i++) {
        list[i].UE_ID = i + 1; // Ensure unique UE_IDs within the list.
        snprintf(list[i].NAS_Message, sizeof(list[i].NAS_Message), "%08X%04X", rand(), rand());
    }

    return list;
}

char* trim(char *s) {
    char *start = s + strlen(s) - 1;
    for ( ; start > s && isspace(*start); start-- ) ;
    memmove(s, start, strlen(start + 1) + 1);
    return s;
}
