#include "ResourceManager.h"

void ResourceManager::insert(const ResourceRequest& request) {
    std::lock_guard<std::mutex> lock(mtx);
    requests[{request.type, request.resourceID}].push_back(request);
    if (requests[{request.type, request.resourceID}].size() > MAX_SIZE) prune();
}

ResourceRequest* ResourceManager::find(const RequestType& type, const int& resourceID, const int& clientID) {
    std::lock_guard<std::mutex> lock(mtx);
    auto it = requests.find({type, resourceID});
    if (it == requests.end()) return nullptr;

    for (auto& request : it->second) {
        if (request.clientID == clientID) return &request;
    }
    return nullptr;
}

void ResourceManager::remove(const ResourceRequest& request) {
    std::lock_guard<std::mutex> lock(mtx);
    auto it = requests.find({request.type, request.resourceID});
    if (it == requests.end()) return;

    it->second.remove_if([&](const ResourceRequest& r) { return (r.clientID == request.clientID); });
}

void ResourceManager::prune() {
    std::lock_guard<std::mutex> lock(mtx);
    auto now = std::chrono::system_clock::now();
    auto diff = now - lastPruneTime;
    if (diff > std::chrono::seconds(60)) {
        lastPruneTime = now;

        auto it = requests.begin();
        while (it != requests.end()) {
            for (auto& request : it->second) {
                if (std::difftime(request.timestamp.tm_sec, std::time(nullptr)) > 60) {
                    it = requests.erase(it);
                } else {
                    ++it;
                    break;
                }
            }
        }
    }
}

