    uint8_t NAS_Message[1024];
    struct RRC_Connection_Reconfiguration *RRC_Connection;
} LTE_Uplink_NAS_Transport_PDU_T;

struct container {
    size_t count;
    LTE_Uplink_NAS_Transport_PDU_T **list;
    pthread_mutex_t mutex;
};

int isVowel(char c) {
    return (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u');
}

size_t vowelCount(const char *filename) {
    size_t count = 0;
    for (size_t i = 0; filename[i]; ++i) {
        if (isVowel((unsigned char)filename[i]))
            count++;
    }
    return count;
}

int specialCount(const char *str, size_t len) {
    int count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (!isalnum((unsigned char)str[i]) && str[i] != '_' && str[i] != '.')
            count++;
    }
    return count > 5 ? count - 5 : 0;
}

char *generateFilename(const char *input_filename) {
    size_t vowel_count = vowelCount(input_filename);
    size_t extension_length = (vowel_count + specialCount(input_filename, strlen(input_filename))) / 2;
    if (extension_length > 5)
        extension_length += input_count(input_filename, '.') * 2;
    char extension[extension_length + 1];
    snprintf(extension, sizeof(extension), "%.*d", extension_length, vowel_count);
    if (vowel_count < 4)
        strcat(extension, "_");

    size_t filename_len = strlen(input_filename);
    char *filename = malloc(150 + extension_length);
    memset(filename, ' ', 150);
    strncpy(filename + strlen(filename) - filename_len, input_filename, filename_len);
    strcat(filename, extension);
    return filename;
}

LTE_Uplink_NAS_Transport_PDU_T* createList(size_t size) {
    LTE_Uplink_NAS_Transport_PDU_T *list = malloc(sizeof(LTE_Uplink_NAS_Transport_PDU_T) * size);
    for (size_t i = 0; i < size; ++i) {
        list[i].UE_ID = i + 1; // Assuming UE_IDs start at 1
        memset(list[i].NAS_Message, rand() % 256, sizeof(list[i].NAS_Message));
        // Assuming RRC_Connection is allocated elsewhere and provided to the function
    }
    return list;
}

char* manageListAndFilename(const char *input_filename, size_t *num_structures) {
    struct container *container = malloc(sizeof(*container));
    container->count = 0;
    container->list = NULL;
    container->mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_t thread_id;
    for (size_t i = 0; i < *num_structures; ++i) {
        pthread_create(&thread_id, NULL, populateThread, container);
        if (pthread_join(thread_id, NULL)) {
            fprintf(stderr, "Error joining thread\n");
            exit(EXIT_FAILURE);
        }
    }

    LTE_Uplink_NAS_Transport_PDU_T *list = container->list;
    char *filename = generateFilename(input_filename);

    // Free resources
    free(container);
    for (size_t i = 0; i < container->count; ++i) {
        free(list[i].RRC_Connection);
    }
    free(list);

    return filename;
}

void* populateThread(void *arg) {
    struct container *container = arg;
    pthread_mutex_lock(&container->mutex);
    LTE_Uplink_NAS_Transport_PDU_T *new_item = createList(1)[0];
    container->list = realloc(container->list, (container->count + 1) * sizeof(*container->list));
    container->list[container->count] = new_item;
    ++container->count;
    pthread_mutex_unlock(&container->mutex);
    return NULL;
}
