pthread_mutex_t queue_mutex; // Mutex for the queue buffer
struct {
    Entry entries[1024]; // Queue buffer
    int head, tail;
} queue;

void add_to_queue(Entry e) {
    pthread_mutex_lock(&queue_mutex);
    if ((queue.head + 1) % ARRAY_SIZE(queue.entries) == queue.tail) {
        // Queue is full, drop the update
        pthread_mutex_unlock(&queue_mutex);
        return;
    }
    queue.entries[queue.head] = e;
    queue.head = (queue.head + 1) % ARRAY_SIZE(queue.entries);
    pthread_mutex_unlock(&queue_mutex);
}

Entry dequeue() {
    if (queue.head == queue.tail) return nullptr;

    Entry e = queue.entries[queue.tail];
    queue.tail = (queue.tail + 1) % ARRAY_SIZE(queue.entries);
    return e;
}

