#include <list>
#include <deque>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <boost/circular_buffer.hpp>
#include <pthreads.h>

class AuditEvent {
public:
    enum EventType { LOGIN, LOGOUT, TRANSACTION, ERROR };
    std::chrono::system_clock::time_point timestamp;
    int userID;
    std::string ipAddress;
    std::string message;
    EventType type;

    AuditEvent(EventType t, const std::chrono::system_clock::time_point& tstamp, int uid, const std::string& ip, const std::string& msg, EventType eventType)
        : timestamp(tstamp), userID(uid), ipAddress(ip), message(msg), type(eventType) {}
};

class LRUCache {
public:
    LRUCache(size_t capacity) : _capacity(capacity), _lru() {}

    void access(const AuditEvent& event) {
        auto it = _lru.find(event);
        if (it != _lru.end()) {
            _lru.erase(it);
            _lru.emplace_back(event);
        } else {
            if (_lru.size() == _capacity) {
                _lru.pop_front();
            }
            _lru.emplace_back(event);
        }
    }

private:
    std::deque<AuditEvent> _lru;
    size_t _capacity;
};

class AuditLogManager {
public:
    using Events = std::unordered_map<std::pair<EventType, std::chrono::system_clock::time_point>, std::list<AuditEvent>>;

    AuditLogManager(size_t maxSize) : _maxSize(maxSize), _cache(50), _observers(), _mutex(), _cv() {}

    void insert(const AuditEvent& event) {
        _cache.access(event);
        auto [it, inserted] = _events.emplace(std::make_pair(std::make_pair(event.type, event.timestamp), std::nullopt), std::list<AuditEvent>{});
        if (inserted) {
            it->second.push_back(event);
            prune();
        }
    }

    void search(const EventType& type, const std::chrono::system_clock::time_point& timestamp, int userID) {
        for (auto& [key, events] : _events) {
            if (key.first.first == type && key.first.second >= timestamp && key.second->at(0).userID == userID) {
                std::cout << "Found event: ";
                for (const auto& e : *key.second) {
                    std::cout << e;
                }
                break;
            }
        }
    }

    void deleteEvent(const AuditEvent& event) {
        auto it = _events.find(std::make_pair(std::make_pair(event.type, event.timestamp), std::nullopt));
        if (it != _events.end()) {
            it->second.remove_if([&](const AuditEvent& e) { return e == event; });
            prune();
        }
    }

    void registerObserver(std::function<void(const AuditEvent&)> observer) { _observers.push_back(observer); }

    void notifyObservers(const AuditEvent& event) {
        std::unique_lock<std::mutex> lock(_mutex);
        _cv.notify_all();
        for (auto& observer : _observers) {
            observer(event);
        }
    }

private:
    void prune() {
        for (auto it = _events.begin(); it != _events.end();) {
            if (it->second.size() == 0) {
                it = _events.erase(it);
            } else {
                ++it;
            }
            if (_events.size() > _maxSize) {
                break;
            }
        }
    }

    Events _events;
    LRUCache _cache;
    std::vector<std::function<void(const AuditEvent&)>> _observers;
    mutable std::mutex _mutex;
    std::condition_variable _cv;
    size_t _maxSize;
};
```

