#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long long value;
    size_t size;
    void* data;
} DynamicArray;

typedef struct {
    time_t timestamp;
    const char* message;
    enum { LOW, MEDIUM, HIGH } severity;
} LogEntry;

typedef struct _LogManager {
    DynamicArray ints;
    DynamicArray events;
    DynamicArray logs;
    size_t max_logs;
    pthread_mutex_t mutex;
} LogManager;

DynamicArray DynamicArrayCreate(size_t initial_size) {
    DynamicArray arr = { 0 };
    arr.data = calloc(initial_size, sizeof(void*));
    arr.size = initial_size;
    return arr;
}

LogManager LogManagerCreate(size_t max_logs) {
    LogManager manager = { DynamicArrayCreate(10), DynamicArrayCreate(10), DynamicArrayCreate(max_logs), max_logs, PTHREAD_MUTEX_INITIALIZER };
    return manager;
}

void LogManagerAddInt(LogManager* manager, long long value) {
    pthread_mutex_lock(&manager->mutex);
        if (manager->ints.size == manager->ints.data_size) {
            void** temp = realloc(manager->ints.data, manager->ints.size * 2 * sizeof(void*));
            if (!temp) {
                pthread_mutex_unlock(&manager->mutex);
                return;
            }
            manager->ints.data = temp;
        }
    manager->ints.data[manager->ints.size++] = &value;
    pthread_mutex_unlock(&manager->mutex);
}

void LogManagerAddEvent(LogManager* manager, const char* message, enum { LOW, MEDIUM, HIGH } severity, time_t timestamp) {
    pthread_mutex_lock(&manager->mutex);
        if (manager->events.size == manager->events.data_size) {
            LogEntry** temp = realloc(manager->events.data, manager->events.size * 2 * sizeof(LogEntry*));
            if (!temp) {
                pthread_mutex_unlock(&manager->mutex);
                return;
            }
            manager->events.data = temp;
        }
    manager->events.data[manager->events.size++] = malloc(sizeof(LogEntry));
    LogEntry* event = manager->events.data[manager->events.size - 1];
    event->message = strdup(message);
    event->severity = severity;
    event->timestamp = timestamp;
    pthread_mutex_unlock(&manager->mutex);
}

void LogManagerAddLog(LogManager* manager, const char* message, enum { LOW, MEDIUM, HIGH } severity, time_t timestamp) {
    pthread_mutex_lock(&manager->mutex);
        if (manager->logs.size == manager->logs.data_size && manager->logs.size >= manager->max_logs) {
            LogEntry** temp = realloc(manager->logs.data, manager->logs.size * 2 * sizeof(LogEntry*));
            if (!temp) {
                pthread_mutex_unlock(&manager->mutex);
                return;
            }
            manager->logs.data = temp;
        }
    manager->logs.data[manager->logs.size++] = malloc(sizeof(LogEntry));
    LogEntry* log = manager->logs.data[manager->logs.size - 1];
    log->message = strdup(message);
    log->severity = severity;
    log->timestamp = timestamp;
    pthread_mutex_unlock(&manager->mutex);
}

void LogManagerSortLogsBySeverityAndTimestamp(LogManager* manager) {
    qsort(manager->logs.data, manager->logs.size, sizeof(LogEntry*), (int (*)(const void*, const void*))compare_log_entries);
}

int compare_log_entries(const void* a, const void* b) {
    const LogEntry* logA = a;
    const LogEntry* logB = b;

    if (logA->severity < logB->severity) return -1;
    else if (logA->severity > logB->severity) return 1;

    time_t aTime = logA->timestamp;
    time_t bTime = logB->timestamp;

    if (aTime < bTime) return -1;
    else if (aTime > bTime) return 1;

    return 0;
}
