void init_list() {
    head = malloc(sizeof(list_node));
    if (!head) {
        fprintf(stderr, "Failed to allocate memory for the list.\n");
        exit(EXIT_FAILURE);
    }
    head->next = NULL;
    pthread_mutex_init(&head->mutex, NULL);
}

void destroy_list() {
    list_node* current = head;
    list_node* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&head->mutex);
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    list_node* new_node = malloc(sizeof(list_node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for the new node.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&new_node->mutex, NULL);
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    list_node* current = head;

    if (!current->next) {
        current->next = new_node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

