    pthread_mutex_lock(&list_mutex);
    list_node* current = head->next;
    if (current == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    list_node* temp = current;
    head->next = current->next;
    pthread_mutex_unlock(&list_mutex);

    // Validate the CRC_INDICATION_REL8_TAG here before returning

    return &temp->data;
}

