    for (unsigned i = 0; i < list->max_size; ++i) {
        if (!list->list[i]) continue;
        Node* node = list->list[i];
        do {
            frequency[(node->entry.priority)]++;
            node = node->next;
        } while (node != list->list[i]);
    }

    unsigned new_size = 0;
    for (unsigned i = 0; i < 3; ++i) {
        Node** current = &list->list[new_size];
        Node* node = NULL;
        for (unsigned j = 0; j < list->max_size; ++j) {
            if (!list->list[j]) continue;
            if (frequency[i] == 0) break;
            Node* temp = list->list[j];
            list->list[j] = NULL;
            node = temp;
            *current = node;
            current = &node->next;
        }
        new_size += frequency[i];
        frequency[i] = 0;
    }
    list->max_size = new_size;
}

LogEntry* find_entry(LogList* list, int priority, time_t timestamp) {
    for (unsigned i = 0; i < list->max_size; ++i) {
        if (!list->list[i]) continue;
        Node* node = list->list[i];
        while (node != list->list[i]) {
            if (node->entry.priority == priority && node->entry.timestamp <= timestamp) {
                return &node->entry;
            }
            node = node->next;
        }
    }
    return NULL;
}

void insert_entry(LogList* list, LogEntry entry) {
    int priority_index = (entry.priority >= 3) ? list->max_size : entry.priority;
    if (list->size == list->max_size) {
        compress(list);
    }
    Node** current = &list->list[priority_index];
    Node* new_node = malloc(sizeof(Node));
    new_node->entry = entry;
    new_node->next = *current;
    *current = new_node;
    list->size++;
}

void delete_entry(LogList* list, int priority, time_t timestamp) {
    int priority_index = (priority >= 3) ? list->max_size : priority;
    Node** current = &list->list[priority_index];
    while (*current != NULL && ((*current)->entry.priority != priority || (*current)->entry.timestamp > timestamp)) {
        Node* temp = *current;
        *current = (*current)->next;
        free(temp);
    }
}

LogList* create_log_list(unsigned max_size) {
    LogList* list = malloc(sizeof(LogList));
    list->max_size = max_size;
    list->size = 0;
    list->list = calloc(max_size, sizeof(Node*));
    return list;
}
```

