class LogManager {
private:
    size_t maxSize;
    boost::circular_buffer<LogEntry> buffer; // Cache
    std::map<std::pair<Priority, std::time_t>, boost::lockfree::slist<LogEntry>> list;

public:
    LogManager(size_t maxSize) : maxSize(maxSize) {}

    void insert(const LogEntry& entry) {
        if (list[{entry.priority, entry.timestamp}].length() >= maxSize) {
            auto leastImportant = getLeastImportantLogEntry();
            buffer.push_back(leastImportant); // Cache the least important log entry
            list[{leastImportant.priority, leastImportant.timestamp}].pop_front();
        }
        list[{entry.priority, entry.timestamp}].push_back(entry);
    }

    LogEntry getLogEntry(const std::pair<Priority, std::time_t>& key) {
        auto it = list.find(key);
        if (it != list.end()) {
            auto front = it->second.front();
            if (!buffer.empty() && buffer.front().id == front.id) { // Check if in cache
