    iconv(cd, &const char* const input_values[][2]{{ *str, NULL }}, &size_t *input_lengths, &char* output_buffer, size_t *output_length);

    int state = last_state;
    int *new_states = malloc((*states_count + 1) * sizeof(int));
    if (new_states == NULL) {
        perror("Memory allocation failed");
        free(*result);
        return;
    }
    memcpy(new_states, *states_count ? states : &last_state, *states_count * sizeof(int));
    new_states[*states_count] = state;

    int **transitions_copy = malloc((*states_count + 1) * sizeof(int*));
    if (transitions_copy == NULL) {
        perror("Memory allocation failed");
        free(new_states);
        free(*result);
        return;
    }
    for (int i = 0; i < *states_count; ++i) {
        transitions_copy[i] = fsa->transitions[i];
    }
    transitions_copy[*states_count] = calloc((fsa->states_count), sizeof(int));
    if (transitions_copy[*states_count] == NULL) {
        perror("Memory allocation failed");
        free(new_states);
        free(transitions_copy);
        free(*result);
        return;
    }

    int current_state = state;
    for (const char *c = *str; *c != '\0'; ++c) {
        current_state = transitions_copy[current_state][*c];
        if (current_state < 0 || current_state >= fsa->states_count) {
            break;
        }
    }

    int next_state = -1;
    for (int i = 0; i < fsa->states_count; ++i) {
        if (fsa->accept_states[i] && transitions_copy[current_state][i] == 1) {
            next_state = i;
            break;
        }
    }

    if (next_state != -1) {
        new_states[*states_count + 1] = next_state;
    } else {
        new_states[*states_count + 1] = current_state;
    }

    free(transitions_copy);
    *states_count += 1;
    fsa->transitions = realloc(fsa->transitions, (*states_count) * sizeof(int*));
    if (fsa->transitions == NULL) {
        perror("Memory allocation failed");
        free(new_states);
        free(*result);
        return;
    }
    fsa->states_count = *states_count;
    fsa->transitions[*states_count - 1] = new_states;

    *((int*)((char*)fsa->transitions + sizeof(int*) * last_state)) = new_states;

    free(new_states);
    *result = (char*)fsa->transitions;
}
