}

void parseCSVData(const char* filepath, size_t max_records, void (*buffer)(record_t*), record_t** records, size_t* num_records, const field_t schema[], size_t last_index) {
    // Initialize iconv for handling multibyte characters
    iconv_init(&iconv, "UTF-8", "UTF-8");

    parseCSVDataArgs_t args = { filepath, max_records, buffer, records, num_records, schema, last_index };

    // Create a pool of worker threads to process lines concurrently
    pthread_t workers[MAX_WORKERS];
    FILE* fp = fopen(filepath, "r");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    size_t num_workers = 0;
    char line[4096];
    size_t line_len = 0;
    int c;

    while (num_workers < MAX_WORKERS && fgets(line + line_len, sizeof(line) - line_len, fp)) {
        line_len += strlen(line);
        pthread_create(&workers[num_workers++], NULL, parse_line, &args);
    }

    // Wait for all worker threads to finish processing
    for (size_t i = 0; i < num_workers; ++i) {
        pthread_join(workers[i], NULL);
    }

    fclose(fp);
}
