pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
int num_calls = 0;

void* parseCSVData(const char *file_path, int max_records, Record **buffer, int *num_processed, const FieldSchema *schema, int last_record_index) {
    // Open the CSV file asynchronously and read its contents line by line
    int fd = open(file_path, O_RDONLY);
    if (fd < 0) return NULL;

    char *line = mmap(NULL, 4096, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);

    iconv_t cd = iconv_open("UTF-8", getenv("LC_CTYPE"));
    char *input = line;
    char *output = malloc(4096);
    size_t output_len = 4096;

    int thread_id = pthread_self();

    while (1) {
        ssize_t result = iconv(cd, &input, &input ? &input + strlen(input) : NULL, &output, &output + output_len);
        if (result == (size_t)-1 && errno != E2BIG) break;

        // Parse each line of the CSV file according to the provided schema
        char *token = strtok(output, ",");
        if (!token) break;

        Record record;
        record.schema = schema;
        record.data = malloc(record.schema[0].type_size);

        int i = 0;
        while (token) {
            if (!strchr(field_delimiters, *token)) {
                field_delimiters += strlen(field_delimiters);
                strcat(field_delimiters, token);
            }

            for (int j = 0; schema[i].name && schema[j].name; ++j) {
                if (!strcmp(schema[i].name, token)) {
                    memcpy(record.data, schema[j].type_func(token), schema[j].type_size);
                    break;
                }
            }

            token = strtok(NULL, ",");
            ++i;
        }

        pthread_mutex_lock(&data_mutex);
        if (*num_processed < max_records) {
            Record *new_buffer = realloc(*buffer, sizeof(Record) * (1 + *num_processed));
            if (!new_buffer) {
                pthread_mutex_unlock(&data_mutex);
                break;
            }
            *buffer = new_buffer;
            (*buffer)[*num_processed] = record;
            ++(*num_processed);
        }
        pthread_mutex_unlock(&data_mutex);

        if (*num_processed >= last_record_index) break;

        input += result;
    }

    munmap(line, 4096);
    free(output);
    iconv_close(cd);

    return thread_id;
}

