    int *transitions;
} FSA;

void initFSA(FSA *fsa, int states, int last_state) {
    fsa->states = states;
    fsa->last_state = last_state;
    fsa->transitions = calloc(states * states, sizeof(int));
}

void processFSAStr(char **str, size_t limit, char *buffer, int *states, int num_states, FSA *fsa, int last_state, void (*log)(const char *, ...), int *calls) {
    if (!*str || !fsa || limit < 0 || num_states <= 0 || last_state >= num_states) return log( "Invalid input parameters" );

    iconv_t cd;
    char *new_str = NULL;
    size_t new_len = 0;
    int *new_states = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    if (buffer) {
        if (strlen(*str) + 1 >= limit) {
            log( "String exceeds size limit" );
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        new_len = strlen(*str) + 1 + 20; // reserve space for unique identifier and null terminator
        if (new_len > limit) {
            log( "Buffer is full" );
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        new_str = realloc(buffer, new_len);
        strcpy(new_str + strlen(*str), uuid_unparse(uuid_time())); // or any other unique identifier generation method
    } else {
        new_str = malloc(strlen(*str) + 1 + 20); // same as above but for dynamically allocated strings
        strcpy(new_str, *str);
        strcat(new_str, uuid_unparse(uuid_time()));
    }

    char **new_fsa = calloc(num_states, sizeof(char*));
    if (!new_fsa) {
        log( "Out of memory while creating new state list" );
        pthread_mutex_unlock(&mutex);
        free(new_str); // deallocate dynamically allocated string if failed to create new FSA
        return NULL;
    }

    for (int i = 0; i < num_states; ++i) {
        if (!fsa->transitions[i * last_state + (*str)[i]]) continue;
        int state = fsa->transitions[i * last_state + (*str)[i]];
        new_fsa[i] = malloc(strlen(&new_states[state]) + 1);
        strcpy(new_fsa[i], &new_states[state]);
    }
    new_fsa[num_states - 1] = NULL; // set last state to null

    fsa->transitions = realloc(fsa->transitions, num_states * (last_state + 1) * sizeof(int));
    memcpy(fsa->transitions, new_states, sizeof(int) * num_states);
    free(new_states); // deallocate dynamically allocated state array

    (*str) = new_str;
    (*calls)++;
    pthread_mutex_unlock(&mutex);

    return new_fsa;
}
