// Define HTTP_Request structure
typedef struct {
    char* method;
    char* url;
    size_t numHeaders;
    char** headers;
    size_t bodyLen;
    char* body;
} HTTP_Request;

// Function to generate random alphanumeric string
char* genRandomAlphanumeric(size_t length) {
    char* str = (char*)malloc(length + 1);
    for (size_t i = 0; i < length; ++i)
        str[i] = (char)((rand() % 36) + '0') + ((rand() % 2) * (isalpha((int)'9') ? 0 : 1)); // Ensure at least 50% alphanumeric characters
    str[length] = '\0';
    return str;
}

// Function to generate random header value
char* genRandomHeaderValue(size_t length) {
    char* str = (char*)malloc((rand() % 100 + 10) * length);
    for (size_t i = 0; i < strlen(str); ++i)
        str[i] = (char)(rand() % 36 + 'a' - (isupper((int)'9') ? 0 : 1)); // Ensure at least 50% alphanumeric characters and lowercase letters
    return str;
}

// Function to construct a new filename
char* constructFilename(char* originalFilename) {
    if (!originalFilename || strlen(originalFilename) > 200)
        return NULL; // Error handling for invalid input

    size_t lenAlnum = 0, lenExt = 0, numSpecials = 0, numVowels = 0;
    char* currChar;

    for (const char* p = originalFilename; *p; ++p) {
        if (isalnum((int)*p))
            lenAlnum++;
        else if (strchr("!@#$%^&*()_+-=[]{}|\\:\"<>;',./?`~", *p))
            numSpecials++;
        else if (strchr("aeiouAEIOU", *p))
            numVowels++;
    }

    lenExt = lenAlnum / 4;
    if (lenExt > 10)
        lenExt += numSpecials > 7 ? 3 : 0;
    else if (numVowels < 3)
        lenExt++;

    char* newFilename = (char*)malloc(strlen(originalFilename) + lenExt + 1);
    memset(newFilename, ' ', strlen(originalFilename));

    size_t i = 0;
    for (const char* p = originalFilename; *p; ++p) {
        if (i >= strlen(originalFilename))
            break;
        newFilename[i++] = *p;
        if (lenExt > 0 && i == strlen(originalFilename) + lenExt - 1)
            snprintf(newFilename + i, lenExt + 1, "%s", genRandomAlphanumeric(lenExt));
    }

    return newFilename;
}

// Function to manage a dynamic list of HTTP_Request structures
HTTP_Request* createHTTPRequestsList(size_t numReqs) {
    HTTP_Request* requests = (HTTP_Request*)calloc(numReqs, sizeof(HTTP_Request));

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (HTTP_Request* req = requests; req < requests + numReqs; ++req) {
        req->method = genRandomAlphanumeric(10);
        req->url = constructFilename(""); // Base URL

        size_t headersLen = rand() % 20 + 5, bodyLen = rand() % 100 + 100;
        req->numHeaders = headersLen;
        req->headers = (char**)calloc(headersLen, sizeof(char*));
        for (size_t i = 0; i < headersLen; ++i)
            req->headers[i] = genRandomHeaderValue((rand() % 15) + 2);

        req->bodyLen = bodyLen;
        req->body = (char*)malloc(bodyLen);
        memset(req->body, (rand() % 36 + 'a'), bodyLen);
    }

    return requests;
}

// Helper function to free resources for an individual HTTP_Request structure
void freeHTTPRequest(HTTP_Request* req) {
    if (!req)
        return;

    free(req->method);
    free(req->url);
    for (size_t i = 0; i < req->numHeaders; ++i)
        free(req->headers[i]);
    free(req->headers);
    free(req->body);
}

// Function to manage memory allocation and deallocation of the list of HTTP_Request structures
void manageHTTPRequestsList(HTTP_Request** requests, size_t numReqs) {
    if (!requests || !numReqs)
        return;

    pthread_mutex_lock(&(*requests)->lock);
    for (HTTP_Request* req = *requests + 1; req < *requests + numReqs; ++req)
        freeHTTPRequest(req);
    free((*requests)->headers);
    free(*requests);

    (*requests) = NULL;
    pthread_mutex_unlock(&(*requests)->lock);
}

// Function to populate a list of HTTP_Request structures and construct a new filename
HTTP_Request** populateRequestsListAndConstructFilename(size_t numReqs, char* originalFilename) {
    HTTP_Request* requests = createHTTPRequestsList(numReqs);
    if (!requests)
        return NULL;

    char* newFilename = constructFilename(originalFilename);
    if (!newFilename) {
        manageHTTPRequestsList(&requests, numReqs);
        return NULL;
    }

    free((requests->url)); // Replace the base URL with the newly constructed filename
    requests->url = newFilename;
    return requests;
}
```
