    if (!fb) return NULL;

    fb->data = malloc(sizeof(FrameMetrics) * size);
    if (!fb->data) {
        free(fb);
        return NULL;
    }

    fb->capacity = size;
    fb->size = 0;
    pthread_mutex_init(&fb->mutex, NULL);
    pthread_cond_init(&fb->cond, NULL);
    return fb;
}

void delete_frame_buffer(struct FrameBuffer *fb) {
    free(fb->data);
    free(fb);
}

// Function to find the index of an element with the given timestamp
