    struct collection *coll = malloc(sizeof(struct collection));
    coll->capacity = capacity;
    coll->size = 0;
    coll->users = calloc(capacity, sizeof(struct user*));
    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

void resize_collection(struct collection *coll) {
    if (coll->size >= coll->capacity) {
        size_t new_capacity = coll->capacity * 2;
        struct user **new_users = realloc(coll->users, new_capacity * sizeof(struct user*));
        memmove(new_users, coll->users, coll->size * sizeof(struct user*));
        coll->users = new_users;
        coll->capacity = new_capacity;
    }
