    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> result;
    result.reserve(N); // Reserve memory to reduce reallocations and improve performance

    auto getUEInfo = []() -> RX_UE_INFORMATION_TAG {
        // Implement the logic to fetch UE information tags from an external source
