    };

    auto getRNTI = []() -> RNTI {
        // Implement the logic to fetch RNTIs from an external source
        // ...
        return RNTI{ /* some random values */ };
    };

    std::mt19937 rng(std::chrono::system_clock::now().time_since_epoch().count());

    auto genCRCFLAG = [rng]() -> CRCFLAG {
        CRCFLAG flag;
        flag.crc_indication = static_cast<uint8_t>(rng() % 2); // Generate a random CRC flag
        return flag;
    };

    auto genPDU = [&getUEInfo, &getRNTI, &genCRCFLAG]() -> std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> {
        auto ueInfo = getUEInfo();
        auto rnti = getRNTI();
        auto crcFlag = genCRCFLAG();

        auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        pdu->ueInformationTag = ueInfo;
        pdu->rnti = rnti;
        pdu->crcIndicationRel8Tag.crcFlag = crcFlag;
        return pdu;
    };

    std::future<void> tasks[N]; // Create a future for each task to generate a PDU
    for (unsigned int i = 0; i < N; ++i) {
        tasks[i] = std::async(std::launch::async, genPDU);
    }

    for (auto& task : tasks) {
        task.wait(); // Wait for all tasks to complete
        result.push_back(std::move(task.get()));
    }

    return result;
}
