2. Implement the memory pool functions:

```c
MemoryPool* createMemoryPool(int capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->capacity = capacity > 0 ? capacity : 16;
    pool->data = calloc(capacity, sizeof(void*));
    if (!pool->data) {
        free(pool);
        return NULL;
    }
    pool->next = 0;
    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    if (pool) {
        for (int i = 0; i < pool->capacity; ++i) {
            void* ptr = pool->data[i];
            if (ptr) mempool_free(pool, ptr);
        }
        free(pool->data);
        free(pool);
    }
}

void* mempool_alloc(MemoryPool* pool) {
    int i = pool->next;
    if (i == pool->capacity) i = 0;
    void* ptr = pool->data[i];
    if (!ptr) return NULL;
    pool->data[i] = NULL;
    pool->next = ++i;
    return ptr;
}

void mempool_free(MemoryPool* pool, void* ptr) {
    if (ptr && pool) {
        for (int i = 0; i < pool->capacity; ++i) {
            if (!pool->data[i]) {
                pool->data[i] = ptr;
                break;
            }
        }
    }
}
```

