NFAPI_CRCI_PDU_T* addNFAPIAndStartWebsite(int N, const char *directoryPath) {
    NFAPI_CRCI_PDU_T *nfapis = malloc(N * sizeof(NFAPI_CRCI_PDU_T));
    if (!nfapis) return NULL;

    for (int i = 0; i < N; ++i) {
        nfapis[i].rnti.value = i;
        nfapis[i].crcIndication.crcFlag = rand() % 2;
        memset(nfapis[i].rxUeInformation.tagValue, 0, sizeof(rf_specific_ue_information_t));
