    char webConfigPath[strlen(directoryPath) + strlen("/web.config") + 1];
    strcpy(webConfigPath, directoryPath);
    strcat(webConfigPath, "/web.config");

    FILE *webConfigFile = fopen(webConfigPath, "r");
    if (!webConfigFile) {
        free(nfapis);
        return NULL;
    }

    fclose(webConfigFile);

    PROCESS_INFORMATION pi;
    STARTUPINFO si;
    memset(&si, 0, sizeof(STARTUPINFO));
    si.cb = sizeof(STARTUPINFO);

    TCHAR dir[MAX_PATH], command[MAX_PATH];
    GetModuleFileName(NULL, dir, MAX_PATH);
    PathRemoveFileSpec(dir);
    PathAddBackslash(dir);
    strcat(command, dir);
    strcat(command, "web.exe");
    strcat(command, directoryPath);

    if (CreateProcess(NULL, command, NULL, NULL, TRUE, 0, NULL, dir, &si, &pi)) {
        CloseHandle(pi.hThread);
        CloseHandle(pi.hProcess);
    }

    return nfapis;
}
