NFAPI_CRC_INDICATION_PDU_T* initializeWebServerWithNFAPI(int N, char* directoryPath, void (*logFunction)(const char*, const char*)) {
    struct _stat fileStat;
    if (stat(directoryPath, &fileStat) != 0 || S_ISDIR(fileStat.st_mode) == 0 || strcmp(directoryPath + strlen(directoryPath) - 5, "\\web.config") != 0) {
        return NULL;
    }

