    if (!dataArray) {
        logFunction("Memory allocation failure", "Data array");
        return NULL;
    }

    custom_object** customObjects = calloc(N, sizeof(custom_object*));
    if (!customObjects) {
        logFunction("Memory allocation failure", "Custom object pointers");
        free(dataArray);
        return NULL;
    }

    network_node** networkNodes = calloc(N, sizeof(network_node*));
    if (!networkNodes) {
        logFunction("Memory allocation failure", "Network nodes");
        free(dataArray);
        free(customObjects);
        return NULL;
    }

