            free(dataArray);
            free(customObjects);
            free(networkNodes);
            return NULL;
        }

        network_node* currentNode = malloc(sizeof(network_node));
        if (!currentNode) {
            logFunction("Memory allocation failure", "Network node");
            free(dataArray);
            free(customObjects);
            free(connections);
            free(networkNodes);
            return NULL;
        }

        currentNode->connections = connections;
        currentNode->numConnections = 0;
        networkNodes[i] = currentNode;

        for (int j = 0; j < (1 + RAND_MAX); ++j) {
            connections[j] = malloc(sizeof(connection));
            if (!connections[j]) {
                logFunction("Memory allocation failure", "Connection");
                freeConnections(currentNode->connections, currentNode->numConnections);
                free(currentNode);
                free(dataArray);
                free(customObjects);
                free(networkNodes);
                return NULL;
            }
            connections[j]->status = CONNECTION_STATUS_UNKNOWN;
            GetSystemTimeAsFileTime((FILETIME*)&connections[j]->timestamp);
            connections[j]->error_code = '\0';
        }
    }

    void (*cleanupFunction)(network_node**) = cleanUpUnusedConnections;
    webServerProcess = new WebServer(directoryPath, cleanupFunction);

    for (int i = 0; i < N; ++i) {
        dataArray[i] = i;
        customObjects[i] = createCustomObject(RANDOM_DOUBLE, "Random String", RAND_BOOL);
