            networkNodes[i]->connections[j]->rnti = RAND_INT(N, 0); // Randomize RNTIs for connections other than the first one
        }
    }

    logFunction("Memory allocation completed", "Initialization");
    return calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}
