sem_t data_source_sem;
bool source_available = false;
size_t capacity = 0;
size_t size = 0;

void init(size_t initial_capacity) {
    capacity = initial_capacity;
    head = mmap(NULL, capacity * sizeof(Node), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    size = 0;
}

void cleanup() {
    if (head)
        munmap(head, capacity * sizeof(Node));
}

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_node->data = data;
    new_node->next = head;
    head = new_node;
    size++;
    if (size == capacity) {
        capacity *= 2;
        void* temp_memory = realloc(head, capacity * sizeof(Node));
        if (!temp_memory) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        head = temp_memory;
    }
    pthread_mutex_unlock(&mutex);
