// Function to generate unique IP and port for a given index
void gen_ip_port(int idx, sockaddr_in* addr) {
    addr->sin_family = AF_INET;
    addr->sin_port = htons((uint16_t)(32768 + (idx % 65536))); // Port range: 32768-65535
    inet_pton(AF_INET, "192.168.0.1", &addr->sin_addr);   // Base IP address
}

// Function to initialize and configure a UDP socket
UDP_SOCKET_T* init_udp_socket() {
    UDP_SOCKET_T* sock = (UDP_SOCKET_T*)malloc(sizeof(UDP_SOCKET_T));
    if (!sock) return NULL;

    // Generate unique IP and port
    sock->addr.sin_family = AF_INET;
    gen_ip_port((size_t)(time(NULL) % MAX_SOCKETS), &sock->addr);

    // Initialize socket, address, stats, and mutex
    sock->udpsocket = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sock->udpsocket == -1) {
        free(sock);
        return NULL;
    }

    // Set up address structure for the socket
    if (bind(sock->udpsocket, (struct sockaddr*)&sock->addr, sizeof(sock->addr)) == -1) {
        close(sock->udpsocket);
        free(sock);
        return NULL;
    }

    // Initialize stats with dynamic latency and packet loss calculation
    memset(&sock->stats, 0, sizeof(TCP_STATS_TAG));
    sock->stats.latency = calculate_latency();
    sock->stats.packet_loss = calculate_packet_loss();

    // Initialize mutex for safe access to the socket structure
    pthread_mutex_init(&sock->mutex, NULL);

    return sock;
}

// Function to manage software resource pool and ensure total number of initialized structures does not exceed budget
UDP_SOCKET_T* get_udp_socket() {
    static UDP_SOCKET_T socket_pool[MAX_SOCKETS];
    static int count = 0;

    if (count < MAX_SOCKETS) {
        count++;
        return &socket_pool[count - 1];
    }

    return NULL;
}
