class SensorData {
public:
    explicit SensorData(int id) : sensorID(id), timestamp(std::chrono::steady_clock::now()) {}

    int getSensorID() const { return sensorID; }
    auto getTimestamp() const { return timestamp; }
    double getTemperature() const { return temperature; }
    double getHumidity() const { return humidity; }

