class SensorBuffer {
public:
    explicit SensorBuffer(size_t bufferSize) : bufferSize(bufferSize), pruneInterval(std::chrono::seconds(60)), data(bufferSize) {}

    void addDataPoint(const SensorData& dataPoint) {
        std::unique_lock<std::mutex> lock(mtx);
        data.push_back(dataPoint);
        cv.notify_all();
    }

    SensorData* getDataPointByID(int id) {
        auto it = ids.find(id);
        if (it == ids.end()) return nullptr;
        std::unique_lock<std::mutex> lock(mtx);
        return &data[it->second];
    }

    SensorData* getDataPointByTimestamp(auto timestamp) {
        auto it = timestamps.find(timestamp);
        if (it == timestamps.end()) return nullptr;
        std::unique_lock<std::mutex> lock(mtx);
        return &data[it->second];
    }

    void removeOldData() {
        auto now = std::chrono::steady_clock::now();
        auto it = data.begin();
        while (it != data.end()) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - it->getTimestamp()).count() > pruneInterval) {
                it = data.erase(it);
            } else {
                it++;
            }
        }

        size_t newSize = data.size();
        for (size_t i = ids.size(); i > newSize; --i) {
            ids.erase(data[i].getSensorID());
            timestamps.erase(data[i].getTimestamp());
        }
    }

private:
    size_t bufferSize;
    std::chrono::seconds pruneInterval;
    std::deque<SensorData> data;
    std::unordered_map<int, size_t> ids;
    std::unordered_map<std::chrono::steady_clock::time_point, size_t> timestamps;
    std::mutex mtx;
    std::condition_variable cv;
};
