public class Deserializer {
    private static final String TOKEN_TYPE = "token_type";
    private static final String EXPIRES_IN = "expires_in";

    private static final String LOG_FILE = "deserialization_log.txt";

    public static <T> T deserialize(byte[] encodedData, byte[] key, byte[] iv) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(encodedData)) {
            Base64Decoder decoder = new Base64Decoder();
            byte[] dataBytes = decoder.decodeBuffer(IOUtils.toString(bais, "UTF-8"));

            TripleDESEngine engine = new TripleDESEngine();
            engine.init(true, new ParametersTripleDES(key, iv));
            engine.processBytes(dataBytes, 0, dataBytes.length, dataBytes, 0);

