            String tokenType = (String) tokenData.get(TOKEN_TYPE);
            Long expiresIn = (Long) tokenData.get(EXPIRES_IN);

            if (!"Bearer".equalsIgnoreCase(tokenType) || expiresIn <= 0) {
                logDeserializationError("Invalid token data: " + object, new Date());
                throw new RuntimeException("Invalid token data");
            }

            return object;
        } catch (IOException | ClassNotFoundException | NoSuchAlgorithmException | InvalidKeyException | IllegalArgumentException | IllegalBlockSizeException e) {
            logDeserializationError(e.getMessage(), new Date());
            throw new RuntimeException("Error during deserialization", e);
