    size_t size;
    sem_t lock;
    pthread_mutex_t stats_lock;
};

void init_buffer(struct Buffer* buffer, size_t capacity) {
    buffer->data = mmap(NULL, capacity * sizeof(FrameMetrics), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!buffer->data) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    buffer->capacity = capacity;
    buffer->size = 0;
    sem_init(&buffer->lock, 0, 1);
    pthread_mutex_init(&buffer->stats_lock, NULL);
}

void resize_buffer(struct Buffer* buffer, size_t new_capacity) {
    FrameMetrics* new_data = mmap(NULL, new_capacity * sizeof(FrameMetrics), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!new_data) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    memcpy(new_data, buffer->data, buffer->size * sizeof(FrameMetrics));

    munmap(buffer->data, buffer->capacity * sizeof(FrameMetrics));
    buffer->data = new_data;
    buffer->capacity = new_capacity;
}

void prune_old_entries(struct Buffer* buffer) {
    time_t current_time = time(NULL);
    size_t old_count = 0;

    sem_wait(&buffer->lock);
    for (size_t i = 0; i < buffer->size; ++i) {
        if (current_time - buffer->data[i].timestamp > 60) { // Adjust time in seconds as needed
            memmove(buffer->data + old_count, buffer->data + i, (buffer->size - i - old_count) * sizeof(FrameMetrics));
            ++old_count;
        }
    }
    buffer->size -= old_count;
    sem_post(&buffer->lock);
}

