    SensorBuffer() : pruneTime(std::chrono::steady_clock::now()), running(true) {}

    void runPruneThread() {
        while (running) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait_until(lock, pruneTime + std::chrono::seconds(1),
                [this] { return (std::chrono::steady_clock::now() - pruneTime) > std::chrono::seconds(60); });

            pruneData();
            lock.unlock();
        }
    }

    void addData(int id, double temperature, double humidity, Timestamp timestamp) {
        std::unique_lock<std::mutex> lock(mtx);
        data[id].push_back({id, temperature, humidity, timestamp});
        pruneTime = std::chrono::steady_clock::now();
        cv.notify_one();
    }

