        std::unique_lock<std::mutex> lock(mtx);
        auto it = data.find(id);
        if (it != data.end()) {
            for (const auto& dataPoint : it->second) {
                if (dataPoint.timestamp == timestamp)
                    return &dataPoint;
            }
        }
        return nullptr;
