static mutex bundleCacheMtx;

int loadResourceBundle(const string& path) {
    auto it = bundleCache.find(path);
    if (it != bundleCache.end()) {
        // Return cached resource bundle from cache
        return it->second->numItems;
    }

    system_error err;
    boost::iostreams::mapped_file_source src(path, boost::ios::in | boost::ios::binary, &err);
    if (err) {
        cerr << "Error opening file: " << err.code().message() << endl;
        return -1;
    }

    ResourceBundle bundle;
    boost::archive::text_iarchive ia(src.data(), src.size());
    ia & bundle;

    if (bundle.items.empty()) {
        cerr << "Invalid or empty resource bundle" << endl;
        return -1;
    }

    // Store the loaded resource bundle in the cache and update the number of items
    unique_lock<mutex> lock(bundleCacheMtx);
    bundleCache[path] = new ResourceBundle(bundle);

    return bundle.numItems;
}
