#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <limits.h>
#include <float.h>

typedef struct FrameMetrics {
    time_t timestamp;
    int signal_strength;
    char *rsi;
} FrameMetrics;

typedef struct QueueNode {
    FrameMetrics metric;
    struct QueueNode *next;
} QueueNode;

struct FrameMetricsQueue {
    unsigned int capacity;
    unsigned int size;
    QueueNode **buffer;
    float weighted_average_rsi;
    time_t prune_time;
};

void frameMetrics_init(FrameMetrics *frameMetrics, time_t timestamp, int signal_strength, char *rsi) {
    frameMetrics->timestamp = timestamp;
    frameMetrics->signal_strength = signal_strength;
    frameMetrics->rsi = rsi;
}

FrameMetrics* frameMetrics_new(time_t timestamp, int signal_strength) {
    FrameMetrics *frameMetrics = malloc(sizeof(FrameMetrics));
    frameMetrics_init(frameMetrics, timestamp, signal_strength, NULL);
    return frameMetrics;
}

void frameMetricsQueue_resize(struct FrameMetricsQueue *queue, unsigned int newCapacity) {
    if (newCapacity > queue->capacity) {
        QueueNode **newBuffer = realloc(queue->buffer, newCapacity * sizeof(QueueNode*));
        if (!newBuffer) {
            fprintf(stderr, "Memory allocation failed!\n");
            exit(1);
        }
        queue->buffer = newBuffer;
    }
}

void frameMetricsQueue_init(struct FrameMetricsQueue *queue, unsigned int initialCapacity, time_t prune_time) {
    queue->capacity = initialCapacity;
    queue->size = 0;
    queue->prune_time = prune_time;
    queue->buffer = malloc(initialCapacity * sizeof(QueueNode*));
}

struct FrameMetricsQueue* frameMetricsQueue_new(unsigned int initialCapacity, time_t prune_time) {
    struct FrameMetricsQueue *queue = malloc(sizeof(struct FrameMetricsQueue));
    frameMetricsQueue_init(queue, initialCapacity, prune_time);
    return queue;
}

void frameMetricsQueue_push(struct FrameMetricsQueue *queue, FrameMetrics *frameMetrics) {
    if (queue->size == queue->capacity) {
        frameMetricsQueue_resize(queue, queue->capacity * 2);
    }
    QueueNode **slot = &queue->buffer[queue->size % queue->capacity];
    QueueNode *newNode = malloc(sizeof(QueueNode));
    newNode->metric = *frameMetrics;
    newNode->next = NULL;
    *slot = newNode;
    queue->size++;
}

FrameMetrics* frameMetricsQueue_pop(struct FrameMetricsQueue *queue) {
    if (queue->size == 0) return NULL;

    QueueNode *first = queue->buffer[0];
    if (--queue->size == 0) {
        free(queue->buffer);
        queue->buffer = NULL;
    } else {
        queue->buffer[0] = first->next;
    }

    FrameMetrics* frameMetrics = &first->metric;
    free(first);
    return frameMetrics;
}

FrameMetrics* frameMetricsQueue_findByTimestamp(struct FrameMetricsQueue *queue, time_t timestamp) {
    for (unsigned int i = 0; i < queue->size; ++i) {
        QueueNode *node = queue->buffer[i];
        if (node->metric.timestamp == timestamp) return &node->metric;
    }
    return NULL;
}

void frameMetricsQueue_prune(struct FrameMetricsQueue *queue) {
    time_t now = time(NULL);
    if (now < queue->prune_time) return;

    QueueNode **slot = &queue->buffer[0];
    while (*slot != NULL) {
        QueueNode *oldest = *slot;
        if (oldest->metric.timestamp + queue->capacity <= now) {
            *slot = oldest->next;
            free(oldest);
        } else break;
        slot = &((*slot)->next);
    }
}

void frameMetricsQueue_updateSignalStrengthAndRSI(struct FrameMetricsQueue *queue, FrameMetrics *frameMetrics) {
    if (queue->size == 0) return;

    float weightedSumRSI = 0.0f;
    unsigned int count = 0;
    FrameMetrics *current = frameMetricsQueue_findByTimestamp(queue, frameMetrics->timestamp);

    for (unsigned int i = 0; i < queue->size; ++i) {
        if (!current || current->timestamp > frameMetrics->timestamp) {
            break;
        }

        weightedSumRSI += current->rsi[0] * expf(-(current->timestamp - frameMetrics->timestamp) / (FLT_MAX - 1));
        count++;
        current = frameMetricsQueue_findByTimestamp(queue, current->timestamp - 1);
    }

    if (count == 0) return;

    float weightedAverageRSI = weightedSumRSI / count;
    frameMetrics->signal_strength = rand() % INT_MAX + 1; // Update the signal strength with a random number within range.
    int rsiLength = strlen(frameMetrics->rsi);
    if (rsiLength > 0) {
        float sum = 0.0f;
        for (int i = 0; i < rsiLength; ++i) {
            sum += frameMetrics->rsi[i] * expf(-(frameMetrics->timestamp - queue->buffer[(queue->size - 1)->timestamp] ->metric.timestamp) / (FLT_MAX - 1));
        }
        frameMetrics->rsi[0] = weightedAverageRSI + sum / rsiLength;
    } else {
        frameMetrics->rsi[0] = weightedAverageRSI;
    }

    queue->weighted_average_rsi = weightedAverageRSI;
}

void frameMetricsQueue_serialize(struct FrameMetricsQueue *queue, FILE *file) {
    fwrite(&queue->capacity, sizeof(unsigned int), 1, file);
    fwrite(&queue->size, sizeof(unsigned int), 1, file);
    for (unsigned int i = 0; i < queue->size; ++i) {
        FrameMetrics *frameMetrics = &queue->buffer[i]->metric;
        fwrite(&frameMetrics->timestamp, sizeof(time_t), 1, file);
        fwrite(&frameMetrics->signal_strength, sizeof(int), 1, file);
        fwrite(frameMetrics->rsi, strlen(frameMetrics->rsi) + 1, 1, file);
    }
}

void frameMetricsQueue_deserialize(struct FrameMetricsQueue *queue, FILE *file) {
    free(queue->buffer);
    queue->capacity = 0;
    queue->size = 0;

    unsigned int capacity, size;
    fread(&capacity, sizeof(unsigned int), 1, file);
    fread(&size, sizeof(unsigned int), 1, file);
    frameMetricsQueue_init(queue, capacity, queue->prune_time);

    for (unsigned int i = 0; i < size; ++i) {
        FrameMetrics *frameMetrics = frameMetrics_new(0, 0);
        fread(&frameMetrics->timestamp, sizeof(time_t), 1, file);
        fread(&frameMetrics->signal_strength, sizeof(int), 1, file);
        fread(frameMetrics->rsi, sizeof(char), strlen(fgets(frameMetrics->rsi, INT_MAX - 1, file)) + 1, file);
        frameMetricsQueue_push(queue, frameMetrics);
    }
}
