    for (int i = 0; i < initial_size; ++i) {
        ArrayListNode* node = malloc(sizeof(ArrayListNode));
        FrameMetrics frame_metrics = va_arg(args, FrameMetrics);
        node->frame_metrics = frame_metrics;
        node->next = array_list->head;
        array_list->head = node;
        ++array_list->size;
    }

    va_end(args);

    return array_list;
}

ArrayListNode* search_node(ArrayList* array_list, time_t timestamp) {
    ArrayListNode *current = array_list->head;

    while (current != NULL) {
        if (current->frame_metrics.timestamp == timestamp)
            return current;
        current = current->next;
    }

    return NULL;
}

void insert(ArrayList* array_list, FrameMetrics frame_metrics) {
    int signal_strength_range = 100;
    frame_metrics.signal_strength = rand() % signal_strength_range + 1;

    double rsi_weight = 0.85; // Weight for the new RSI calculation
    ArrayListNode *current = array_list->head;
    double total_rsi = 0;
    int count = 0;

    while (current != NULL) {
        if (current->frame_metrics.timestamp > frame_metrics.timestamp)
            break;

        total_rsi += current->frame_metrics.rsi[0] * rsi_weight;
        rsi_weight *= 0.15;
        ++count;

        current = current->next;
    }

    frame_metrics.rsi = malloc(sizeof(char) * (count + 2));
    strcpy(frame_metrics.rsi, "");

    current = array_list->head;

    while (current != NULL) {
        if (current->frame_metrics.timestamp > frame_metrics.timestamp)
            break;

        total_rsi += current->frame_metrics.rsi[0] * rsi_weight;
        sprintf(frame_metrics.rsi, "%s%c", frame_metrics.rsi, current->frame_metrics.rsi[0]);
        rsi_weight *= 0.15;
        ++count;

        current = current->next;
    }

    frame_metrics.rsi[count] = '\0';
    frame_metrics.rsi[(count+1)/2] = (total_rsi + 1) / (count + 1);

    ArrayListNode *new_node = malloc(sizeof(ArrayListNode));
    new_node->frame_metrics = frame_metrics;
    new_node->next = array_list->head;
    array_list->head = new_node;
    ++array_list->size;
}

void remove(ArrayList* array_list, time_t timestamp) {
    ArrayListNode *current = array_list->head;
    ArrayListNode *prev = NULL;

    while (current != NULL) {
        if (current->frame_metrics.timestamp == timestamp) {
            if (prev == NULL)
                array_list->head = current->next;
            else
                prev->next = current->next;

            free(current);
            --array_list->size;
            return;
        }
        prev = current;
        current = current->next;
    }
}

void serialize(ArrayList* array_list, const char* filename) {
    FILE *file = fopen(filename, "wb");

    if (file == NULL) {
        perror("Error opening file for serialization.");
        return;
    }

    fwrite(&array_list->size, sizeof(int), 1, file);

    ArrayListNode *current = array_list->head;

    while (current != NULL) {
        fwrite(&current->frame_metrics.timestamp, sizeof(time_t), 1, file);
        fwrite(&current->frame_metrics.signal_strength, sizeof(int), 1, file);
        fwrite(current->frame_metrics.rsi, sizeof(char), strlen(current->frame_metrics.rsi)+1, file);

        current = current->next;
    }

    fclose(file);
}

void deserialize(ArrayList* array_list, const char* filename) {
    FILE *file = fopen(filename, "rb");

    if (file == NULL) {
        perror("Error opening file for deserialization.");
        return;
    }

    FrameMetrics frame_metrics;
    fread(&array_list->size, sizeof(int), 1, file);

    while (array_list->size > 0) {
        fread(&frame_metrics.timestamp, sizeof(time_t), 1, file);
        fread(&frame_metrics.signal_strength, sizeof(int), 1, file);
        size_t length = strlen(frame_metrics.rsi = malloc(sizeof(char) * (length + 1)));
        fread(frame_metrics.rsi, sizeof(char), length, file);

        // Adjust the pointer to account for the null-terminator read by fread
        frame_metrics.rsi[length] = '\0';

        ArrayListNode* new_node = malloc(sizeof(ArrayListNode));
        new_node->frame_metrics = frame_metrics;
        new_node->next = array_list->head;
        array_list->head = new_node;
        ++array_list->size;
    }

    fclose(file);
}
