    void addSensorData(std::uint32_t id, const std::tm& timestamp) {
        auto it = data_.emplace(keys_[id], SensorData{id}).first;
        if (it != data_.end()) {
            it->second.timestamp = timestamp;
        }
    }

    void removeOldData() {
        std::deque<std::uint32_t> toRemove;
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        for (auto& entry : data_) {
            if (entry.second.timestamp + FIXED_BUFFER_SIZE < now) {
                toRemove.push_back(entry.first);
            }
        }
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto id : toRemove) {
            data_.erase(id);
        }
    }

    SensorData* getSensorDataByIdAndTimestamp(std::uint32_t id, const std::tm& timestamp) {
        auto it = data_.find(keys_[id]);
        if (it != data_.end() && it->second.timestamp == timestamp) {
            return &it->second;
        }
        return nullptr;
    }

    const std::string appendSlashIfNeeded(const std::string& input) {
        if (input.length() <= SIZE_LIMIT) {
            return input + "/";
        }
        return nullptr;
    }

private:
