class DynamicArray {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    std::mutex mtx;
    size_t size = 0;
    const static size_t maxSize = 10000;

public:
    DynamicArray() {
        data.resize(maxSize);
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> newPdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(pdu);
        std::unique_lock<std::mutex> lock(mtx);
        if (size == maxSize) {
            throw std::runtime_error("DynamicArray is full.");
        }
        data[size++] = std::move(newPdu);
    }

    NFAPI_CRC_INDICATION_PDU_T& get(size_t index) {
        std::unique_lock<std::mutex> lock(mtx);
        if (index >= size) {
            throw std::out_of_range("Index out of range.");
        }
        return *data[index];
    }

    ~DynamicArray() {
