#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static Node *head = NULL, *tail = NULL;
static size_t size = 0;

void add_element(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Out of memory\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (size == 0) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    size++;
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(size_t index) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    if (current == NULL) {
        printf("Error: Index out of range\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    pthread_mutex_unlock(&mutex);

    return &current->data;
}
```

