class SensorDataManager {
private:
    const size_t buffer_size = 100000; // Adjust as per requirement
    std::vector<SensorData> data_buffer;
    std::unordered_map<int, size_t> sensor_ids;
    std::unordered_map<std::tm, size_t> timestamps;
    std::deque<size_t> remove_queue;
    mutex mtx;
    default_random_engine generator; // External data source for seed generation

public:
    SensorDataManager() : generator(rand()) {}

    void addDataPoint(int sensor_id, const Record& data, const std::tm& timestamp) {
        unique_lock<mutex> lock(mtx);

        auto it = sensor_ids.find(sensor_id);
        if (it == sensor_ids.end()) { // New sensor ID
            sensor_ids[sensor_id] = data_buffer.size();
            timestamps[timestamp] = data_buffer.size();
            data_buffer.push_back({sensor_id, data, timestamp});
        } else {
            size_t index = it->second;
            data_buffer[index].data = data;
            data_buffer[index].timestamp = timestamp;
        }

        pruneOldData();
    }

    SensorData getDataPoint(int sensor_id, const std::tm& timestamp) {
        unique_lock<mutex> lock(mtx);

        auto it_sensor = sensor_ids.find(sensor_id);
        if (it_sensor == sensor_ids.end())
            throw std::invalid_argument("Invalid sensor ID");

        auto it_timestamp = timestamps.find(timestamp);
        if (it_timestamp == timestamps.end())
            throw std::invalid_argument("Timestamp not found in the buffer");

        size_t index = it_sensor->second;
        if (index != it_timestamp->second)
            throw std::runtime_error("Sensor data out of order");

        return data_buffer[index];
    }

    // Implement other methods such as removeDataPoint, clear, etc.

    void pruneOldData() {
        unique_lock<mutex> lock(mtx);

        while (!remove_queue.empty() && remove_queue.front() + buffer_size < std::chrono::duration_cast<std::chrono::seconds>(clock_cast<system_clock>::now().time_since_epoch()).count()) {
            size_t index = data_buffer[remove_queue.front()].timestamp;
            size_t id = sensor_ids[data_buffer[index].sensor_id];

            if (id == remove_queue.front()) {
                sensor_ids.erase(data_buffer[index].sensor_id);
                timestamps.erase(index);
                data_buffer.erase(data_buffer.begin() + remove_queue.front());
            }

            remove_queue.pop_front();
        }
    }

    // Implement the method to process a given string and size limit
};
