    size_t input_len = strlen(input);
    if (input_len > size_limit - 1) return NULL; // Adjust this condition according to the unique identifier size

    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input, input_len);
    char hash[MD5_DIGEST_LENGTH];
