    char *inbuf = malloc(inbuf_size), *outbuf = malloc(outbuf_size);
    if (!inbuf || !outbuf) {
        free(inbuf);
        free(outbuf);
        return NULL;
    }

    size_t inlen, outlen;
    iconv_open("UTF-8", "UTF-8", &cd);
    iconv(cd, &const char *const *(&input), &size_t const *(&input_len), &outbuf, &outlen); // Convert input to UTF-8

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        free(inbuf);
        free(outbuf);
        return NULL;
    }

    for (size_t i = 0; i < num_structures; ++i) {
        strncpy(pdu[i].hash, hash, MD5_DIGEST_LENGTH);
        strncat(pdu[i].data, input, input_len);
        strncat(pdu[i].data, &timestamp, sizeof(timestamp)); // Replace this with the unique identifier generation code
        pdu[i].tag = RX_UE_INFORMATION_TAG__eNB_ID;
        pdu[i].rnti = i + 1;
        pdu[i].crc_indication.crci = i % 8;
        pdu[i].crc_indication.crcflag = rand() % 2;
    }

    if (buffer) {
        size_t total_size = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T) + remaining * num_structures;
        char *pdu_buf = malloc(total_size);
        if (!pdu_buf) {
            free(inbuf);
            free(outbuf);
            free(pdu);
            return NULL;
        }

        size_t pdu_offset = 0;
        for (size_t i = 0; i < num_structures; ++i) {
            strncpy(pdu_buf + pdu_offset, pdu[i].data, strlen(pdu[i].data) + 1);
            pdu_offset += strlen(pdu[i].data) + 1;
        }
        free(inbuf);
        free(outbuf);
        free(pdu);
        return pdu_buf;
    } else {
        free(inbuf);
        free(outbuf);
        free(pdu);
        log_function_call();
        return malloc(remaining * num_structures);
    }
}
