    private static final ScheduledExecutorService progressUpdater = Executors.newScheduledThreadPool(1);

    public static int processFileWithMetadata(String filePath, Metadata metadata, CallbackHandler callback) {
        if (metadata == null || callback == null) return ERROR_INVALID_INPUT;
        if (!isValidFileType(metadata)) return ERROR_UNSUPPORTED_FILE_TYPE;
        if (!isCreationDateValid(metadata)) return ERROR_CREATION_DATE_OUT_OF_RANGE;

        File file = new File(filePath);
        try (BufferedReader reader = Files.newBufferedReader(file.toPath())) {
            long totalBytes = file.length();
            long processedBytes = 0;
            int progressInterval = (int) Math.ceil((double) totalBytes / PROGRESS_INTERVAL);

            progressUpdater.scheduleWithFixedDelay(() -> {
                double progress = (double) processedBytes / totalBytes;
                callback.onProgress(progress);
            }, 0, PROGRESS_UPDATE_DELAY, TimeUnit.MILLISECONDS);

            String line;
            while ((line = reader.readLine()) != null) {
                processedBytes += line.getBytes().length;

                if (processedBytes % progressInterval == 0) {
                    double progress = (double) processedBytes / totalBytes;
                    callback.onProgress(progress);
                }
            }

            List<String> tags = fetchTags(metadata);
            if (tagsValidationFailed(tags, metadata)) return ERROR_INVALID_TAGS;

