typedef struct {
    char *name;
    int value;
} item;

typedef struct collection_s {
    char *name;
    size_t max_items;
    size_t capacity;
    size_t length;
    item **data;
    pthread_mutex_t mutex;
    int random_value_range;
    unsigned int concurrency_limit;
} collection;

collection *init_collection(char *config_path) {
    json_object *root = json_tokener_parse_ex(open_and_read(config_path), JSON_PARSE_RELATIVE_JSON_KEY);
    if (!json_object_get_string(root, "collection_name") || !json_object_get_integer(root, "max_items") || !json_object_get_integer(root, "initial_capacity")) {
        fprintf(stderr, "Invalid configuration: collection_name, max_items, and initial_capacity are required fields\n");
        json_object_put(root);
        return NULL;
    }
    size_t max_items = json_object_get_integer(root, "max_items");
    size_t initial_capacity = json_object_get_integer(root, "initial_capacity");
    if (max_items <= 0 || initial_capacity > max_items) {
        fprintf(stderr, "Invalid configuration: max_items must be a positive integer and initial_capacity cannot exceed max_items\n");
        json_object_put(root);
        return NULL;
    }

    collection *coll = malloc(sizeof(collection));
    coll->name = strdup(json_object_get_string(root, "collection_name"));
    coll->max_items = max_items;
    coll->capacity = initial_capacity;
    coll->length = 0;
    coll->data = calloc(initial_capacity, sizeof(item *));
    coll->random_value_range = json_object_get_integer_ex(root, "random_value_range", 100);
    coll->concurrency_limit = json_object_get_integer_ex(root, "concurrency_limit", 8);
    pthread_mutex_init(&coll->mutex, NULL);

    json_object_put(root);
    return coll;
}

item *new_item() {
    item *item = malloc(sizeof(item));
    item->name = "";
    item->value = 0;
    return item;
}

void grow(collection *coll) {
    if (coll->length >= coll->max_items || coll->capacity == 0) {
        size_t new_capacity = coll->capacity == 0 ? 4 : coll->capacity * 2;
        item **new_data = realloc(coll->data, new_capacity * sizeof(item *));
        if (new_data != NULL) {
            coll->data = new_data;
            coll->capacity = new_capacity;
        } else {
            fprintf(stderr, "Error: failed to allocate memory for collection growth\n");
        }
    }
}

void push_back(collection *coll, item *item) {
    pthread_mutex_lock(&coll->mutex);
    grow(coll);
    coll->data[coll->length++] = item;
    pthread_mutex_unlock(&coll->mutex);
}

int get_random_number(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void update_item(collection *coll, size_t i) {
    pthread_mutex_lock(&coll->mutex);
    coll->data[i]->value = get_random_number(0, coll->random_value_range);
    pthread_mutex_unlock(&coll->mutex);
}

size_t perform_operation(collection *coll, enum operation op, size_t index) {
    switch (op) {
        case INSERT:
            push_back(coll, new_item());
            update_item(coll, coll->length - 1);
            break;
        case UPDATE:
            if (index >= coll->length) {
                fprintf(stderr, "Invalid index for update operation\n");
                return -1;
            }
            pthread_mutex_lock(&coll->mutex);
            update_item(coll, index);
            pthread_mutex_unlock(&coll->mutex);
            break;
        case DELETE:
            if (index >= coll->length) {
                fprintf(stderr, "Invalid index for delete operation\n");
                return -1;
            }
            pthread_mutex_lock(&coll->mutex);
            memmove(coll->data + index, coll->data + index + 1, --coll->length - index);
            free(coll->data[coll->length]);
            pthread_mutex_unlock(&coll->mutex);
            break;
    }
    return coll->length;
}

size_t get_collection_state(collection *coll) {
    size_t sum = 0;
    for (size_t i = 0; i < coll->length; ++i) {
        sum += coll->data[i]->value;
    }
    return coll->length + sum;
}
```

