#define PRODUCT_INITIAL_SIZE 10
#define PRICE_RANGE {0, 100} // Minimum and maximum price range for randomization

typedef struct Product {
    char name[50];
    int quantity;
    double price;
} Product;

void resizeProductArray(Product **products, size_t *size, size_t newSize) {
    if (newSize > *size && *size != 0) {
        Product *tmp = realloc(*products, newSize * sizeof(Product));
        if (!tmp) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        *products = tmp;
    } else if (*size > newSize) {
        *products = realloc(*products, newSize * sizeof(Product));
    }
    *size = newSize;
}

void updatePriceRandomly(double *price, double min, double max) {
    *price = (rand() / (RAND_MAX + 1.0)) * (max - min) + min;
}

Product* createProduct(const char *name, int quantity) {
    Product *product = malloc(sizeof(Product));
    if (!product) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    strcpy(product->name, name);
    product->quantity = quantity;
    updatePriceRandomly(&product->price, PRICE_RANGE[0], PRICE_RANGE[1]);

    return product;
}

void manageProducts(size_t initialSize, size_t *numProducts) {
    Product *products = malloc(initialSize * sizeof(Product));
    if (!products) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t size = initialSize;
    *numProducts = 0;

    resizeProductArray(&products, &size, initialSize);

    for (int i = 0; i < size && *numProducts < 10000; ++i) { // Maximum number of products
        if (*numProducts == size) {
            resizeProductArray(&products, &size, size * 2);
        }

        Product *product = createProduct("product_name", 1);
        products[*numProducts] = *product;
        ++(*numProducts);
    }
}
