// Function to initialize a Bloom Filter
void bloom_init(bloom_filter* bf, size_t n) {
    // Initialize parameters
    bf->m = 1 + (n * 8ULL) / 5;
    bf->k = ceil(log2((double)(bf->m - 1)));
    bf->bits = calloc(bf->m, sizeof(unsigned long long));
}

// Function to add an element to the Bloom Filter
void bloom_add(bloom_filter* bf, size_t key) {
    // Bitwise operations to mark the bits corresponding to the key
    for (size_t i = key & ((1ULL << bf->k) - 1); i < bf->m; i += 1 << bf->k)
        bf->bits[i] |= 1ULL << (key % bf->m);
}

// Function to check if an element is in the Bloom Filter
bool bloom_test(bloom_filter* bf, size_t key) {
    for (size_t i = key & ((1ULL << bf->k) - 1); i < bf->m; i += 1 << bf->k) {
        if (!(bf->bits[i] & (1ULL << (key % bf->m))) )
            return false;
    }
    return true;
}

// Function to manage memory allocation, initialization, and integration of a dynamic dataset of records
void manage_dataset(size_t offset_len, size_t key_len, size_t record_count) {
    // Allocate memory for offset values
    long* offsets = mmap(NULL, offset_len * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

