    // Check if memory allocation succeeded
    if (!records) {
        free(keys);
        munmap(offsets, offset_len * sizeof(long));
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize bloom filter for collision resolution
    bloom_filter bf;
    bloom_init(&bf, record_count);

    // Set each record's int field to a random value within a specified range
    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = i;
        records[i].value = rand() % 100000; // Specify your desired range here

        // Mark the key in the bloom filter to resolve collisions
        bloom_add(&bf, records[i].key);
    }

    // Integrate records into an external data processing system asynchronously using threads
    pthread_t threads[record_count];

    for (size_t i = 0; i < record_count; ++i) {
        int rc = pthread_create(&threads[i], NULL, integrate_record, &records[i]);
        if (rc) {
