void init_memory(size_t length, Record** records) {
    *records = malloc(length * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = calloc(length, sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        free(*records);
        exit(EXIT_FAILURE);
    }

    int* keys = malloc(length * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        free(offsets);
        free(*records);
        exit(EXIT_FAILURE);
    }

    // Initialize each record with the corresponding index value and a reference count of 1
    for (size_t i = 0; i < length; ++i) {
        (*records)[i].offset = i;
        (*keys)[i] = i;
        (*records + i)->refCount = 1;
        (*records + i)->key = (*keys + i);
    }

    // Fill the records array with random values within specified ranges
    srand(time(NULL));
    for (size_t i = length; i--;) {
        long minOffset = 0, maxOffset = length - 1;
        int minKey = 0, maxKey = INT_MAX;

        // Set random values within specified ranges for offset and key fields
        (*records)[i].offset = (long)(rand() * (maxOffset - minOffset + 1) + minOffset);
        (*records)[i].key = (int)(rand() * (maxKey - minKey + 1) + minKey);
    }
}

void incRefCount(Record* record) {
    ++record->refCount;
}

void decRefCount(Record* record) {
    if (--record->refCount == 0) {
        // Free memory when reference count reaches zero
        free(record);
    }
}

// Clean up allocated memory at the end of function execution
void cleanup() {
    for (size_t i = 0; i < length; ++i)
        decRefCount(*(records + i));

    free(keys);
    free(offsets);
    free(records);
}
