```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    int ref_count;
    pthread_mutex_t mutex;
} Record;

void init_data_structures(long size, Record** records) {
    *records = malloc(size * sizeof(Record));
    if (!*records) {
        perror("Failed to allocate memory for records");
        return;
    }

    for (long i = 0; i < size; ++i) {
        (*records)[i].offset = i;
        (*records)[i].key = i;
        (*records)[i].ref_count = 1;
        pthread_mutex_init(&(*records)[i].mutex, NULL);
    }
}

void inc_ref_count(Record* record) {
    pthread_mutex_lock(&record->mutex);
    ++record->ref_count;
    pthread_mutex_unlock(&record->mutex);
}

void dec_ref_count(Record* record) {
    pthread_mutex_lock(&record->mutex);
    if (--record->ref_count == 0) {
        // Free the record when its reference count reaches zero.
        free(record);
    }
    pthread_mutex_unlock(&record->mutex);
}

// Function to fill the records array with random values within specified ranges.
void fill_records(Record* records, long size) {
    srand(time(NULL)); // Seed random number generator.
    for (long i = 0; i < size; ++i) {
        records[i].offset = (long)(rand() % MAX_OFFSET);
        records[i].key = (int)(rand() % MAX_KEY);
    }
}
