[' Here is a simple C implementation using linked list and manual memory allocation/deallocation. I've used a struct Task to represent each task, and struct Node to represent each node in the linked list.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    int priority;
    char status; // 'A' for active, 'I' for inactive
} Task;

typedef struct Node {
    Task task;
    struct Node *next;
} Node;

Node* create_task(int id, int priority, char status) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->task.id = id;
    new_node->task.priority = priority;
    new_node->task.status = status;
    new_node->next = NULL;
    return new_node;
}

void add_task(Node** head, Node* new_task) {
    if (*head == NULL) {
        *head = new_task;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_task;
    }
}

Node* find_task(Node* head, int id) {
    Node* current = head;
    while (current != NULL) {
        if (current->task.id == id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void update_task(Node** head, int id, int priority, char status) {
    Node* task_to_update = find_task(*head, id);
    if (task_to_update != NULL) {
        task_to_update->task.priority = priority;
        task_to_update->task.status = status;
    } else {
        printf("Task not found.\n");
    }
}

void mark_active(Node** head, int id) {
    Node* task_to_mark = find_task(*head, id);
    if (task_to_mark != NULL) {
        task_to_mark->task.status = 'A';
    } else {
        printf("Task not found.\n");
    }
}

void mark_inactive(Node** head, int id) {
    Node* task_to_mark = find_task(*head, id);
    if (task_to_mark != NULL) {
        task_to_mark->task.status = 'I';
    } else {
        printf("Task not found.\n");
    }
}

Node* filter(Node* head, int priority, char status) {
    Node* current = head;
    Node* filtered_list = NULL;
    while (current != NULL) {
        if (current->task.priority == priority && current->task.status == status) {
            add_task(&filtered_list, current);
        }
        current = current->next;
    }
    return filtered_list;
}

void free_tasks(Node** head) {
    Node* current = *head;
    Node* temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
```

