[" ```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Task {
    int id;
    int priority;
    char status; // 'A' for active, 'I' for inactive
    struct Task *next;
} Task;

Task* head = NULL;

void add_task(int id, int priority, char status) {
    Task *new_task = (Task *)malloc(sizeof(Task));
    new_task->id = id;
    new_task->priority = priority;
    new_task->status = status;
    new_task->next = head;
    head = new_task;
}

void update_task(int id, int priority, char status) {
    Task *current = head;
    Task *previous = NULL;

    while (current != NULL) {
        if (current->id == id) {
            if (current == head) {
                head = current->next;
            } else {
                previous->next = current->next;
            }

            current->id = id;
            current->priority = priority;
            current->status = status;
            return;
        }
        previous = current;
        current = current->next;
    }
}

void mark_active(int id) {
    Task *current = head;

    while (current != NULL) {
        if (current->id == id && current->status == 'I') {
            current->status = 'A';
            return;
        }
        current = current->next;
    }
}

void mark_inactive(int id) {
    Task *current = head;

    while (current != NULL) {
        if (current->id == id && current->status == 'A') {
            current->status = 'I';
            return;
        }
        current = current->next;
    }
}

Task* filter_tasks(int priority, char status) {
    Task *current = head;
    Task *result = NULL;
    Task *prev_result = NULL;

    while (current != NULL) {
        if (current->priority == priority && current->status == status) {
            if (result == NULL) {
                result = current;
                prev_result = NULL;
            } else {
                prev_result->next = current;
                prev_result = current;
            }
        }
        current = current->next;
    }

    return result;
}

void free_list() {
    Task *current = head;
    Task *next_task;

    while (current != NULL) {
        next_task = current->next;
        free(current);
        current = next_task;
    }

    head = NULL;
}
