#include <time.h>
#include <string.h>

typedef struct {
    int user_id;
    time_t start_time;
    char *ip_address;
    char *data;
} LogEntry;

struct log_manager {
    size_t capacity;
    size_t count;
    LogEntry **entries;
};

void grow(struct log_manager *lm) {
    lm->capacity *= 2;
    lm->entries = realloc(lm->entries, sizeof(LogEntry*) * lm->capacity);
}

void insert(struct log_manager *lm, const LogEntry *entry) {
    if (lm->count >= lm->capacity) grow(lm);
    lm->entries[lm->count] = malloc(sizeof(LogEntry));
    memcpy(lm->entries[lm->count], entry, sizeof(LogEntry));
    ++lm->count;
}

LogEntry *find_by_id(struct log_manager *lm, int user_id) {
    for (size_t i = 0; i < lm->count; ++i) {
        if (lm->entries[i]->user_id == user_id) return lm->entries[i];
    }
    return NULL;
}

LogEntry *find_by_time(struct log_manager *lm, const time_t time) {
    for (size_t i = 0; i < lm->count; ++i) {
        if (lm->entries[i]->start_time == time) return lm->entries[i];
    }
    return NULL;
}

void compress(struct log_manager *lm, const time_t threshold) {
    size_t new_capacity = 0;
    for (size_t i = 0; i < lm->count; ++i) {
        if (lm->entries[i]->start_time > threshold) {
            ++new_capacity;
        } else {
            free(lm->entries[i]->ip_address);
            free(lm->entries[i]->data);
            free(lm->entries[i]);
        }
    }

    if (new_capacity != 0) {
        lm->capacity = new_capacity;
        grow(lm);
    }
}

void log_manager_init(struct log_manager *lm, size_t initial_size) {
    lm->capacity = initial_size;
    lm->count = 0;
    lm->entries = malloc(sizeof(LogEntry*) * lm->capacity);
}
