typedef struct BufferManager {
    size_t capacity;
    size_t size;
    FrameMetrics** data;
} BufferManager;

int init_buffer(BufferManager* buffer, size_t initial_size) {
    buffer->capacity = initial_size;
    buffer->size = 0;
    buffer->data = calloc(initial_size, sizeof(FrameMetrics*));
    if (!buffer->data) return -1;
    return 0;
}

void resize_buffer(BufferManager* buffer, size_t new_capacity) {
    FrameMetrics** temp = realloc(buffer->data, new_capacity * sizeof(FrameMetrics*));
    if (!temp) return;
    buffer->data = temp;
    buffer->capacity = new_capacity;
}

void push_metric(BufferManager* buffer, const json_t* metric_json) {
    if (json_is_object(metric_json)) {
        json_t *timestamp_val, *signal_strength_val, *rsi_data_val;
        int timestamp, signal_strength;
        size_t rsi_data_len;
        const char* rsi_data;
        if (!json_unpack(metric_json, "{ssisiab}", &timestamp_key, &timestamp_val, &signal_strength_key, &signal_strength_val, &rsi_data_key, &rsi_data_val, &rsi_data)) {
            fprintf(stderr, "Invalid FrameMetrics JSON format\n");
            return;
        }
        if (!json_is_integer(timestamp_val) || json_integer_value(timestamp_val) < 0) {
            fprintf(stderr, "Invalid timestamp value in FrameMetrics JSON\n");
            return;
        }
        timestamp = json_integer_value(timestamp_val);
        if (!json_is_integer(signal_strength_val) || json_integer_value(signal_strength_val) < 0) {
            fprintf(stderr, "Invalid signal strength value in FrameMetrics JSON\n");
            return;
        }
        signal_strength = json_integer_value(signal_strength_val);
        if (rsi_data_val->type != JSON_STRING) {
            fprintf(stderr, "Invalid RSI data format in FrameMetrics JSON\n");
            return;
        }
        rsi_data = json_string_value(rsi_data_val);
        rsi_data_len = strlen(rsi_data);
        if (buffer->size == buffer->capacity) {
            resize_buffer(buffer, buffer->capacity * 2);
        }
        FrameMetrics* metric = &buffer->data[buffer->size];
        metric->timestamp = timestamp;
        metric->signal_strength = rand() % (GNUTLS_RSA_SIZE + 1) + 1; // Update with a random signal strength value within the specified range
        metric->rsi_data = malloc(rsi_data_len + 1);
        strcpy(metric->rsi_data, rsi_data);
        buffer->size++;
    } else {
        fprintf(stderr, "Invalid FrameMetrics JSON format\n");
    }
}

void prune_old_metrics(BufferManager* buffer) {
    time_t now = time(NULL);
    for (size_t i = 0; i < buffer->size; ) {
        if (buffer->data[i]->timestamp + PRUNE_INTERVAL < now) {
            free(buffer->data[i]->rsi_data);
            memmove(&buffer->data[i], &buffer->data[i+1], (buffer->size-i-1)*sizeof(FrameMetrics*));
            buffer->size--;
        } else {
            i++;
        }
    }
}

