    struct listNode *next;
    time_t timestamp;
    bool error;
    pthread_mutex_t lock;
} ListNode;

ListNode* newNode(NFAPI_L1_FCI_T data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    node->timestamp = time(NULL);
    node->error = false;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

ListNode* listHead = NULL;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

void addToList(NFAPI_L1_FCI_T data) {
    ListNode* newNode = newNode(data);
    if (!newNode) return;
    pthread_mutex_lock(&listLock);
    newNode->next = listHead;
    listHead = newNode;
    pthread_mutex_unlock(&listLock);
}

void removeFromList(ListNode* node) {
    if (!node || !listHead) return;
    pthread_mutex_lock(&listLock);
    if (listHead == node) listHead = node->next;
    ListNode *current = listHead;
    while (current->next && current->next != node) {
        current = current->next;
    }
    if (current->next) current->next = node->next;
    pthread_mutex_unlock(&listLock);
    free(node);
}

void listIterate() {
    ListNode *current = listHead;
    while (current) {
        ListNode* temp = current;
        current = current->next;
        printf("FCI: TPC=%d, RLC_STATUS=%d, PREAMBLE_TYPE=%d\n",
               temp->data.TPC, temp->data.RLC_STATUS, temp->data.PREAMBLE_TYPE);
        printf("Metadata: timestamp=%ld, error=%s\n", temp->timestamp, temp->error ? "true" : "false");
        removeFromList(temp);
    }
}
