    node_t* tail;
    size_t size;
    pthread_mutex_t list_mutex;
};

fci_list_t* fci_list_create() {
    fci_list_t *list = malloc(sizeof(fci_list_t));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->list_mutex, NULL);
    return list;
}

void fci_list_destroy(fci_list_t* list) {
    node_t *current, *next;
    pthread_mutex_lock(&list->list_mutex);
    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->list_mutex);
}

node_t* fci_list_alloc() {
    node_t *node = malloc(sizeof(node_t));
    if (!node) return NULL;
    node->data.timestamp = 0;
    node->next = NULL;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

