    node_t *new_node = fci_list_alloc();
    if (!new_node) return;
    new_node->data = data;
    pthread_mutex_lock(&list->list_mutex);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    ++list->size;
    pthread_mutex_unlock(&list->list_mutex);
}

void fci_list_update(fci_list_t* list, size_t index, NFAPI_L1_FCI_T data) {
    node_t *current;
    pthread_mutex_lock(&list->list_mutex);
    if (index >= list->size) {
        printf("Index out of range\n");
        pthread_mutex_unlock(&list->list_mutex);
        return;
    }
    current = list->head;
    for (size_t i = 0; i < index; ++i) {
        if (!current) {
            printf("Index out of range\n");
            pthread_mutex_unlock(&list->list_mutex);
            return;
        }
        current = current->next;
    }
    pthread_mutex_lock(&current->mutex);
    current->data = data;
    pthread_mutex_unlock(&current->mutex);
    pthread_mutex_unlock(&list->list_mutex);
}

void fci_list_batch_update(fci_list_t* list, size_t start_index, size_t num_items, NFAPI_L1_FCI_T* data) {
    node_t *current;
    pthread_mutex_lock(&list->list_mutex);
    if (start_index + num_items > list->size) {
        printf("Batch update out of range\n");
        pthread_mutex_unlock(&list->list_mutex);
        return;
    }
    current = list->head;
    for (size_t i = 0; i < start_index; ++i) {
        if (!current) {
            printf("Batch update out of range\n");
            pthread_mutex_unlock(&list->list_mutex);
            return;
        }
        current = current->next;
    }
    for (size_t i = 0; i < num_items; ++i) {
        if (!current) break;
        if (!data[i].error_flag) {
            pthread_mutex_lock(&current->mutex);
            current->data = data[i];
            pthread_mutex_unlock(&current->mutex);
        } else {
            printf("Invalid FCI data\n");
        }
        if (current->next == NULL) break;
        current = current->next;
    }
    pthread_mutex_unlock(&list->list_mutex);
}

void fci_list_log(const char* operation, size_t num_fcis, size_t time_taken) {
    printf("%s: Processed %zu FCIs in %.3fs\n", operation, num_fcis, (float)time_taken / CLOCKS_PER_SEC);
}
