#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_ACCESS 10

typedef struct {
    char id[32];
    char interface[64];
    time_t timestamp;
    int status; // connection status flag (e.g., 1 for connected, 0 for disconnected)
    double latency;
    double throughput;
    double packet_loss_rate;
    double jitter;
} NetworkMetrics;

typedef struct MetricsListNode {
    NetworkMetrics data;
    struct MetricsListNode* next;
    pthread_mutex_t mutex;
} MetricsListNode;

struct MetricsList {
    MetricsListNode* head;
    MetricsListNode* tail;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
};

MetricsList* createMetricsList() {
    MetricsList *list = malloc(sizeof(MetricsList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_empty, NULL);
    return list;
}

void addToMetricsList(MetricsList* list, NetworkMetrics metrics) {
    MetricsListNode *node = malloc(sizeof(MetricsListNode));
    if (!node) return;
    node->data = metrics;
    node->next = NULL;
    pthread_mutex_init(&node->mutex, NULL);

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void removeFromMetricsList(MetricsList* list, NetworkMetrics metrics) {
    MetricsListNode *current = list->head;
    MetricsListNode *prev = NULL;

    while (current != NULL) {
        if (compareNetworkMetrics(&current->data, &metrics)) {
            pthread_mutex_lock(&current->mutex);
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&current->mutex);
            return;
        }
        prev = current;
        current = current->next;
    }
