import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed

def md5(file):
    block_size = 65536
    hasher = hashlib.md5()
    with open(file, "rb") as f:
        while True:
            buf = f.read(block_size)
            if not buf:
                break
            hasher.update(buf)
    return hasher.hexdigest()

def process_files(files, chunk_size=16):
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(md5, file) for file in files]
        results = list(as_completed(futures))
        return [res.result() for res in results]
```

