        std::cerr << "Missing required fields: amount, currency, transaction_id or status." << std::endl;
        return -1;
    }

    if (obj["currency"] != CurrencyToString((Currency)obj["currency"].get<int>()) ||
        obj["amount"].get<double>() <= 0.0 ||
        obj["transaction_id"].size() > 256 || // Adjust this value based on your requirements
        (obj["status"] != "success" && obj["status"] != "failure" && obj["status"] != "pending")) {
        std::cerr << "Invalid transaction data." << std::endl;
        return -1;
    }

    Transaction newTransaction;
    newTransaction.amount = static_cast<double>(rand()) / RAND_MAX * 100; // Set a random number within a specified range
    newTransaction.timestamp = time(nullptr);
    newTransaction.id = obj["transaction_id"].get<std::string>();
    newTransaction.status = StatusFromString(obj["status"].get<std::string>());

    if (transactions.size() == capacity) { // Resize the collection when necessary
        capacity *= 2;
        std::vector<Transaction> newTransactions(capacity);
        std::copy(transactions.begin(), transactions.end(), newTransactions.begin());
        transactions = newTransactions;
    }

    transactions.push_back(newTransaction);
    return 0;
}

