#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <dirent.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <semaphore.h>

typedef struct {
    int id;
    enum EventType { FILE, DIRECTORY } type;
    const char *path;
    void (*callback)(struct FileEvent*, const char* metadata);
    char *metadata; // Optional metadata from external API
} FileEvent;

typedef struct WorkerPool {
    sem_t queue_not_empty;
    sem_t worker_not_busy;
    pthread_mutex_t task_queue;
    int capacity;
    int count;
    FileEvent **tasks;
} WorkerPool;

void *worker(void *arg) {
    WorkerPool *pool = arg;
    while (1) {
        sem_wait(&pool->worker_not_busy);
        sem_wait(&pool->queue_not_empty);
        pthread_mutex_lock(&pool->task_queue);

        int index = pool->count++;
        FileEvent *task = pool->tasks[index];
        pthread_mutex_unlock(&pool->task_queue);

        task->callback(task, task->metadata); // Process the event with provided callback function

        sem_post(&pool->worker_not_busy);
    }
}

void processFileEvents(const char *dir, size_t limit, char *buffer, int *states, int num_states, const FiniteStateAutomaton fsa, int last_state) {
    // Initialize worker pool
    WorkerPool pool = { .capacity = 16 };

    // Process directory recursively
    DIR *d;
    struct dirent *entry;
    d = opendir(dir);
    if (!d) return NULL;

    sem_init(&pool.queue_not_empty, 0, 0);
    sem_init(&pool.worker_not_busy, 0, pool.capacity);
    pthread_mutex_init(&pool.task_queue, NULL);

    for (;;) {
        entry = readdir(d);
        if (!entry) break;

        // Skip '.' and '..' entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        struct stat st;
        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", dir, entry->d_name);
        if (lstat(path, &st) != 0) continue;

        if (S_ISDIR(st.st_mode)) {
            // Recursively process directories
            if (st.st_size <= limit) {
                char newPath[sizeof(path) + 256];
                snprintf(newPath, sizeof(newPath), "%s/%s", path, buffer ? (buffer < st.st_size ? buffer : strdup("")) : "(new)");
                if (rename(path, newPath)) continue;
                processFileEvents(newPath, limit, buffer, states, num_states, fsa, last_state);
            } else {
                continue; // Skip directories exceeding the size limit
            }
        } else {
            // Process files within the size limit
            if (st.st_size <= limit) {
                char newPath[sizeof(path) + 256];
                snprintf(newPath, sizeof(newPath), "%s/%s", path, buffer ? (buffer < st.st_size ? buffer : strdup("")) : "(new)");
                FileEvent *event = malloc(sizeof(FileEvent));
                event->id = time(NULL);
                event->type = FILE;
                event->path = newPath;
                event->callback = some_metadata_processing_function; // External API callback implementation

                // Enqueue the event in the worker pool, handling full queue cases gracefully
                pthread_mutex_lock(&pool.task_queue);
                if (pool.count >= pool.capacity) {
                    pthread_mutex_unlock(&pool.task_queue);
                    sem_post(&pool.queue_not_empty);
                    sem_wait(&pool.worker_not_busy);
                }
                pool.tasks[pool.count++] = event;
                pthread_mutex_unlock(&pool.task_queue);
            } else {
                continue; // Skip files exceeding the size limit
            }
        }
    }

    closedir(d);

    // Launch worker threads and process events concurrently
    for (int i = 0; i < pool.capacity; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, worker, &pool);
    }

    // Wait for all tasks to be processed
    sem_wait(&pool.worker_not_busy);
    sem_destroy(&pool.queue_not_empty);
    sem_destroy(&pool.worker_not_busy);
    pthread_mutex_destroy(&pool.task_queue);

    // Parse JSON configuration and process events based on the defined event queue
    json_object *root = some_json_parsing_function(...); // Implement your JSON parsing function here
    // ...
}
```

