#include <openssl/aes.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <assert.h>
#include <sys/mman.h>

#define M 1024
#define N 64
#define IV_LEN 12

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} CRCI_STRUCTURE_T;

typedef struct {
    pthread_mutex_t mutex;
    CRCI_STRUCTURE_T *pool;
    size_t active_count;
    size_t pool_size;
} CRCI_POOL_T;

CRCI_POOL_T crc_pool;
AES_KEY aes_key;

void derive_key(const unsigned char *password, AES_KEY *key) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen((char*)password));
    SHA256_Final(key->encrypt, &sha256);
}

CRCI_STRUCTURE_T *crc_pool_acquire() {
    pthread_mutex_lock(&crc_pool.mutex);
    while (crc_pool.active_count + 1 > crc_pool.pool_size) {
        // Wait for a structure to be freed if the pool is full
        pthread_cond_wait(&crc_pool.mutex, &crc_pool.mutex);
    }
    CRCI_STRUCTURE_T *structure = &(crc_pool.pool[crc_pool.active_count]);
    structure->crc_ind.CRCFLAG = (uint8_t)(rand() % 2); // Set CRCFLAG to either 0 or 1 randomly
    crc_pool.active_count++;
    pthread_mutex_unlock(&crc_pool.mutex);
    return structure;
}

void cipher_context_cleanup(AES_KEY *key) {
    AES_set_encrypt_key((const unsigned char *)key->encrypt, 256, &key->decrypt);
    AES_free_key(key);
}

CRCI_STRUCTURE_T *crc_pool_get() {
    CRCI_STRUCTURE_T *structure = crc_pool_acquire();
    assert(structure != NULL);
    return structure;
}

void crc_pool_put(CRCI_STRUCTURE_T *structure) {
    pthread_mutex_lock(&crc_pool.mutex);
    structure->crc_ind.CRCFLAG = -1; // Mark the structure as available for reuse
    crc_pool.active_count--;
    pthread_mutex_unlock(&crc_pool.mutex);
}

void log_info(const char *message) {
    printf("%s\n", message);
}

CRCI_POOL_T *initialize_crc_pool() {
    CRCI_POOL_T *pool = mmap(NULL, sizeof(CRCI_STRUCTURE_T)*M*N, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;
    pool->pool = pool;
    pool->active_count = 0;
    pool->pool_size = M*N;
    return pool;
}

void cleanup_crc_pool(CRCI_POOL_T *pool) {
    CRCI_STRUCTURE_T *structure;
    pthread_mutex_lock(&pool->mutex);
    while (pool->active_count > 0) {
        structure = &(pool->pool[0]);
        pool->pool++;
        crc_pool_put(structure);
    }
    munmap((void*)pool, sizeof(CRCI_STRUCTURE_T)*M*N);
    pthread_mutex_destroy(&pool->mutex);
}

void initialize_aes256_cbc(const unsigned char *password) {
    unsigned char iv[IV_LEN];
    randombytes_buf(iv, IV_LEN); // Initialize IV with random values
    AES_KEY key;
    derive_key(password, &key);
    AES_set_encrypt_key((const unsigned char *)key.encrypt, 256, &key.decrypt);
    AES_cbc_encrypt((const unsigned char*)iv, iv, IV_LEN, &key, NULL, AES_ENCRYPT);
    memcpy(aes_key.encrypt, iv, IV_LEN);
}
```

