    unsigned char key[32], iv[16];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, password, strlen(password));
    SHA256_Final(key, &ctx);

    AES_set_encrypt_key(key, 256, &aes_ctx);
    AES_cbc_encrypt((const unsigned char*)iv, iv, 16, &aes_ctx, (unsigned char*)iv, AES_ENCRYPT);
    return &aes_ctx;
}

