    pthread_mutex_lock(&pool_mutex);
    if (!pool || active_count >= pool_size) {
        if (pool_size == 0) {
            pool = calloc(1, sizeof(*pool) * M);
            if (!pool) goto error;
            pool_size *= NFAPI_CRC_INDICATION_PDU_T_MAX;
        } else {
            pool = realloc(pool, sizeof(*pool) * (2 * pool_size));
            if (!pool) goto error;
            pool_size *= 2;
        }
    }

    size_t index = active_count++;
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool[index];

error:
    pthread_mutex_unlock(&pool_mutex);
    return pdu;
}

