import re
from typing import Iterable

def sort_lines_and_extract_seqnum(filepath: str) -> Iterable[str]:
    with open(filepath, 'r') as f:
        lines = sorted(f.readlines())

    last_line = lines[-1]
    seqnum_pattern = r'(\d+)$'
    match = re.search(seqnum_pattern, last_line)

    if not match:
        raise ValueError(f"Sequence number not found in last line of '{filepath}'.")

    seqnum = int(match.group(1))
    for line in lines:
        yield line.strip()
    yield str(seqnum)
