    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & timestamp & logLevel & message;
    }
};

struct LogCollection {
    std::mutex mtx;
    std::vector<LogEntry> logs;
    std::unordered_map<int, std::vector<LogEntry>> levelMap;
    int maxEntries = 1000000;
    int currentSize = 0;
    std::chrono::steady_clock::time_point lastPruneTime;
    std::string dataFilePath;

    LogCollection(const std::string& dataFilePath) : dataFilePath(dataFilePath) {}

    void insert(const LogEntry& log) {
        std::lock_guard<std::mutex> lock(mtx);

        logs.push_back(log);
        levelMap[log.logLevel].push_back(log);
        currentSize++;

        if (currentSize > maxEntries && std::chrono::steady_clock::now() - lastPruneTime > std::chrono::minutes(1)) {
            prune();
        }
    }

    LogEntry find(int logLevel, const std::string& timestamp) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = levelMap.find(logLevel);
        if (it == levelMap.end()) return LogEntry(); // Not found

        for (const auto& log : it->second) {
            if (log.timestamp == timestamp) return log;
        }
        return LogEntry(); // Not found
    }

    void remove(int logLevel, const std::string& timestamp) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = levelMap.find(logLevel);
        if (it == levelMap.end()) return; // Not found

        auto newEnd = std::remove_if(it->second.begin(), it->second.end(),
            [&](const LogEntry& log) { return log.timestamp == timestamp; });

        it->second.erase(newEnd, it->second.end());
        currentSize--;
    }

    void serializeToDisk() {
        // ... Implement serialization to disk using Boost libraries
    }

    void deserializeFromDisk() {
        // ... Implement deserialization from disk using Boost libraries
    }

    void prune() {
        std::lock_guard<std::mutex> lock(mtx);

        auto now = std::chrono::steady_clock::now();
        auto it = logs.begin();
        auto end = logs.end();

        for (; it != end && currentSize > maxEntries; ++it) {
            auto duration = now - std::chrono::string_to_time_t(it->timestamp);
            if (duration >= 60 * 24 * 7) // Keep logs older than a week
                it = logs.erase(it);
        }

        lastPruneTime = now;
    }
};
