    if (temperatures > 0) memset(temperature_arr, 32767, temperatures * sizeof(float)); // Using a large number to fill with a value that can be easily differentiated from valid temperature readings.

    // Update the callback function periodically as needed.
    if (update_cb && measurements > 0) {
        size_t update_interval = 1000; // Milliseconds between updates.
        clock_t last_update = clock();

        while(1) {
            clock_t current = clock();
            if ((current - last_update) >= (clock_t)(update_interval * CLOCKS_PER_SEC)) {
                last_update = current;
                for (size_t i = 0; i < measurements; ++i) {
                    update_cb(&measurements_arr[i]);
                }
            }
        }
    }
