        validateOptionalField("transaction_details", transaction, result);
        validateOptionalField("shipping_address", transaction, result);
        validateOptionalField("customer_notes", transaction, result);

        // Validate and process payment methods
        Map<String, Object> validPaymentMethods = validatePaymentMethods(transaction.getJSONArray("payment_method"));

        // Log transaction events
        logger.log("[PaymentProcessor] Processing transaction started: " + startTime);
        if (!processTransaction(result)) {
            String errorMessage = "[PaymentProcessor] Transaction processing failed";
            logger.logError(errorMessage, new Exception());
            return result;
        }
        Instant endTime = Instant.now();
        logger.log("[PaymentProcessor] Processing transaction completed: " + endTime);

        // Return the valid payment methods and any additional transaction data
        return validPaymentMethods.isEmpty() ? result : Map.of("payment_methods", validPaymentMethods);
    }

    private static void validateAndExtractField(String fieldName, JSONObject transaction) {
        if (!transaction.has(fieldName)) {
            throw new IllegalArgumentException("[PaymentProcessor] Missing required field: " + fieldName);
        }
        Object value = transaction.get(fieldName);
        if (value instanceof String) {
            switch (fieldName) {
                case "transaction_id":
                    if (!TRANSACTION_ID_PATTERN.matcher(value.toString()).matches()) {
                        throw new IllegalArgumentException("[PaymentProcessor] Invalid transaction ID: " + value);
                    }
                    break;
                case "customer_id":
                    if (!UUID_PATTERN.matcher(value.toString()).matches()) {
                        throw new IllegalArgumentException("[PaymentProcessor] Invalid customer ID: " + value);
                    }
                    break;
            }
        } else {
            throw new IllegalArgumentException("[PaymentProcessor] Expected string for field: " + fieldName);
        }
        transaction.remove(fieldName); // Remove the field from the transaction data to avoid recursive validation
    }

    private static void validateCurrencyCode(JSONObject transaction) {
        String currencyCode = transaction.getString("currency_code");
        if (!ISO4217.isValidCurrencyCode(currencyCode)) {
            throw new IllegalArgumentException("[PaymentProcessor] Invalid currency code: " + currencyCode);
        }
    }

    private static void validateOptionalField(String fieldName, JSONObject transaction, Map<String, Object> result) {
        if (transaction.has(fieldName)) {
            Object value = transaction.get(fieldName);
            switch (fieldName) {
                case "transaction_details":
                    if (!isValidJson(value.toString())) {
                        throw new IllegalArgumentException("[PaymentProcessor] Invalid JSON string for transaction details");
                    }
                    result.put(fieldName, value);
                    break;
                case "shipping_address":
                    if (value instanceof JSONObject) {
                        // Implement shipping address validation here
                    } else {
                        throw new IllegalArgumentException("[PaymentProcessor] Expected JSON object for shipping address");
                    }
                    result.put(fieldName, value);
                    break;
                case "customer_notes":
                    if (value instanceof String && value.toString().length() > 500) {
                        throw new IllegalArgumentException("[PaymentProcessor] Customer notes exceed maximum length");
                    }
                    result.put(fieldName, value);
            }
        }
    }

    private static Map<String, Object> validatePaymentMethods(JSONArray paymentMethods) {
        Map<String, Object> validPaymentMethods = new HashMap<>();
        for (int i = 0; i < paymentMethods.length(); i++) {
            String paymentMethod = paymentMethods.getString(i);
            if (!SUPPORTED_PAYMENT_METHODS.contains(paymentMethod)) {
                logger.log("[PaymentProcessor] Unsupported or invalid payment method: " + paymentMethod);
            } else {
                validPaymentMethods.put(paymentMethod, new JSONObject());
            }
        }
        return validPaymentMethods;
    }

    private static boolean processTransaction(Map<String, Object> transactionData) {
        // Implement the e-commerce platform's business logic to process transactions here
        return true; // Assuming the transaction is processed successfully in this example
    }

    private static boolean isValidJson(String json) {
        try {
            new JSONObject(json);
            return true;
        } catch (JSONException e) {
            return false;
        }
    }
}
