bool validate_access_token(const char *json_string) {
    json_t *root;
    json_error_t error;
    root = json_loads(json_string, 0, &error);
    if (!root) {
        fprintf(stderr, "Error on parsing JSON: %s\n", error.text);
        return false;
    }

    if (!json_object_get_field(root, "access_token") ||
        !json_object_get_field(root, "expires_in") ||
        !json_object_get_field(root, "token_type")) {
        json_decref(root);
        return false;
    }

    if (!json_is_string(json_object_get(root, "access_token")) ||
        !json_is_integer(json_object_get(root, "expires_in")) ||
        !json_is_string(json_object_get(root, "token_type")) ||
        json_string_value(json_object_get(root, "expires_in")) <= 0) {
        json_decref(root);
        return false;
    }

    if (strcmp(json_string_value(json_object_get(root, "token_type")), "Bearer") != 0) {
        json_decref(root);
        return false;
    }

    const char *access_token = json_string_value(json_object_get(root, "access_token"));
    if (!isBase64EncodedStringValid(access_token)) {
        json_decref(root);
        return false;
    }

    bool has_refresh_token = json_object_has_field(root, "refresh_token");
    if (has_refresh_token) {
        const char *refresh_token = json_string_value(json_object_get(root, "refresh_token"));
        if (!isValidUuidString(refresh_token)) {
            json_decref(root);
            return false;
        }
    }

    json_decref(root);
    return true;
}

