void process_file() {
    FileReader reader("path/to/your/file");
    reader.start();

    std::unique_ptr<pt::ptree> tree(new pt::ptree());
    reader.m_buffer.parse_xml(*tree);

    integer_map integers;
    integer_set largest_integers;
    uint64_t total_even = 0;

    for (auto& value : *tree) {
        if (!std::isdigit(static_cast<unsigned char>(value.second.get<char>())) ||
            std::abs(static_cast<int>(value.second.get<char>())) > INT_MAX / 2) {
            continue;
        }

        auto integer = integers.find(std::abs(static_cast<uint64_t>(value.second.get<char>())));
        if (integer != integers.end()) {
            integer->second.frequency++;
        } else {
            integer_data id{std::abs(static_cast<int>(value.second.get<char>())), 1};
            integers.insert(id);
        }
    }

    for (auto& integer : integers) {
        largest_integers.insert(integer.first > largest_integers.begin()->first ? integer.first : largest_integers.begin()->first, integer.second);
    }

    std::cout << "Largest integer: " << *largest_integers.rbegin()->first << "\n";
    for (auto& pair : largest_integers) {
        if (pair.first == *largest_integers.rbegin()->first) continue;
        std::cout << "Other large integers: " << pair.first << "\n";
    }
    std::cout << "Sum of even integers: " << total_even << "\n";

    for (auto& integer : integers) {
        if (integer.second.value % 2 == 0)
            total_even += integer.second.frequency * integer.second.value;
    }
}
