UserManager::UserManager(int initialSize) {
    users.resize(initialSize);
    for (auto& user : users) user = nullptr;
    pthread_mutex_init(&mutex, NULL);
}

void UserManager::addUser(const std::string& key, double value) {
    pthread_mutex_lock(&mutex);
    auto it = users.begin();
    for (; it != users.end() && it->key.compare(key) < 0; ++it) {}
    User* newUser = new User();
    newUser->key = key;
    newUser->value = rand() % 100 + 50.0 / 100; // Generate random floating-point number within range [50, 100]
    newUser->next = it != users.end() ? *it : nullptr;
    if (it != users.begin()) {
        *(it - 1) = newUser;
    } else {
        users.insert(it, newUser);
    }
    pthread_mutex_unlock(&mutex);
}

User* UserManager::findUser(const std::string& key) {
    User* result = nullptr;
    pthread_mutex_lock(&mutex);
    auto it = users.begin();
    for (; it != users.end() && it->key.compare(key) < 0; ++it) {}
    if (it != users.end() && it->key.compare(key) == 0) {
        result = it;
    }
    pthread_mutex_unlock(&mutex);
    return result;
}
