void InventorySystem::insert(const InventoryItem& item) {
    inventory[item.category].push_back(item);
}

InventoryItem* InventorySystem::find(const std::string& productID) const {
    auto it = std::find_if(begin(inventory["All Categories"].begin()), end(inventory["All Categories"]),
                           [&](const InventoryItem& i) { return i.productID == productID; });

    if (it != inventory["All Categories"].end()) {
        return &*it;
    }

    for (const auto& categoryItems : inventory) {
        it = std::find_if(categoryItems.second.begin(), categoryItems.second.end(),
                          [&](const InventoryItem& i) { return i.productID == productID; });

        if (it != categoryItems.second.end()) {
            return &*it;
        }
    }

    return nullptr;
}

InventoryItem* InventorySystem::findByCategoryAndExpiration(const std::string& category, const std::tm& expirationDate) const {
    auto it = std::find_if(begin(inventory[category].begin()), end(inventory[category]),
                           [&](const InventoryItem& i) { return std::tm(*std::localtime(&i.expirationDate)) == expirationDate; });

    if (it != inventory[category].end()) {
        return &*it;
    }

    return nullptr;
}

void InventorySystem::deleteById(const std::string& productID) {
    for (auto& categoryItems : inventory) {
        auto it = std::find_if(categoryItems.second.begin(), categoryItems.second.end(),
                               [&](const InventoryItem& i) { return i.productID == productID; });

        if (it != categoryItems.second.end()) {
            categoryItems.second.erase(it);
            break;
        }
    }
}

void InventorySystem::revaluatePrices() {
    for (auto& categoryItems : inventory) {
        for (auto& item : categoryItems.second) {
            item.price = adjustPrice(item.price, std::time(0));
        }
    }
}

