import java.util.*;
import java.time.*;
import java.util.concurrent.*;
import java.nio.file.*;
import java.io.*;

public class LogAggregator {
    private final L Ruqeue<LogEntry> logBuffer = new LinkedBlockingQueue<>(1000); // Fixed-size buffer for log entries
    private final SortedMap<Long, LogEntry> logIdMap = new TreeMap<>(); // Map for efficient lookup by log ID
    private final SortedMap<Instant, LogEntry> timestampMap = new TreeMap<>(Comparator.comparing(entry -> entry.getTimestamp())); // Map for efficient lookup by timestamp
    private final ExecutorService executor = Executors.newFixedThreadPool(5); // Thread pool for log processing tasks
    private final AtomicInteger concurrentTasks = new AtomicInteger(0); // Counter for tracking the number of concurrent tasks

    // Class for a single log entry
    public static class LogEntry {
        private final long id;
        private final Instant timestamp;
        private final String sourceIP;
        private final String messageContent;

        public LogEntry(long id, Instant timestamp, String sourceIP, String messageContent) {
            this.id = id;
            this.timestamp = timestamp;
            this.sourceIP = sourceIP;
            this.messageContent = messageContent;
        }

        // Getters and setters for log entry attributes
    }

    public void addLogEntry(LogEntry entry) {
        logBuffer.add(entry);
        logIdMap.put(entry.getId(), entry);
        timestampMap.put(entry.getTimestamp(), entry);
    }

    public void removeOldLogEntries() {
        Instant currentTime = Instant.now();
        for (Map.Entry<Instant, LogEntry> entry : timestampMap.tailMap(currentTime.minusSeconds(300))) { // Remove entries older than 5 minutes
            logBuffer.remove(entry.getValue());
            logIdMap.remove(entry.getValue().getId());
            timestampMap.remove(entry.getKey());
        }
    }

    public void processLogs(List<LogEntry> logs, int maxBufferSize) {
        Runnable logProcessingTask = () -> {
            Map<String, List<LogEntry>> groupedLogs = new HashMap<>();
            for (LogEntry log : logs) {
