typedef struct {
    int id;
    enum { ACTIVE, INACTIVE } status;
    enum { LOW, MEDIUM, HIGH } priority;
} Task;

typedef struct Node {
    Task task;
    struct Node *next;
} Node;

Node* create_node(Task task) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->task = task;
    node->next = NULL;
    return node;
}

void add_task(Node** head, Task task) {
    Node* new_node = create_node(task);
    if (!new_node) return;

    // Implement logic for efficient insertion into the list based on priority and status

    new_node->next = *head;
    *head = new_node;
}

void update_task(Node** head, int id, enum { ACTIVE, INACTIVE } status) {
    Node* current = *head;
    while (current != NULL) {
        if (current->task.id == id) {
            current->task.status = status;
            return;
        }
        current = current->next;
    }
}

void filter_tasks(Node* head, enum { LOW, MEDIUM, HIGH } priority, enum { ACTIVE, INACTIVE }) {
    // Implement logic for efficient filtering based on priority and status
}

Task get_task_by_id(Node* head, int id) {
    Node* current = head;
    while (current != NULL) {
        if (current->task.id == id) return current->task;
        current = current->next;
    }
    return (Task){0}; // Return a dummy task for non-existent IDs
}

void free_list(Node** head) {
    Node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

