using namespace std;

struct LineStat {
    size_t line_count = 0;
    size_t max_len = 0;
    size_t min_len = INT32_MAX;
};

struct FileStat {
    string filename;
    LineStat stat;
};

vector<FileStat> files;
string output_file;
bool compress = false, verbose = false, manpage = false, csv = false, recursive = false, merge = false;
char *format = nullptr;
PerformanceProfile pp = PerformanceProfile::Balanced;
string directory;

void signal_handler(int sig) {
    // Implement graceful shutdown logic here
}

void readFile(const string &filename) {
    ifstream file(filename);
    LineStat stat = {};
    size_t line_number = 0;
    string line;

    if (!file.is_open()) {
        cerr << "Error opening file: " << filename << endl;
        return;
    }

    while (getline(file, line)) {
        ++line_number;
        stat.line_count++;
        stat.max_len = max(stat.max_len, static_cast<size_t>(line.length()));
        stat.min_len = min(stat.min_len, static_cast<size_t>(line.length()));

        if (compress) {
            string compressed;
            for (char c : line) {
                if (!isspace(c))
                    compressed += c;
            }
            cout << compressed << endl;
        } else {
            cout << line << endl;
        }
    }

    files.push_back({filename, stat});
}

void processDirectoryRecursive(const string &directory) {
    DIR *dp;
    struct dirent *entry;
    dp = opendir(directory.c_str());

    if (nullptr == dp) {
        cerr << "Error: Could not open directory: " << directory << endl;
        return;
    }

    while ((entry = readdir(dp)) != nullptr) {
        string path = directory + "/" + entry->d_name;
        struct stat st;
        if (stat(path.c_str(), &st) == -1) continue;

        if (S_ISDIR(st.st_mode)) {
            if (!recursive) continue;
            processDirectoryRecursive(path);
        } else {
            readFile(path);
        }
    }

    closedir(dp);
}

void printStatistics() {
    cout << "Line Count: ";
    size_t total_lines = 0;
    for (const FileStat &fs : files) total_lines += fs.stat.line_count;
    cout << total_lines << endl;

    if (files.size() > 1) {
        cout << "Files: ";
        size_t file_count = files.size();
        cout << file_count - 1 << endl;
    }

    cout << "Longest Line Length: ";
    size_t total_max_len = 0;
    for (const FileStat &fs : files) total_max_len = max(total_max_len, fs.stat.max_len);
    cout << total_max_len << endl;

    cout << "Shortest Line Length: ";
    size_t total_min_len = INT32_MAX;
    for (const FileStat &fs : files) total_min_len = min(total_min_len, fs.stat.min_len);
    cout << total_min_len << endl;

    if (csv) {
        cout << "File,Lines,Longest Line Length,Shortest Line Length" << endl;
        for (const FileStat &fs : files) {
            cout << fs.filename << ","
                 << fs.stat.line_count << ","
                 << fs.stat.max_len << ","
                 << fs.stat.min_len << endl;
        }
    }
}

int main(int argc, char *argv[]) {
    log4cxx::BasicConfigurator config;
    config.setRootLevel(log4cxx::LevelForLogger("main", log4cxx::INFO));
    config.configure();

    struct option long_options[] = {
        {"compress", no_argument, nullptr, 'c'},
        {"output-file", required_argument, nullptr, 'o'},
        {"manpage", no_argument, nullptr, 'h'},
        {"verbose", no_argument, nullptr, 'v'},
        {"format", required_argument, nullptr, 'f'},
        {"csv", no_argument, nullptr, 'n'},
        {"merge", no_argument, nullptr, 'm'},
        {"recursive", no_argument, nullptr, 'r'},
        {"performance-profile", required_argument, nullptr, 'p'},
        {0, 0, 0, 0}
    };

    bool opt = false;
    while ((opt = getopt_long(argc, argv, "c:o:hvfr:nmp:", long_options)) != -1) {
        switch (opt) {
            case 'c': compress = true; break;
            case 'o': output_file = optarg; break;
            case 'h': manpage = true; break;
            case 'v': verbose = true; break;
            case 'f': format = optarg; break;
            case 'n': csv = true; break;
            case 'm': merge = true; break;
            case 'r': recursive = true; break;
            case 'p':
                if (strcasecmp(optarg, "speed") == 0) pp = PerformanceProfile::Speed;
                else if (strcasecmp(optarg, "memory") == 0) pp = PerformanceProfile::Memory;
                else {
                    cerr << "Invalid performance profile: " << optarg << endl;
                    manpage = true;
                }
                break;
            default: manpage = true; break;
        }
    }

    if (manpage) {
        cout << "Usage: myprogram [options] [input_file]..." << endl;
        cout << "\nOptions:" << endl;
        cout << "  -c, --compress            Compress lines in the input file" << endl;
        cout << "      --output-file FILE    Output to specified file instead of stdout" << endl;
        cout << "  -h, --manpage              Print comprehensive usage information and examples" << endl;
        cout << "  -v, --verbose              Enable verbose mode" << endl;
        cout << "  -f, --format FORMAT        Specify a custom format string for line statistics (e.g., %d lines, %d shortest, %d longest)" << endl;
        cout << "  -n, --csv                   Output CSV-formatted statistics" << endl;
        cout << "  -m, --merge                Merge individual file statistics into a single report" << endl;
        cout << "  -r, --recursive             Recursively process subdirectories" << endl;
        cout << "  -p, --performance-profile   Adjust processing parameters to optimize for either speed or memory usage" << endl;
        return 0;
    }

    if (optind < argc) directory = argv[optind];

    if (recursive && (argc - optind > 1)) {
        cerr << "Error: Cannot use --recursive and specify input files." << endl;
        return 1;
    }

    if (!directory && argc - optind <= 1) {
        cerr << "Error: No input files or directory specified." << endl;
        manpage = true;
        return 1;
    }

    if (recursive) processDirectoryRecursive(directory);
    else for (int i = optind; i < argc; ++i) readFile(argv[i]);

    if (!merge) printStatistics();
    else {
        LineStat stat = {};
        for (const FileStat &fs : files) {
            stat.line_count += fs.stat.line_count;
            stat.max_len = max(stat.max_len, fs.stat.max_len);
            stat.min_len = min(stat.min_len, fs.stat.min_len);
        }
        printStatistics();
        cout << "Aggregated Statistics:" << endl;
        if (csv) {
            cout << stat.line_count << ","
                 << stat.max_len << ","
                 << stat.min_len << endl;
        } else {
            cout << "Line Count: " << stat.line_count << endl;
            cout << "Longest Line Length: " << stat.max_len << endl;
            cout << "Shortest Line Length: " << stat.min_len << endl;
        }
    }

    return 0;
}
