#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef enum { INT, STRING, BOOLEAN } Type;

struct ConfigParam {
    char key[256];
    Type type;
    union {
        int i;
        char *str;
        bool b;
    } value;
    struct ConfigParam *next;
};

struct HashTable {
    int size;
    struct ConfigParam **entries;
    pthread_mutex_t lock;
};

void init_hash_table(struct HashTable *ht, int size) {
    ht->size = size;
    ht->entries = calloc(size, sizeof(struct ConfigParam*));
    memset(ht->entries, 0, sizeof(struct ConfigParam*) * size);
    pthread_mutex_init(&ht->lock, NULL);
}

unsigned int hash(const char *key) {
    unsigned int hash = 5381;
    int c;

    while ((c = *key++))
        hash = (hash * 33) ^ c; /* hash * 33 + c */

    return hash % ht->size;
}

struct ConfigParam *find_param(struct HashTable *ht, const char *key) {
    struct ConfigParam *entry = ht->entries[hash(key)];

    while (entry) {
        if (strcmp(entry->key, key) == 0)
            return entry;
        entry = entry->next;
    }

    return NULL;
}

void add_param(struct HashTable *ht, const char *key, Type type, void *value) {
    struct ConfigParam *param = malloc(sizeof(struct ConfigParam));
    strcpy(param->key, key);
    param->type = type;

    if (type == STRING)
        param->value.str = malloc(256);

    switch (type) {
        case INT:
            param->value.i = *(int *) value;
            break;
        case STRING:
            strcpy(param->value.str, value);
            break;
        case BOOLEAN:
            param->value.b = *(bool *) value;
            break;
    }

    pthread_mutex_lock(&ht->lock);

    param->next = ht->entries[hash(key)];
    ht->entries[hash(key)] = param;

    pthread_mutex_unlock(&ht->lock);
}

void *update_param(struct HashTable *ht, const char *key, Type type, void *value) {
    struct ConfigParam *param = find_param(ht, key);

    if (!param)
        return NULL;

    pthread_mutex_lock(&ht->lock);

    switch (type) {
        case INT:
            param->value.i = *(int *) value;
            break;
        case STRING:
            free(param->value.str);
            param->value.str = malloc(256);
            strcpy(param->value.str, value);
            break;
        case BOOLEAN:
            param->value.b = *(bool *) value;
            break;
    }

    pthread_mutex_unlock(&ht->lock);

    return param;
}

void delete_param(struct HashTable *ht, const char *key) {
    struct ConfigParam **prev, *current;

    prev = &ht->entries[hash(key)];
    current = *prev;

    while (current) {
        if (strcmp(current->key, key) == 0) {
            *prev = current->next;
            free(current);
            return;
        }

        prev = &current->next;
        current = current->next;
    }
}

void serialize_config(struct HashTable *ht, FILE *fp) {
    // Implement serialization logic here...
}

void deserialize_config(struct HashTable *ht, FILE *fp) {
    // Implement deserialization logic here...
}
