// Custom memory pool allocator for integer_pool
struct int_pool {
    void *memory;
    size_t allocated_size;
    size_t used_size;
};

// Function to initialize the custom memory pool
void init_int_pool(struct int_pool *pool, size_t initial_size) {
    // Initialize the pool with the given size
    pool->memory = malloc(initial_size);
    pool->allocated_size = initial_size;
    pool->used_size = 0;
}

// Function to allocate an integer from the pool
int *int_pool_alloc(struct int_pool *pool) {
    if (pool->used_size >= pool->allocated_size) {
        pool->allocated_size *= 2;
        pool->memory = realloc(pool->memory, pool->allocated_size);
    }
    return pool->memory + pool->used_size++;
}

