    ConfigType type;
    union {
        int i;
        char *s;
        bool b;
    } value;
} ConfigParam;

#define MAX_KEY_LENGTH 32
#define MAX_VALUE_LENGTH 1024
typedef struct HashNode_t {
    ConfigParam param;
    struct HashNode_t *next;
} HashNode;

typedef struct {
    HashNode **table;
    int size;
    int capacity;
} HashTable;

HashTable config_table;

void init_config_table(int capacity) {
    config_table.capacity = capacity;
    config_table.size = 0;
    config_table.table = calloc((size_t)capacity, sizeof(ConfigParam*));
}

// Implement functions for adding, updating, retrieving parameters, serialization, deserialization, etc. Here is a simplified example of adding a parameter:

void add_config_param(const char *key, ConfigType type, union value) {
    int index = hash(key);
    HashNode *node = config_table.table[index];

    while (node != NULL && strcmp(node->param.key, key) != 0)
        node = node->next;

    if (node == NULL || strcmp(node->param.key, key) == 0) {
        if (node != NULL) {
            node->param.type = type;
            node->param.value = value;
        } else {
            HashNode *new_node = malloc(sizeof(HashNode));
            strncpy(new_node->param.key, key, MAX_KEY_LENGTH);
            new_node->param.type = type;
            new_node->param.value = value;
            new_node->next = config_table.table[index];
            config_table.table[index] = new_node;
        }
    } else {
        fprintf(stderr, "Error: Key already exists.\n");
    }
}

int hash(const char *key) {
    int hash = 5381;
    int c;

    while ((c = *key++) != '\0') {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % config_table.capacity;
}

