char* append_slash_if_needed(const char *input, size_t limit, bool strict) {
    if (!input || limit == 0) {
        return NULL;
    }

    size_t input_len = strlen(input);
    if (input_len > limit && strict) {
        return NULL;
    }

    char *result = malloc(input_len + (strict && input_len < limit ? 1 : 0));
    if (!result) {
        return NULL;
    }

    memcpy(result, input, input_len);
    if (strict && input_len >= limit) {
        result[input_len] = '\0'; // Ensure null termination even if size limit is exceeded.
    } else if (!strict && input_len == limit) {
        result[input_len] = '\0'; // Null terminate the original string for safety.
    } else {
        result[input_len] = '/';
    }

    return result;
}
