        current->crc_indication.crcflag = CRCI_FLAG;

        pthread_mutex_unlock(&mutex);
        pthread_mutex_unlock(&mutexes[i]);
        ++success_count;
    }

    if (success_count != N) {
        fprintf(stderr, "Error: Incomplete array initialization\n");
        for (size_t i = 0; i < N; ++i) pthread_mutex_destroy(&mutexes[i]);
