```java
public class FileHasher {
    private static final int THREAD_COUNT = Runtime.getRuntime().availableProcessors();

    public String hashFile(Path filePath) throws IOException, InterruptedException {
        ByteBuffer buffer = ByteBuffer.allocateDirect(1024 * 1024); // 1 MB chunk
        MessageDigest md = MessageDigest.getInstance("MD5");
        List<Future<String>> hashingTasks = new CopyOnWriteArrayList<>();

        try (BufferedInputStream inputStream = Files.newBufferedInputStream(filePath)) {
            executeHashingTasks(hashingTasks, inputStream, buffer, md);
        }

        for (Future<String> future : hashingTasks) {
            future.get();
        }

        return String.join("", hashingTasks.stream().map(Future::get).collect(Collectors.toList()));
    }

    private void executeHashingTasks(List<Future<String>> hashingTasks, InputStream inputStream, ByteBuffer buffer, MessageDigest md) {
        executor.submit(() -> {
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                buffer.flip();
                md.update(buffer);
                buffer.clear();
            }
            return String.valueOf(new BigInteger(1, md.digest()));
        }).thenApplyAsync(this::toHexDigest).thenAccept(hashingTasks::add);
    }

    private Future<String> toHexDigest(String hexDigest) {
        return CompletableFuture.supplyAsync(() -> hexDigest.toUpperCase(Locale.ROOT));
    }
}
```

