void init_pipeline(size_t num_threads, ProcessFunction process_text,
                    ProcessFunction process_binary) {
    sem_init(&buffer_mutex, 0, 1);
    pthread_mutex_init(&worker_mutex, NULL);

    workers = malloc(num_threads * sizeof(struct Worker));
    buffers = calloc(num_threads, sizeof(FILE *));

    for (size_t i = 0; i < num_threads; ++i) {
        workers[i].process_func = (i == 0) ? process_text : process_binary;
        pthread_create(&workers[i].thread_id, NULL, worker_main, &i);
    }

    num_workers = num_threads;
}

void worker_main(void *arg) {
    size_t worker_idx = *(size_t *)arg;
    free(arg);

    while (true) {
        FileInfo file_info;
        pthread_mutex_lock(&worker_mutex);
        if (!num_workers) break; // no more workers, exit the loop
        num_workers--;
        pthread_mutex_unlock(&worker_mutex);

        sem_wait(&buffer_mutex);
        memset(&file_info, 0, sizeof(FileInfo));
        file_info.file_type = worker_idx == 0 ? FILE_TYPE::TEXT : FILE_TYPE::BINARY;
        // Acquire the next file
        // ... implementation details omitted for brevity ...
        sem_post(&buffer_mutex);

        workers[worker_idx].process_func(&file_info);
    }
}

void add_file(const char *filename, enum FileType file_type, size_t size, int urgency) {
    FileInfo file_info;
    file_info.filename = strdup(filename);
    file_info.file_type = file_type;
    file_info.size = size;
    file_info.urgency = urgency;

    sem_wait(&buffer_mutex);
    // Enqueue the file in the appropriate buffer based on file type and other criteria
    // ... implementation details omitted for brevity ...
    sem_post(&buffer_mutex);
}

void scale_workers(int new_num_threads) {
    int old_num_workers = num_workers;
    pthread_mutex_lock(&worker_mutex);

    while (num_workers < new_num_threads) {
        pthread_t new_worker_id;
        size_t worker_idx = num_workers;
        workers[worker_idx].process_func = NULL;
        pthread_create(&new_worker_id, NULL, worker_main, &worker_idx);
        workers[worker_idx] = (struct Worker){ .thread_id = new_worker_id };
        num_workers++;
    }

    while (num_workers > old_num_workers) {
        pthread_join(workers[old_num_workers].thread_id, NULL);
        workers[old_num_workers] = workers[num_workers - 1];
        workers[num_workers - 1] = (struct Worker){ .process_func = NULL };
        num_workers--;
    }

    pthread_mutex_unlock(&worker_mutex);
}
