    if (!cfg->trim || len < cfg->max_len) {
        // No need to trim or append slash if string fits within the limit
    } else {
        res[cfg->max_len - 1] = '/';
        memset(&res[cfg->max_len], 0, len - (cfg->max_len - 1));
    }

#ifdef DEBUG
    if (cfg->log) fprintf(cfg->log, "Allocated %zu bytes for string: '%s'\n", len+1, res);
#endif

    if (len > cfg->max_len && cfg->strict) {
        if (cfg->log) fprintf(cfg->log, "String exceeded size limit (%zu > %zu), strict enforcement\n", len+1, cfg->max_len);
    } else if (!cfg->trim && len == cfg->max_len) {
        if (cfg->log) fprintf(cfg->log, "String exactly matches size limit (%zu = %zu), relaxed enforcement\n", len+1, cfg->max_len);
    } else if (cfg->trim && len > cfg->max_len) {
        if (cfg->log) fprintf(cfg->log, "String exceeded size limit (%zu > %zu), trimming to fit: '%s'\n", len+1, res);
