#include <inttypes.h>

struct counter {
    atomic_long_t calls;
};

char* append_slash(const char *input, size_t size_limit, size_t max_buffer_size, char *buffer, size_t buffer_size, struct counter *counter) {
    if (!input || size_limit < 1 || max_buffer_size < 2 || buffer && buffer_size < 2)
        return NULL;

    const size_t input_len = strlen(input);
    if (input_len > size_limit || input_len + 1 > max_buffer_size)
        return NULL;

    struct counter *local_counter = counter;
    atomic_fetch_add(&local_counter->calls, 1);

    char *result = malloc(input_len + (input_len >= size_limit ? 0 : 2));
    if (!result)
        return NULL;

    if (buffer && buffer_size >= input_len + 1) {
        memcpy(buffer, result, input_len + (input_len >= size_limit ? 0 : 2));
        free(result);
        return buffer;
    }

    strcpy(result, input);
    if (input_len < size_limit && input_len + 1 <= max_buffer_size)
        strcat(result, "/");

    return result;
}
