['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char *truncate_string(const char *input, size_t limit, int modify) {
    size_t input_len = strlen(input);
    if (input_len > limit || !limit) return NULL;

    size_t current_word_start = 0;
    size_t current_word_len = 0;
    char *result = malloc(limit + 1);
    if (!result) return NULL;

    for (size_t i = 0; i < input_len; ++i) {
        if (!isalnum(input[i])) {
            current_word_start = i + 1;
            continue;
        }

        result[current_word_len++] = input[i];

        if (i + current_word_len >= limit) {
            memcpy(&result[0], &input[current_word_start], limit - 1);
            result[limit - 1] = '\0';

            // Append ellipsis if necessary and modify the string.
            if (modify && input_len > limit) {
                size_t ellipsis_length = sizeof("...") - 1;
                memcpy(&result[limit - ellipsis_length], "...", ellipsis_length);
            }
            break;
        }
    }

    result[current_word_len] = '\0'; // Null terminate the result.
    return result;
}
