    new_node->packet = packet;
    new_node->next = *queue;
    *queue = new_node;
}

Packet dequeue(Queue *queue) {
    Queue current = *queue;
    Packet temp_packet;

    if (current == NULL) return (Packet){0};

    temp_packet = current->packet;
    *queue = current->next;
    free(current);

    return temp_packet;
}

