        if (adjusted_len > len) adjusted_len = len;
        size_t new_size = adjusted_len + ellipsis_len + 1;

        char *result = (char *)malloc(new_size);
        if (!result) return NULL;

        // Copy the string, truncating it if necessary and adding an ellipsis.
        size_t index = 0;
        for (size_t i = 0; i < len && index < adjusted_len; ++i) {
            char c = (case_insensitive ? tolower((unsigned char)src[i]) : src[i]);
            result[index++] = c;
            if (c == ' ') { // Skip spaces in the middle of truncation.
                index++;
            }
        }
        result[index] = '\0';

        // Add ellipsis to the end of the string.
        for (size_t i = index; i < new_size - 1; ++i) {
            result[i] = ' ';
        }
