    const char* message;
};

class SafeStringAppender {
public:
    SafeStringAppender(size_t maxBufferSize, boost::lockfree::spsc_queue<std::unique_ptr<char[]>>& bufferQueue, size_t atomicCounter)
        : maxBufferSize_(maxBufferSize), bufferQueue_(bufferQueue), atomicCounter_(atomicCounter) {}

    // Function to append a slash if applicable and return the resulting string
    boost::optional<std::string> appendSlashIfApplicable(const std::string& input, size_t sizeLimit) {
        if (input.empty() || sizeLimit <= 0 || maxBufferSize_ <= 0) {
            return boost::none;
        }

        // Determine the total length of the resulting string with a potential slash
        size_t requiredLength = input.length() + 1;
        if (requiredLength > sizeLimit) {
            return boost::none;
        }

        // Allocate memory for the temporary buffer and append the slash if necessary
        const size_t bufferSize = std::max(requiredLength, 1);
        auto tempBuffer = std::make_unique<char[]>(bufferSize);
        if (requiredLength > 1) {
            tempBuffer[0] = '/';
            std::copy(input.begin(), input.end(), tempBuffer + 1);
        } else {
            tempBuffer[0] = '\0'; // Empty string with a potential slash
        }

        // Check if the buffer queue can accommodate the temporary buffer and return early if not
        auto buffer = getNextAvailableBuffer();
        if (!buffer) {
            free(tempBuffer.get());
            return boost::none;
        }

        // Copy the temporary buffer to the allocated buffer, ensuring it fits within the provided buffer size
        std::copy(tempBuffer.get(), tempBuffer.get() + requiredLength, buffer->get());

        // Update the atomic counter and return the resulting string
        ++atomicCounter_;
        return *buffer;
    }

private:
    boost::lockfree::spsc_queue<std::unique_ptr<char[]>>& bufferQueue_;
    size_t maxBufferSize_;
    std::atomic<size_t> atomicCounter_;

    // Function to get the next available buffer from the queue
    std::unique_ptr<char[]> getNextAvailableBuffer() {
        auto buffer = bufferQueue_.pop();
        if (!buffer) {
            return nullptr;
        }

        const size_t bufferSize = buffer->size();
        // Check if the buffer can fit the required length for the input string with a potential slash
        if (bufferSize < maxBufferSize_ && bufferSize >= requiredLength_) {
            return buffer;
        }

        free(buffer.get()); // Free the buffer since it's not usable
        return nullptr;
    }

    size_t requiredLength_{1}; // Length of a potential slash string
};
```

