// Validate input string against a predefined pattern
bool validate_string(const char *input) {
    // Implement regular expression matching for the desired pattern
    regex_t regex;
    int reti = regcomp(&regex, "<pattern>", REG_EXTENDED | REG_NEWLINE);
    if (reti) {
        fprintf(stderr, "Regular expression compilation failed: %s\n", regerror(reti, &regex, NULL, 0));
        return false;
    }

    size_t nmatch = 1;
    regmatch_t pmatch[1];

    int retti = regexec(&regex, input, nmatch, pmatch, REG_NOTBOLT);
    regfree(&regex);

    if (retti == 0) {
        return true;
    } else if (regerror(retti, &regex, NULL, 0) != NULL) {
        fprintf(stderr, "Regex match failed: %s\n", regerror(retti, &regex, NULL, 0));
    }
    return false;
}

// Thread-safe function to append a slash if possible
char *append_slash(const char *input, size_t sizeLimit, size_t maxBufferSize, char *buffer, size_t bufferSize, std::atomic<uint64_t> &counter) {
    if (!validate_string(input)) {
        return NULL;
    }

    // Calculate the required length for the appended string
    size_t requiredLength = strlen(input) + 1;
    if (requiredLength > sizeLimit || requiredLength > maxBufferSize) {
        return NULL;
    }

    if (buffer && requiredLength > bufferSize) {
        return NULL;
    }

    char *compressedInput = nullptr;
    uint32_t compressedSize = 0;
    // Compress the input string (optional)
    if (compress_func) {
        compressedInput = static_cast<char*>(malloc(compressedSize + 1));
        compressedSize = compress_func(const_cast<char*>(input), strlen(input), compressedInput, compressedSize + 1);
    } else {
        compressedInput = static_cast<char*>(malloc(strlen(input) + 1));
        strcpy(compressedInput, input);
    }

    char *result;
    if (buffer && requiredLength <= bufferSize) {
        result = static_cast<char*>(realloc(buffer, requiredLength));
        if (!result) {
            free(compressedInput);
            return NULL;
        }
        strcpy(result + (requiredLength - strlen(input) - 1), input);
        result[0] = '/';
    } else {
        result = static_cast<char*>(malloc(requiredLength));
        if (!result) {
            free(compressedInput);
            return NULL;
        }
        strcpy(result, compressedInput);
        free(compressedInput);
        result[strlen(result)] = '/';
    }

    ++counter;
    log4cxx::LoggerPtr loggerCopy(logger->clone("thread"));
    log4cxx::LayoutPtr layout = log4cxx::PatternLayout::newFormatter("%d: appended slash to string", counter.load());
    log4cxx::AppenderPtr appender(log4cxx::ConsoleAppender::getRootLogger());
    log4cxx::BasicConfigurator::configure(appender, layout);
