Counter global_counter = { .mutex = PTHREAD_MUTEX_INITIALIZER, .counter = 0 };

const char *append_slash(const char *filename, size_t size_limit, size_t max_buffer_size, size_t buffer_size, char *buffer, Counter *counter) {
    if (!filename || size_limit < 0 || max_buffer_size <= 0)
        return NULL;

    size_t filename_len = strlen(filename);
    if (filename_len >= size_limit || filename_len + 1 >= max_buffer_size)
        return NULL;

    pthread_mutex_lock(&global_counter->mutex);
    ++global_counter->counter;
    pthread_mutex_unlock(&global_counter->mutex);

    if (buffer && filename_len + 1 >= buffer_size) {
        // Reallocate buffer to accommodate the new string
        char *new_buffer = realloc(buffer, filename_len + 2);
        if (!new_buffer)
            return NULL;
        buffer = new_buffer;
    }

    strcpy(buffer, filename);
    if (filename[filename_len - 1] != '/')
        buffer[filename_len++] = '/';

    // Count vowels and determine extension length
    size_t vowel_count = 0;
    for (size_t i = 0; filename[i]; ++i) {
        wint_t c = tolower((wint_t)filename[i]);
        if ((c >= L'a' && c <= L'z') || (c >= L'A' && c <= L'Z')) {
            switch (c) {
                case L'a':
                case L'e':
                case L'i':
                case L'o':
                case L'u':
                    ++vowel_count;
                    break;
            }
        }
    }
    size_t extension_len = (vowel_count + 1) / 2 * 3;

    // Append extension and special sequence
    size_t new_filename_len = filename_len + extension_len + 4;
    if (new_filename_len > max_buffer_size) {
        free(buffer);
        return NULL;
    }

    char *new_buffer = realloc(buffer, new_filename_len);
    if (!new_buffer)
        return NULL;
    buffer = new_buffer;

    size_t extension_start = filename_len;
    strncpy(buffer + extension_start, "@#$", 4);
    for (size_t i = 0; i < extension_len - 3; ++i) {
        buffer[extension_start + i + 4] = '\0'; // Create null-terminated extensions
        strncpy(buffer + extension_start + i + 4, filename + (i * 2 / extension_len), 2);
    }
    buffer[new_filename_len - 1] = '\0'; // Ensure the last character is a null terminator

    log4c_logger_t *logger = log4c_logger_get_root();
    log4c_category_t *category = log4c_category_get(logger, "append_slash");
    log4c_info(category, "Successfully appended slash to filename: %s (size limit: %zu, buffer size: %zu)", filename, size_limit, max_buffer_size);

    return buffer;
}
