#include <atomic>
#include <map>
#include <vector>

typedef struct {
    int sockfd;
    struct sockaddr_in addr;
} Interface;

class PacketQueue {
public:
    std::atomic<int> size;
    std::priority_queue<std::pair<int, void*>, std::vector<std::pair<int, void*>>, std::greater<>> packets;

    void enqueue(int priority, void* packet) {
        packets.push({priority, packet});
        size++;
    }

    void* dequeue() {
        if (packets.empty()) return nullptr;
        auto packet = packets.top().second;
        packets.pop();
        size--;
        return packet;
    }
};

class ThreadPool {
public:
    std::vector<pthread_t> threads;
    std::map<int, PacketQueue*> queues;

    void start(size_t numThreads) {
        threads.resize(numThreads);
        for (auto& thread : threads) pthread_create(&thread, nullptr, processPacket, this);
    }

    void addQueue(int id, PacketQueue* queue) {
        queues[id] = queue;
    }

    static void* processPacket(void* arg) {
        ThreadPool* pool = static_cast<ThreadPool*>(arg);
        while (true) {
            // Monitor and log thread status

            PacketQueue* queue = nullptr;
            void* packet = nullptr;
            int id = -1;
            {
                std::lock_guard<std::mutex> lock(pool->queuesMutex);
