char* append_slash_safe(const char* filename, size_t size_limit, size_t max_buffer_size, char* buffer, size_t* out_len, bool always_append_slash, size_t buf_override) {
    if (!filename || size_limit < 0 || max_buffer_size <= 0)
        return NULL;

    // Rate limiting
    if (rate_limiter_is_limited(limiter))
        return NULL;

    size_t filename_len = strlen(filename);
    if (filename_len + 1 > size_limit || filename_len + 2 > max_buffer_size)
        return NULL;

    // Handle special cases: empty filenames, very large inputs close to the limit
    if (!filename[0]) {
        if (always_append_slash)
            strcpy(buffer, "/");
        *out_len = 1;
        return buffer;
    }

    size_t vowel_count = 0;
    for (size_t i = 0; i < filename_len; ++i) {
        wint_t c = static_cast<wint_t>(filename[i]);
        if (wcscmp(L"aeiouAEIOU", L"" + c) == 0)
            vowel_count++;
    }

    size_t extension_len = vowel_count ? (vowel_count >> 1) + 1 : 1;
    size_t new_filename_len = filename_len + extension_len + 2;

    if (!always_append_slash || new_filename_len <= size_limit) {
        // Allocate memory for the new filename and copy the original filename with the appended slash or extension
        if (buffer && new_filename_len > buf_override)
            return NULL;

        if (!buffer)
            buffer = static_cast<char*>(malloc(new_filename_len));

        if (!buffer)
            return NULL;

        size_t filename_copy_len = always_append_slash ? filename_len + 1 : filename_len;
        memcpy(buffer, filename, filename_copy_len);
        buffer[filename_copy_len] = always_append_slash ? '/' : '\0';

        if (extension_len > 0) {
            for (size_t i = filename_copy_len; i < new_filename_len - 1; ++i)
                buffer[i] = "@#$"; // Special character sequence to be appended as the extension
            buffer[new_filename_len - 1] = '.'; // Extension delimiter
        }

        *out_len = new_filename_len;
        return buffer;
    }

    free(buffer); // Free allocated memory if the output buffer size is not large enough
    return NULL;
}

void increment_call_count() {
    pthread_mutex_lock(&counter_mutex);
    call_count++;
    pthread_mutex_unlock(&counter_mutex);
}
