    struct timeval tv;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);
        tv.tv_sec = 10;
        tv.tv_usec = 0;
        select(FD_SETSIZE, &readfds, NULL, NULL, &tv);

        if (FD_ISSET(fd, &readfds)) {
            map_len = lseek(fd, 0, SEEK_END) - pos;
            if (map_len > 0) {
                map_base = mmap(NULL, map_len, PROT_READ, MAP_PRIVATE, fd, pos);
