// Configuration options
extern bool always_append_slash;
extern size_t dynamic_max_buffer_size;
std::atomic<uint64_t> function_calls{ 0 };
static std::mutex calls_mutex;
static std::queue<std::function<void()>> rate_limiter_queue;
static std::deque<std::pair<const char*, size_t>> pending_operations;
static pthread_mutex_t pending_operations_mutex = PTHREAD_MUTEX_INITIALIZER;

// Rate limiter using leaky bucket algorithm with 100 tokens per minute
static void rate_limiter() {
    const double tokens_per_second = 100.0 / 60.0;
    const std::chrono::seconds time_between_tokens(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::duration<double>(1.0 / tokens_per_second)));

    while (true) {
        std::this_thread::sleep_for(time_between_tokens);
        std::unique_lock<std::mutex> lock(rate_limiter_queue.mutex());
        rate_limiter_queue.push_back([&]() { });
        lock.unlock();
    }
}

// Helper function to count vowels in a string
size_t count_vowels(const char* str) {
    size_t count = 0;
    const char* vowels = "aeiouAEIOU";

    for (const char* p = str; *p != '\0'; ++p) {
        if (strchr(vowels, *p) != nullptr) {
            ++count;
        }
    }

    return count;
}

// Helper function to create a new filename with extension and special character sequence
std::string generate_new_filename(const char* original_filename, size_t vowel_count) {
    const size_t extension_length = (vowel_count > 1) ? (vowel_count / 2 + 1) : 1;
    std::string new_extension(".@#$");
    new_extension.resize(extension_length + new_extension.size());

    return original_filename + (always_append_slash ? "/" : "") +
           std::string(original_filename + strlen(original_filename), '.') +
           new_extension;
}

void* process_filename_thread(void* arg) {
    auto args = static_cast<std::pair<const char*, size_t>*>(arg);

    // Perform the processing tasks and return the processed filename
    const char* filename = args->first;
    size_t size_limit = args->second;
    const size_t max_buffer_size = (dynamic_max_buffer_size > 0) ? dynamic_max_buffer_size : MAXPATHLEN;
    size_t vowel_count = count_vowels(filename);
    std::string new_filename = generate_new_filename(filename, vowel_count);

    if (new_filename.length() > max_buffer_size) {
        return nullptr;
    }

    // Increment the function call counter and record the operation metadata
    std::unique_lock<std::mutex> lock(calls_mutex);
    ++function_calls;
    log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("file_processor");
    log4cxx::BasicConfigurator::configure();
    logger->info("Processed filename: " + std::string(filename) + ", size limit: " + std::to_string(size_limit) +
                 ", max buffer size: " + std::to_string(max_buffer_size) +
                 ", new extension: " + new_extension +
                 (new_filename.length() <= max_buffer_size ? ", success" : ", failure"));
    lock.unlock();

    return const_cast<char*>(new_filename.c_str());
}

void* rate_limiter_thread(void* arg) {
    while (true) {
        rate_limiter();
    }
    return nullptr;
}

char* process_filename(const char* filename, size_t size_limit, size_t max_buffer_size, char* output_buffer, size_t output_buffer_size) {
    // Push the operation onto the queue and wait for a thread to pick it up if needed
    std::unique_lock<std::mutex> lock(pending_operations_mutex);
    pending_operations.push_back(std::make_pair(filename, size_limit));
    lock.unlock();

    // Start the rate limiter thread if it's not already running
    pthread_t rate_limiter_thread_id;
    if (pthread_create(&rate_limiter_thread_id, nullptr, rate_limiter_thread, nullptr) != 0) {
        perror("pthread_create: rate limiter thread");
        return nullptr;
    }

    // Wait for a thread to process the operation and return the result
    std::unique_lock<std::mutex> rate_limiter_queue_lock(rate_limiter_queue.mutex());
    while (rate_limiter_queue.empty()) {
        rate_limiter_queue_lock.wait();
    }
    void* result = rate_limiter_queue.front();
    rate_limiter_queue.pop_front();
    rate_limiter_queue_lock.unlock();

    // Check if the result is a processed filename or an error indication
