typedef struct {
    size_t count;
    pthread_mutex_t mutex;
} Counter;

void init_counter(Counter* c) {
    pthread_mutex_init(&c->mutex, NULL);
    c->count = 0;
}

void increment_counter(Counter* c) {
    pthread_mutex_lock(&c->mutex);
    ++c->count;
    pthread_mutex_unlock(&c->mutex);
}

size_t get_counter(const Counter* c) {
