    size_t count = c->count;
    pthread_mutex_unlock(&c– c->mutex);
    return count;
}

int append_slash(char** dest, const char* src, size_t limit, size_t max_buffer_size, Counter* counter, void (*callback)(const char*, size_t, bool)) {
    if (!src || limit <= 0 || max_buffer_size <= 0)
        return false;

    size_t src_len = strlen(src);
    if (src_len > limit || src_len + 1 > max_buffer_size)
        return false;

    iconv_t cd;
    char* tmp = malloc(src_len + 2);
    if (!tmp) {
        // Handle error and call the callback if necessary.
        if (callback) callback(src, limit, false);
        return false;
    }

    strcpy(tmp, src);
    tmp[src_len] = '/';
    tmp[src_len + 1] = '\0';

    size_t converted_len;
    char* result = iconv(cd, &tmp, &tmp + src_len + 2, NULL, &converted_len);
    if (!result) {
        // Handle error and call the callback if necessary.
        if (callback) callback(src, limit, false);
        free(tmp);
        return false;
    }

    size_t new_len = strlen(result);
    if (new_len > max_buffer_size - 1) {
        // Handle error and call the callback if necessary.
        if (callback) callback(src, limit, false);
        free(tmp);
        free(result);
        return false;
    }

    if (*dest && new_len + strlen(*dest) > max_buffer_size) {
        // Handle error and call the callback if necessary.
        if (callback) callback(src, limit, false);
        free(tmp);
        free(result);
        return false;
    }

    if (*dest) {
        size_t old_len = strlen(*dest);
        char* new_buf = realloc(*dest, old_len + new_len + 1);
        if (!new_buf) {
            // Handle error and call the callback if necessary.
            if (callback) callback(src, limit, false);
            free(tmp);
            free(result);
            return false;
        }
        memcpy(new_buf + old_len, result, new_len + 1);
        *dest = new_buf;
    } else {
        *dest = result;
    }

    increment_counter(counter);
    if (callback) callback(src, limit, true);
    return true;
}
