void compress_and_encode_data(const void* data, size_t dataSize, float targetCompressionRatio, size_t maxOutputBufferSize, char* outputBuffer, size_t bufferSize, size_t* encodedSize) {
    if (!data || !targetCompressionRatio >= 0.0f || !maxOutputBufferSize || !bufferSize || bufferSize < dataSize + HEADER_LENGTH + WHITESPACE_CHARS_COUNT(data, dataSize) + encodedSize) {
        return; // Invalid inputs
    }

    size_t compressedSize = static_cast<size_t>(ceilf(dataSize * targetCompressionRatio));
    if (compressedSize > maxOutputBufferSize - HEADER_LENGTH - WHITESPACE_CHARS_COUNT(data, dataSize) - encodedSize) {
        return; // Compressed size exceeds maximum output buffer size
    }

    uint8_t* compressedData = static_cast<uint8_t*>(malloc(compressedSize));
    if (!compressedData) {
        return; // Failed to allocate memory for compression
    }

    size_t uncompressedDataSize;
    if (compress2(compressedData, &uncompressedDataSize, static_cast<const Bytef*>(data), dataSize, Z_BEST_SPEED) != Z_OK) {
        free(compressedData);
        return; // Failed to compress the input data
    }

    size_t encodedDataLength = base64_encoded_length(uncompressedDataSize);
    if (encodedDataLength > maxOutputBufferSize - HEADER_LENGTH - WHITESPACE_CHARS_COUNT(data, dataSize) - encodedSize) {
        free(compressedData);
        return; // Encoded data exceeds maximum output buffer size
    }

    char* encodedData = static_cast<char*>(malloc(encodedDataLength));
    if (!encodedData) {
        free(compressedData);
        return; // Failed to allocate memory for Base64 encoding
    }

    base64_encode(static_cast<const uint8_t*>(compressedData), uncompressedDataSize, encodedData, encodedDataLength);

    size_t metadataLength = WHITESPACE_CHARS_COUNT(data, dataSize) > WHITESPACE_MIN ? WHITESPACE_CHARS_COUNT(data, dataSize) : 1;
    char* metadata = static_cast<char*>(malloc(metadataLength));
    if (!metadata) {
        free(encodedData);
        free(compressedData);
        return; // Failed to allocate memory for metadata
    }

    countWhitespaceChars(data, dataSize, metadata);

    size_t totalLength = HEADER_LENGTH + metadataLength + encodedDataLength;
    if (totalLength > maxOutputBufferSize) {
        free(metadata);
        free(encodedData);
        free(compressedData);
        return; // Total length exceeds maximum output buffer size
    }

    char* result = static_cast<char*>(malloc(totalLength));
    if (!result) {
        free(metadata);
        free(encodedData);
        free(compressedData);
        return; // Failed to allocate memory for the final result
    }

    snprintf(result, totalLength, "DATA:%s%s", metadata, encodedData);

    *encodedSize = totalLength;
    free(metadata);
    free(encodedData);
    free(compressedData);
}
