#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <regex.h>
#include <zlib.h>
#include <time.h>

typedef struct {
    char *path;
    int fd;
    size_t pos;
    gzFile gz;
    regex_t reg;
} FileData;

static pthread_mutex_t files_mutex = PTHREAD_MUTEX_INITIALIZER;
static int max_threads = 4;
static int num_files = 0;
static FILE *log_file = stderr;

void progress(int total, int completed) {
    double percentage = (double)completed / total * 100.0;
    fprintf(log_file, "[%3.2f%%] Processing...\n", percentage);
}

int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0 && S_ISREG(st.st_mode);
}

void *process_file(void *data) {
    FileData *fd = (FileData *)data;
    char line[4096];
    ssize_t len;
    size_t lines = 0;

    while ((len = gzgets(fd->gz, line, sizeof(line))) != EOF) {
        if (regcomp(&fd->reg, fd->path + optind, REG_EXTENDED | REG_NEWLINE)) {
            perror("Error compiling regular expression");
            goto end;
        }

        if (!regexec(&fd->reg, line, 0, NULL, 0)) {
            continue;
        }

        lines++;
    }

    if (regfree(&fd->reg)) {
        perror("Error freeing regular expression");
        goto end;
    }

end:
    progress(num_files, fd - files + 1);
    pthread_mutex_lock(&files_mutex);
    num_files--;
    pthread_mutex_unlock(&files_mutex);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(log_file, "Usage: %s [-o output] [--manpage] [input1 input2 ...]\n", argv[0]);
        return 1;
    }

    const int opt_index = 0;
    char *output_path = NULL;
    int manpage = 0, compress = 0;

    opterr = 0;
    while (1) {
        static const struct option long_opts[] = {
            {"manpage", no_argument, NULL, 'h'},
            {"output", required_argument, NULL, 'o'},
            {NULL}
        };

        int c = getopt_long(argc, argv, "ho:", long_opts, NULL);
        if (c == -1)
            break;

        switch (c) {
            case 'h':
                manpage = 1;
                break;
            case 'o':
                output_path = optarg;
                break;
            default:
                fprintf(log_file, "Invalid option\n");
                return 1;
        }
    }

    if (manpage) {
        // Print manpage here
        return 0;
    }

    FILE *out = output_path ? fopen(output_path, "w") : stdout;
    if (!out) {
        perror("Error opening output file");
        return 1;
    }

    int i;
    FileData *files = malloc((argc - optind) * sizeof(FileData));
    num_files = argc - optind;

    for (i = optind; i < argc; ++i) {
        if (!file_exists(argv[i])) {
            fprintf(log_file, "Error: Invalid input file '%s'\n", argv[i]);
            return 1;
        }

        files[num_files].path = argv[i];
    }

    pthread_t threads[max_threads];
    for (int t = 0; t < max_threads && num_files > 0; ++t) {
        if (num_files <= max_threads - 1) {
            max_threads = num_files;
        }

        int start = num_files - max_threads;
        for (int i = start; i < num_files; ++i) {
            files[i].fd = open(files[i].path, O_RDONLY | O_BINARY);
            if (files[i].fd == -1) {
                perror("Error opening input file");
                goto end;
            }

            struct stat st;
            fstat(files[i].fd, &st);
            files[i].pos = st.st_size;
            if (strchr(files[i].path + optind, '.') && strcmp(strrchr(files[i].path + optind, '.'), ".gz")) {
                char *tmp_name = malloc((strlen(files[i].path) + strlen(".tmp.") + 1) * sizeof(char));
                sprintf(tmp_name, "%s.tmp.", files[i].path);
                int fd_tmp = open(tmp_name, O_WRONLY | O_CREAT | O_TRUNC | O_BINARY, S_IRUSR | S_IWUSR | S_IXUSR);
                if (fd_tmp == -1) {
                    perror("Error creating temporary file");
                    goto end;
                }

                gzFile gzfile = gzdopen(fd_tmp, "wb");
                files[i].gz = gzfile;
                int read_len;
                while ((read_len = read(files[i].fd, tmpnam(NULL), sizeof(tmpnam(NULL)))) > 0) {
                    gzwrite(gzfile, tmpnam(NULL), read_len);
                }

                close(fd_tmp);
                unlink(files[i].path);
                rename(tmp_name, files[i].path);
            } else {
                files[i].gz = gzopen(files[i].path, "rb");
            }
        }

        for (int i = start; i < num_files && max_threads > t; ++i) {
            pthread_create(&threads[t], NULL, process_file, &files[i]);
        }
    }

    for (int i = 0; i < max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

end:
    if (output_path && out != stdout) fclose(out);
    free(files);
    return 0;
}
