    if ((current.tv_sec - last_task_call.tv_sec > 1) || (current.tv_nsec - last_task_call.tv_nsec > RETRY_INTERVAL * NANOSECONDS_PER_SECOND)) {
        last_task_call = current;
    } else {
        usleep(RETRY_INTERVAL * 1000000); // Sleep for the remaining time before retrying.
    }
}

