        if (!temp) return NULL;
        memcpy(temp, buffer, outlen + 1);

        // Cache the result for future use
        if (cache_max > 0 && outlen + 1 < cache_max) {
            free(cache);
            cache = temp;
            cache_size = outlen + 1;
        }
    }

    return buffer;
}
