typedef struct Interface {
    char name[32];
    char ip[16];
    char mask[16];
    int active;
} Interface;

struct InterfaceList {
    size_t length;
    size_t capacity;
    Interface *interfaces;
};

void validateIP(const char *ip, const char *mask) {
    struct in_addr ip_addr;
    struct in_addr mask_addr;

    if (inet_pton(AF_INET, ip, &ip_addr) <= 0 ||
        inet_pton(AF_INET, mask, &mask_addr) <= 0) {
        fprintf(stderr, "Invalid IP or subnet mask format.\n");
        exit(1);
    }

    if (ntohl(ip_addr.s_addr) >> 24 != ntohl(mask_addr.s_addr) >> 24) {
        fprintf(stderr, "IP and subnet mask must have the same network prefix.\n");
        exit(1);
    }
}

void interfaceListInit(struct InterfaceList *list) {
    list->capacity = 10;
    list->length = 0;
    list->interfaces = calloc(list->capacity, sizeof(Interface));
}

void interfaceListDestroy(struct InterfaceList *list) {
    free(list->interfaces);
}

int interfaceListAdd(struct InterfaceList *list, const char *name, const char *ip, const char *mask, int active) {
    if (list->length >= list->capacity) {
        list->capacity *= 2;
        list->interfaces = realloc(list->interfaces, sizeof(Interface) * list->capacity);
    }

    Interface *interface = &list->interfaces[list->length];
    strcpy(interface->name, name);
    strcpy(interface->ip, ip);
    strcpy(interface->mask, mask);
    interface->active = active;

    int i;
    for (i = 0; i < list->length; ++i) {
        if (strcmp(list->interfaces[i].name, name) == 0) {
            fprintf(stderr, "Error: Interface with the given name already exists.\n");
            return -1;
        }
    }

    list->length++;
    return 0;
}

int interfaceListUpdate(struct InterfaceList *list, const char *name, const char *new_ip, const char *new_mask, int new_active) {
    int i;
    for (i = 0; i < list->length; ++i) {
        if (strcmp(list->interfaces[i].name, name) == 0) {
            strcpy(list->interfaces[i].ip, new_ip);
            strcpy(list->interfaces[i].mask, new_mask);
            list->interfaces[i].active = new_active;
            validateIP(new_ip, new_mask);
            return 0;
        }
    }

    fprintf(stderr, "Error: Interface with the given name does not exist.\n");
    return -1;
}

int interfaceListFind(const struct InterfaceList *list, const char *name) {
    int i;
    for (i = 0; i < list->length; ++i) {
        if (strcmp(list->interfaces[i].name, name) == 0) {
            return i;
        }
    }

    return -1;
}
