typedef struct NetInterface {
 char name[MAX_NAME_LENGTH];
 char ip[INET_ADDRSTRLEN];
 unsigned int mask;
 bool active;
 char mac[ETH_ALEN];
 unsigned short mtu;
 pthread_mutex_t lock;
} NetInterface;

NetInterface interfaces[MAX_INTERFACES];
unsigned int num_interfaces = 0;
pthread_mutex_t interfaces_lock = PTHREAD_MUTEX_INITIALIZER;

int add_interface(const char *name, const char *ip, unsigned int mask, bool active, const char *mac, unsigned short mtu) {
 if (num_interfaces >= MAX_INTERFACES) return -1; // Max interfaces reached

 for (unsigned int i = 0; i < num_interfaces; ++i) {
 pthread_mutex_lock(&interfaces[i].lock);
 if (!strcmp(name, interfaces[i].name)) {
 pthread_mutex_unlock(&interfaces[i].lock);
 return -2; // Interface name already exists
 }
 pthread_mutex_unlock(&interfaces[i].lock);
 }

 if (!valid_ip(ip) || !((1 << mask) == (~0 << (32 - mask)))) return -3; // Invalid IP address or subnet mask

 strncpy(interfaces[num_interfaces].name, name, MAX_NAME_LENGTH);
 strncpy(interfaces[num_interfaces].ip, ip, INET_ADDRSTRLEN);
 interfaces[num_interfaces].mask = mask;
 interfaces[num_interfaces].active = active;
 memcpy(interfaces[num_interfaces].mac, mac, ETH_ALEN);
 interfaces[num_interfaces].mtu = mtu;
 pthread_mutex_init(&interfaces[num_interfaces].lock, NULL);

 ++num_interfaces;
 return 0;
}

int update_interface(const char *name, const char *ip, unsigned int mask, bool active, const char *mac, unsigned short mtu) {
 for (unsigned int i = 0; i < num_interfaces; ++i) {
 pthread_mutex_lock(&interfaces[i].lock);
 if (!strcmp(name, interfaces[i].name)) {
 interfaces[i].ip[0] = '\0';
 strncpy(interfaces[i].ip, ip, INET_ADDRSTRLEN);
 interfaces[i].mask = mask;
 interfaces[i].active = active;
 memcpy(interfaces[i].mac, mac, ETH_ALEN);
 interfaces[i].mtu = mtu;
 pthread_mutex_unlock(&interfaces[i].lock);
 return 0;
 }
 pthread_mutex_unlock(&interfaces[i].lock);
 }
 return -2; // Interface not found
}

int delete_interface(const char *name) {
 for (unsigned int i = 0; i < num_interfaces; ++i) {
 pthread_mutex_lock(&interfaces[i].lock);
 if (!strcmp(name, interfaces[i].name)) {
 memmove(&interfaces[i], &interfaces[i+1], (num_interfaces - i - 1)*sizeof(NetInterface));
 --num_interfaces;
 pthread_mutex_destroy(&interfaces[num_interfaces].lock);
 pthread_mutex_unlock(&interfaces[i].lock);
 return 0;
 }
 pthread_mutex_unlock(&interfaces[i].lock);
 }
 return -2; // Interface not found
}

int check_interface(const char *name) {
 for (unsigned int i = 0; i < num_interfaces; ++i) {
 pthread_mutex_lock(&interfaces[i].lock);
 if (!strcmp(name, interfaces[i].name)) {
 pthread_mutex_unlock(&interfaces[i].lock);
 return i;
 }
 pthread_mutex_unlock(&interfaces[i].lock);
 }
 return -2; // Interface not found
}
