// Function to manage memory usage and log if it exceeds the threshold
void manage_memory(Config* config, void *ptr, size_t size) {
    sem_wait(config->mem_lock);
    size_t current_usage = *config->mem_counter + size;
    if (current_usage > config->mem_threshold) {
        // Log memory usage exceeded
        char msg[128];
        sprintf(msg, "Memory usage: %zu bytes\n", current_usage);
        config->log(msg);
    }
    *config->mem_counter += size;
    sem_post(config->mem_lock);
}

// Thread-safe counter increment function
void increment_counter(Config* config) {
    sem_wait(config->mem_lock);
    (*config->mem_counter)++;
    sem_post(config->mem_lock);
}

