    char *buffer = malloc(config.buffer_size);
    manage_memory(&config, buffer, config.buffer_size);

    if (buffer == NULL || !buffer_fits(buffer, config.buffer_size - config.mem_counter, input_len + strlen(config.suffix))) {
        free(buffer);
        return NULL;
    }

    strcpy(buffer, input);
    strcat(buffer, config.suffix);

